package com.kierenboal.npcsnap.features;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.ItemLayer;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

public final class GroundItemBillboardTracker
{
	private final Map<TileItem, GroundItemBillboard> groundItems = new HashMap<>();

	public void track(TileItem item, Tile tile)
	{
		if (item == null || tile == null)
		{
			return;
		}

		LocalPoint localPoint = tile.getLocalLocation();
		if (localPoint == null)
		{
			return;
		}

		ItemLayer itemLayer = tile.getItemLayer();
		int verticalOffset = itemLayer != null ? itemLayer.getHeight() : 0;
		groundItems.put(item, new GroundItemBillboard(tile.getPlane(), localPoint, verticalOffset));
	}

	public void untrack(TileItem item)
	{
		if (item == null)
		{
			return;
		}

		groundItems.remove(item);
	}

	public void clear()
	{
		groundItems.clear();
	}

	public GroundItemBillboard get(TileItem item)
	{
		return groundItems.get(item);
	}

	public Set<Map.Entry<TileItem, GroundItemBillboard>> entries()
	{
		return groundItems.entrySet();
	}

	public Set<TileItem> items()
	{
		return groundItems.keySet();
	}

	public void seed(WorldView worldView)
	{
		forEachSceneGroundItem(worldView, this::track);
	}

	private static void forEachSceneGroundItem(WorldView worldView, GroundItemConsumer groundItemConsumer)
	{
		if (worldView == null)
		{
			return;
		}

		Scene scene = worldView.getScene();
		if (scene == null || scene.getTiles() == null)
		{
			return;
		}

		for (Tile[][] planeTiles : scene.getTiles())
		{
			if (planeTiles == null)
			{
				continue;
			}

			for (Tile[] row : planeTiles)
			{
				trackGroundItems(row, groundItemConsumer);
			}
		}
	}

	private static void trackGroundItems(Tile[] row, GroundItemConsumer groundItemConsumer)
	{
		if (row == null)
		{
			return;
		}

		for (Tile tile : row)
		{
			if (tile == null || tile.getGroundItems() == null)
			{
				continue;
			}

			for (TileItem item : tile.getGroundItems())
			{
				if (item != null)
				{
					groundItemConsumer.accept(item, tile);
				}
			}
		}
	}

	private interface GroundItemConsumer
	{
		void accept(TileItem item, Tile tile);
	}
}

package com.kierenboal.npcsnap.features;

import net.runelite.api.GameState;
import net.runelite.api.events.StatChanged;

public final class LoginXpDropGuard
{
	private static final int GRACE_TICKS = 10;

	private int gameTick;
	private int graceUntilTick = Integer.MIN_VALUE;
	private int ignoredDropTick = Integer.MIN_VALUE;

	public void advanceTick()
	{
		gameTick++;
	}

	public void onLoggedIn()
	{
		graceUntilTick = gameTick + GRACE_TICKS;
		ignoredDropTick = Integer.MIN_VALUE;
	}

	public void onLoggedOut()
	{
		graceUntilTick = Integer.MIN_VALUE;
		ignoredDropTick = Integer.MIN_VALUE;
	}

	public boolean shouldIgnore(StatChanged change, GameState gameState, SkillingActivityTracker tracker)
	{
		if (change == null
			|| gameState != GameState.LOGGED_IN
			|| gameTick > graceUntilTick
			|| !tracker.isTrackedXpIncrease(change.getSkill(), change.getXp()))
		{
			return false;
		}

		if (ignoredDropTick == Integer.MIN_VALUE)
		{
			ignoredDropTick = gameTick;
			return true;
		}

		return ignoredDropTick == gameTick;
	}
}

package com.kierenboal.npcsnap.features;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.ArrayList;
import java.util.List;

final class RetroChatRenderer
{
	private static final long RANDOM_BUCKET_MILLIS = 200L;
	private static final int EFFECT_MARGIN = 8;
	private static final Map<String, Color> RETRO_COLORS = retroColors();
	private static final Color[] RANDOM_COLORS = RETRO_COLORS.values().toArray(new Color[0]);

	static ParsedChat plain(String text)
	{
		return uniform(text, Color.YELLOW, ColorMode.SOLID, Motion.NONE);
	}

	static ParsedChat parse(String source)
	{
		String text = source == null ? "" : source;
		Color color = Color.YELLOW;
		ColorMode colorMode = ColorMode.SOLID;
		Motion motion = Motion.NONE;
		boolean colorFound = false;
		boolean motionFound = false;

		for (int pass = 0; pass < 2; pass++)
		{
			Prefix prefix = leadingPrefix(text);
			if (prefix == null)
			{
				break;
			}
			String code = prefix.code.toLowerCase(Locale.ROOT);
			Color retro = RETRO_COLORS.get(code);
			if (!colorFound && retro != null)
			{
				color = retro;
				colorFound = true;
				text = text.substring(prefix.length);
				continue;
			}
			if (!colorFound && "ran".equals(code))
			{
				colorMode = ColorMode.RANDOM;
				colorFound = true;
				text = text.substring(prefix.length);
				continue;
			}
			ColorMode parsedColor = builtInColor(code);
			if (!colorFound && parsedColor != null)
			{
				colorMode = parsedColor;
				color = builtInSolidColor(code);
				colorFound = true;
				text = text.substring(prefix.length);
				continue;
			}
			Motion parsedMotion = motion(code);
			if (!motionFound && parsedMotion != null)
			{
				motion = parsedMotion;
				motionFound = true;
				text = text.substring(prefix.length);
				continue;
			}
			break;
		}
		StringBuilder visible = new StringBuilder();
		List<Color> colors = new ArrayList<>();
		List<ColorMode> modes = new ArrayList<>();
		Color currentColor = color;
		ColorMode currentMode = colorMode;
		for (int index = 0; index < text.length();)
		{
			if (text.charAt(index) == '@' && index + 4 < text.length() && text.charAt(index + 4) == '@')
			{
				String code = text.substring(index + 1, index + 4).toLowerCase(Locale.ROOT);
				Color inlineColor = RETRO_COLORS.get(code);
				if (inlineColor != null || "ran".equals(code))
				{
					currentColor = inlineColor == null ? Color.YELLOW : inlineColor;
					currentMode = inlineColor == null ? ColorMode.RANDOM : ColorMode.SOLID;
					index += 5;
					continue;
				}
			}
			visible.append(text.charAt(index++));
			colors.add(currentColor);
			modes.add(currentMode);
		}
		return new ParsedChat(visible.toString(), color, colorMode, motion,
			colors.toArray(new Color[0]), modes.toArray(new ColorMode[0]));
	}

	private static ParsedChat uniform(String text, Color color, ColorMode mode, Motion motion)
	{
		Color[] colors = new Color[text.length()];
		ColorMode[] modes = new ColorMode[text.length()];
		java.util.Arrays.fill(colors, color);
		java.util.Arrays.fill(modes, mode);
		return new ParsedChat(text, color, mode, motion, colors, modes);
	}

	Rectangle bounds(ParsedChat chat, FontMetrics metrics, int centerX, int cursorY)
	{
		int width = metrics.stringWidth(chat.text);
		int margin = chat.motion == Motion.NONE ? 0 : EFFECT_MARGIN;
		return new Rectangle(centerX - width / 2 - margin, cursorY - metrics.getHeight() - margin,
			Math.max(1, width + margin * 2), metrics.getHeight() + margin * 2);
	}

	void draw(Graphics2D graphics, ParsedChat chat, Rectangle bounds, Object actor, long nowMillis, Color shadow)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int textWidth = metrics.stringWidth(chat.text);
		int margin = chat.motion == Motion.NONE ? 0 : EFFECT_MARGIN;
		int startX = bounds.x + margin + Math.max(0, (bounds.width - margin * 2 - textWidth) / 2);
		int baseline = bounds.y + margin + metrics.getAscent();
		Shape oldClip = graphics.getClip();
		graphics.clip(bounds);
		long phase = Math.floorMod(nowMillis, 4000L);
		int x = startX + wholeTextX(chat.motion, phase, bounds.width, textWidth);
		for (int i = 0; i < chat.text.length(); i++)
		{
			String character = chat.text.substring(i, i + 1);
			int y = baseline + characterY(chat.motion, phase, i);
			int charX = x + characterX(chat.motion, phase, i);
			Color color = color(chat, actor, nowMillis, i);
			graphics.setColor(shadow);
			graphics.drawString(character, charX + 1, y + 1);
			graphics.setColor(color);
			graphics.drawString(character, charX, y);
			x += metrics.stringWidth(character);
		}
		graphics.setClip(oldClip);
	}

	static Color color(ParsedChat chat, Object actor, long nowMillis, int characterIndex)
	{
		long phase = Math.floorMod(nowMillis, 4000L);
		ColorMode mode = characterIndex < chat.colorModes.length ? chat.colorModes[characterIndex] : chat.colorMode;
		Color solidColor = characterIndex < chat.colors.length ? chat.colors[characterIndex] : chat.color;
		switch (mode)
		{
			case RANDOM:
				long bucket = Math.floorDiv(nowMillis, RANDOM_BUCKET_MILLIS);
				int seed = System.identityHashCode(actor) * 31 + chat.text.hashCode() + characterIndex * 131;
				return RANDOM_COLORS[Math.floorMod(mix(seed, bucket), RANDOM_COLORS.length)];
			case FLASH1:
				return (phase / 250L) % 2 == 0 ? Color.RED : Color.YELLOW;
			case FLASH2:
				return (phase / 250L) % 2 == 0 ? Color.CYAN : Color.BLUE;
			case FLASH3:
				return (phase / 250L) % 2 == 0 ? new Color(0x80FF80) : new Color(0x008000);
			case GLOW1:
				return cycle(phase, characterIndex, Color.RED, Color.ORANGE, Color.YELLOW, Color.GREEN, Color.CYAN);
			case GLOW2:
				return cycle(phase, characterIndex, Color.RED, Color.MAGENTA, Color.BLUE, new Color(0x800000));
			case GLOW3:
				return cycle(phase, characterIndex, Color.WHITE, Color.GREEN, Color.WHITE, Color.CYAN);
			default:
				return solidColor;
		}
	}

	private static int mix(int seed, long bucket)
	{
		long value = bucket ^ seed;
		value ^= value >>> 33;
		value *= 0xff51afd7ed558ccdl;
		value ^= value >>> 33;
		return (int) value;
	}

	private static Color cycle(long phase, int characterIndex, Color... colors)
	{
		return colors[Math.floorMod((int) (phase / 200L) + characterIndex / 2, colors.length)];
	}

	private static int characterY(Motion motion, long phase, int index)
	{
		if (motion == Motion.WAVE || motion == Motion.WAVE2)
		{
			return (int) Math.round(Math.sin((phase / 180.0) + index * (motion == Motion.WAVE ? 0.7 : 0.45)) * 5.0);
		}
		if (motion == Motion.SHAKE)
		{
			return Math.floorMod(mix(index, phase / 80L), 7) - 3;
		}
		if (motion == Motion.SLIDE)
		{
			return (int) Math.round(-7.0 * Math.cos(phase * Math.PI / 2000.0));
		}
		return 0;
	}

	private static int characterX(Motion motion, long phase, int index)
	{
		if (motion == Motion.WAVE2)
		{
			return (int) Math.round(Math.sin((phase / 210.0) + index * 0.55) * 3.0);
		}
		if (motion == Motion.SHAKE)
		{
			return Math.floorMod(mix(index + 17, phase / 80L), 5) - 2;
		}
		return 0;
	}

	private static int wholeTextX(Motion motion, long phase, int boundsWidth, int textWidth)
	{
		if (motion != Motion.SCROLL)
		{
			return 0;
		}
		int distance = boundsWidth + textWidth;
		return boundsWidth - (int) (distance * phase / 4000L);
	}

	private static Prefix leadingPrefix(String text)
	{
		if (text.startsWith("@") && text.length() >= 5 && text.charAt(4) == '@')
		{
			return new Prefix(text.substring(1, 4), 5);
		}
		int colon = text.indexOf(':');
		if (colon > 0 && colon <= 7)
		{
			String code = text.substring(0, colon).toLowerCase(Locale.ROOT);
			if (builtInColor(code) != null || motion(code) != null)
			{
				return new Prefix(code, colon + 1);
			}
		}
		return null;
	}

	private static ColorMode builtInColor(String code)
	{
		switch (code)
		{
			case "yellow": case "red": case "green": case "cyan": case "purple": case "white": return ColorMode.SOLID;
			case "flash1": return ColorMode.FLASH1;
			case "flash2": return ColorMode.FLASH2;
			case "flash3": return ColorMode.FLASH3;
			case "glow1": return ColorMode.GLOW1;
			case "glow2": return ColorMode.GLOW2;
			case "glow3": return ColorMode.GLOW3;
			default: return null;
		}
	}

	private static Color builtInSolidColor(String code)
	{
		switch (code)
		{
			case "red": return Color.RED;
			case "green": return Color.GREEN;
			case "cyan": return Color.CYAN;
			case "purple": return new Color(0x800080);
			case "white": return Color.WHITE;
			default: return Color.YELLOW;
		}
	}

	private static Motion motion(String code)
	{
		switch (code)
		{
			case "wave": return Motion.WAVE;
			case "wave2": return Motion.WAVE2;
			case "shake": return Motion.SHAKE;
			case "slide": return Motion.SLIDE;
			case "scroll": return Motion.SCROLL;
			default: return null;
		}
	}

	private static Map<String, Color> retroColors()
	{
		Map<String, Color> colors = new LinkedHashMap<>();
		colors.put("red", new Color(0xFF0000)); colors.put("dre", new Color(0x800000));
		colors.put("lre", new Color(0xFF6060)); colors.put("ora", new Color(0xFF9040));
		colors.put("or1", new Color(0xFF7F00)); colors.put("or2", new Color(0xC06000));
		colors.put("or3", new Color(0xFF4000)); colors.put("yel", new Color(0xFFFF00));
		colors.put("gr1", new Color(0xC0FF00)); colors.put("gre", new Color(0x00C000));
		colors.put("gr2", new Color(0x40FF40)); colors.put("gr3", new Color(0x80FF00));
		colors.put("blu", new Color(0x0000FF)); colors.put("cya", new Color(0x00FFFF));
		colors.put("mag", new Color(0xFF00FF)); colors.put("bla", Color.BLACK);
		colors.put("whi", Color.WHITE);
		return Collections.unmodifiableMap(colors);
	}

	static final class ParsedChat
	{
		final String text;
		final Color color;
		final ColorMode colorMode;
		final Motion motion;
		final Color[] colors;
		final ColorMode[] colorModes;

		private ParsedChat(String text, Color color, ColorMode colorMode, Motion motion,
			Color[] colors, ColorMode[] colorModes)
		{
			this.text = text;
			this.color = color;
			this.colorMode = colorMode;
			this.motion = motion;
			this.colors = colors;
			this.colorModes = colorModes;
		}
	}

	enum ColorMode { SOLID, RANDOM, FLASH1, FLASH2, FLASH3, GLOW1, GLOW2, GLOW3 }
	enum Motion { NONE, WAVE, WAVE2, SHAKE, SLIDE, SCROLL }

	private static final class Prefix
	{
		private final String code;
		private final int length;
		private Prefix(String code, int length) { this.code = code; this.length = length; }
	}
}

package com.kierenboal.npcsnap.features;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.util.HashMap;
import java.util.Map;
import java.util.Random;
import net.runelite.api.HitsplatID;

/** Flat vector demakes of native hitsplats. No game sprites or textures are required. */
public final class RetroHitsplatRenderer
{
	private static final Color GOLD = new Color(0xFFD65A);
	private static final Color TINTED_DAMAGE_BORDER = new Color(0x752B28);
	private static final Color TINTED_BLOCK_BORDER = new Color(0x252F72);
	private static final Color BURN_CENTER = new Color(0xBA0000);
	private static final Stroke OUTLINE = new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL);
	private static final Stroke TRIM_BACKING = new BasicStroke(3, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL);
	private static final Map<Integer, UnknownStyle> UNKNOWN_STYLES = new HashMap<>();
	private static final int UNKNOWN_BLOCK_SIZE = 32;

	enum UnknownShape { CIRCLE, SQUARE, TRIANGLE }

	private static final class UnknownStyle
	{
		final Color color;
		final UnknownShape shape;

		UnknownStyle(Color color, UnknownShape shape)
		{
			this.color = color;
			this.shape = shape;
		}
	}

	enum Style
	{
		DAMAGE(0xE51B17, 0xE51B17, null), BLOCK(0x3155D9, 0x3155D9, null),
		SHIELD(0x0DAB93, 0x08737D, polygon(1, 1, 19, 1, 19, 12, 16, 17, 10, 20, 4, 17, 1, 12)),
		ARMOUR(0xBD4B00, 0xA72400, polygon(5, 2, 8, 0, 12, 0, 15, 2, 20, 4, 18, 9, 15, 7,
			15, 16, 12, 20, 8, 20, 5, 16, 5, 7, 2, 9, 0, 4)),
		CHARGE(0xBCBD00, 0x666600, arrow(true)), UNCHARGE(0x9A9A9A, 0x343826, arrow(false)),
		ALT_CHARGE(0x086758, 0x086758, arrow(true)), ALT_UNCHARGE(0x05454B, 0x05454B, arrow(false)),
		POISE(0xBCBD00, 0x6E6C00, poise()),
		POISON(0x00C000, 0x00C000, burst(12, 0.68)), VENOM(0x40957E, 0x40957E, burst(12, 0.68)),
		DISEASE(0xFCB712, 0xFCB712, burst(10, 0.64)),
		HEAL(0x9813AA, 0x9813AA, polygon(6, 0, 14, 0, 14, 6, 20, 6, 20, 14, 14, 14,
			14, 20, 6, 20, 6, 14, 0, 14, 0, 6, 6, 6)),
		PRAYER(0x6D4AB2, 0x453369, arrow(false)),
		CORRUPTION(0x9030FF, 0x9030FF, polygon(3, 0, 8, 5, 12, 5, 17, 0, 20, 3, 15, 8, 15, 12,
			20, 17, 17, 20, 12, 15, 8, 15, 3, 20, 0, 17, 5, 12, 5, 8, 0, 3)),
		BLEED(0xF30000, 0xF30000, burst(10, 0.68)), BURN(0xF88100, 0xF88100, burst(8, 0.46)),
		SANITY(0x89626D, 0x89626D, brain()), SANITY_RESTORE(0x9813AA, 0x9813AA, brain()),
		DOOM(0x343826, 0x343826, skull()),
		UNKNOWN(0xFFFFFF, 0xFFFFFF, new Ellipse2D.Double(0, 0, 20, 20));

		final Color fill;
		final Color tintedFill;
		final Color detail;
		final Shape shape;

		Style(int fill, int tintedFill, Shape shape)
		{
			this.fill = new Color(fill);
			this.tintedFill = new Color(tintedFill);
			this.detail = this.fill.darker();
			this.shape = shape;
		}
	}

	private RetroHitsplatRenderer()
	{
	}

	static Style style(int type, int amount)
	{
		switch (type)
		{
			case HitsplatID.BLOCK_ME: case HitsplatID.BLOCK_OTHER: return Style.BLOCK;
			case HitsplatID.DAMAGE_ME: case HitsplatID.DAMAGE_OTHER: case HitsplatID.DAMAGE_MAX_ME: return Style.DAMAGE;
			case HitsplatID.DAMAGE_ME_CYAN: case HitsplatID.DAMAGE_OTHER_CYAN: case HitsplatID.DAMAGE_MAX_ME_CYAN: return Style.SHIELD;
			case HitsplatID.DAMAGE_ME_ORANGE: case HitsplatID.DAMAGE_OTHER_ORANGE: case HitsplatID.DAMAGE_MAX_ME_ORANGE: return Style.ARMOUR;
			case HitsplatID.DAMAGE_ME_YELLOW: case HitsplatID.DAMAGE_OTHER_YELLOW: case HitsplatID.DAMAGE_MAX_ME_YELLOW: return Style.CHARGE;
			case HitsplatID.DAMAGE_ME_WHITE: case HitsplatID.DAMAGE_OTHER_WHITE: case HitsplatID.DAMAGE_MAX_ME_WHITE: return Style.UNCHARGE;
			case HitsplatID.CYAN_UP: return Style.ALT_CHARGE;
			case HitsplatID.CYAN_DOWN: return Style.ALT_UNCHARGE;
			case HitsplatID.DAMAGE_ME_POISE: case HitsplatID.DAMAGE_OTHER_POISE: case HitsplatID.DAMAGE_MAX_ME_POISE: return Style.POISE;
			case HitsplatID.POISON: return Style.POISON;
			case HitsplatID.VENOM: return Style.VENOM;
			case HitsplatID.DISEASE: case HitsplatID.DISEASE_BLOCKED: return Style.DISEASE;
			case HitsplatID.HEAL: return Style.HEAL;
			case HitsplatID.PRAYER_DRAIN: return Style.PRAYER;
			case HitsplatID.CORRUPTION: return Style.CORRUPTION;
			case HitsplatID.BLEED: return Style.BLEED;
			case HitsplatID.BURN: return Style.BURN;
			case HitsplatID.SANITY_DRAIN: return Style.SANITY;
			case HitsplatID.SANITY_RESTORE: return Style.SANITY_RESTORE;
			case HitsplatID.DOOM: return Style.DOOM;
			default: return Style.UNKNOWN;
		}
	}

	static boolean tinted(int type)
	{
		switch (type)
		{
			case HitsplatID.BLOCK_OTHER: case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_OTHER_CYAN: case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_OTHER_YELLOW: case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_OTHER_POISE: return true;
			default: return false;
		}
	}

	static boolean maxHit(int type)
	{
		switch (type)
		{
			case HitsplatID.DAMAGE_MAX_ME: case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE: case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE: case HitsplatID.DAMAGE_MAX_ME_POISE: return true;
			default: return false;
		}
	}

	static Color fill(int type, int amount)
	{
		Style style = style(type, amount);
		if (style == Style.UNKNOWN)
		{
			return unknownStyle(type).color;
		}
		return tinted(type) ? style.tintedFill : style.fill;
	}

	/** Stable, conspicuous pastel: two full/half channels and one intermediate channel. */
	private static Color rollUnknownColor(Random random)
	{
		int[] channels = {random.nextBoolean() ? 255 : 128, random.nextBoolean() ? 255 : 128,
			129 + random.nextInt(126)};
		int intermediate = random.nextInt(3);
		int temporary = channels[intermediate];
		channels[intermediate] = channels[2];
		channels[2] = temporary;
		return new Color(channels[0], channels[1], channels[2]);
	}

	static UnknownShape unknownShape(int type)
	{
		return unknownStyle(type).shape;
	}

	private static UnknownStyle rollUnknownStyle(int type, UnknownStyle previous, UnknownStyle next)
	{
		Random random = new Random(type * 0x9E3779B97F4A7C15L);
		Color color;
		do
		{
			color = rollUnknownColor(random);
		}
		while ((previous != null && color.equals(previous.color)) || (next != null && color.equals(next.color)));
		UnknownShape shape;
		do
		{
			shape = UnknownShape.values()[random.nextInt(3)];
		}
		while ((previous != null && shape == previous.shape) || (next != null && shape == next.shape));
		return new UnknownStyle(color, shape);
	}

	private static UnknownStyle unknownStyle(int type)
	{
		UnknownStyle cached = UNKNOWN_STYLES.get(type);
		if (cached != null)
		{
			return cached;
		}
		// Fixed-size ID blocks keep generation bounded and independent of lookup
		// order. The last entry also avoids the next block's seeded anchor, so
		// neighbours cannot repeat across a block boundary either.
		int start = type & ~(UNKNOWN_BLOCK_SIZE - 1);
		UnknownStyle next = rollUnknownStyle(start + UNKNOWN_BLOCK_SIZE, null, null);
		UnknownStyle previous = null;
		for (int offset = 0; offset < UNKNOWN_BLOCK_SIZE; offset++)
		{
			int id = start + offset;
			UnknownStyle generated = rollUnknownStyle(id, previous, offset == UNKNOWN_BLOCK_SIZE - 1 ? next : null);
			UNKNOWN_STYLES.put(id, generated);
			previous = generated;
		}
		return UNKNOWN_STYLES.get(type);
	}

	static int unknownWidth(int type, int diameter)
	{
		return unknownShape(type) == UnknownShape.TRIANGLE ? diameter * 2 : diameter;
	}

	private static Shape unknownGeometry(int type, int centerX, int centerY, int diameter)
	{
		double top = centerY - diameter / 2.0, left = centerX - diameter / 2.0;
		switch (unknownShape(type))
		{
			case SQUARE: return new Rectangle2D.Double(left, top, diameter, diameter);
			case TRIANGLE:
				// A wider base leaves room for the number below the pointed tip.
				return polygon(centerX, top, centerX + diameter, top + diameter, centerX - diameter, top + diameter);
			default: return new Ellipse2D.Double(left, top, diameter, diameter);
		}
	}

	static Color border(int type, int amount)
	{
		if (maxHit(type))
		{
			return GOLD;
		}
		Style style = style(type, amount);
		return tinted(type) && (style == Style.DAMAGE || style == Style.BLOCK)
			? (style == Style.DAMAGE ? TINTED_DAMAGE_BORDER : TINTED_BLOCK_BORDER) : Color.BLACK;
	}

	/** Caller supplies the existing hitsplat font and the number's baseline. */
	public static void draw(Graphics2D graphics, int type, int amount, int centerX, int baselineY)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			FontMetrics metrics = g.getFontMetrics();
			String text = Integer.toString(amount);
			int width = Math.max(20, metrics.stringWidth(text) + 12);
			int x = centerX - width / 2, y = baselineY - 15;
			Style style = style(type, amount);
			boolean classic = style == Style.DAMAGE || style == Style.BLOCK;
			Shape shape = style == Style.UNKNOWN
				? unknownGeometry(type, centerX, baselineY - 5, width)
				: classic ? classicStar(x, y, width, 20)
				: new AffineTransform(width / 20.0, 0, 0, 1, x, y).createTransformedShape(style.shape);
			g.setStroke(maxHit(type) ? TRIM_BACKING : OUTLINE);
			g.setColor(Color.BLACK);
			g.draw(shape);
			g.setColor(fill(type, amount));
			g.fill(shape);
			g.setStroke(OUTLINE);
			g.setColor(border(type, amount));
			g.draw(shape);
			if (!classic && style != Style.UNKNOWN)
			{
				details(g, style, x, y, width);
			}
			int textX = centerX - metrics.stringWidth(text) / 2;
			g.setColor(Color.BLACK);
			g.drawString(text, textX + 1, baselineY + 1);
			g.setColor(Color.WHITE);
			g.drawString(text, textX, baselineY);
		}
		finally
		{
			g.dispose();
		}
	}

	private static void details(Graphics2D g, Style style, int x, int y, int width)
	{
		g.setColor(style.detail);
		if (style == Style.SHIELD)
		{
			g.drawLine(x + 2, y + 5, x + width - 2, y + 5);
			g.drawLine(x + width / 2, y + 2, x + width / 2, y + 18);
		}
		else if (style == Style.SANITY || style == Style.SANITY_RESTORE)
		{
			g.drawLine(x + width / 2, y + 2, x + width / 2, y + 18);
			g.drawPolyline(new int[] {x + width / 4, x + width / 3, x + width / 4}, new int[] {y + 4, y + 8, y + 16}, 3);
			g.drawPolyline(new int[] {x + 3 * width / 4, x + 2 * width / 3, x + 3 * width / 4}, new int[] {y + 4, y + 8, y + 16}, 3);
		}
		else if (style == Style.DOOM)
		{
			g.setColor(Color.BLACK);
			g.fillRect(x + width / 4, y + 6, Math.max(2, width / 5), 3);
			g.fillRect(x + 3 * width / 5, y + 6, Math.max(2, width / 5), 3);
		}
		else if (style == Style.BURN)
		{
			g.setColor(BURN_CENTER);
			g.fillOval(x + width / 4, y + 5, width / 2, 10);
		}
	}

	private static Shape polygon(double... coordinates)
	{
		Path2D.Double path = new Path2D.Double();
		path.moveTo(coordinates[0], coordinates[1]);
		for (int i = 2; i < coordinates.length; i += 2)
		{
			path.lineTo(coordinates[i], coordinates[i + 1]);
		}
		path.closePath();
		return path;
	}

	private static Shape arrow(boolean up)
	{
		Shape down = polygon(0, 0, 5, 3, 5, 12, 0, 12, 10, 20, 20, 12, 15, 12, 15, 3, 20, 0, 10, 4);
		return up ? new AffineTransform(1, 0, 0, -1, 0, 20).createTransformedShape(down) : down;
	}

	private static Shape burst(int points, double innerRadius)
	{
		Path2D.Double path = new Path2D.Double();
		for (int i = 0; i < points * 2; i++)
		{
			double angle = -Math.PI / 2 + i * Math.PI / points;
			double radius = (i % 2 == 0 ? 1 : innerRadius) * 10;
			double x = 10 + Math.cos(angle) * radius, y = 10 + Math.sin(angle) * radius;
			if (i == 0) { path.moveTo(x, y); } else { path.lineTo(x, y); }
		}
		path.closePath();
		return path;
	}

	private static Shape brain()
	{
		Path2D.Double path = new Path2D.Double();
		path.moveTo(10, 1);
		path.curveTo(6, -1, 3, 3, 3, 5);
		path.curveTo(-1, 6, -1, 12, 3, 14);
		path.curveTo(3, 18, 7, 21, 10, 19);
		path.curveTo(13, 21, 17, 18, 17, 14);
		path.curveTo(21, 12, 21, 6, 17, 5);
		path.curveTo(17, 3, 14, -1, 10, 1);
		path.closePath();
		return path;
	}

	private static Shape poise()
	{
		Path2D.Double path = new Path2D.Double();
		path.moveTo(1, 0);
		path.curveTo(3, 2, 3, 6, 5, 8);
		path.curveTo(8, 4, 14, 4, 17, 8);
		path.curveTo(19, 10, 17, 14, 19, 18);
		path.lineTo(20, 20);
		path.curveTo(14, 18, 19, 14, 16, 12);
		path.curveTo(12, 16, 5, 16, 3, 12);
		path.curveTo(1, 10, 3, 5, 1, 0);
		path.closePath();
		return path;
	}

	private static Shape skull()
	{
		return polygon(1, 2, 4, 5, 4, 2, 8, 0, 12, 0, 16, 2, 16, 5, 19, 2, 20, 7,
			17, 10, 16, 14, 14, 16, 14, 20, 6, 20, 6, 16, 4, 14, 3, 10, 0, 7);
	}

	static Polygon classicStar(int x, int y, int width, int height)
	{
		int right = x + width, bottom = y + height;
		int midX = x + width / 2, midY = y + height / 2;
		int bodyHalfWidth = Math.max(6, (width * 3) / 10), bodyHalfHeight = Math.max(5, height / 4);
		int spikeHalfWidth = Math.max(2, width / 10), spikeHalfHeight = Math.max(2, height / 10);
		int bodyLeft = midX - bodyHalfWidth, bodyRight = midX + bodyHalfWidth;
		int bodyTop = midY - bodyHalfHeight, bodyBottom = midY + bodyHalfHeight;
		return new Polygon(
			new int[] {midX - spikeHalfWidth, midX, midX + spikeHalfWidth,
				bodyRight, right - 2, bodyRight, right, bodyRight, right - 2,
				bodyRight, midX + spikeHalfWidth, midX, midX - spikeHalfWidth,
				bodyLeft, x + 2, bodyLeft, x, bodyLeft, x + 2, bodyLeft},
			new int[] {bodyTop, y, bodyTop, bodyTop, y + 2, midY - spikeHalfHeight, midY,
				midY + spikeHalfHeight, bottom - 2, bodyBottom, bodyBottom, bottom, bodyBottom,
				bodyBottom, bottom - 2, midY + spikeHalfHeight, midY, midY - spikeHalfHeight, y + 2, bodyTop}, 20);
	}
}

package com.kierenboal.npcsnap.features;

import java.util.ArrayList;
import java.util.Collection;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Skill;

@Singleton
public class SkillingActivityTracker
{
	private static final EnumSet<Skill> TRACKED_SKILLS = EnumSet.of(
		Skill.MINING,
		Skill.AGILITY,
		Skill.SMITHING,
		Skill.HERBLORE,
		Skill.FISHING,
		Skill.THIEVING,
		Skill.COOKING,
		Skill.CRAFTING,
		Skill.FIREMAKING,
		Skill.FLETCHING,
		Skill.WOODCUTTING,
		Skill.RUNECRAFT,
		Skill.FARMING,
		Skill.CONSTRUCTION,
		Skill.HUNTER,
		Skill.SAILING
	);

	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
	private final Map<Skill, Long> visibleFromMillis = new EnumMap<>(Skill.class);
	private final Map<Skill, Long> activeUntilMillis = new EnumMap<>(Skill.class);

	public Collection<Skill> getTrackedSkills()
	{
		return TRACKED_SKILLS;
	}

	public boolean isTrackedSkill(Skill skill)
	{
		return skill != null && TRACKED_SKILLS.contains(skill);
	}

	public boolean isTrackedXpIncrease(Skill skill, int xp)
	{
		if (!isTrackedSkill(skill))
		{
			return false;
		}

		Integer previousXp = lastXp.get(skill);
		return previousXp != null && xp > previousXp;
	}

	public void seedXp(Skill skill, int xp)
	{
		if (!isTrackedSkill(skill))
		{
			return;
		}

		lastXp.put(skill, xp);
	}

	public boolean recordXp(Skill skill, int xp, long nowMillis, long timeoutMillis)
	{
		if (skill == null)
		{
			return false;
		}

		Integer previousXp = lastXp.put(skill, xp);
		if (previousXp == null || xp <= previousXp || !isTrackedSkill(skill))
		{
			return false;
		}

		Long expiresAt = activeUntilMillis.get(skill);
		if (expiresAt == null || expiresAt <= nowMillis)
		{
			visibleFromMillis.put(skill, nowMillis);
		}

		activeUntilMillis.put(skill, nowMillis + Math.max(0L, timeoutMillis));
		return true;
	}

	public List<Skill> getRenderableSkills(long nowMillis, long fadeOutMillis)
	{
		List<Skill> activeSkills = new ArrayList<>(activeUntilMillis.size());
		long removalThreshold = nowMillis - Math.max(0L, fadeOutMillis);
		Iterator<Map.Entry<Skill, Long>> iterator = activeUntilMillis.entrySet().iterator();
		while (iterator.hasNext())
		{
			Map.Entry<Skill, Long> entry = iterator.next();
			if (entry.getValue() <= removalThreshold)
			{
				visibleFromMillis.remove(entry.getKey());
				iterator.remove();
			}
		}

		for (Skill skill : TRACKED_SKILLS)
		{
			Long expiresAt = activeUntilMillis.get(skill);
			if (expiresAt != null && expiresAt > removalThreshold)
			{
				activeSkills.add(skill);
			}
		}

		return activeSkills;
	}

	public long getVisibleFromMillis(Skill skill)
	{
		return visibleFromMillis.getOrDefault(skill, 0L);
	}

	public long getActiveUntilMillis(Skill skill)
	{
		return activeUntilMillis.getOrDefault(skill, 0L);
	}

	public void clear()
	{
		lastXp.clear();
		visibleFromMillis.clear();
		activeUntilMillis.clear();
	}
}

package com.kierenboal.npcsnap.features;

import java.util.List;
import net.runelite.api.Skill;

public final class SkillingBubbleAnimation
{
	private final SkillingActivityTracker tracker;

	public SkillingBubbleAnimation(SkillingActivityTracker tracker)
	{
		this.tracker = tracker;
	}

	public float bubbleAlpha(List<Skill> activeSkills, long nowMillis)
	{
		float alpha = 0.0f;
		for (Skill skill : activeSkills)
		{
			alpha = Math.max(alpha, skillAlpha(skill, nowMillis));
		}
		return alpha;
	}

	public float introProgress(List<Skill> activeSkills, long nowMillis)
	{
		float progress = 1.0f;
		for (Skill skill : activeSkills)
		{
			long visibleFrom = tracker.getVisibleFromMillis(skill);
			if (visibleFrom > 0L)
			{
				progress = Math.min(progress, clamp((float) (nowMillis - visibleFrom) / SkillingThoughtBubbleOverlay.FADE_IN_MILLIS));
			}
		}
		return progress;
	}

	public float skillAlpha(Skill skill, long nowMillis)
	{
		long visibleFrom = tracker.getVisibleFromMillis(skill);
		long activeUntil = tracker.getActiveUntilMillis(skill);
		if (visibleFrom <= 0L || activeUntil <= 0L)
		{
			return 0.0f;
		}

		if (nowMillis < visibleFrom + SkillingThoughtBubbleOverlay.FADE_IN_MILLIS)
		{
			return clamp((float) (nowMillis - visibleFrom) / SkillingThoughtBubbleOverlay.FADE_IN_MILLIS);
		}
		if (nowMillis <= activeUntil)
		{
			return 1.0f;
		}
		return clamp(1.0f - ((float) (nowMillis - activeUntil) / SkillingThoughtBubbleOverlay.FADE_OUT_MILLIS));
	}

	private static float clamp(float value)
	{
		return Math.max(0.0f, Math.min(1.0f, value));
	}
}

package com.kierenboal.npcsnap.features;

import com.kierenboal.npcsnap.NpcSnapConfig;
import com.kierenboal.npcsnap.targeting.BillboardWorldViewVisibility;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.awt.geom.Path2D;
import java.awt.geom.AffineTransform;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Skill;
import net.runelite.api.SpriteID;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.SpriteID.IconStat50x50;
import net.runelite.api.gameval.SpriteID.Staticons2;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class SkillingThoughtBubbleOverlay extends Overlay
{
	public static final long FADE_IN_MILLIS = 500L;
	public static final long FADE_OUT_MILLIS = 2_500L;
	private static final Color BUBBLE_FILL = new Color(255, 255, 255, 150);
	private static final Color BUBBLE_OUTLINE = new Color(255, 255, 255, 215);
	private static final int ICON_SIZE = 24;
	private static final int ICON_GAP = 4;
	private static final int BUBBLE_PADDING = 8;
	private static final int MIN_BUBBLE_SIZE = 44;
	private static final int HEAD_GAP = 34;
	private static final int BUBBLE_SIDE_OFFSET = 42;
	private static final int BUBBLE_UP_OFFSET = 32;
	private static final int FACING_PROBE_DISTANCE = 96;
	private static final int VIEWPORT_MARGIN = 8;
	private static final int WOBBLE_POINTS = 48;
	private static final double WOBBLE_AMOUNT = 1.6d;
	private static final double REFERENCE_CAMERA_SCALE = 1024.0d;
	private static final double ZOOM_SCALE_EXPONENT = 0.2d;

	private final Client client;
	private final NpcSnapConfig config;
	private final SkillingActivityTracker skillingActivityTracker;
	private final SpriteManager spriteManager;
	private final SkillIconManager skillIconManager;
	private final SkillingBubbleAnimation animation;
	private final Map<Skill, BufferedImage> skillImages = new EnumMap<>(Skill.class);
	private volatile boolean active;
	private final BillboardWorldViewVisibility worldViewVisibility;

	SkillingThoughtBubbleOverlay(
		Client client,
		NpcSnapConfig config,
		SkillingActivityTracker skillingActivityTracker,
		SpriteManager spriteManager,
		SkillIconManager skillIconManager
	)
	{
		this(client, config, skillingActivityTracker, spriteManager, skillIconManager, null);
	}

	@Inject
	SkillingThoughtBubbleOverlay(
		Client client,
		NpcSnapConfig config,
		SkillingActivityTracker skillingActivityTracker,
		SpriteManager spriteManager,
		SkillIconManager skillIconManager,
		BillboardWorldViewVisibility worldViewVisibility
	)
	{
		this.client = client;
		this.worldViewVisibility = worldViewVisibility;
		this.config = config;
		this.skillingActivityTracker = skillingActivityTracker;
		this.spriteManager = spriteManager;
		this.skillIconManager = skillIconManager;
		this.animation = new SkillingBubbleAnimation(skillingActivityTracker);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!active || !config.enableSkillingBubbles() || client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		if (player == null || (worldViewVisibility != null && !worldViewVisibility.isVisible(player)))
		{
			return null;
		}

		long nowMillis = System.currentTimeMillis();
		List<Skill> activeSkills = skillingActivityTracker.getRenderableSkills(nowMillis, FADE_OUT_MILLIS);
		if (activeSkills.isEmpty())
		{
			return null;
		}

		Point anchor = getBubbleAnchor(player);
		if (anchor == null)
		{
			return null;
		}

		float alpha = animation.bubbleAlpha(activeSkills, nowMillis);
		if (alpha <= 0.0f)
		{
			return null;
		}

		drawBubble(graphics, player, anchor, activeSkills, nowMillis, alpha);
		return null;
	}

	public void setActive(boolean active)
	{
		this.active = active;
	}

	private Point getBubbleAnchor(Player player)
	{
		LocalPoint localPoint = player.getLocalLocation();
		if (localPoint == null || player.getWorldView() == null)
		{
			return null;
		}

		int zOffset = player.getAnimationHeightOffset() + player.getModelHeight() + HEAD_GAP;
		return Perspective.localToCanvas(client, localPoint, player.getWorldView().getPlane(), zOffset);
	}

	void drawBubble(Graphics2D graphics, Player player, Point anchor, List<Skill> activeSkills, long nowMillis, float alpha)
	{
		// Follow zoom more gently than the sprite, keeping the projected head anchor
		// fixed. Scaling the graphics also scales icons, trails, strokes and wobble.
		AffineTransform bubbleTransform = bubbleTransform(anchor, client.getScale());
		Graphics2D bubbleGraphics = (Graphics2D) graphics.create();
		try
		{
			bubbleGraphics.transform(bubbleTransform);
			drawBubbleAtReferenceScale(bubbleGraphics, player, anchor, activeSkills, nowMillis, alpha, bubbleTransform);
		}
		finally
		{
			bubbleGraphics.dispose();
		}
	}

	static AffineTransform bubbleTransform(Point anchor, int cameraScale)
	{
		// Retain about 87% at zoom 512 and 79% at zoom 315.
		double scale = cameraScale > 0
			? Math.pow(cameraScale / REFERENCE_CAMERA_SCALE, ZOOM_SCALE_EXPONENT) : 1.0d;
		AffineTransform transform = AffineTransform.getTranslateInstance(anchor.getX(), anchor.getY());
		transform.scale(scale, scale);
		transform.translate(-anchor.getX(), -anchor.getY());
		return transform;
	}

	private void drawBubbleAtReferenceScale(Graphics2D graphics, Player player, Point anchor, List<Skill> activeSkills,
		long nowMillis, float alpha, AffineTransform bubbleTransform)
	{
		int iconCount = activeSkills.size();
		int iconsWidth = (iconCount * ICON_SIZE) + ((iconCount - 1) * ICON_GAP);
		int bubbleWidth = Math.max(MIN_BUBBLE_SIZE, iconsWidth + (BUBBLE_PADDING * 2));
		int bubbleHeight = MIN_BUBBLE_SIZE;
		double time = nowMillis / 1000.0d;
		float introProgress = animation.introProgress(activeSkills, nowMillis);
		BubblePlacement restingPlacement = chooseBubblePlacement(player, anchor, bubbleWidth, bubbleHeight, bubbleTransform);
		BubblePlacement animatedPlacement = interpolatePlacement(anchor, restingPlacement, bubbleWidth, bubbleHeight, introProgress);
		int bubbleX = animatedPlacement.x + (int) Math.round(Math.sin(time * 1.2d) * 1.2d);
		int bubbleY = animatedPlacement.y + (int) Math.round(Math.cos(time * 1.0d) * 0.8d);
		Shape bubbleShape = createWobblyOval(bubbleX, bubbleY, bubbleWidth, bubbleHeight, time);

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

		drawTrailingCircles(graphics, anchor.getX(), anchor.getY(), bubbleX + (bubbleWidth / 2), bubbleY + bubbleHeight, time);

		graphics.setColor(BUBBLE_FILL);
		graphics.fill(bubbleShape);
		graphics.setColor(BUBBLE_OUTLINE);
		graphics.draw(bubbleShape);

		int iconX = bubbleX + ((bubbleWidth - iconsWidth) / 2);
		int iconY = bubbleY + ((bubbleHeight - ICON_SIZE) / 2);
		for (Skill skill : activeSkills)
		{
			BufferedImage image = getSkillImage(skill);
			if (image != null)
			{
				drawContainedImage(graphics, image, iconX, iconY, ICON_SIZE, ICON_SIZE);
			}

			iconX += ICON_SIZE + ICON_GAP;
		}

	}

	private static void drawContainedImage(Graphics2D graphics, BufferedImage image, int x, int y, int maxWidth, int maxHeight)
	{
		int imageWidth = image.getWidth();
		int imageHeight = image.getHeight();
		if (imageWidth <= 0 || imageHeight <= 0)
		{
			return;
		}

		double scale = Math.min((double) maxWidth / imageWidth, (double) maxHeight / imageHeight);
		int drawWidth = Math.max(1, (int) Math.round(imageWidth * scale));
		int drawHeight = Math.max(1, (int) Math.round(imageHeight * scale));
		int drawX = x + ((maxWidth - drawWidth) / 2);
		int drawY = y + ((maxHeight - drawHeight) / 2);
		graphics.drawImage(image, drawX, drawY, drawWidth, drawHeight, null);
	}

	private BubblePlacement chooseBubblePlacement(Player player, Point anchor, int bubbleWidth, int bubbleHeight,
		AffineTransform bubbleTransform)
	{
		int facingSide = projectedFacingSide(player, anchor);
		int screenRoomSide = anchor.getX() < client.getViewportXOffset() + (client.getViewportWidth() / 2) ? 1 : -1;
		BubblePlacement left = candidatePlacement(anchor, bubbleWidth, bubbleHeight, -1);
		BubblePlacement right = candidatePlacement(anchor, bubbleWidth, bubbleHeight, 1);
		double leftScore = placementScore(left, -1, facingSide, screenRoomSide, player, bubbleTransform);
		double rightScore = placementScore(right, 1, facingSide, screenRoomSide, player, bubbleTransform);
		return rightScore > leftScore ? right : left;
	}

	private static BubblePlacement interpolatePlacement(Point anchor, BubblePlacement targetPlacement, int bubbleWidth, int bubbleHeight, float progress)
	{
		int startX = anchor.getX() - (bubbleWidth / 2);
		int startY = anchor.getY() - (bubbleHeight / 2);
		int x = Math.round(startX + ((targetPlacement.x - startX) * progress));
		int y = Math.round(startY + ((targetPlacement.y - startY) * progress));
		return new BubblePlacement(x, y, bubbleWidth, bubbleHeight);
	}

	private BubblePlacement candidatePlacement(Point anchor, int bubbleWidth, int bubbleHeight, int side)
	{
		int centerX = anchor.getX() + (side * (BUBBLE_SIDE_OFFSET + (bubbleWidth / 2)));
		int centerY = anchor.getY() - BUBBLE_UP_OFFSET - (bubbleHeight / 2);
		return new BubblePlacement(centerX - (bubbleWidth / 2), centerY - (bubbleHeight / 2), bubbleWidth, bubbleHeight);
	}

	private double placementScore(BubblePlacement placement, int side, int facingSide, int screenRoomSide, Player player,
		AffineTransform bubbleTransform)
	{
		double score = 0.0d;
		if (side == facingSide)
		{
			score += 75.0d;
		}
		if (side == screenRoomSide)
		{
			score += 35.0d;
		}

		Rectangle viewport = new Rectangle(
			client.getViewportXOffset() + VIEWPORT_MARGIN,
			client.getViewportYOffset() + VIEWPORT_MARGIN,
			Math.max(0, client.getViewportWidth() - (VIEWPORT_MARGIN * 2)),
			Math.max(0, client.getViewportHeight() - (VIEWPORT_MARGIN * 2))
		);
		Rectangle screenBounds = bubbleTransform.createTransformedShape(placement.bounds).getBounds();
		score -= overflowAmount(screenBounds, viewport) * 3.0d;

		Shape hull = player.getConvexHull();
		if (hull != null && hull.getBounds().intersects(screenBounds))
		{
			score -= 100.0d;
		}

		return score;
	}

	private int projectedFacingSide(Player player, Point anchor)
	{
		LocalPoint localPoint = player.getLocalLocation();
		if (localPoint == null || player.getWorldView() == null)
		{
			return 0;
		}

		int orientation = Math.floorMod(player.getCurrentOrientation(), 2048);
		int dx = Perspective.SINE[orientation] * FACING_PROBE_DISTANCE / 65536;
		int dy = Perspective.COSINE[orientation] * FACING_PROBE_DISTANCE / 65536;
		LocalPoint facingPoint = new LocalPoint(localPoint.getX() + dx, localPoint.getY() + dy, player.getWorldView());
		int zOffset = player.getAnimationHeightOffset() + player.getModelHeight() + HEAD_GAP;
		Point projectedFacing = Perspective.localToCanvas(client, facingPoint, player.getWorldView().getPlane(), zOffset);
		if (projectedFacing == null)
		{
			return 0;
		}

		int projectedDx = projectedFacing.getX() - anchor.getX();
		if (Math.abs(projectedDx) < 4)
		{
			return 0;
		}

		return projectedDx > 0 ? 1 : -1;
	}

	private static int overflowAmount(Rectangle inner, Rectangle outer)
	{
		int overflow = 0;
		overflow += Math.max(0, outer.x - inner.x);
		overflow += Math.max(0, outer.y - inner.y);
		overflow += Math.max(0, (inner.x + inner.width) - (outer.x + outer.width));
		overflow += Math.max(0, (inner.y + inner.height) - (outer.y + outer.height));
		return overflow;
	}

	private void drawTrailingCircles(Graphics2D graphics, int startX, int startY, int endX, int endY, double time)
	{
		drawTrailCircle(graphics, startX, startY, endX, endY, 0.28d, 7, time + 0.7d);
		drawTrailCircle(graphics, startX, startY, endX, endY, 0.52d, 10, time + 1.5d);
		drawTrailCircle(graphics, startX, startY, endX, endY, 0.76d, 14, time + 2.3d);
	}

	private static void drawTrailCircle(Graphics2D graphics, int startX, int startY, int endX, int endY, double progress, int size, double time)
	{
		double dx = endX - startX;
		double dy = endY - startY;
		double length = Math.max(1.0d, Math.sqrt((dx * dx) + (dy * dy)));
		double perpendicularX = -dy / length;
		double perpendicularY = dx / length;
		double offset = Math.sin((time * 1.4d) + (progress * 4.0d)) * 2.0d;
		int centerX = (int) Math.round(startX + (dx * progress) + (perpendicularX * offset));
		int centerY = (int) Math.round(startY + (dy * progress) + (perpendicularY * offset));
		drawCircle(graphics, centerX, centerY, size, time);
	}

	private static void drawCircle(Graphics2D graphics, int centerX, int centerY, int size, double time)
	{
		int radius = size / 2;
		Shape bubbleShape = createWobblyOval(centerX - radius, centerY - radius, size, size, time);
		graphics.setColor(BUBBLE_FILL);
		graphics.fill(bubbleShape);
		graphics.setColor(BUBBLE_OUTLINE);
		graphics.draw(bubbleShape);
	}

	private static Shape createWobblyOval(int x, int y, int width, int height, double time)
	{
		double centerX = x + (width / 2.0d);
		double centerY = y + (height / 2.0d);
		double radiusX = width / 2.0d;
		double radiusY = height / 2.0d;
		Path2D.Double path = new Path2D.Double();

		for (int i = 0; i <= WOBBLE_POINTS; i++)
		{
			double angle = (Math.PI * 2.0d * i) / WOBBLE_POINTS;
			double noise = (Math.sin((angle * 3.0d) + (time * 1.3d)) * 0.55d)
				+ (Math.sin((angle * 5.0d) - (time * 0.9d)) * 0.35d)
				+ (Math.cos((angle * 2.0d) + (time * 0.7d)) * 0.25d);
			double wobble = noise * WOBBLE_AMOUNT;
			double pointX = centerX + (Math.cos(angle) * (radiusX + wobble));
			double pointY = centerY + (Math.sin(angle) * (radiusY + wobble));

			if (i == 0)
			{
				path.moveTo(pointX, pointY);
			}
			else
			{
				path.lineTo(pointX, pointY);
			}
		}

		path.closePath();
		return path;
	}

	BufferedImage getSkillImage(Skill skill)
	{
		return skillImages.computeIfAbsent(skill, this::loadSkillImage);
	}

	private BufferedImage loadSkillImage(Skill skill)
	{
		BufferedImage gameSprite = spriteManager.getSprite(skillSpriteId(skill), 0);
		if (gameSprite != null)
		{
			return gameSprite;
		}

		return skillIconManager.getSkillImage(skill);
	}

	static int skillSpriteId(Skill skill)
	{
		switch (skill)
		{
			case AGILITY:
				return SpriteID.SKILL_AGILITY;
			case HERBLORE:
				return SpriteID.SKILL_HERBLORE;
			case THIEVING:
				return SpriteID.SKILL_THIEVING;
			case CRAFTING:
				return SpriteID.SKILL_CRAFTING;
			case FLETCHING:
				return SpriteID.SKILL_FLETCHING;
			case MINING:
				return SpriteID.SKILL_MINING;
			case SMITHING:
				return SpriteID.SKILL_SMITHING;
			case FISHING:
				return SpriteID.SKILL_FISHING;
			case COOKING:
				return SpriteID.SKILL_COOKING;
			case FIREMAKING:
				return SpriteID.SKILL_FIREMAKING;
			case WOODCUTTING:
				return SpriteID.SKILL_WOODCUTTING;
			case RUNECRAFT:
				return SpriteID.SKILL_RUNECRAFT;
			case FARMING:
				return SpriteID.SKILL_FARMING;
			case HUNTER:
				return SpriteID.SKILL_HUNTER;
			case CONSTRUCTION:
				return SpriteID.SKILL_CONSTRUCTION;
			case SAILING:
				return Staticons2.SAILING;
			default:
				return IconStat50x50._0 + skill.ordinal();
		}
	}

	private static final class BubblePlacement
	{
		private final int x;
		private final int y;
		private final Rectangle bounds;

		private BubblePlacement(int x, int y, int width, int height)
		{
			this.x = x;
			this.y = y;
			this.bounds = new Rectangle(x, y, width, height);
		}
	}
}

package com.kierenboal.npcsnap.occlusion;

import com.kierenboal.npcsnap.rendering.BillboardCanvasPoint;
import com.kierenboal.npcsnap.rendering.BillboardDepthCalculator;
import com.kierenboal.npcsnap.rendering.BillboardRenderRequest;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/** Clips submerged NPC pixels against their tile surface without changing sprite placement. */
public final class BillboardNpcSurfaceOcclusion
{
	private BillboardNpcSurfaceOcclusion()
	{
	}

	public static int firstOccludedRow(Client client, BillboardDepthCalculator depthCalculator, BillboardRenderRequest request)
	{
		if (request == null || !(request.renderable instanceof NPC) || request.model == null || request.localPoint == null)
		{
			return Integer.MAX_VALUE;
		}
		NPC npc = (NPC) request.renderable;
		WorldView view = npc.getWorldView();
		LocalPoint location = request.localPoint;
		// Nested actors stand on their own deck, not the top-level sea surface.
		if (view == null || !view.isTopLevel() || view != client.getTopLevelWorldView()
			|| view.getScene() == null || !view.contains(location))
		{
			return Integer.MAX_VALUE;
		}
		Model model = request.model;
		// Actor models normally already have cylinder bounds. This is cached by
		// the model and avoids another per-frame scan of its vertices.
		model.calculateBoundsCylinder();
		// Model Y and world height increase downwards, while verticalOffset is
		// positive upwards. Ordinary NPCs with feet at Y=0 do not need clipping.
		if (model.getBottomY() <= request.verticalOffset)
		{
			return Integer.MAX_VALUE;
		}

		Tile[][][] tiles = view.getScene().getTiles();
		int plane = request.plane;
		int x = location.getSceneX();
		int y = location.getSceneY();
		if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane] == null
			|| x < 0 || x >= tiles[plane].length || tiles[plane][x] == null
			|| y < 0 || y >= tiles[plane][x].length)
		{
			return Integer.MAX_VALUE;
		}
		Tile tile = tiles[plane][x][y];
		if (tile == null || (tile.getSceneTilePaint() == null && tile.getSceneTileModel() == null))
		{
			return Integer.MAX_VALUE;
		}
		// The surface stays at the tile height, independently of animation depth
		// and of the cached sprite's height, pitch, padding or position.
		BillboardCanvasPoint surface = depthCalculator.projectCanvasPoint(location, plane, 0);
		if (surface == null || !Double.isFinite(surface.y))
		{
			return Integer.MAX_VALUE;
		}
		return (int) Math.floor(surface.y + 0.5d);
	}
}

package com.kierenboal.npcsnap.occlusion;

/** Controls how partially transparent scenery affects billboard pixels. */
public enum BillboardOcclusionComposition
{
	TRANSPARENCY_AWARE("Transparency-aware"),
	HARD_CUTOUT("Hard cutout");

	private final String displayName;

	BillboardOcclusionComposition(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}

	public static BillboardOcclusionComposition normalize(BillboardOcclusionComposition composition)
	{
		return composition != null ? composition : TRANSPARENCY_AWARE;
	}
}

package com.kierenboal.npcsnap.occlusion;

import com.kierenboal.npcsnap.rendering.BillboardDepthSurface;
import com.kierenboal.npcsnap.rendering.BillboardRenderRequest;
import com.kierenboal.npcsnap.rendering.PreparedBillboardDraw;

import java.awt.image.DataBufferInt;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.Function;
import net.runelite.api.Point;

public final class BillboardOcclusionDebugSampler
{
	private static final int SAMPLE_LIMIT = 24;
	private static final double[] X_FRACTIONS = {0.25d, 0.5d, 0.75d};
	private static final double[] Y_FRACTIONS = {0.25d, 0.5d, 0.75d, 0.9d};

	private final BillboardOcclusionMask occlusionMask;
	private final Function<PreparedBillboardDraw, BillboardDepthSurface> depthSurfaceFactory;
	private final List<String> samples = new ArrayList<>();

	public BillboardOcclusionDebugSampler(
		BillboardOcclusionMask occlusionMask,
		Function<PreparedBillboardDraw, BillboardDepthSurface> depthSurfaceFactory)
	{
		this.occlusionMask = occlusionMask;
		this.depthSurfaceFactory = depthSurfaceFactory;
	}

	public void clear()
	{
		samples.clear();
	}

	public List<String> samples()
	{
		return samples;
	}

	public void collect(List<PreparedBillboardDraw> draws, boolean enabled)
	{
		if (!enabled || draws == null || draws.isEmpty())
		{
			return;
		}
		for (PreparedBillboardDraw draw : draws)
		{
			if (samples.size() >= SAMPLE_LIMIT)
			{
				return;
			}
			collect(draw);
		}
	}

	private void collect(PreparedBillboardDraw draw)
	{
		if (draw == null || draw.image == null || draw.bounds == null || draw.bounds.isEmpty()
			|| !(draw.image.getRaster().getDataBuffer() instanceof DataBufferInt))
		{
			return;
		}

		int sourceWidth = draw.image.getWidth();
		int sourceHeight = draw.image.getHeight();
		int[] sourcePixels = ((DataBufferInt) draw.image.getRaster().getDataBuffer()).getData();
		BillboardDepthSurface depthSurface = depthSurfaceFactory.apply(draw);
		for (double yFraction : Y_FRACTIONS)
		{
			for (double xFraction : X_FRACTIONS)
			{
				if (samples.size() >= SAMPLE_LIMIT)
				{
					return;
				}

				int sourceX = clampSample(sourceWidth, xFraction);
				int sourceY = clampSample(sourceHeight, yFraction);
				Point canvasPoint = draw.geometry != null
					? draw.geometry.canvasPoint(xFraction, yFraction)
					: new Point(
						draw.bounds.x + clampSample(draw.bounds.width, xFraction),
						draw.bounds.y + clampSample(draw.bounds.height, yFraction));
				int canvasX = canvasPoint.getX();
				int canvasY = canvasPoint.getY();
				int sourceAlpha = (sourcePixels[(sourceY * sourceWidth) + sourceX] >>> 24) & 0xFF;
				if (sourceAlpha == 0)
				{
					continue;
				}

				BillboardDepthSurface.DebugPoint point = depthSurface.debugPointAt(sourceX, sourceY, sourceWidth, sourceHeight, canvasY);
				float worldDepth = occlusionMask.depthAt(canvasX, canvasY, draw.occlusionIgnoredTileObject);
				float bias = occlusionMask.occlusionDepthBias();
				double margin = point.depth - (worldDepth + bias);
				boolean enabled = depthSurface.supportsWorldOcclusion();
				int transmittance = enabled
					? occlusionMask.transmittanceAt(canvasX, canvasY, point.depth, draw.occlusionIgnoredTileObject) : 255;
				samples.add(format(
					draw, canvasX, canvasY, sourceX, sourceY, sourceAlpha, point,
					worldDepth, occlusionMask.sourceAt(canvasX, canvasY, draw.occlusionIgnoredTileObject), bias, margin,
					transmittance, enabled));
			}
		}
	}

	private static int clampSample(int size, double fraction)
	{
		return Math.max(0, Math.min(size - 1, (int) Math.round((size - 1) * fraction)));
	}

	private static String format(
		PreparedBillboardDraw draw,
		int canvasX,
		int canvasY,
		int sourceX,
		int sourceY,
		int sourceAlpha,
		BillboardDepthSurface.DebugPoint point,
		float worldDepth,
		String worldSource,
		float bias,
		double worldDepthMargin,
		int transmittance,
		boolean worldOcclusionEnabled)
	{
		BillboardRenderRequest request = draw.request;
		String target = request != null && request.renderable != null ? request.renderable.getClass().getSimpleName() : "-";
		return String.format(
			Locale.ROOT,
			"{target=%s canvas=(%d,%d) src=(%d,%d) alpha=%d draw=%s sourceBounds=%s modelH=%d worldOcclusionEnabled=%s local=(%d,%d) h=%s xOff=%s zOff=%s billboardDepth=%s worldDepth=%s worldSource=%s bias=%s worldDepthMargin=%s transmittance=%d occluded=%s}",
			target, canvasX, canvasY, sourceX, sourceY, sourceAlpha, draw.bounds, draw.sourceBounds,
			draw.modelHeight, worldOcclusionEnabled,
			point.localX, point.localY, decimal(point.height), decimal(point.horizontalOffset),
			decimal(point.verticalOffset), decimal(point.depth), decimal(worldDepth),
			worldSource == null ? "-" : worldSource, decimal(bias), decimal(worldDepthMargin), transmittance, transmittance == 0);
	}

	private static String decimal(double value)
	{
		return Double.isFinite(value) ? String.format(Locale.ROOT, "%.2f", value) : "NaN";
	}
}

package com.kierenboal.npcsnap.occlusion;

import com.kierenboal.npcsnap.state.BillboardPerformanceMetrics;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Path2D;
import net.runelite.api.geometry.SimplePolygon;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import net.runelite.api.TileObject;

public final class BillboardOcclusionMask
{
	public enum CellResult
	{
		VISIBLE,
		OCCLUDED,
		REFINE
	}

	private final BillboardPerformanceMetrics performanceMetrics;

	public BillboardOcclusionMask()
	{
		this(new BillboardPerformanceMetrics());
	}

	public BillboardOcclusionMask(BillboardPerformanceMetrics performanceMetrics)
	{
		this.performanceMetrics = performanceMetrics;
	}

	private int[] heads = new int[0];
	private int[] next = new int[0];
	private int[] candidates = new int[0];
	private int[] coverageRows = new int[0];
	private int[] coverageOffsets = new int[0];
	private int[] candidateTransmittance = new int[0];
	private int[] candidateTintRgb = new int[0];
	private int coverageRowCount;
	private float[] candidateFar = new float[0];
	private float[] lower = new float[0];
	private float[] upper = new float[0];
	private boolean[] active = new boolean[0];
	private boolean[] fullRegion = new boolean[0];
	private boolean[] rowCoverage = new boolean[0];
	private List<Occluder> occluders = Collections.emptyList();
	private List<Rectangle> regions = Collections.emptyList();
	private Rectangle bounds;
	private int width;
	private int height;
	private int step;
	private boolean blocky;
	private BillboardOcclusionComposition composition = BillboardOcclusionComposition.TRANSPARENCY_AWARE;
	private int references;
	private int coveredCellCount;
	private long uniformDecisions;
	private long refinedPixels;
	private long candidateTests;
	private int[] compatibilityTransmittance = new int[0];

	public void prepare(List<Occluder> occluders, BillboardOcclusionQuality quality,
		int x, int y, int w, int h)
	{
		prepare(occluders, quality, BillboardOcclusionComposition.TRANSPARENCY_AWARE, x, y, w, h, null, null);
	}

	public void prepare(List<Occluder> occluders, BillboardOcclusionQuality quality,
		int x, int y, int w, int h, Rectangle interest)
	{
		prepare(occluders, quality, BillboardOcclusionComposition.TRANSPARENCY_AWARE, x, y, w, h, interest, null);
	}

	public void prepare(List<Occluder> occluders, BillboardOcclusionQuality quality,
		int x, int y, int w, int h, Rectangle interest, Collection<Rectangle> activeRegions)
	{
		prepare(occluders, quality, BillboardOcclusionComposition.TRANSPARENCY_AWARE, x, y, w, h, interest, activeRegions);
	}

	public void prepare(List<Occluder> occluders, BillboardOcclusionQuality quality, BillboardOcclusionComposition composition,
		int x, int y, int w, int h, Rectangle interest, Collection<Rectangle> activeRegions)
	{
		step = BillboardOcclusionQuality.normalize(quality).sampleStep();
		blocky = quality == BillboardOcclusionQuality.BLOCKY;
		this.composition = BillboardOcclusionComposition.normalize(composition);
		bounds = new Rectangle(x, y, Math.max(0, w), Math.max(0, h));
		if (interest != null)
		{
			bounds = bounds.intersection(interest);
		}
		references = coveredCellCount = coverageRowCount = 0;
		this.occluders = occluders == null ? Collections.emptyList() : occluders;
		if (step == 0 || bounds.isEmpty())
		{
			step = width = height = 0;
			this.occluders = Collections.emptyList();
			return;
		}
		regions = new ArrayList<>();
		if (activeRegions == null || activeRegions.isEmpty())
		{
			regions.add(bounds);
		}
		else
		{
			for (Rectangle region : activeRegions)
			{
				if (region != null && region.intersects(bounds))
				{
					regions.add(bounds.intersection(region));
				}
			}
		}
		try (BillboardPerformanceMetrics.Timer ignored = performanceMetrics.time("Initialize mask buffers"))
		{
			width = (bounds.width + step - 1) / step;
			height = (bounds.height + step - 1) / step;
			int size = width * height;
			if (heads.length < size)
			{
				heads = new int[size];
				lower = new float[size];
				upper = new float[size];
				active = new boolean[size];
				fullRegion = new boolean[size];
			}
			if (rowCoverage.length < height)
			{
				rowCoverage = new boolean[height];
			}
			Arrays.fill(heads, 0, size, -1);
			Arrays.fill(lower, 0, size, Float.POSITIVE_INFINITY);
			Arrays.fill(upper, 0, size, Float.POSITIVE_INFINITY);
			Arrays.fill(active, 0, size, false);
			Arrays.fill(fullRegion, 0, size, false);
			Arrays.fill(rowCoverage, 0, height, false);
		}
		try (BillboardPerformanceMetrics.Timer ignored = performanceMetrics.time("Mark active mask regions"))
		{
			// Mark each rectangle's cell span directly, rather than visiting every region per cell.
			for (Rectangle region : regions)
			{
				int left = (region.x - bounds.x) / step;
				int right = (region.x + region.width - 1 - bounds.x) / step;
				int top = (region.y - bounds.y) / step;
				int bottom = (region.y + region.height - 1 - bounds.y) / step;
				for (int cy = top; cy <= bottom; cy++)
				{
					int py = bounds.y + cy * step;
					int ch = Math.min(step, bounds.y + bounds.height - py);
					Arrays.fill(active, cy * width + left, cy * width + right + 1, true);
					for (int cx = left; cx <= right; cx++)
					{
						int px = bounds.x + cx * step;
						int cw = Math.min(step, bounds.x + bounds.width - px);
						fullRegion[cy * width + cx] |= region.contains(px, py, cw, ch);
					}
				}
			}
		}
		try (BillboardPerformanceMetrics.Timer ignored = performanceMetrics.time("Index occluder coverage"))
		{
			for (int id = 0; id < this.occluders.size(); id++)
			{
				Occluder o = this.occluders.get(id);
				if (o == null || o.bounds == null || !o.bounds.intersects(bounds))
				{
					continue;
				}
				int left = Math.max(0, Math.floorDiv(o.bounds.x - bounds.x, step));
				int top = Math.max(0, Math.floorDiv(o.bounds.y - bounds.y, step));
				int right = Math.min(width - 1, Math.floorDiv(o.bounds.x + o.bounds.width - 1 - bounds.x, step));
				int bottom = Math.min(height - 1, Math.floorDiv(o.bounds.y + o.bounds.height - 1 - bounds.y, step));
				for (int cy = top; cy <= bottom; cy++)
				{
					int py = bounds.y + cy * step;
					int ch = Math.min(step, bounds.y + bounds.height - py);
					float near = o.minimumDepth(py, ch);
					float far = blocky ? near : o.maximumDepth(py, ch);
					for (int cx = left; cx <= right; cx++)
					{
						int cell = cy * width + cx;
						if (!active[cell])
						{
							continue;
						}
						int px = bounds.x + cx * step;
						int cw = Math.min(step, bounds.x + bounds.width - px);
						// Blocky fills bounding-box cells without triangle or per-pixel coverage tests.
						int coverage = blocky ? 2 : o.coverage(px, py, cw, ch);
						if (coverage == 0)
						{
							continue;
						}
						if (references == next.length)
						{
							int capacity = Math.max(256, references + references / 2);
							next = Arrays.copyOf(next, capacity);
							candidates = Arrays.copyOf(candidates, capacity);
							candidateFar = Arrays.copyOf(candidateFar, capacity);
							coverageOffsets = Arrays.copyOf(coverageOffsets, capacity);
							candidateTransmittance = Arrays.copyOf(candidateTransmittance, capacity);
							candidateTintRgb = Arrays.copyOf(candidateTintRgb, capacity);
						}
						if (heads[cell] == -1)
						{
							coveredCellCount++;
							rowCoverage[cy] = true;
						}
						// Coverage bits retain crisp edges without repeating triangle membership
						// calculations for each overlapping billboard.
						if (coverage == 2)
						{
							// Negative offsets encode a constant full row, without allocating row data.
							coverageOffsets[references] = -((1 << cw) - 1);
						}
						else
						{
							int requiredRows = coverageRowCount + ch;
							if (coverageRows.length < requiredRows)
							{
								coverageRows = Arrays.copyOf(coverageRows,
									Math.max(requiredRows, Math.max(256, coverageRows.length * 2)));
							}
							coverageOffsets[references] = coverageRowCount;
							for (int row = 0; row < ch; row++)
							{
								coverageRows[coverageRowCount++] = o.coverageRow(px, py + row, cw);
							}
						}
						int reference = references++;
						candidateFar[reference] = far;
						candidates[reference] = id;
						candidateTransmittance[reference] = effectiveTransmittance(o);
						candidateTintRgb[reference] = o.tintRgb;
						next[reference] = heads[cell];
						heads[cell] = reference;
						lower[cell] = Math.min(lower[cell], near);
						if (coverage == 2 && candidateTransmittance[reference] == 0)
						{
							upper[cell] = Math.min(upper[cell], far);
						}
					}
				}
			}
		}

	}

	private int index(int x, int y)
	{
		if (step == 0 || !bounds.contains(x, y))
		{
			return -1;
		}
		int cell = ((y - bounds.y) / step) * width + (x - bounds.x) / step;
		if (!fullRegion[cell])
		{
			boolean inside = false;
			for (Rectangle region : regions)
			{
				inside |= region.contains(x, y);
			}
			if (!inside)
			{
				return -1;
			}
		}
		return cell;
	}

	public CellResult classifySample(int sampleX, int y, double depth)
	{
		return classifySample(sampleX, y, depth, null);
	}

	public CellResult classifySample(int sampleX, int y, double depth, TileObject ignoredTileObject)
	{
		if (step == 0 || !Double.isFinite(depth) || sampleX < 0 || sampleX >= width
			|| y < bounds.y || y >= bounds.y + bounds.height)
		{
			return CellResult.VISIBLE;
		}
		int cell = ((y - bounds.y) / step) * width + sampleX;
		// The aggregate cell bounds include every scene object. If this billboard is
		// replacing one of those objects, force the precise path whenever its own
		// geometry is present so the self-occluder can be skipped without affecting
		// other world objects in the same cell.
		if (ignoredTileObject != null && cellContainsOwner(cell, ignoredTileObject))
		{
			return CellResult.REFINE;
		}
		CellResult result = CellResult.REFINE;
		if (heads[cell] == -1 || lower[cell] + depthBias() >= depth)
		{
			result = CellResult.VISIBLE;
		}
		else if (fullRegion[cell] && upper[cell] + depthBias() < depth)
		{
			result = CellResult.OCCLUDED;
		}
		if (result != CellResult.REFINE)
		{
			uniformDecisions++;
		}
		return result;
	}

	private int coverageBits(int ref, int row)
	{
		int offset = coverageOffsets[ref];
		return offset < 0 ? -offset : coverageRows[offset + row];
	}

	private boolean cellContainsOwner(int cell, TileObject ignoredTileObject)
	{
		for (int ref = heads[cell]; ref != -1; ref = next[ref])
		{
			if (occluders.get(candidates[ref]).belongsTo(ignoredTileObject))
			{
				return true;
			}
		}
		return false;
	}

	private int effectiveTransmittance(Occluder occluder)
	{
		return composition == BillboardOcclusionComposition.HARD_CUTOUT ? 0 : occluder.transmittance;
	}

	/**
	 * Returns the amount of the billboard pixel which remains visible after all
	 * closer world geometry. 255 is fully visible and 0 is fully occluded.
	 */
	public int transmittanceAt(int x, int y, double depth)
	{
		return transmittanceAt(x, y, depth, null);
	}

	public int transmittanceAt(int x, int y, double depth, TileObject ignoredTileObject)
	{
		int cell = index(x, y);
		if (cell < 0 || !Double.isFinite(depth))
		{
			return 255;
		}
		if (!blocky)
		{
			refinedPixels++;
		}
		int localX = (x - bounds.x) % step;
		int localY = (y - bounds.y) % step;
		int bit = 1 << localX;
		int transmittance = 255;
		for (int ref = heads[cell]; ref != -1; ref = next[ref])
		{
			candidateTests++;
			if (occluders.get(candidates[ref]).belongsTo(ignoredTileObject))
			{
				continue;
			}
			if ((coverageBits(ref, localY) & bit) == 0)
			{
				continue;
			}
			if (candidateFar[ref] + depthBias() >= depth)
			{
				if (blocky)
				{
					continue;
				}
				float value = occluders.get(candidates[ref]).depthAt(x, y);
				if (!Float.isFinite(value) || value + depthBias() >= depth)
				{
					continue;
				}
			}
			transmittance = multiplyTransmittance(transmittance, candidateTransmittance[ref]);
			if (transmittance == 0)
			{
				return 0;
			}
		}
		return transmittance;
	}

	/**
	 * Applies closer translucent face colours over an opaque billboard pixel,
	 * preserving the billboard's original alpha rather than making it ghostly.
	 */
	public int tintPixel(int x, int y, double depth, int pixel)
	{
		return tintPixel(x, y, depth, pixel, null);
	}

	public int tintPixel(int x, int y, double depth, int pixel, TileObject ignoredTileObject)
	{
		int cell = index(x, y);
		if (cell < 0 || !Double.isFinite(depth))
		{
			return pixel;
		}
		int localX = (x - bounds.x) % step;
		int localY = (y - bounds.y) % step;
		int bit = 1 << localX;
		int tinted = pixel;
		for (int ref = heads[cell]; ref != -1; ref = next[ref])
		{
			if (occluders.get(candidates[ref]).belongsTo(ignoredTileObject))
			{
				continue;
			}
			if ((coverageBits(ref, localY) & bit) == 0 || candidateTransmittance[ref] == 0)
			{
				continue;
			}
			if (candidateFar[ref] + depthBias() >= depth)
			{
				if (blocky)
				{
					continue;
				}
				float value = occluders.get(candidates[ref]).depthAt(x, y);
				if (!Float.isFinite(value) || value + depthBias() >= depth)
				{
					continue;
				}
			}
			tinted = blendScreenTint(tinted, candidateTintRgb[ref], candidateTransmittance[ref]);
		}
		return tinted;
	}

	private static int blendScreenTint(int pixel, int tintRgb, int transmittance)
	{
		int foregroundOpacity = 255 - transmittance;
		int red = screenBlend((pixel >>> 16) & 0xFF, (tintRgb >>> 16) & 0xFF, transmittance, foregroundOpacity);
		int green = screenBlend((pixel >>> 8) & 0xFF, (tintRgb >>> 8) & 0xFF, transmittance, foregroundOpacity);
		int blue = screenBlend(pixel & 0xFF, tintRgb & 0xFF, transmittance, foregroundOpacity);
		return (pixel & 0xFF000000) | (red << 16) | (green << 8) | blue;
	}

	private static int screenBlend(int source, int tint, int transmittance, int foregroundOpacity)
	{
		int screened = 255 - (((255 - source) * (255 - tint) + 127) / 255);
		return (source * transmittance + screened * foregroundOpacity + 127) / 255;
	}

	private static int multiplyTransmittance(int left, int right)
	{
		return (left * right + 127) / 255;
	}

	public boolean isOccluded(int x, int y, double depth)
	{
		return isOccluded(x, y, depth, null);
	}

	public boolean isOccluded(int x, int y, double depth, TileObject ignoredTileObject)
	{
		return transmittanceAt(x, y, depth, ignoredTileObject) == 0;
	}

	/**
	 * Resolves a short ambiguous cell row once. Each bit is an independent pixel
	 * decision; sharing this bitset never spreads one sample across an edge.
	 */
	public int refinedSampleBits(int sampleX, int y, double depth)
	{
		return refinedSampleBits(sampleX, y, depth, null);
	}

	public int refinedSampleBits(int sampleX, int y, double depth, TileObject ignoredTileObject)
	{
		if (compatibilityTransmittance.length < Math.max(1, step))
		{
			compatibilityTransmittance = new int[Math.max(1, step)];
		}
		refinedSampleTransmittance(sampleX, y, depth, compatibilityTransmittance, ignoredTileObject);
		int bits = 0;
		for (int offset = 0; offset < step; offset++)
		{
			if (compatibilityTransmittance[offset] == 0)
			{
				bits |= 1 << offset;
			}
		}
		return bits;
	}

	/** Resolves every pixel in a coarse-cell row into reusable caller-owned storage. */
	public void refinedSampleTransmittance(int sampleX, int y, double depth, int[] output)
	{
		refinedSampleTransmittance(sampleX, y, depth, output, null);
	}

	public void refinedSampleTransmittance(int sampleX, int y, double depth, int[] output, TileObject ignoredTileObject)
	{
		if (output == null || output.length < step)
		{
			throw new IllegalArgumentException("Output must fit one occlusion sample row");
		}
		Arrays.fill(output, 0, step, 255);
		if (step == 0 || sampleX < 0 || sampleX >= width || !Double.isFinite(depth)
			|| y < bounds.y || y >= bounds.y + bounds.height)
		{
			return;
		}
		if (blocky)
		{
			int cell = ((y - bounds.y) / step) * width + sampleX;
			int value = 255;
			for (int reference = heads[cell]; reference != -1; reference = next[reference])
			{
				candidateTests++;
				if (occluders.get(candidates[reference]).belongsTo(ignoredTileObject))
				{
					continue;
				}
				if (candidateFar[reference] + depthBias() < depth)
				{
					value = multiplyTransmittance(value, candidateTransmittance[reference]);
				}
			}
			Arrays.fill(output, 0, step, value);
			// Keep clipping to actual sprite regions even though geometry edges are coarse.
			int startX = bounds.x + sampleX * step;
			if (!fullRegion[cell])
			{
				for (int offset = 0; offset < step; offset++)
				{
					if (index(startX + offset, y) < 0)
					{
						output[offset] = 255;
					}
				}
			}
			return;
		}
		int cell = ((y - bounds.y) / step) * width + sampleX;
		int localY = (y - bounds.y) % step;
		int x = bounds.x + sampleX * step;
		for (int ref = heads[cell]; ref != -1; ref = next[ref])
		{
			candidateTests++;
			if (occluders.get(candidates[ref]).belongsTo(ignoredTileObject))
			{
				continue;
			}
			int covered = coverageBits(ref, localY);
			Occluder o = occluders.get(candidates[ref]);
			while (covered != 0)
			{
				int offset = Integer.numberOfTrailingZeros(covered);
				if (!blocky)
		{
			refinedPixels++;
		}
				if (candidateFar[ref] + depthBias() < depth)
				{
					output[offset] = multiplyTransmittance(output[offset], candidateTransmittance[ref]);
				}
				else
				{
					float value = o.depthAt(x + offset, y);
					if (Float.isFinite(value) && value + depthBias() < depth)
					{
						output[offset] = multiplyTransmittance(output[offset], candidateTransmittance[ref]);
					}
				}
				covered &= covered - 1;
			}
		}
		if (!fullRegion[cell])
		{
			for (int offset = 0; offset < step; offset++)
			{
				if (index(x + offset, y) < 0)
				{
					output[offset] = 255;
				}
			}
		}
	}

	public int sampleOffset(int x)
	{
		return (x - bounds.x) % step;
	}
	public boolean isOccludedSample(int sampleX, int y, double depth)
	{
		return step > 0 && sampleX >= 0 && sampleX < width
			&& isOccluded(bounds.x + sampleX * step + step / 2, y, depth);
	}

	public float depthAt(int x, int y)
	{
		return depthAt(x, y, null);
	}

	public float depthAt(int x, int y, TileObject ignoredTileObject)
	{
		int cell = index(x, y);
		if (cell < 0)
		{
			return Float.NaN;
		}
		float value = Float.POSITIVE_INFINITY;
		for (int ref = heads[cell]; ref != -1; ref = next[ref])
		{
			Occluder occluder = occluders.get(candidates[ref]);
			if (occluder.belongsTo(ignoredTileObject))
			{
				continue;
			}
			float d = occluder.depthAt(x, y);
			if (Float.isFinite(d))
			{
				value = Math.min(value, d);
			}
		}
		return value;
	}

	public String sourceAt(int x, int y)
	{
		return sourceAt(x, y, null);
	}

	public String sourceAt(int x, int y, TileObject ignoredTileObject)
	{
		int cell = index(x, y);
		if (cell < 0)
		{
			return null;
		}
		float nearest = Float.POSITIVE_INFINITY;
		String source = null;
		int winner = Integer.MAX_VALUE;
		for (int ref = heads[cell]; ref != -1; ref = next[ref])
		{
			int id = candidates[ref];
			Occluder o = occluders.get(id);
			if (o.belongsTo(ignoredTileObject))
			{
				continue;
			}
			float d = o.depthAt(x, y);
			if (Float.isFinite(d) && (d < nearest || (d == nearest && id < winner)))
			{
				nearest = d;
				winner = id;
				source = o.source;
			}
		}
		return source;
	}

	public boolean hasCoverageAt(int y)
	{
		return step > 0 && y >= bounds.y && y < bounds.y + bounds.height
			&& rowCoverage[(y - bounds.y) / step];
	}

	public int sampleX(int x)
	{
		return step > 0 && x >= bounds.x && x < bounds.x + bounds.width ? (x - bounds.x) / step : -1;
	}

	public int sampleStep()
	{
		return step;
	}
	public int coveredCellCount()
	{
		return coveredCellCount;
	}
	private float depthBias()
	{
		return Math.max(8f, step * 2f);
	}
	public float occlusionDepthBias()
	{
		return depthBias();
	}

	// Read by the collector's existing throttled debug logger, after preceding frames blit.
	public String drainDebugStats()
	{
		String result = "candidates=" + references + " uniform=" + uniformDecisions
			+ " refinedPixels=" + refinedPixels + " candidateTests=" + candidateTests;
		uniformDecisions = refinedPixels = candidateTests = 0;
		return result;
	}

	static Shape filledFallbackShape(Shape shape)
	{
		// SimplePolygon's rectangle intersection tests boundary crossings only.
		// Use Java2D's filled-area semantics for both contained and crossing cells.
		return shape instanceof SimplePolygon ? new Path2D.Double(shape) : shape;
	}
	public static final class Occluder
	{
		private final Shape shape;
		private final float depth;
		private final boolean triangle;
		private final boolean vertical;
		private final int x0;
		private final int y0;
		private final float depth0;
		private final int x1;
		private final int y1;
		private final float depth1;
		private final int x2;
		private final int y2;
		private final float depth2;
		private final double barycentricDenominator;
		private final double ax;
		private final double ay;
		private final double bx;
		private final double by;
		private final Rectangle bounds;
		private final String source;
		private final int transmittance;
		private final int tintRgb;
		private final TileObject owner;

		Occluder(Shape shape, float depth)
		{
			this(shape, depth, null);
		}

		Occluder(Shape shape, float depth, String source)
		{
			this(shape, depth, source, 0);
		}

		Occluder(Shape shape, float depth, String source, int transmittance)
		{
			this(shape, depth, source, transmittance, 0xFFFFFF);
		}

		Occluder(Shape shape, float depth, String source, int transmittance, int tintRgb)
		{
			this(shape, depth, source, transmittance, tintRgb, null);
		}

		Occluder(Shape shape, float depth, String source, int transmittance, int tintRgb, TileObject owner)
		{
			this.shape = filledFallbackShape(shape);
			this.depth = depth;
			triangle = false;
			vertical = false;
			x0 = 0;
			y0 = 0;
			depth0 = Float.NaN;
			x1 = 0;
			y1 = 0;
			depth1 = Float.NaN;
			x2 = 0;
			y2 = 0;
			depth2 = Float.NaN;
			barycentricDenominator = Double.NaN;
			ax = ay = bx = by = 0d;
			bounds = shape != null ? shape.getBounds() : null;
			this.source = source;
			this.transmittance = clampTransmittance(transmittance);
			this.tintRgb = tintRgb & 0xFFFFFF;
			this.owner = owner;
		}

		static Occluder triangle(int x0, int y0, float depth0, int x1, int y1, float depth1, int x2, int y2, float depth2)
		{
			return triangle(x0, y0, depth0, x1, y1, depth1, x2, y2, depth2, null);
		}

		static Occluder triangle(int x0, int y0, float depth0, int x1, int y1, float depth1, int x2, int y2, float depth2, String source)
		{
			return triangle(x0, y0, depth0, x1, y1, depth1, x2, y2, depth2, source, 0);
		}

		static Occluder triangle(int x0, int y0, float depth0, int x1, int y1, float depth1, int x2, int y2, float depth2, String source, int transmittance)
		{
			return triangle(x0, y0, depth0, x1, y1, depth1, x2, y2, depth2, source, transmittance, 0xFFFFFF);
		}

		static Occluder triangle(int x0, int y0, float depth0, int x1, int y1, float depth1, int x2, int y2, float depth2, String source, int transmittance, int tintRgb)
		{
			return triangle(x0, y0, depth0, x1, y1, depth1, x2, y2, depth2, source, transmittance, tintRgb, null);
		}

		static Occluder triangle(int x0, int y0, float depth0, int x1, int y1, float depth1, int x2, int y2, float depth2,
			String source, int transmittance, int tintRgb, TileObject owner)
		{
			if (!Float.isFinite(depth0) || !Float.isFinite(depth1) || !Float.isFinite(depth2))
			{
				return null;
			}

			return new Occluder(x0, y0, depth0, x1, y1, depth1, x2, y2, depth2, source, transmittance, tintRgb, owner);
		}

		private Occluder(int x0, int y0, float depth0, int x1, int y1, float depth1, int x2, int y2, float depth2,
			String source, int transmittance, int tintRgb, TileObject owner)
		{
			shape = null;
			depth = Float.NaN;
			triangle = true;
			vertical = false;
			this.x0 = x0;
			this.y0 = y0;
			this.depth0 = depth0;
			this.x1 = x1;
			this.y1 = y1;
			this.depth1 = depth1;
			this.x2 = x2;
			this.y2 = y2;
			this.depth2 = depth2;
			barycentricDenominator = ((y1 - y2) * (double) (x0 - x2))
				+ ((x2 - x1) * (double) (y0 - y2));
			ax = (y1 - y2) / barycentricDenominator;
			ay = (x2 - x1) / barycentricDenominator;
			bx = (y2 - y0) / barycentricDenominator;
			by = (x0 - x2) / barycentricDenominator;
			int minX = Math.min(x0, Math.min(x1, x2));
			int minY = Math.min(y0, Math.min(y1, y2));
			int maxX = Math.max(x0, Math.max(x1, x2));
			int maxY = Math.max(y0, Math.max(y1, y2));
			bounds = new Rectangle(minX, minY, Math.max(1, (maxX - minX) + 1), Math.max(1, (maxY - minY) + 1));
			this.source = source;
			this.transmittance = clampTransmittance(transmittance);
			this.tintRgb = tintRgb & 0xFFFFFF;
			this.owner = owner;
		}

		static Occluder vertical(Shape shape, int baseY, float baseDepth, int topY, float topDepth, String source)
		{
			return vertical(shape, baseY, baseDepth, topY, topDepth, source, null);
		}

		static Occluder vertical(Shape shape, int baseY, float baseDepth, int topY, float topDepth, String source, TileObject owner)
		{
			if (shape == null || shape.getBounds().isEmpty() || baseY == topY
				|| !Float.isFinite(baseDepth) || !Float.isFinite(topDepth) || baseDepth <= 0.0f || topDepth <= 0.0f)
			{
				return null;
			}

			return new Occluder(shape, baseY, baseDepth, topY, topDepth, source, owner);
		}

		private Occluder(Shape shape, int baseY, float baseDepth, int topY, float topDepth, String source, TileObject owner)
		{
			this.shape = filledFallbackShape(shape);
			depth = Float.NaN;
			triangle = false;
			vertical = true;
			x0 = 0;
			y0 = baseY;
			depth0 = baseDepth;
			x1 = 0;
			y1 = topY;
			depth1 = topDepth;
			x2 = 0;
			y2 = 0;
			depth2 = Float.NaN;
			barycentricDenominator = Double.NaN;
			ax = ay = bx = by = 0d;
			bounds = shape.getBounds();
			this.source = source;
			this.transmittance = 0;
			this.tintRgb = 0xFFFFFF;
			this.owner = owner;
		}

		private boolean belongsTo(TileObject tileObject)
		{
			return tileObject != null && owner == tileObject;
		}

		private static int clampTransmittance(int value)
		{
			return Math.max(0, Math.min(255, value));
		}

		// 0: outside, 1: uncertain/partial, 2: every integer pixel is covered.
		private int coverage(int x, int y, int w, int h)
		{
			if (!triangle)
			{
				if (shape == null || !shape.intersects(x, y, w, h))
				{
					return 0;
				}
				return shape.contains(x, y, w, h) ? 2 : 1;
			}
			if (Math.abs(barycentricDenominator) <= 1.0e-6d)
			{
				return 0;
			}
			double a = ax * (x - x2) + ay * (y - y2);
			double b = bx * (x - x2) + by * (y - y2);
			int ea = edgeCoverage(a, ax * (w - 1), ay * (h - 1));
			int eb = edgeCoverage(b, bx * (w - 1), by * (h - 1));
			int ec = edgeCoverage(1d - a - b, (-ax - bx) * (w - 1), (-ay - by) * (h - 1));
			return ea == 0 || eb == 0 || ec == 0 ? 0 : Math.min(ea, Math.min(eb, ec));
		}

		private int coverageRow(int x, int y, int w)
		{
			int bits = 0;
			for (int dx = 0; dx < w; dx++)
			{
				if (triangle)
				{
					double a = ax * (x + dx - x2) + ay * (y - y2);
					double b = bx * (x + dx - x2) + by * (y - y2);
					if (a >= -1.0e-6d && b >= -1.0e-6d && 1d - a - b >= -1.0e-6d)
					{
						bits |= 1 << dx;
					}
				}
				else if (shape.contains(x + dx, y))
				{
					bits |= 1 << dx;
				}
			}
			return bits;
		}
		private static int edgeCoverage(double origin, double dx, double dy)
		{
			// Leave a numerical guard around the exact point-in-triangle tolerance.
			double min = origin + Math.min(0d, dx) + Math.min(0d, dy);
			double max = origin + Math.max(0d, dx) + Math.max(0d, dy);
			return max < -1.0001e-6d ? 0 : min >= -0.9999e-6d ? 2 : 1;
		}

		private float minimumDepth(int y, int h)
		{
			if (vertical)
			{
				float a = verticalDepth(y);
				float b = verticalDepth(y + h - 1);
				return Float.isFinite(a) && Float.isFinite(b) ? Math.min(a, b) : Float.NEGATIVE_INFINITY;
			}
			if (!triangle)
			{
				return Float.isFinite(depth) ? depth : Float.NEGATIVE_INFINITY;
			}
			float min = Math.min(depth0, Math.min(depth1, depth2));
			float max = Math.max(depth0, Math.max(depth1, depth2));
			return Math.nextDown((float) (min - 3.0e-6d * ((double) max - min)));
		}

		private float maximumDepth(int y, int h)
		{
			if (vertical)
			{
				float a = verticalDepth(y);
				float b = verticalDepth(y + h - 1);
				return Float.isFinite(a) && Float.isFinite(b) ? Math.max(a, b) : Float.POSITIVE_INFINITY;
			}
			if (!triangle)
			{
				return Float.isFinite(depth) ? depth : Float.POSITIVE_INFINITY;
			}
			float min = Math.min(depth0, Math.min(depth1, depth2));
			float max = Math.max(depth0, Math.max(depth1, depth2));
			return Math.nextUp((float) (max + 3.0e-6d * ((double) max - min)));
		}

		private float verticalDepth(int y)
		{
			// Reciprocal camera depth is linear along the projected vertical anchor.
			double t = (y - y0) / (double) (y1 - y0);
			double reciprocalDepth = ((1.0d - t) / depth0) + (t / depth1);
			if (!Double.isFinite(reciprocalDepth) || reciprocalDepth <= 0d)
			{
				return Float.NaN;
			}
			return (float) (1d / reciprocalDepth);
		}
		private float depthAt(int canvasX, int canvasY)
		{
			if (vertical)
			{
				return shape.contains(canvasX, canvasY) ? verticalDepth(canvasY) : Float.NaN;
			}
			if (!triangle)
			{
				return shape != null && shape.contains(canvasX, canvasY) ? depth : Float.NaN;
			}

			if (Math.abs(barycentricDenominator) <= 1.0e-6d)
			{
				return Float.NaN;
			}

			double a = ax * (canvasX - x2) + ay * (canvasY - y2);
			double b = bx * (canvasX - x2) + by * (canvasY - y2);
			double c = 1.0d - a - b;
			if (a < -1.0e-6d || b < -1.0e-6d || c < -1.0e-6d)
			{
				return Float.NaN;
			}

			double interpolated = (a * depth0) + (b * depth1) + (c * depth2);
			return Double.isFinite(interpolated) ? (float) interpolated : Float.NaN;
		}
	}

}

