package com.kierenboal.npcsnap.occlusion;

import net.runelite.api.Perspective;

/** Applies the same 0..2047 model orientation used by RuneLite projection. */
public final class SceneryModelRotation
{
	private SceneryModelRotation()
	{
	}

	public static float x(int orientation, float x, float z)
	{
		int angle = orientation & 2047;
		return x * Perspective.COSINEF[angle] + z * Perspective.SINEF[angle];
	}

	public static float z(int orientation, float x, float z)
	{
		int angle = orientation & 2047;
		return z * Perspective.COSINEF[angle] - x * Perspective.SINEF[angle];
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Rectangle;
import net.runelite.api.AABB;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/** Geometry of the pose captured in a sprite, independent of its outline padding. */
public final class ActorBillboardBounds
{
	private final Rectangle modelBounds;
	private final Rectangle hullBounds;

	public ActorBillboardBounds(Rectangle modelBounds, Rectangle hullBounds)
	{
		this.modelBounds = usableCopy(modelBounds);
		this.hullBounds = usableCopy(hullBounds);
	}

	public boolean exceedsResizeThreshold(ActorBillboardBounds displayed, int percent)
	{
		if (displayed == null || percent <= 0)
		{
			return false;
		}
		double threshold = Math.min(100, percent) / 100.0d;
		return resized(modelBounds, displayed.modelBounds, threshold)
			|| resized(hullBounds, displayed.hullBounds, threshold);
	}

	private static boolean resized(Rectangle current, Rectangle displayed, double threshold)
	{
		return current != null && displayed != null
			&& (Math.abs((double) current.width - displayed.width) / displayed.width > threshold
				|| Math.abs((double) current.height - displayed.height) / displayed.height > threshold);
	}

	private static Rectangle usableCopy(Rectangle bounds)
	{
		return bounds == null || bounds.width <= 0 || bounds.height <= 0 ? null : new Rectangle(bounds);
	}

	/** Reuses projection buffers; only called on the client thread. */
	public static final class Sampler
	{
		private final Client client;
		private int[] canvasX = new int[0];
		private int[] canvasY = new int[0];
		private final float[] cornersX = new float[8];
		private final float[] cornersY = new float[8];
		private final float[] cornersZ = new float[8];

		public Sampler(Client client)
		{
			this.client = client;
		}

		public ActorBillboardBounds sample(Actor actor, Model model)
		{
			return sampleForResize(actor, model, null, 0);
		}

		public ActorBillboardBounds sampleForResize(Actor actor, Model model, ActorBillboardBounds displayed, int percent)
		{
			LocalPoint location = actor.getLocalLocation();
			WorldView view = actor.getWorldView();
			if (model == null || location == null || view == null || !view.contains(location))
			{
				return null;
			}
			int orientation = Math.floorMod(actor.getCurrentOrientation(), BillboardAngleUtils.BILLBOARD_FULL_CIRCLE);
			int height = Perspective.getFootprintTileHeight(client, location, view.getPlane(), actor.getFootprintSize())
				- actor.getAnimationHeightOffset();
			Rectangle box = null;
			AABB aabb = model.getAABB(orientation);
			if (aabb != null)
			{
				for (int i = 0; i < 8; i++)
				{
					cornersX[i] = aabb.getCenterX() + ((i & 1) == 0 ? -aabb.getExtremeX() : aabb.getExtremeX());
					cornersY[i] = aabb.getCenterZ() + ((i & 2) == 0 ? -aabb.getExtremeZ() : aabb.getExtremeZ());
					cornersZ[i] = aabb.getCenterY() + ((i & 4) == 0 ? -aabb.getExtremeY() : aabb.getExtremeY());
				}
				ensureCapacity(8);
				// getAABB already applies orientation, so do not rotate its corners twice.
				Perspective.modelToCanvas(client, view, 8, location.getX(), location.getY(), height,
					0, cornersX, cornersY, cornersZ, canvasX, canvasY);
				box = projectedBounds(8);
			}
			// Eight corners can already prove a resize. Only project the complete
			// vertex set when the model box has not triggered it independently.
			if (displayed != null && percent > 0 && resized(box, displayed.modelBounds, Math.min(100, percent) / 100.0d))
			{
				return new ActorBillboardBounds(box, null);
			}
			Rectangle hull = null;
			float[] x = model.getVerticesX();
			float[] y = model.getVerticesY();
			float[] z = model.getVerticesZ();
			if (x != null && y != null && z != null)
			{
				int count = Math.min(model.getVerticesCount(), Math.min(x.length, Math.min(y.length, z.length)));
				if (count > 0)
				{
					ensureCapacity(count);
					Perspective.modelToCanvas(client, view, count, location.getX(), location.getY(), height,
						orientation, x, z, y, canvasX, canvasY);
					// The bounds of a convex hull equal the extrema of its projected vertices.
					hull = projectedBounds(count);
				}
			}
			return new ActorBillboardBounds(box, hull);
		}

		private void ensureCapacity(int count)
		{
			if (canvasX.length < count)
			{
				canvasX = new int[count];
				canvasY = new int[count];
			}
		}

		private Rectangle projectedBounds(int count)
		{
			int minX = Integer.MAX_VALUE;
			int minY = Integer.MAX_VALUE;
			int maxX = Integer.MIN_VALUE;
			int maxY = Integer.MIN_VALUE;
			for (int i = 0; i < count; i++)
			{
				if (canvasX[i] == Integer.MIN_VALUE || canvasY[i] == Integer.MIN_VALUE)
				{
					continue;
				}
				minX = Math.min(minX, canvasX[i]);
				minY = Math.min(minY, canvasY[i]);
				maxX = Math.max(maxX, canvasX[i]);
				maxY = Math.max(maxY, canvasY[i]);
			}
			return maxX > minX && maxY > minY ? new Rectangle(minX, minY, maxX - minX, maxY - minY) : null;
		}
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.coords.LocalPoint;

/** Projects the captured sprite's model-space bounds onto a camera-facing world plane. */
public final class ActorWorldPlane
{
	private ActorWorldPlane()
	{
	}

	/** Horizontal camera-facing right axis, using the same camera conventions as projection. */
	public static double viewingBearing(Client client, LocalPoint location)
	{
		double cameraX = client.isGpu() ? client.getCameraFpX() : client.getCameraX();
		double cameraY = client.isGpu() ? client.getCameraFpY() : client.getCameraY();
		double dx = location.getX() - cameraX, dy = location.getY() - cameraY;
		if (Math.hypot(dx, dy) > 1.0d)
		{
			return Math.atan2(-dx, dy);
		}
		return client.isGpu() ? client.getCameraFpYaw()
			: client.getCameraYaw() * (2.0d * Math.PI / BillboardAngleUtils.CAMERA_FULL_CIRCLE);
	}

	public static BillboardDrawGeometry project(BillboardDepthCalculator calculator, LocalPoint location, double baseWorldZ,
		double viewingBearing, Rectangle image, Rectangle content)
	{
		if (location == null || image == null || image.isEmpty() || content == null || content.isEmpty()
			|| !Double.isFinite(baseWorldZ) || !Double.isFinite(viewingBearing))
		{
			return null;
		}
		// Sprite selection has already applied actor rotation and snapping. The
		// sheet itself faces the camera on yaw, independently of that captured view.
		double bearing = viewingBearing;
		double rightX = Math.cos(bearing), rightY = Math.sin(bearing);
		// Bounds are in captured model units, not texture pixels. Preserve both
		// dimensions and their offset from model zero, including outline padding.
		double left = image.x, right = image.getMaxX();
		double top = image.y, bottom = image.getMaxY();
		return BillboardDrawGeometry.projected(BillboardProjectedQuad.create(
			corner(calculator, location, baseWorldZ, rightX, rightY, left, top),
			corner(calculator, location, baseWorldZ, rightX, rightY, right, top),
			corner(calculator, location, baseWorldZ, rightX, rightY, right, bottom),
			corner(calculator, location, baseWorldZ, rightX, rightY, left, bottom), image, content));
	}

	private static BillboardCanvasPoint corner(BillboardDepthCalculator calculator, LocalPoint location,
		double baseWorldZ, double rightX, double rightY, double horizontal, double vertical)
	{
		return calculator.projectCanvasPoint(location.getX() + rightX * horizontal,
			location.getY() + rightY * horizontal, baseWorldZ + vertical);
	}
}

package com.kierenboal.npcsnap.rendering;

import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Actor;
import net.runelite.api.Client;

@Singleton
@Slf4j
public class AnimationFrameSnapper
{
	private static final int GAME_FRAMES_PER_SECOND = 50;
	private final Client client;
	private final Map<Integer, AnimationMetadata> animationFrameCache = new HashMap<>();
	private final Map<Actor, ActorAnimationState> actorAnimationStates = new IdentityHashMap<>();

	@Inject
	public AnimationFrameSnapper(Client client)
	{
		this.client = client;
	}

	public int snapAnimationFrame(int animationId, int frame, int visibleFrameCount)
	{
		return snapAnimationFrame(animationId, frame, visibleFrameCount, true);
	}

	public int snapAnimationFrame(int animationId, int frame, int visibleFrameCount, boolean deterministicLooping)
	{
		if (animationId < 0 || frame < 0 || visibleFrameCount <= 0)
		{
			return frame;
		}

		AnimationMetadata metadata = animationFrameCache.computeIfAbsent(animationId, this::loadAnimationMetadata);
		boolean looped = !deterministicLooping && frame >= metadata.totalFrames && hasPartialLoop(metadata);
		return snap(metadata, frame, visibleFrameCount, deterministicLooping, looped, false);
	}

	public int snapActorAnimationFrame(
		Actor actor,
		int animationId,
		int frame,
		int visibleFrameCount,
		boolean deterministicLooping,
		boolean poseAnimation)
	{
		return snapActorAnimationFrame(actor, animationId, frame, visibleFrameCount,
			deterministicLooping, poseAnimation, false);
	}

	public int snapActorAnimationFrame(
		Actor actor,
		int animationId,
		int frame,
		int visibleFrameCount,
		boolean deterministicLooping,
		boolean poseAnimation,
		boolean logAnimationData)
	{
		if (actor == null)
		{
			return frame;
		}

		ActorAnimationState state = actorAnimationStates.computeIfAbsent(actor, ignored -> new ActorAnimationState());
		AnimationTrack track = poseAnimation ? state.pose : state.action;
		if (animationId < 0 || frame < 0)
		{
			// The same emote can be played again after it has finished. Do not carry the
			// previous run's loop offset into the new animation.
			track.reset();
			if (logAnimationData)
			{
				log.debug("Billboard animation track reset: actor={}, track={}, animation={}, frame={}",
					actor, trackName(poseAnimation), animationId, frame);
			}
			return frame;
		}

		if (visibleFrameCount <= 0)
		{
			return frame;
		}

		AnimationMetadata metadata = animationFrameCache.computeIfAbsent(animationId, this::loadAnimationMetadata);
		boolean looped = hasPartialLoop(metadata)
			&& track.animationId == animationId
			&& frame < track.lastFrame
			&& track.lastFrame >= loopStart(metadata);

		if (track.animationId != animationId)
		{
			track.start(animationId, frame);
		}
		else if (frame < track.lastFrame)
		{
			// A real loop/restart may return to a lower frame; a resize redraw may not.
			track.renderedFrameFloor = -1;
		}

		long accumulatedFrame = hasPartialLoop(metadata) ? accumulateActorFrame(track, metadata, frame) : frame;
		if (!deterministicLooping && hasPartialLoop(metadata))
		{
			long scheduledFrame = accumulatedFrame / frameInterval(visibleFrameCount) * frameInterval(visibleFrameCount);
			int renderedFrame = scheduledFrame <= track.renderedAccumulatedFrameFloor
				? track.renderedAccumulatedFrame : animationFrameAt(metadata, scheduledFrame);
			if (logAnimationData)
			{
				log.debug("Billboard animation: actor={}, track={}, animation={}, rawFrame={}, totalFrames={}, frameStep={}, loopStart={}, detectedLoopReset={}, deterministic={}, frameInterval={}, accumulatedFrame={}, scheduledFrame={}, renderedFrame={}",
					actor, trackName(poseAnimation), animationId, frame, metadata.totalFrames, metadata.frameStep,
					loopStart(metadata), looped, false, frameInterval(visibleFrameCount), accumulatedFrame, scheduledFrame, renderedFrame);
			}
			track.lastFrame = frame;
			return renderedFrame;
		}

		int normalizedFrame = snap(metadata, frame, visibleFrameCount, deterministicLooping, false, false);
		normalizedFrame = Math.max(normalizedFrame, track.renderedFrameFloor);
		if (logAnimationData)
		{
			log.debug("Billboard animation: actor={}, track={}, animation={}, rawFrame={}, totalFrames={}, frameStep={}, loopStart={}, detectedLoopReset={}, deterministic={}, visibleFrames={}, renderedFrame={}",
				actor, trackName(poseAnimation), animationId, frame, metadata.totalFrames, metadata.frameStep,
				loopStart(metadata), looped, deterministicLooping, visibleFrameCount, normalizedFrame);
		}
		track.lastFrame = frame;
		return normalizedFrame;
	}

	/** Called only after a resize-forced sprite has successfully captured the live pose. */
	public void commitActorLivePose(Actor actor, int animationId, int animationFrame, int poseAnimationId, int poseFrame)
	{
		ActorAnimationState state = actorAnimationStates.get(actor);
		if (state != null)
		{
			commitLiveTrack(state.action, animationId, animationFrame);
			commitLiveTrack(state.pose, poseAnimationId, poseFrame);
		}
	}

	private void commitLiveTrack(AnimationTrack track, int animationId, int frame)
	{
		if (animationId >= 0 && frame >= 0 && track.animationId == animationId && track.lastFrame == frame)
		{
			track.renderedFrameFloor = frame;
			track.renderedAccumulatedFrameFloor = track.accumulatedFrame;
			track.renderedAccumulatedFrame = frame;
		}
	}

	public int snapFrame(Animation animation, int frame, boolean enabled, int visibleFrameCount)
	{
		return snapFrame(animation, frame, enabled, visibleFrameCount, true);
	}

	public int snapFrame(Animation animation, int frame, boolean enabled, int visibleFrameCount, boolean deterministicLooping)
	{
		if (!enabled || animation == null || frame < 0 || visibleFrameCount <= 0)
		{
			return frame;
		}

		int totalFrames = animation.getNumFrames();
		if (totalFrames <= 1)
		{
			return frame;
		}

		AnimationMetadata metadata = new AnimationMetadata(totalFrames, animation.getFrameStep());
		boolean looped = !deterministicLooping && frame >= totalFrames && hasPartialLoop(metadata);
		return snap(metadata, frame, visibleFrameCount, deterministicLooping, looped, false);
	}

	public void clear()
	{
		animationFrameCache.clear();
		actorAnimationStates.clear();
	}

	private int snap(
		AnimationMetadata metadata,
		int frame,
		int visibleFrameCount,
		boolean deterministicLooping,
		boolean loopReferenceActive,
		boolean loopSourceStartsAtZero)
	{
		if (metadata.totalFrames <= 1)
		{
			return frame;
		}

		int normalizedFrame = normalizeFrame(frame, metadata.totalFrames, metadata.frameStep,
			deterministicLooping, loopSourceStartsAtZero);
		if (!deterministicLooping && loopReferenceActive && hasPartialLoop(metadata))
		{
			return snapRange(normalizedFrame, loopStart(metadata), metadata.frameStep, visibleFrameCount);
		}

		return snapRange(normalizedFrame, 0, metadata.totalFrames, visibleFrameCount);
	}

	private int snapRange(int frame, int rangeStart, int rangeLength, int visibleFrameCount)
	{
		if (visibleFrameCount >= rangeLength)
		{
			return Math.min(frame, rangeStart + rangeLength - 1);
		}

		int clampedFrame = Math.max(rangeStart, Math.min(frame, rangeStart + rangeLength - 1));
		int snappedBucket = (clampedFrame - rangeStart) * visibleFrameCount / rangeLength;
		return rangeStart + snappedBucket * rangeLength / visibleFrameCount;
	}

	private long accumulateActorFrame(AnimationTrack track, AnimationMetadata metadata, int frame)
	{
		if (track.lastFrame >= 0)
		{
			if (frame >= track.lastFrame)
			{
				track.accumulatedFrame += frame - track.lastFrame;
			}
			else
			{
				int cycleEnd = metadata.totalFrames - 1;
				track.accumulatedFrame += Math.max(0, cycleEnd - track.lastFrame)
					+ Math.max(0, frame - loopStart(metadata));
			}
		}

		return track.accumulatedFrame;
	}

	private int frameInterval(int framesPerSecond)
	{
		return Math.max(1, GAME_FRAMES_PER_SECOND / framesPerSecond);
	}

	private int animationFrameAt(AnimationMetadata metadata, long accumulatedFrame)
	{
		int cycleEnd = metadata.totalFrames - 1;
		if (accumulatedFrame <= cycleEnd)
		{
			return (int) accumulatedFrame;
		}

		return loopStart(metadata) + (int) ((accumulatedFrame - cycleEnd) % metadata.frameStep);
	}

	private int normalizeFrame(int frame, int totalFrames, int frameStep, boolean deterministicLooping, boolean loopSourceStartsAtZero)
	{
		if (frame < totalFrames)
		{
			if (!deterministicLooping && loopSourceStartsAtZero && frameStep > 0 && frameStep < totalFrames)
			{
				return totalFrames - frameStep + frame % frameStep;
			}

			return frame;
		}

		if (deterministicLooping)
		{
			return totalFrames - 1;
		}

		if (frameStep > 0 && frameStep <= totalFrames)
		{
			int loopStart = totalFrames - frameStep;
			return loopStart + (frame - totalFrames) % frameStep;
		}

		if (frameStep == 0)
		{
			return frame % totalFrames;
		}

		return totalFrames - 1;
	}

	private int loopStart(AnimationMetadata metadata)
	{
		return hasPartialLoop(metadata)
			? metadata.totalFrames - metadata.frameStep
			: metadata.totalFrames;
	}

	private boolean hasPartialLoop(AnimationMetadata metadata)
	{
		return metadata.frameStep > 0 && metadata.frameStep < metadata.totalFrames;
	}

	private String trackName(boolean poseAnimation)
	{
		return poseAnimation ? "pose" : "action";
	}

	private AnimationMetadata loadAnimationMetadata(int animationId)
	{
		Animation animation = client.loadAnimation(animationId);
		if (animation == null)
		{
			return new AnimationMetadata(-1, -1);
		}

		return new AnimationMetadata(animation.getNumFrames(), animation.getFrameStep());
	}

	private static final class AnimationMetadata
	{
		private final int totalFrames;
		private final int frameStep;

		private AnimationMetadata(int totalFrames, int frameStep)
		{
			this.totalFrames = totalFrames;
			this.frameStep = frameStep;
		}
	}

	private static final class ActorAnimationState
	{
		private final AnimationTrack action = new AnimationTrack();
		private final AnimationTrack pose = new AnimationTrack();
	}

	private static final class AnimationTrack
	{
		private int animationId = -1;
		private int lastFrame = -1;
		private long accumulatedFrame;
		private int renderedFrameFloor = -1;
		private long renderedAccumulatedFrameFloor = -1;
		private int renderedAccumulatedFrame = -1;

		private void start(int animationId, int frame)
		{
			this.animationId = animationId;
			lastFrame = -1;
			accumulatedFrame = frame;
			renderedFrameFloor = -1;
			renderedAccumulatedFrameFloor = -1;
		}

		private void reset()
		{
			animationId = -1;
			lastFrame = -1;
			accumulatedFrame = 0;
			renderedFrameFloor = -1;
			renderedAccumulatedFrameFloor = -1;
		}
	}
}

package com.kierenboal.npcsnap.rendering;

public final class BillboardAngleUtils
{
	public static final int LEGACY_FULL_CIRCLE = 2048;
	public static final int BILLBOARD_FULL_CIRCLE = 16384;
	public static final int CAMERA_FULL_CIRCLE = BILLBOARD_FULL_CIRCLE;
	public static final int ACTOR_FULL_CIRCLE = LEGACY_FULL_CIRCLE;
	public static final int PROJECTILE_FULL_CIRCLE = LEGACY_FULL_CIRCLE;
	public static final int MAX_PITCH = angleToBillboardUnits(512, LEGACY_FULL_CIRCLE);
	public static final int GROUND_ITEM_MIN_PITCH = angleToBillboardUnits(128, LEGACY_FULL_CIRCLE);
	public static final int COMBAT_YAW = angleToBillboardUnits(512, LEGACY_FULL_CIRCLE);
	public static final int OPPOSITE_COMBAT_YAW = angleToBillboardUnits(1536, LEGACY_FULL_CIRCLE);

	private BillboardAngleUtils()
	{
	}

	public static int angleToBillboardUnits(int angle, int sourceFullCircle)
	{
		int sourceUnits = Math.max(1, sourceFullCircle);
		int normalized = Math.floorMod(angle, sourceUnits);
		return Math.floorMod((int) Math.round((normalized * (double) BILLBOARD_FULL_CIRCLE) / sourceUnits), BILLBOARD_FULL_CIRCLE);
	}

	public static int combatYaw(int rawRelativeYaw)
	{
		int normalized = Math.floorMod(rawRelativeYaw, BILLBOARD_FULL_CIRCLE);
		int combatDistance = jauDistance(normalized, COMBAT_YAW);
		int oppositeDistance = jauDistance(normalized, OPPOSITE_COMBAT_YAW);
		return combatDistance <= oppositeDistance ? COMBAT_YAW : OPPOSITE_COMBAT_YAW;
	}

	public static int snapJauByAngles(int jau, int angleCount)
	{
		int clampedAngleCount = Math.max(1, angleCount);
		int step = Math.max(1, BILLBOARD_FULL_CIRCLE / clampedAngleCount);
		int normalized = Math.floorMod(jau, BILLBOARD_FULL_CIRCLE);
		return Math.floorMod(((normalized + (step / 2)) / step) * step, BILLBOARD_FULL_CIRCLE);
	}

	public static int snapPitchByAngles(int pitch, int minPitch, int angleCount)
	{
		int clampedMinPitch = Math.max(0, Math.min(minPitch, MAX_PITCH));
		int clampedPitch = Math.max(clampedMinPitch, Math.min(pitch, MAX_PITCH));
		int clampedAngleCount = Math.max(1, angleCount);
		int pitchRange = Math.max(1, MAX_PITCH - clampedMinPitch);
		if (clampedAngleCount == 1)
		{
			return clampedMinPitch;
		}

		int snappedIndex = Math.max(0, Math.min(clampedAngleCount - 1, ((clampedPitch - clampedMinPitch) * clampedAngleCount) / pitchRange));
		if (snappedIndex == 0)
		{
			return clampedMinPitch;
		}
		if (snappedIndex == clampedAngleCount - 1)
		{
			return MAX_PITCH;
		}

		int snappedPitch = clampedMinPitch + (int) Math.round(((snappedIndex + 0.5d) * pitchRange) / clampedAngleCount);
		return Math.max(clampedMinPitch, Math.min(MAX_PITCH, snappedPitch));
	}

	private static int jauDistance(int a, int b)
	{
		int distance = Math.abs(Math.floorMod(a, BILLBOARD_FULL_CIRCLE) - Math.floorMod(b, BILLBOARD_FULL_CIRCLE));
		return Math.min(distance, BILLBOARD_FULL_CIRCLE - distance);
	}
}

package com.kierenboal.npcsnap.rendering;

import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Texture;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.kit.KitType;

public final class BillboardAnimatedTextures
{
	private static final float ANIMATED_TEXTURE_V_SCROLL_PER_SECOND = -0.25f;
	private static final int[] ANIMATED_TEXTURE_IDS = {
		ItemID.TZHAAR_CAPE_FIRE,
		ItemID.TZHAAR_CAPE_FIRE_DUMMY,
		ItemID.TZHAAR_CAPE_FIRE_TROUVER,
		ItemID.TZHAAR_CAPE_FIRE_BROKEN,
		ItemID.INFERNAL_CAPE,
		ItemID.INFERNAL_CAPE_DUMMY,
		ItemID.INFERNAL_CAPE_TROUVER,
		ItemID.INFERNAL_CAPE_BROKEN,
		ItemID.BR_INFERNAL_CAPE
	};

	private BillboardAnimatedTextures()
	{
	}

	public static int findAnimatedTextureId(Actor actor)
	{
		if (!(actor instanceof Player))
		{
			return -1;
		}

		PlayerComposition composition = ((Player) actor).getPlayerComposition();
		if (composition == null)
		{
			return -1;
		}

		int capeId = normalizeEquipmentItemId(composition.getEquipmentId(KitType.CAPE));
		if (isAnimatedTextureId(capeId))
		{
			return capeId;
		}

		int[] equipmentIds = composition.getEquipmentIds();
		if (equipmentIds == null)
		{
			return -1;
		}

		for (int equipmentId : equipmentIds)
		{
			int normalizedId = normalizeEquipmentItemId(equipmentId);
			if (isAnimatedTextureId(normalizedId))
			{
				return normalizedId;
			}
		}

		return -1;
	}

	public static boolean isAnimatedTextureId(int textureId)
	{
		for (int animatedTextureId : ANIMATED_TEXTURE_IDS)
		{
			if (animatedTextureId == textureId)
			{
				return true;
			}
		}

		return false;
	}

	public static float vOffset(long nowMillis, Texture texture, boolean frameSnappingEnabled, int animationFrameCount)
	{
		double speedMultiplier = texture != null && texture.getAnimationSpeed() > 0
			? texture.getAnimationSpeed()
			: 1.0d;
		double offset = (nowMillis / 1000.0d) * ANIMATED_TEXTURE_V_SCROLL_PER_SECOND * speedMultiplier;
		return snappedOffset(offset, frameSnappingEnabled, animationFrameCount);
	}

	public static int offsetStateHash(int animatedTextureId, long nowMillis, boolean frameSnappingEnabled, int animationFrameCount)
	{
		if (!isAnimatedTextureId(animatedTextureId))
		{
			return 0;
		}

		return Float.floatToIntBits(vOffset(nowMillis, null, frameSnappingEnabled, animationFrameCount));
	}

	private static float snappedOffset(double offset, boolean frameSnappingEnabled, int animationFrameCount)
	{
		offset = BillboardGeometryUtils.wrapUnit(offset);
		if (!frameSnappingEnabled)
		{
			return (float) offset;
		}

		int visibleFrameCount = Math.max(1, animationFrameCount);
		double snapped = Math.round(offset * visibleFrameCount) / (double) visibleFrameCount;
		return (float) BillboardGeometryUtils.wrapUnit(snapped);
	}

	private static int normalizeEquipmentItemId(int equipmentId)
	{
		if (equipmentId >= PlayerComposition.ITEM_OFFSET)
		{
			return equipmentId - PlayerComposition.ITEM_OFFSET;
		}

		return equipmentId;
	}
}

package com.kierenboal.npcsnap.rendering;

import net.runelite.api.Client;
import net.runelite.api.TextureProvider;

public final class BillboardBrightness
{
	private static final double DARKEST = 0.9d;
	private static final double BRIGHTEST = 0.6d;

	private BillboardBrightness()
	{
	}

	public static int effectiveLightBoostPercent(Client client, int configuredPercent)
	{
		TextureProvider provider = client == null ? null : client.getTextureProvider();
		if (provider == null)
		{
			return configuredPercent;
		}
		double brightness = provider.getBrightness();
		if (!Double.isFinite(brightness))
		{
			return configuredPercent;
		}
		double position = Math.max(0.0d, Math.min(1.0d, (DARKEST - brightness) / (DARKEST - BRIGHTEST)));
		return (int) Math.round(configuredPercent * (1.0d + position));
	}
}

package com.kierenboal.npcsnap.rendering;

public final class BillboardCanvasPoint
{
	public final double x;
	public final double y;
	public final double depth;
	// Screen-space world-up derivative, divided by scale / depth.
	public final double verticalRight;
	public final double verticalUp;

	public BillboardCanvasPoint(double x, double y, double depth, double verticalRight, double verticalUp)
	{
		this.x = x;
		this.y = y;
		this.depth = depth;
		this.verticalRight = verticalRight;
		this.verticalUp = verticalUp;
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Color;
import net.runelite.api.Model;

public final class BillboardColorUtils
{
	private static final int CAPE_ARTIFACT_FACE_RED = 147;
	private static final int CAPE_ARTIFACT_FACE_GREEN = 143;
	private static final int CAPE_ARTIFACT_FACE_BLUE = 143;
	private static final int CAPE_ARTIFACT_FACE_ALPHA = 255;

	private BillboardColorUtils()
	{
	}

	public static Color resolveFaceColor(
		int face,
		int[] faceColors1,
		int[] faceColors2,
		int[] faceColors3,
		short[] unlitFaceColors,
		int alpha
	)
	{
		Color unlitColor = null;
		if (unlitFaceColors != null && face < unlitFaceColors.length && unlitFaceColors[face] != -1)
		{
			unlitColor = packedHslToColor(Short.toUnsignedInt(unlitFaceColors[face]), alpha);
		}

		Color litColor = decodedLitFaceColor(face, faceColors1, faceColors2, faceColors3, alpha);

		Color color = chooseFaceColor(unlitColor, litColor);
		if (color != null)
		{
			return color;
		}

		return new Color(0, 0, 0, Math.max(0, Math.min(255, alpha)));
	}

	public static Color resolveFaceColor(
		int face,
		int[] faceColors1,
		int[] faceColors2,
		int[] faceColors3,
		short[] unlitFaceColors,
		int alpha,
		Model model)
	{
		if (model == null || model.getOverrideAmount() <= 0)
		{
			return resolveFaceColor(face, faceColors1, faceColors2, faceColors3, unlitFaceColors, alpha);
		}

		Color unlitColor = unlitFaceColors != null && face < unlitFaceColors.length && unlitFaceColors[face] != -1
			? packedHslToColor(applyHslOverride(Short.toUnsignedInt(unlitFaceColors[face]), model), alpha)
			: null;
		Color litColor = null;
		if (hasFlatFaceColor(face, faceColors1, faceColors3))
		{
			litColor = packedHslToColor(applyHslOverride(faceColors1[face], model), alpha);
		}
		else if (hasLitFaceColors(face, faceColors1, faceColors2, faceColors3))
		{
			litColor = averagePackedFaceColor(
				applyHslOverride(faceColors1[face], model),
				applyHslOverride(faceColors2[face], model),
				applyHslOverride(faceColors3[face], model), alpha);
		}
		Color color = chooseFaceColor(unlitColor, litColor);
		return color != null ? color : new Color(0, 0, 0, Math.max(0, Math.min(255, alpha)));
	}

	static int applyHslOverride(int packedHsl, Model model)
	{
		int amount = model.getOverrideAmount();
		if (amount <= 0 || packedHsl < 0)
		{
			return packedHsl;
		}
		int hue = blend((packedHsl >> 10) & 63, model.getOverrideHue(), amount);
		int saturation = blend((packedHsl >> 7) & 7, model.getOverrideSaturation(), amount);
		int luminance = blend(packedHsl & 127, model.getOverrideLuminance(), amount);
		return ((hue << 10) | (saturation << 7) | luminance) & 0xFFFF;
	}

	private static int blend(int original, int replacement, int amount)
	{
		// Match RuneLite's ModelUploader: 128-step interpolation, with -1 meaning
		// that this HSL component is left as it was.
		return replacement == -1 ? original : original + ((amount * (replacement - original)) >> 7);
	}

	public static boolean isSkippedCapeArtifactFaceColor(Color color)
	{
		// Fire Cape and Infernal Cape player models include unwanted rear geometry
		// with this exact raw face color; skip it before light boost and rasterizing.
		return color != null
			&& color.getRed() == CAPE_ARTIFACT_FACE_RED
			&& color.getGreen() == CAPE_ARTIFACT_FACE_GREEN
			&& color.getBlue() == CAPE_ARTIFACT_FACE_BLUE
			&& color.getAlpha() == CAPE_ARTIFACT_FACE_ALPHA;
	}

	public static boolean isInvisibleFace(int face, int[] faceColors3, byte[] transparencies)
	{
		// -1 is flat shading, not hidden. RuneLite stores transparency separately:
		// unsigned 0 is opaque, while unsigned 255 has no visible opacity.
		return face >= 0
			&& ((faceColors3 != null && face < faceColors3.length && faceColors3[face] == -2)
			|| (transparencies != null && face < transparencies.length && (transparencies[face] & 0xFF) == 255));
	}

	public static Color decodedLitFaceColor(int face, int[] faceColors1, int[] faceColors2, int[] faceColors3, int alpha)
	{
		if (hasFlatFaceColor(face, faceColors1, faceColors3))
		{
			return packedHslToColor(faceColors1[face], alpha);
		}

		if (hasLitFaceColors(face, faceColors1, faceColors2, faceColors3))
		{
			return averagePackedFaceColor(faceColors1[face], faceColors2[face], faceColors3[face], alpha);
		}

		return null;
	}

	public static Integer faceColorValue(int[] faceColors, int face)
	{
		return faceColors != null && face < faceColors.length ? faceColors[face] : null;
	}

	public static Integer unlitFaceColorValue(short[] unlitFaceColors, int face)
	{
		return unlitFaceColors != null && face < unlitFaceColors.length && unlitFaceColors[face] != -1
			? Short.toUnsignedInt(unlitFaceColors[face])
			: null;
	}

	public static String formatColor(Color color)
	{
		return color == null
			? "null"
			: color.getRed() + "," + color.getGreen() + "," + color.getBlue() + "," + color.getAlpha();
	}

	public static Color applyLightBoost(Color color, double lightBoostPercent)
	{
		double boost = lightBoostPercent / 100.0d;
		int red = Math.min(255, (int) Math.round(color.getRed() * boost));
		int green = Math.min(255, (int) Math.round(color.getGreen() * boost));
		int blue = Math.min(255, (int) Math.round(color.getBlue() * boost));
		return new Color(red, green, blue, color.getAlpha());
	}

	public static int modulateTexturePixel(int samplePixel, Color shade, int colorBands)
	{
		int sampleAlpha = (samplePixel >>> 24) & 0xFF;
		if (sampleAlpha == 0 && (samplePixel & 0xFFFFFF) != 0)
		{
			sampleAlpha = 0xFF;
		}

		int alpha = (sampleAlpha * shade.getAlpha()) / 255;
		int red = (((samplePixel >> 16) & 0xFF) * shade.getRed()) / 255;
		int green = (((samplePixel >> 8) & 0xFF) * shade.getGreen()) / 255;
		int blue = ((samplePixel & 0xFF) * shade.getBlue()) / 255;
		int modulatedPixel = (alpha << 24) | (red << 16) | (green << 8) | blue;
		return NpcSnapColorBanding.snapTexturePixel(modulatedPixel, colorBands);
	}

	private static boolean hasLitFaceColors(int face, int[] faceColors1, int[] faceColors2, int[] faceColors3)
	{
		return hasLitFaceColor(faceColors1, face)
			&& hasLitFaceColor(faceColors2, face)
			&& hasLitFaceColor(faceColors3, face);
	}

	private static boolean hasLitFaceColor(int[] faceColors, int face)
	{
		return faceColors != null && face < faceColors.length && faceColors[face] >= 0;
	}

	private static boolean hasFlatFaceColor(int face, int[] faceColors1, int[] faceColors3)
	{
		return hasLitFaceColor(faceColors1, face)
			&& faceColors3 != null
			&& face < faceColors3.length
			&& faceColors3[face] == -1;
	}

	private static Color averagePackedFaceColor(int packed1, int packed2, int packed3, int alpha)
	{
		Color vertexA = packedHslToColor(packed1, alpha);
		Color vertexB = packedHslToColor(packed2, alpha);
		Color vertexC = packedHslToColor(packed3, alpha);
		int red = (vertexA.getRed() + vertexB.getRed() + vertexC.getRed()) / 3;
		int green = (vertexA.getGreen() + vertexB.getGreen() + vertexC.getGreen()) / 3;
		int blue = (vertexA.getBlue() + vertexB.getBlue() + vertexC.getBlue()) / 3;
		return new Color(red, green, blue, alpha);
	}

	private static Color chooseFaceColor(Color unlitColor, Color litColor)
	{
		Color selected = unlitColor != null ? unlitColor : litColor;
		selected = chooseMoreColorful(selected, litColor);
		return selected;
	}

	private static Color chooseMoreColorful(Color current, Color candidate)
	{
		if (candidate != null
			&& maxRgb(candidate) > 2
			&& (current == null || colorfulness(candidate) > colorfulness(current) + 0.03f))
		{
			return candidate;
		}

		return current;
	}

	private static float colorfulness(Color color)
	{
		float[] hsb = Color.RGBtoHSB(color.getRed(), color.getGreen(), color.getBlue(), null);
		return hsb[1] * hsb[2];
	}

	private static int maxRgb(Color color)
	{
		return Math.max(color.getRed(), Math.max(color.getGreen(), color.getBlue()));
	}

	private static Color packedHslToColor(int packedHsl, int alpha)
	{
		int hue = (packedHsl >> 10) & 0x3F;
		int saturation = (packedHsl >> 7) & 0x07;
		int lightness = packedHsl & 0x7F;
		float h = hue / 64.0f;
		float s = saturation / 7.0f;
		float l = lightness / 128.0f;

		float r;
		float g;
		float b;

		if (s == 0.0f)
		{
			r = l;
			g = l;
			b = l;
		}
		else
		{
			float q = l < 0.5f ? l * (1.0f + s) : l + s - (l * s);
			float p = 2.0f * l - q;
			r = hueToRgb(p, q, h + (1.0f / 3.0f));
			g = hueToRgb(p, q, h);
			b = hueToRgb(p, q, h - (1.0f / 3.0f));
		}

		return new Color(clamp(r), clamp(g), clamp(b), Math.max(0, Math.min(255, alpha)));
	}

	private static float hueToRgb(float p, float q, float t)
	{
		if (t < 0)
		{
			t += 1.0f;
		}
		if (t > 1)
		{
			t -= 1.0f;
		}
		if (t < (1.0f / 6.0f))
		{
			return p + ((q - p) * 6.0f * t);
		}
		if (t < 0.5f)
		{
			return q;
		}
		if (t < (2.0f / 3.0f))
		{
			return p + ((q - p) * ((2.0f / 3.0f) - t) * 6.0f);
		}
		return p;
	}

	private static int clamp(float component)
	{
		return Math.max(0, Math.min(255, Math.round(component * 255.0f)));
	}
}

package com.kierenboal.npcsnap.rendering;

import com.kierenboal.npcsnap.features.GroundItemBillboard;
import com.kierenboal.npcsnap.targeting.ObjectRenderablePart;
import com.kierenboal.npcsnap.targeting.ObservedTileObject;
import com.kierenboal.npcsnap.targeting.WorldViewLocationResolver;

import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Client;
import net.runelite.api.GraphicsObject;
import net.runelite.api.Perspective;
import net.runelite.api.Projectile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.LocalPoint;

public final class BillboardDepthCalculator
{
	private static final double MIN_CANVAS_PROJECTION_DEPTH = 50.0d;
	private final Client client;

	public BillboardDepthCalculator(Client client)
	{
		this.client = client;
	}

	public double depth(Projectile projectile)
	{
		// Use the same flight origin as the sprite, independent of animated height.
		return cameraDistance(projectile.getX(), projectile.getY(), projectile.getZ());
	}

	public double depth(GraphicsObject graphicsObject)
	{
		LocalPoint localPoint = graphicsObject.getLocation();
		if (localPoint == null)
		{
			return Double.NEGATIVE_INFINITY;
		}

		double verticalOffset = BillboardEffectGeometry.graphicsVerticalOffset(client, graphicsObject)
			+ (graphicsObject.getModelHeight() / 2.0);
		return cameraDistance(localPoint, graphicsObject.getLevel(), verticalOffset);
	}

	public double depth(ActorSpotAnim actorSpotAnim, Actor actor)
	{
		LocalPoint localPoint = actor != null
			? WorldViewLocationResolver.toMainWorld(client.getTopLevelWorldView(), actor)
			: null;
		if (localPoint == null)
		{
			return Double.NEGATIVE_INFINITY;
		}

		double verticalOffset = BillboardEffectGeometry.actorSpotVerticalOffset(actorSpotAnim);
		int plane = actor.getWorldView() != null && actor.getWorldView().isTopLevel()
			? actor.getWorldView().getPlane()
			: 0;
		return cameraDistance(localPoint, plane,
			verticalOffset + (actorSpotAnim.getModelHeight() / 2.0));
	}

	public double depth(TileItem item, GroundItemBillboard groundItem)
	{
		if (groundItem == null)
		{
			return Double.NEGATIVE_INFINITY;
		}

		return cameraDistance(
			groundItem.localPoint,
			groundItem.plane,
			groundItem.verticalOffset + (item.getModelHeight() / 2.0));
	}

	public double depth(ObservedTileObject observed)
	{
		double nearest = Double.POSITIVE_INFINITY;
		for (ObjectRenderablePart part : observed.parts)
		{
			if (part.localPoint == null || part.renderable == null)
			{
				continue;
			}

			// Sort scenery by its fixed world origin, independently of the live
			// animated height while a previously captured sprite is displayed.
			double distance = cameraDistance(part.localPoint, part.plane, 0);
			if (distance < nearest)
			{
				nearest = distance;
			}
		}

		return Double.isFinite(nearest) ? nearest : Double.NEGATIVE_INFINITY;
	}

	public double cameraDistance(LocalPoint localPoint, int plane, double verticalOffset)
	{
		double groundHeight = Perspective.getTileHeight(client, localPoint, plane);
		return cameraDistance(localPoint.getX(), localPoint.getY(), worldHeight(groundHeight, verticalOffset));
	}

	private double cameraDistance(double localX, double localY, double worldZ)
	{
		double dx = localX - client.getCameraFpX();
		double dy = localY - client.getCameraFpY();
		double dz = worldZ - client.getCameraFpZ();
		return Math.sqrt((dx * dx) + (dy * dy) + (dz * dz));
	}

	/**
	 * Converts RuneLite's positive height offset (above the tile) to its world
	 * z coordinate. RuneLite's world z axis increases downwards, so height is
	 * subtracted from the tile height.
	 */
	public static double worldHeight(double tileHeight, double verticalOffset)
	{
		return tileHeight - verticalOffset;
	}

	public double cameraForwardDepth(LocalPoint localPoint, int plane, double verticalOffset)
	{
		if (localPoint == null)
		{
			return Double.NaN;
		}

		double worldHeight = worldHeight(Perspective.getTileHeight(client, localPoint, plane), verticalOffset);
		return cameraForwardDepth(localPoint.getX(), localPoint.getY(), worldHeight);
	}

	public double cameraForwardDepth(int localX, int localY, double worldHeight)
	{
		double x = localX - client.getCameraFpX();
		double y = localY - client.getCameraFpY();
		double z = worldHeight - client.getCameraFpZ();
		int yaw = cameraYawIndex();
		int pitch = cameraPitchIndex();
		double yawSin = Perspective.SINE[yaw] / 65536.0d;
		double yawCos = Perspective.COSINE[yaw] / 65536.0d;
		double pitchSin = Perspective.SINE[pitch] / 65536.0d;
		double pitchCos = Perspective.COSINE[pitch] / 65536.0d;
		double cameraY = (y * yawCos) - (x * yawSin);
		return (z * pitchSin) + (cameraY * pitchCos);
	}

	public double cameraForwardDepthOnVerticalPlane(int localX, int localY, int canvasY)
	{
		double x = localX - client.getCameraFpX();
		double y = localY - client.getCameraFpY();
		int yaw = cameraYawIndex();
		int pitch = cameraPitchIndex();
		double yawSin = Perspective.SINE[yaw] / 65536.0d;
		double yawCos = Perspective.COSINE[yaw] / 65536.0d;
		double pitchSin = Perspective.SINE[pitch] / 65536.0d;
		double pitchCos = Perspective.COSINE[pitch] / 65536.0d;
		double cameraY = (y * yawCos) - (x * yawSin);
		double zoom = client.get3dZoom();
		if (!Double.isFinite(cameraY) || cameraY <= 0.0d || !Double.isFinite(zoom) || zoom <= 0.0d)
		{
			return Double.NaN;
		}

		double viewportCenterY = client.getViewportYOffset() + (client.getViewportHeight() / 2.0d);
		double screenSlope = (canvasY - viewportCenterY) / zoom;
		double denominator = pitchCos - (screenSlope * pitchSin);
		if (!Double.isFinite(denominator) || denominator <= 0.0d)
		{
			return Double.NaN;
		}

		// Intersect the pixel's camera ray with the yaw-facing world-vertical
		// plane through the target. In camera coordinates:
		// cameraY = depth * (cos(pitch) - screenSlope * sin(pitch)).
		return cameraY / denominator;
	}

	public BillboardCanvasPoint projectCanvasPoint(LocalPoint localPoint, int plane, double verticalOffset)
	{
		if (localPoint == null || !Double.isFinite(verticalOffset))
		{
			return null;
		}

		double worldZ = worldHeight(Perspective.getTileHeight(client, localPoint, plane), verticalOffset);
		return projectCanvasPoint(localPoint.getX(), localPoint.getY(), worldZ);
	}

	public BillboardCanvasPoint projectCanvasPoint(double localX, double localY, double worldZ)
	{
		// Match Perspective.localToCanvas's GPU/CPU camera conventions, retaining
		// subpixel precision until rasterization. RuneLite's vertical axis points
		// down, so world-up is decreasing worldZ.
		double cameraX;
		double cameraY;
		double cameraZ;
		double yawSin;
		double yawCos;
		double pitchSin;
		double pitchCos;
		if (client.isGpu())
		{
			cameraX = client.getCameraFpX();
			cameraY = client.getCameraFpY();
			cameraZ = client.getCameraFpZ();
			double yaw = client.getCameraFpYaw();
			double pitch = client.getCameraFpPitch();
			yawSin = Math.sin(yaw);
			yawCos = Math.cos(yaw);
			pitchSin = Math.sin(pitch);
			pitchCos = Math.cos(pitch);
		}
		else
		{
			cameraX = client.getCameraX();
			cameraY = client.getCameraY();
			cameraZ = client.getCameraZ();
			int yaw = Math.floorMod(client.getCameraYaw(), Perspective.SINE14.length);
			int pitch = Math.floorMod(client.getCameraPitch(), Perspective.SINE14.length);
			yawSin = Perspective.SINE14[yaw] / 65536.0d;
			yawCos = Perspective.COSINE14[yaw] / 65536.0d;
			pitchSin = Perspective.SINE14[pitch] / 65536.0d;
			pitchCos = Perspective.COSINE14[pitch] / 65536.0d;
		}

		double translatedX = localX - cameraX;
		double translatedY = localY - cameraY;
		double translatedZ = worldZ - cameraZ;
		double cameraRight = (translatedX * yawCos) + (translatedY * yawSin);
		double cameraForward = (translatedY * yawCos) - (translatedX * yawSin);
		double cameraVertical = (translatedZ * pitchCos) - (cameraForward * pitchSin);
		double depth = (cameraForward * pitchCos) + (translatedZ * pitchSin);
		double scale = client.getScale();
		if (!Double.isFinite(depth) || depth < MIN_CANVAS_PROJECTION_DEPTH
			|| !Double.isFinite(scale) || scale <= 0.0d)
		{
			return null;
		}

		double canvasX = client.getViewportXOffset() + (client.getViewportWidth() / 2.0d)
			+ ((cameraRight * scale) / depth);
		double canvasY = client.getViewportYOffset() + (client.getViewportHeight() / 2.0d)
			+ ((cameraVertical * scale) / depth);
		// Differentiate the perspective divide with respect to world-up. Removing
		// the common scale/depth factor gives (right*sin(pitch)/depth, forward/depth)
		// for unit-length trig values. Retain the CPU table's rounding below.
		// Unlike a base-to-model-top delta, this never depends on animated height.
		return Double.isFinite(canvasX) && Double.isFinite(canvasY)
			? new BillboardCanvasPoint(canvasX, canvasY, depth,
				cameraRight * pitchSin / depth,
				cameraForward * (pitchCos * pitchCos + pitchSin * pitchSin) / depth)
			: null;
	}

	public int cameraYawIndex()
	{
		return cameraAngleIndex(client.getCameraYaw());
	}

	public int cameraPitchIndex()
	{
		return cameraAngleIndex(client.getCameraPitch());
	}

	private int cameraAngleIndex(int cameraAngle)
	{
		return Math.floorMod(
			(int) Math.round((Math.floorMod(cameraAngle, BillboardAngleUtils.CAMERA_FULL_CIRCLE) * (double) Perspective.SINE.length) / BillboardAngleUtils.CAMERA_FULL_CIRCLE),
			Perspective.SINE.length
		);
	}

}

package com.kierenboal.npcsnap.rendering;

import java.awt.Rectangle;
import net.runelite.api.Model;
import net.runelite.api.TileItem;
import net.runelite.api.coords.LocalPoint;

public final class BillboardDepthSurface
{
	private static final BillboardDepthSurface INVALID = new BillboardDepthSurface(null, 0, 0, Double.NaN, 0, false, null, null);

	private final BillboardDepthCalculator depthCalculator;
	private final int baseLocalX;
	private final int baseLocalY;
	private final double baseHeight;
	private final int modelHeight;
	private final boolean supportsWorldOcclusion;
	private final Rectangle sourceBounds;
	private final Rectangle drawBounds;
	private final BillboardProjectedQuad projectedQuad;

	public BillboardDepthSurface(
		BillboardDepthCalculator depthCalculator,
		int baseLocalX,
		int baseLocalY,
		double baseHeight,
		int modelHeight,
		Rectangle sourceBounds,
		Rectangle drawBounds)
	{
		this(
			depthCalculator,
			baseLocalX,
			baseLocalY,
			baseHeight,
			Math.max(0, modelHeight),
			modelHeight > 0,
			sourceBounds != null ? new Rectangle(sourceBounds) : null,
			drawBounds != null ? new Rectangle(drawBounds) : null
		);
	}

	private BillboardDepthSurface(
		BillboardDepthCalculator depthCalculator,
		int baseLocalX,
		int baseLocalY,
		double baseHeight,
		int modelHeight,
		boolean supportsWorldOcclusion,
		Rectangle sourceBounds,
		Rectangle drawBounds)
	{
		this.depthCalculator = depthCalculator;
		this.baseLocalX = baseLocalX;
		this.baseLocalY = baseLocalY;
		this.baseHeight = baseHeight;
		this.modelHeight = modelHeight;
		this.supportsWorldOcclusion = supportsWorldOcclusion;
		this.sourceBounds = sourceBounds;
		this.drawBounds = drawBounds;
		this.projectedQuad = null;
	}

	private BillboardDepthSurface(BillboardDepthSurface surface, BillboardProjectedQuad quad)
	{
		depthCalculator = surface.depthCalculator;
		baseLocalX = surface.baseLocalX;
		baseLocalY = surface.baseLocalY;
		baseHeight = surface.baseHeight;
		modelHeight = Math.max(1, surface.modelHeight);
		supportsWorldOcclusion = true;
		sourceBounds = surface.sourceBounds;
		drawBounds = surface.drawBounds;
		projectedQuad = quad;
	}

	public static BillboardDepthSurface invalid()
	{
		return INVALID;
	}

	public static BillboardDepthSurface from(BillboardDepthCalculator depthCalculator, PreparedBillboardDraw draw, double baseHeight)
	{
		if (draw == null)
		{
			return invalid();
		}
		BillboardDepthSurface surface = from(depthCalculator, draw.request, draw.sourceBounds, draw.bounds,
			baseHeight, draw.modelHeight, draw.supportsWorldOcclusion);
		return draw.geometry != null && draw.geometry.projectedQuad != null && surface != INVALID
			? new BillboardDepthSurface(surface, draw.geometry.projectedQuad) : surface;
	}

	public static BillboardDepthSurface from(BillboardDepthCalculator depthCalculator, BillboardRenderRequest request, Rectangle sourceBounds, Rectangle drawBounds, double baseHeight)
	{
		return from(depthCalculator, request, sourceBounds, drawBounds, baseHeight,
			modelHeight(request), supportsWorldOcclusion(request));
	}

	static int modelHeight(BillboardRenderRequest request)
	{
		if (request == null || request.renderable == null)
		{
			return 0;
		}
		int height = request.renderable.getModelHeight();
		return request.renderable instanceof TileItem ? Math.max(1, height) : Math.max(0, height);
	}

	static boolean supportsWorldOcclusion(BillboardRenderRequest request)
	{
		// Ground-item sprites use the same camera-facing depth plane as actors,
		// even when their source model is flat or reports zero height.
		return request != null && (request.renderable instanceof TileItem
			|| (!request.lowProfile && supportsVerticalPlaneOcclusion(request.model)));
	}

	private static BillboardDepthSurface from(BillboardDepthCalculator depthCalculator,
		BillboardRenderRequest request, Rectangle sourceBounds, Rectangle drawBounds, double baseHeight,
		int modelHeight, boolean supportsWorldOcclusion)
	{
		if (depthCalculator == null || request == null || request.localPoint == null || request.renderable == null || sourceBounds == null
			|| sourceBounds.width <= 0 || sourceBounds.height <= 0 || drawBounds == null || drawBounds.width <= 0 || drawBounds.height <= 0 || !Double.isFinite(baseHeight))
		{
			return invalid();
		}

		LocalPoint localPoint = request.localPoint;
		return new BillboardDepthSurface(
			depthCalculator,
			localPoint.getX(),
			localPoint.getY(),
			BillboardDepthCalculator.worldHeight(baseHeight, request.verticalOffset),
			modelHeight,
			supportsWorldOcclusion,
			sourceBounds,
			drawBounds
		);
	}

	public boolean supportsWorldOcclusion()
	{
		return supportsWorldOcclusion;
	}

	static boolean supportsVerticalPlaneOcclusion(Model model)
	{
		return BillboardModelProfile.supportsVerticalPlaneOcclusion(model);
	}

	public double depthAt(int sourceX, int sourceY, int sourceWidth, int sourceHeight, int canvasY)
	{
		DebugPoint point = debugPointAt(sourceX, sourceY, sourceWidth, sourceHeight, canvasY);
		return point.depth;
	}

	public double depthAtRow(int sourceHeight, int canvasY)
	{
		if (depthCalculator == null || sourceBounds == null || drawBounds == null || sourceHeight <= 0 || modelHeight <= 0 || !Double.isFinite(baseHeight))
		{
			return Double.NaN;
		}

		return depthCalculator.cameraForwardDepthOnVerticalPlane(baseLocalX, baseLocalY, canvasY);
	}

	public DebugPoint debugPointAt(int sourceX, int sourceY, int sourceWidth, int sourceHeight, int canvasY)
	{
		if (projectedQuad != null && sourceWidth > 0 && sourceHeight > 0)
		{
			return new DebugPoint(baseLocalX, baseLocalY, baseHeight, 0.0d, 0.0d,
				projectedQuad.depthAt((sourceX + 0.5d) / sourceWidth, (sourceY + 0.5d) / sourceHeight));
		}
		if (depthCalculator == null || sourceBounds == null || drawBounds == null || sourceWidth <= 0 || sourceHeight <= 0 || modelHeight <= 0 || !Double.isFinite(baseHeight))
		{
			return DebugPoint.invalid();
		}

		double spriteX = sourceBounds.x + (((sourceX + 0.5d) * sourceBounds.width) / sourceWidth);
		double horizontalOffset = spriteX;
		if (!Double.isFinite(horizontalOffset))
		{
			return DebugPoint.invalid();
		}

		int localX = baseLocalX;
		int localY = baseLocalY;
		double depth = depthCalculator.cameraForwardDepthOnVerticalPlane(localX, localY, canvasY);
		return new DebugPoint(localX, localY, baseHeight, horizontalOffset, 0.0d, depth);
	}

	public double depthAt(int sourceX, int sourceY, int sourceWidth, int sourceHeight)
	{
		int canvasY = drawBounds != null
			? drawBounds.y + (int) Math.round(((sourceY + 0.5d) * drawBounds.height) / Math.max(1.0d, sourceHeight))
			: 0;
		return depthAt(sourceX, sourceY, sourceWidth, sourceHeight, canvasY);
	}

	public static final class DebugPoint
	{
		public final int localX;
		public final int localY;
		public final double height;
		public final double horizontalOffset;
		public final double verticalOffset;
		public final double depth;

		private DebugPoint(int localX, int localY, double height, double horizontalOffset, double verticalOffset, double depth)
		{
			this.localX = localX;
			this.localY = localY;
			this.height = height;
			this.horizontalOffset = horizontalOffset;
			this.verticalOffset = verticalOffset;
			this.depth = depth;
		}

		private static DebugPoint invalid()
		{
			return new DebugPoint(0, 0, Double.NaN, Double.NaN, Double.NaN, Double.NaN);
		}
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Polygon;
import java.awt.Rectangle;
import net.runelite.api.Point;

public final class BillboardDrawGeometry
{
	public final Rectangle unskewedBounds;
	public final Rectangle bounds;
	public final BillboardProjectedQuad projectedQuad;
	private final double contentTopY;
	private final double contentBottomY;
	private final double contentCenterX;
	private final double topOffsetX;
	private final double bottomOffsetX;

	private BillboardDrawGeometry(
		Rectangle unskewedBounds,
		double contentCenterX,
		double contentTopY,
		double contentBottomY,
		double topOffsetX,
		double bottomOffsetX)
	{
		this.unskewedBounds = new Rectangle(unskewedBounds);
		this.projectedQuad = null;
		this.contentCenterX = contentCenterX;
		this.contentTopY = contentTopY;
		this.contentBottomY = contentBottomY;
		this.topOffsetX = Double.isFinite(topOffsetX) ? topOffsetX : 0.0d;
		this.bottomOffsetX = Double.isFinite(bottomOffsetX) ? bottomOffsetX : 0.0d;
		this.bounds = enclosingBounds();
	}

	private BillboardDrawGeometry(BillboardProjectedQuad quad)
	{
		projectedQuad = quad;
		bounds = new Rectangle(quad.bounds);
		unskewedBounds = new Rectangle(bounds);
		contentCenterX = contentTopY = contentBottomY = topOffsetX = bottomOffsetX = 0.0d;
	}

	public static BillboardDrawGeometry projected(BillboardProjectedQuad quad)
	{
		return quad != null ? new BillboardDrawGeometry(quad) : null;
	}

	public static BillboardDrawGeometry rectangular(Rectangle bounds)
	{
		if (bounds == null)
		{
			return null;
		}
		return new BillboardDrawGeometry(bounds, bounds.getCenterX(), bounds.y, bounds.y + bounds.height, 0.0d, 0.0d);
	}

	public static BillboardDrawGeometry sheared(
		Rectangle bounds,
		double contentCenterX,
		double contentTopY,
		double contentBottomY,
		double topOffsetX,
		double bottomOffsetX)
	{
		if (bounds == null || bounds.isEmpty() || !Double.isFinite(contentCenterX) || !Double.isFinite(contentTopY)
			|| !Double.isFinite(contentBottomY) || contentBottomY <= contentTopY
			|| !Double.isFinite(topOffsetX) || !Double.isFinite(bottomOffsetX))
		{
			return rectangular(bounds);
		}
		return new BillboardDrawGeometry(
			bounds, contentCenterX, contentTopY, contentBottomY, topOffsetX, bottomOffsetX);
	}

	public boolean isSheared()
	{
		return topOffsetX != 0.0d || bottomOffsetX != 0.0d;
	}

	public static BillboardDrawGeometry actorSkew(
		Rectangle drawBounds, Rectangle imageBounds, Rectangle contentBounds, double slope)
	{
		if (drawBounds == null || imageBounds == null || imageBounds.isEmpty()
			|| contentBounds == null || contentBounds.isEmpty() || !Double.isFinite(slope))
		{
			return rectangular(drawBounds);
		}

		double scaleX = drawBounds.width / (double) imageBounds.width;
		double scaleY = drawBounds.height / (double) imageBounds.height;
		double contentTop = drawBounds.y + (contentBounds.y - imageBounds.y) * scaleY;
		double contentBottom = drawBounds.y + (contentBounds.getMaxY() - imageBounds.y) * scaleY;
		double contentCenter = drawBounds.x + (contentBounds.getCenterX() - imageBounds.x) * scaleX;
		// Pivot around model-local zero. The bottom of a pitched or animated sprite
		// is not the actor's ground point, and may lie on either side of this pivot.
		return sheared(drawBounds, contentCenter, contentTop, contentBottom,
			-contentBounds.y * scaleY * slope, -contentBounds.getMaxY() * scaleY * slope);
	}

	public int rowLeftAt(int canvasY)
	{
		return unskewedBounds.x + (int) Math.round(offsetAt(canvasY + 0.5d));
	}

	public double offsetAt(double canvasY)
	{
		if (!isSheared())
		{
			return 0.0d;
		}
		double fractionFromTop = (canvasY - contentTopY) / (contentBottomY - contentTopY);
		return topOffsetX + ((bottomOffsetX - topOffsetX) * fractionFromTop);
	}

	public int sourceXAt(int canvasX, int canvasY, int sourceWidth)
	{
		if (sourceWidth <= 0 || unskewedBounds.width <= 0)
		{
			return -1;
		}
		int rowX = canvasX - rowLeftAt(canvasY);
		if (rowX < 0 || rowX >= unskewedBounds.width)
		{
			return -1;
		}
		return (int) (((long) rowX * sourceWidth) / unskewedBounds.width);
	}

	public int sourceYAt(int canvasY, int sourceHeight)
	{
		if (sourceHeight <= 0 || unskewedBounds.height <= 0)
		{
			return -1;
		}
		int rowY = canvasY - unskewedBounds.y;
		if (rowY < 0 || rowY >= unskewedBounds.height)
		{
			return -1;
		}
		return (int) (((long) rowY * sourceHeight) / unskewedBounds.height);
	}

	public Point canvasPoint(double sourceXFraction, double sourceYFraction)
	{
		if (projectedQuad != null)
		{
			return projectedQuad.canvasPoint(sourceXFraction, sourceYFraction);
		}
		double canvasY = unskewedBounds.y + (sourceYFraction * unskewedBounds.height);
		double canvasX = unskewedBounds.x + (sourceXFraction * unskewedBounds.width) + offsetAt(canvasY);
		return new Point((int) Math.round(canvasX), (int) Math.round(canvasY));
	}

	public Point contentTopCenter()
	{
		if (projectedQuad != null)
		{
			return projectedQuad.contentTopCenter();
		}
		double canvasX = contentCenterX + offsetAt(contentTopY);
		return new Point((int) Math.round(canvasX), (int) Math.round(contentTopY));
	}

	public Polygon polygon()
	{
		if (projectedQuad != null)
		{
			return projectedQuad.polygon();
		}
		int topY = unskewedBounds.y;
		int bottomY = unskewedBounds.y + unskewedBounds.height;
		int topOffset = (int) Math.round(offsetAt(topY));
		int bottomOffset = (int) Math.round(offsetAt(bottomY));
		return new Polygon(
			new int[] {
				unskewedBounds.x + topOffset,
				unskewedBounds.x + unskewedBounds.width + topOffset,
				unskewedBounds.x + unskewedBounds.width + bottomOffset,
				unskewedBounds.x + bottomOffset
			},
			new int[] {topY, topY, bottomY, bottomY},
			4);
	}

	private Rectangle enclosingBounds()
	{
		double topOffset = offsetAt(unskewedBounds.y);
		double bottomOffset = offsetAt(unskewedBounds.y + unskewedBounds.height);
		double minimumOffset = Math.min(topOffset, bottomOffset);
		double maximumOffset = Math.max(topOffset, bottomOffset);
		int left = (int) Math.floor(unskewedBounds.x + minimumOffset);
		int right = (int) Math.ceil(unskewedBounds.x + unskewedBounds.width + maximumOffset);
		return new Rectangle(left, unskewedBounds.y, Math.max(1, right - left), unskewedBounds.height);
	}
}

package com.kierenboal.npcsnap.rendering;

import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Client;
import net.runelite.api.GraphicsObject;
import net.runelite.api.Perspective;
import net.runelite.api.gameval.SpotanimID;

public final class BillboardEffectGeometry
{
	private BillboardEffectGeometry()
	{
	}

	public static int actorSpotVerticalOffset(ActorSpotAnim spotAnimation)
	{
		if (spotAnimation == null)
		{
			return 0;
		}

		// Binding impacts are drawn around the actor's feet in the client. Their
		// model origin is not a reliable ground point, so the caller aligns the
		// lowest visible sprite pixel to the actor's base instead.
		if (isGroundContactEffect(spotAnimation))
		{
			return 0;
		}

		// The spot animation is anchored to the actor's world location. Its own
		// height is the displacement; adding actor animation height counts it twice.
		return Math.max(0, spotAnimation.getHeight());
	}

	public static VerticalAnchor actorSpotVerticalAnchor(ActorSpotAnim spotAnimation)
	{
		return isGroundContactEffect(spotAnimation) ? VerticalAnchor.GROUND_CONTACT : VerticalAnchor.BOTTOM;
	}

	public static boolean isGroundContactEffect(ActorSpotAnim spotAnimation)
	{
		if (spotAnimation == null)
		{
			return false;
		}

		int id = spotAnimation.getId();
		return id == SpotanimID.BIND_IMPACT
			|| id == SpotanimID.SNARE_IMPACT
			|| id == SpotanimID.ENTANGLE_IMPACT;
	}

	public static int graphicsVerticalOffset(Client client, GraphicsObject object)
	{
		return (int) Math.round(BillboardDepthCalculator.worldHeight(
			Perspective.getTileHeight(client, object.getLocation(), object.getLevel()), object.getZ()));
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Color;
import java.awt.Rectangle;

public final class BillboardFaceRasterizer
{
	private BillboardFaceRasterizer()
	{
	}

	public static void rasterizeTexturedFace(
		int[] imagePixels,
		int imageWidth,
		int imageHeight,
		Rectangle imageBounds,
		double qualityScale,
		FaceDraw face,
		int colorBands)
	{
		TextureSample textureSample = face.getTextureSample();
		if (textureSample == null)
		{
			return;
		}

		float x0 = scaleCoordinate(face.x0, imageBounds.x, qualityScale);
		float y0 = scaleCoordinate(face.y0, imageBounds.y, qualityScale);
		float x1 = scaleCoordinate(face.x1, imageBounds.x, qualityScale);
		float y1 = scaleCoordinate(face.y1, imageBounds.y, qualityScale);
		float x2 = scaleCoordinate(face.x2, imageBounds.x, qualityScale);
		float y2 = scaleCoordinate(face.y2, imageBounds.y, qualityScale);

		float area = BillboardTriangleRasterizer.edge(x0, y0, x1, y1, x2, y2);
		if (Math.abs(area) < 1.0e-6f)
		{
			return;
		}

		int minX = BillboardTriangleRasterizer.clampRasterCoordinate((int) Math.floor(Math.min(x0, Math.min(x1, x2))), imageWidth);
		int maxX = BillboardTriangleRasterizer.clampRasterCoordinate((int) Math.ceil(Math.max(x0, Math.max(x1, x2))), imageWidth);
		int minY = BillboardTriangleRasterizer.clampRasterCoordinate((int) Math.floor(Math.min(y0, Math.min(y1, y2))), imageHeight);
		int maxY = BillboardTriangleRasterizer.clampRasterCoordinate((int) Math.ceil(Math.max(y0, Math.max(y1, y2))), imageHeight);
		if (minX > maxX || minY > maxY)
		{
			return;
		}

		Color shade = NpcSnapColorBanding.snapToRamp(face.getColor(), colorBands);
		TextureUvs textureUvs = face.getTextureUvs();
		float inverseArea = 1.0f / area;
		float w0StepX = (y2 - y1) * inverseArea;
		float w1StepX = (y0 - y2) * inverseArea;
		float sampleX = minX + 0.5f;
		float rowW0 = BillboardTriangleRasterizer.edge(x1, y1, x2, y2, sampleX, minY + 0.5f) * inverseArea;
		float rowW1 = BillboardTriangleRasterizer.edge(x2, y2, x0, y0, sampleX, minY + 0.5f) * inverseArea;
		float w0StepY = (x1 - x2) * inverseArea;
		float w1StepY = (x2 - x0) * inverseArea;
		for (int y = minY; y <= maxY; y++)
		{
			int row = y * imageWidth;
			float w0 = rowW0;
			float w1 = rowW1;
			for (int x = minX; x <= maxX; x++)
			{
				float w2 = 1.0f - w0 - w1;
				if (w0 >= 0f && w1 >= 0f && w2 >= 0f)
				{
					float u = (float) BillboardGeometryUtils.wrapUnit((w0 * textureUvs.u0) + (w1 * textureUvs.u1) + (w2 * textureUvs.u2) + textureSample.uOffset);
					float v = (float) BillboardGeometryUtils.wrapUnit((w0 * textureUvs.v0) + (w1 * textureUvs.v1) + (w2 * textureUvs.v2) + textureSample.vOffset);
					int textureX = Math.min(textureSample.entry.width - 1, (int) (u * textureSample.entry.width));
					int textureY = Math.min(textureSample.entry.height - 1, (int) (v * textureSample.entry.height));
					int samplePixel = textureSample.entry.pixels[(textureY * textureSample.entry.width) + textureX];
					if ((samplePixel >>> 24) != 0 || (samplePixel & 0xFFFFFF) != 0)
					{
						int shadedPixel = BillboardColorUtils.modulateTexturePixel(samplePixel, shade, colorBands);
						int pixelIndex = row + x;
						imagePixels[pixelIndex] = BillboardTriangleRasterizer.blendPixel(imagePixels[pixelIndex], shadedPixel);
					}
				}

				w0 += w0StepX;
				w1 += w1StepX;
			}
			rowW0 += w0StepY;
			rowW1 += w1StepY;
		}
	}

	public static void rasterizeSolidFace(
		int[] imagePixels,
		int imageWidth,
		int imageHeight,
		Rectangle imageBounds,
		double qualityScale,
		FaceDraw face,
		int argb)
	{
		BillboardTriangleRasterizer.rasterizeSolidTriangle(
			imagePixels,
			imageWidth,
			imageHeight,
			scaleCoordinate(face.x0, imageBounds.x, qualityScale),
			scaleCoordinate(face.y0, imageBounds.y, qualityScale),
			scaleCoordinate(face.x1, imageBounds.x, qualityScale),
			scaleCoordinate(face.y1, imageBounds.y, qualityScale),
			scaleCoordinate(face.x2, imageBounds.x, qualityScale),
			scaleCoordinate(face.y2, imageBounds.y, qualityScale),
			argb
		);
	}

	private static float scaleCoordinate(int coordinate, int origin, double qualityScale)
	{
		return (float) ((coordinate - origin) * qualityScale);
	}
}

package com.kierenboal.npcsnap.rendering;

import com.kierenboal.npcsnap.occlusion.BillboardOcclusionMask;
import com.kierenboal.npcsnap.state.BillboardPerformanceMetrics;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.Arrays;
import net.runelite.api.TileObject;

public final class BillboardFrameBuffer
{
	public interface DepthSurfaceFactory
	{
		BillboardDepthSurface create(PreparedBillboardDraw draw);
	}

	private static final int DEBUG_OCCLUDED_PIXEL = new Color(255, 32, 32, 150).getRGB();

	private final BillboardOcclusionMask occlusionMask;
	private final BillboardPerformanceMetrics performanceMetrics;
	private final DepthSurfaceFactory depthSurfaceFactory;
	private boolean[] rowHasDepth = new boolean[0];
	private double[] rowDepth = new double[0];
	private int[] sampleTransmittance = new int[0];
	private final BillboardProjectedQuad.Sample projectedSample = new BillboardProjectedQuad.Sample();
	private BufferedImage image;
	private int[] pixels = new int[0];
	private char[] paintOrder = new char[0];
	private int width;
	private int height;

	public BillboardFrameBuffer(
		BillboardOcclusionMask occlusionMask,
		BillboardPerformanceMetrics performanceMetrics,
		DepthSurfaceFactory depthSurfaceFactory)
	{
		this.occlusionMask = occlusionMask;
		this.performanceMetrics = performanceMetrics;
		this.depthSurfaceFactory = depthSurfaceFactory;
	}

	public void begin(int width, int height)
	{
		ensureCapacity(width, height);
		Arrays.fill(pixels, 0, width * height, 0);
		Arrays.fill(paintOrder, 0, width * height, (char) 0);
	}

	public BufferedImage image()
	{
		return image;
	}

	public void blit(
		PreparedBillboardDraw draw,
		int viewportX,
		int viewportY,
		int viewportWidth,
		int viewportHeight,
		boolean drawOccludedPixels)
	{
		if (draw == null || draw.image == null || draw.bounds == null || draw.bounds.isEmpty()
			|| !(draw.image.getRaster().getDataBuffer() instanceof DataBufferInt))
		{
			return;
		}

		int clipLeft = Math.max(draw.bounds.x, viewportX);
		int clipTop = Math.max(draw.bounds.y, viewportY);
		int clipRight = Math.min(draw.bounds.x + draw.bounds.width, viewportX + viewportWidth);
		int clipBottom = Math.min(draw.bounds.y + draw.bounds.height, viewportY + viewportHeight);
		if (!drawOccludedPixels)
		{
			// The water/ground plane is one row cutoff for this NPC. Skip entire
			// submerged rows before any per-pixel depth or alpha work.
			clipBottom = Math.min(clipBottom, draw.surfaceOcclusionRow);
		}
		if (clipLeft >= clipRight || clipTop >= clipBottom)
		{
			return;
		}

		int[] sourcePixels = ((DataBufferInt) draw.image.getRaster().getDataBuffer()).getData();
		int sourceWidth = draw.image.getWidth();
		int sourceHeight = draw.image.getHeight();
		BillboardDrawGeometry geometry = draw.geometry != null
			? draw.geometry
			: BillboardDrawGeometry.rectangular(draw.bounds);
		int drawWidth = geometry.unskewedBounds.width;
		BillboardProjectedQuad quad = geometry.projectedQuad;
		int drawPaintOrder = draw.paintOrder;
		TileObject ignoredTileObject = draw.occlusionIgnoredTileObject;
		BillboardDepthSurface billboardDepth = occlusionMask.coveredCellCount() > 0 ? depthSurfaceFactory.create(draw) : null;
		boolean hasActiveOcclusion = billboardDepth != null && billboardDepth.supportsWorldOcclusion();
		int clippedHeight = clipBottom - clipTop;
		if (hasActiveOcclusion)
		{
			ensureRowCapacity(clippedHeight);
			Arrays.fill(rowHasDepth, 0, clippedHeight, false);
		}

		long occlusionElapsedNanos = 0L;
		boolean measureOcclusion = performanceMetrics.isEnabled() && hasActiveOcclusion;
		int occlusionSampleStep = hasActiveOcclusion ? occlusionMask.sampleStep() : 0;
		if (occlusionSampleStep > 1 && sampleTransmittance.length < occlusionSampleStep)
		{
			sampleTransmittance = new int[occlusionSampleStep];
		}
		for (int y = clipTop; y < clipBottom; y++)
		{
			int sourceY = quad == null ? geometry.sourceYAt(y, sourceHeight) : 0;
			if (sourceY < 0 || sourceY >= sourceHeight)
			{
				continue;
			}
			int destinationRow = (y - viewportY) * viewportWidth;
			int sourceRow = sourceY * sourceWidth;
			// Translate whole pixel rows, preserving the same nearest-neighbour
			// sampling at every slope, including zero. Compute the shear once per row.
			int rowLeft = geometry.rowLeftAt(y);
			int clippedRow = y - clipTop;
			boolean belowSurface = y >= draw.surfaceOcclusionRow;
			boolean rowHasOcclusion = hasActiveOcclusion && occlusionMask.hasCoverageAt(y);
			long rowOcclusionStart = measureOcclusion && rowHasOcclusion ? System.nanoTime() : 0L;
			BillboardOcclusionMask.CellResult cachedSampleResult = BillboardOcclusionMask.CellResult.VISIBLE;
			int cachedSampleX = Integer.MIN_VALUE;
			int cachedSampleStartX = 0;
			for (int x = clipLeft; x < clipRight; x++)
			{
				int destinationIndex = destinationRow + (x - viewportX);
				if (paintOrder[destinationIndex] > drawPaintOrder)
				{
					continue;
				}

				int sourceX;
				if (quad != null)
				{
					if (!quad.sample(x + 0.5d, y + 0.5d, projectedSample))
					{
						continue;
					}
					sourceX = Math.min(sourceWidth - 1, (int) (projectedSample.u * sourceWidth));
					sourceY = Math.min(sourceHeight - 1, (int) (projectedSample.v * sourceHeight));
					sourceRow = sourceY * sourceWidth;
				}
				else
				{
					int rowX = x - rowLeft;
					if (rowX < 0 || rowX >= drawWidth)
					{
						continue;
					}
					sourceX = (int) (((long) rowX * sourceWidth) / drawWidth);
				}
				int sourcePixel = sourcePixels[sourceRow + sourceX];
				int sourceAlpha = (sourcePixel >>> 24) & 0xFF;
				if (sourceAlpha == 0)
				{
					continue;
				}
				if (belowSurface)
				{
					pixels[destinationIndex] = BillboardTriangleRasterizer.blendPixel(pixels[destinationIndex], DEBUG_OCCLUDED_PIXEL);
					continue;
				}

				if (rowHasOcclusion)
				{
					if (quad == null && !rowHasDepth[clippedRow])
					{
						rowDepth[clippedRow] = billboardDepth.depthAtRow(sourceHeight, y);
						rowHasDepth[clippedRow] = true;
					}
					double pixelDepth = quad != null ? projectedSample.depth : rowDepth[clippedRow];
					int transmittance;
					// A rotated plane varies in depth across the row. Do not reuse a
					// cell classification made at a different point on that plane.
					if (occlusionSampleStep > 1 && quad == null)
					{
						int sampleX = occlusionMask.sampleX(x);
						if (sampleX != cachedSampleX)
						{
							cachedSampleX = sampleX;
							cachedSampleResult = occlusionMask.classifySample(sampleX, y, pixelDepth, ignoredTileObject);
							if (cachedSampleResult == BillboardOcclusionMask.CellResult.REFINE)
							{
								occlusionMask.refinedSampleTransmittance(sampleX, y, pixelDepth, sampleTransmittance, ignoredTileObject);
								cachedSampleStartX = x - occlusionMask.sampleOffset(x);
							}
						}
						transmittance = cachedSampleResult == BillboardOcclusionMask.CellResult.OCCLUDED ? 0
							: cachedSampleResult == BillboardOcclusionMask.CellResult.REFINE
								? sampleTransmittance[x - cachedSampleStartX] : 255;
					}
					else
					{
						transmittance = occlusionMask.transmittanceAt(x, y, pixelDepth, ignoredTileObject);
					}
					if (transmittance == 0)
					{
						if (drawOccludedPixels)
						{
							pixels[destinationIndex] = BillboardTriangleRasterizer.blendPixel(pixels[destinationIndex], DEBUG_OCCLUDED_PIXEL);
						}
						continue;
					}
					if (transmittance < 255)
					{
						if (drawOccludedPixels)
						{
							pixels[destinationIndex] = BillboardTriangleRasterizer.blendPixel(
								pixels[destinationIndex], debugOcclusionPixel(transmittance));
						}
						sourcePixel = occlusionMask.tintPixel(x, y, pixelDepth, sourcePixel, ignoredTileObject);
					}
				}

				// Draws arrive nearest-to-farthest. The accumulated destination is therefore
				// in front of this source pixel and must be composited over it. Reversing the
				// blend arguments preserves transparent foreground layers instead of allowing
				// later, farther pixels to draw on top of or replace them.
				pixels[destinationIndex] = BillboardTriangleRasterizer.blendPixel(sourcePixel, pixels[destinationIndex]);
				if (sourceAlpha == 0xFF)
				{
					paintOrder[destinationIndex] = (char) drawPaintOrder;
				}
			}
			if (rowOcclusionStart > 0L)
			{
				occlusionElapsedNanos += System.nanoTime() - rowOcclusionStart;
			}
		}
		if (occlusionElapsedNanos > 0L)
		{
			performanceMetrics.addElapsed("Per-pixel occlusion checks", occlusionElapsedNanos);
		}
	}

	private static int debugOcclusionPixel(int transmittance)
	{
		int alpha = ((DEBUG_OCCLUDED_PIXEL >>> 24) & 0xFF) * (255 - transmittance) / 255;
		return (DEBUG_OCCLUDED_PIXEL & 0x00FFFFFF) | (alpha << 24);
	}

	private void ensureCapacity(int width, int height)
	{
		if (image != null && this.width == width && this.height == height)
		{
			return;
		}
		image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		pixels = ((DataBufferInt) image.getRaster().getDataBuffer()).getData();
		paintOrder = new char[width * height];
		this.width = width;
		this.height = height;
	}

	private void ensureRowCapacity(int requiredHeight)
	{
		if (rowHasDepth.length < requiredHeight)
		{
			rowHasDepth = new boolean[requiredHeight];
			rowDepth = new double[requiredHeight];
		}
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Rectangle;
import java.util.List;
import net.runelite.api.Model;
import net.runelite.api.Point;
import net.runelite.api.Perspective;

public final class BillboardGeometryUtils
{
	private static final int MAX_SOURCE_BILLBOARD_SIZE = 4096;
	private static final int MAX_SOURCE_BILLBOARD_COORDINATE = 32768;
	private static final int MAX_DRAW_BILLBOARD_SIZE = 8192;
	private static final int MAX_CANVAS_COORDINATE = 1_000_000;
	private static final double MAX_PROJECTION_SHEAR_SLOPE = 0.20d;
	private static final double MIN_VERTICAL_PROJECTION = 0.15d;
	private static final double FULL_VERTICAL_PROJECTION = 0.50d;

	private BillboardGeometryUtils()
	{
	}

	public static Rectangle expandedBounds(Rectangle bounds, int padding)
	{
		if (bounds == null || padding <= 0)
		{
			return bounds;
		}

		return new Rectangle(bounds.x - padding, bounds.y - padding, bounds.width + (padding * 2), bounds.height + (padding * 2));
	}

	public static boolean isUsableSourceBounds(Rectangle bounds)
	{
		return bounds != null
			&& bounds.width > 0
			&& bounds.height > 0
			&& bounds.width <= MAX_SOURCE_BILLBOARD_SIZE
			&& bounds.height <= MAX_SOURCE_BILLBOARD_SIZE
			&& Math.abs(bounds.x) <= MAX_SOURCE_BILLBOARD_COORDINATE
			&& Math.abs(bounds.y) <= MAX_SOURCE_BILLBOARD_COORDINATE;
	}

	public static boolean isUsableDistance(double distance)
	{
		return Double.isFinite(distance) && distance >= 1.0d;
	}

	public static int scaledSize(int sourceSize, double scale)
	{
		if (!Double.isFinite(scale) || scale <= 0.0d)
		{
			return -1;
		}

		double scaled = sourceSize * scale;
		if (!Double.isFinite(scaled) || scaled <= 0.0d || scaled > MAX_DRAW_BILLBOARD_SIZE)
		{
			return -1;
		}

		return Math.max(1, (int) Math.round(scaled));
	}

	public static int projectedHeight(Point basePoint, Point topPoint)
	{
		if (basePoint == null || topPoint == null)
		{
			return 0;
		}

		long height = Math.abs((long) basePoint.getY() - topPoint.getY());
		if (height > MAX_DRAW_BILLBOARD_SIZE)
		{
			return -1;
		}

		return (int) height;
	}

	public static int aspectWidth(Rectangle bounds, int targetHeight)
	{
		if (targetHeight <= 0 || bounds.height <= 0)
		{
			return -1;
		}

		double width = bounds.width * (targetHeight / (double) bounds.height);
		if (!Double.isFinite(width) || width <= 0.0d || width > MAX_DRAW_BILLBOARD_SIZE)
		{
			return -1;
		}

		return Math.max(1, (int) Math.round(width));
	}

	/**
	 * Place an orthographic sprite at its model origin using RuneLite's canvas
	 * scale and depth at that same origin. Using an animated model's height to
	 * choose the scale makes even a cached frame breathe as the animation runs.
	 */
	public static Rectangle projectedDrawBounds(Rectangle imageBounds, BillboardCanvasPoint origin, double canvasScale)
	{
		if (imageBounds == null || imageBounds.isEmpty() || origin == null
			|| !isUsableDistance(origin.depth) || !Double.isFinite(origin.x) || !Double.isFinite(origin.y))
		{
			return null;
		}
		double scale = canvasScale / origin.depth;
		int width = scaledSize(imageBounds.width, scale);
		int height = scaledSize(imageBounds.height, scale);
		if (!isUsableDrawSize(width, height))
		{
			return null;
		}
		int x = (int) Math.round(origin.x + imageBounds.x * (width / (double) imageBounds.width));
		int y = (int) Math.round(origin.y + imageBounds.y * (height / (double) imageBounds.height));
		return isUsableCanvasCoordinate(x) && isUsableCanvasCoordinate(y)
			? new Rectangle(x, y, width, height)
			: null;
	}

	/**
	 * Follow the projected world-up direction without fitting the animated model.
	 * Inputs are the screen derivative divided by scale / depth, so zoom, model
	 * height and sprite padding cannot change the lean. Near an overhead view the
	 * projected up direction degenerates; smoothly fade it out before dividing.
	 */
	public static double projectionShearSlope(double verticalRight, double verticalUp)
	{
		if (!Double.isFinite(verticalRight) || !Double.isFinite(verticalUp)
			|| verticalUp <= MIN_VERTICAL_PROJECTION)
		{
			return 0.0d;
		}

		double fraction = Math.min(1.0d,
			(verticalUp - MIN_VERTICAL_PROJECTION) / (FULL_VERTICAL_PROJECTION - MIN_VERTICAL_PROJECTION));
		double fade = fraction * fraction * (3.0d - 2.0d * fraction);
		double slope = verticalRight / verticalUp;
		// A soft limit avoids a sudden change in speed as the camera pans.
		return fade * MAX_PROJECTION_SHEAR_SLOPE * Math.tanh(slope / MAX_PROJECTION_SHEAR_SLOPE);
	}

	public static boolean isUsableDrawSize(int width, int height)
	{
		return isUsableDrawDimension(width) && isUsableDrawDimension(height);
	}

	public static boolean isUsableCanvasCoordinate(int coordinate)
	{
		return Math.abs(coordinate) <= MAX_CANVAS_COORDINATE;
	}

	/**
	 * Transform model vertices into billboard space without allocating scratch arrays.
	 */
	public static void transformVertices(
		Model model,
		int yaw,
		int pitch,
		int offsetX,
		int offsetZ,
		float[] spriteX,
		float[] spriteY,
		float[] spriteDepth)
	{
		float[] verticesX = model.getVerticesX();
		float[] verticesY = model.getVerticesY();
		float[] verticesZ = model.getVerticesZ();
		int vertexCount = model.getVerticesCount();
		double yawSin = Perspective.SINE14[yaw] / 65536.0;
		double yawCos = Perspective.COSINE14[yaw] / 65536.0;
		int inversePitch = Math.floorMod(-pitch, BillboardAngleUtils.BILLBOARD_FULL_CIRCLE);
		double pitchSin = Perspective.SINE14[inversePitch] / 65536.0;
		double pitchCos = Perspective.COSINE14[inversePitch] / 65536.0;
		for (int i = 0; i < vertexCount; i++)
		{
			double modelX = verticesX[i] + offsetX;
			double modelZ = verticesZ[i] + offsetZ;
			double rotatedX = (modelX * yawCos) + (modelZ * yawSin);
			double rotatedZ = (modelZ * yawCos) - (modelX * yawSin);
			spriteX[i] = (float) rotatedX;
			spriteY[i] = (float) ((verticesY[i] * pitchCos) - (rotatedZ * pitchSin));
			spriteDepth[i] = (float) ((rotatedZ * pitchCos) + (verticesY[i] * pitchSin));
		}
	}

	public static boolean isBackFace(float[] spriteX, float[] spriteY, float[] spriteDepth, int a, int b, int c)
	{
		float abx = spriteX[b] - spriteX[a];
		float aby = spriteY[b] - spriteY[a];
		float acx = spriteX[c] - spriteX[a];
		float acy = spriteY[c] - spriteY[a];
		float normalZ = (abx * acy) - (aby * acx);
		if (Math.abs(normalZ) <= 1.0e-4f)
		{
			return true;
		}

		float abz = spriteDepth[b] - spriteDepth[a];
		float acz = spriteDepth[c] - spriteDepth[a];
		float normalDepth = (aby * acz) - (abz * acy);
		return normalZ >= 0.0f || !Float.isFinite(normalDepth);
	}

	public static Rectangle computeBounds(List<FaceDraw> faces)
	{
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int maxY = Integer.MIN_VALUE;

		for (FaceDraw face : faces)
		{
			minX = Math.min(minX, Math.min(face.x0, Math.min(face.x1, face.x2)));
			minY = Math.min(minY, Math.min(face.y0, Math.min(face.y1, face.y2)));
			maxX = Math.max(maxX, Math.max(face.x0, Math.max(face.x1, face.x2)));
			maxY = Math.max(maxY, Math.max(face.y0, Math.max(face.y1, face.y2)));
		}

		if (minX == Integer.MAX_VALUE)
		{
			return new Rectangle();
		}

		return new Rectangle(minX, minY, Math.max(1, (maxX - minX) + 1), Math.max(1, (maxY - minY) + 1));
	}

	public static double wrapUnit(double coordinate)
	{
		double wrapped = coordinate - Math.floor(coordinate);
		return wrapped < 0.0d ? wrapped + 1.0d : wrapped;
	}

	private static boolean isUsableDrawDimension(int dimension)
	{
		return dimension > 0 && dimension <= MAX_DRAW_BILLBOARD_SIZE;
	}

}

package com.kierenboal.npcsnap.rendering;

import com.kierenboal.npcsnap.BillboardConstants;

import net.runelite.api.Model;

/**
 * Classifies models that need ground-plane billboard handling instead of the
 * ordinary vertical-plane handling.
 */
final class BillboardModelProfile
{
	private static final int MAX_LOW_PROFILE_MODEL_HEIGHT = BillboardConstants.LOCAL_TILE_SIZE / 4;
	private static final double MAX_LOW_PROFILE_VERTICAL_RATIO = 0.10d;

	private BillboardModelProfile()
	{
	}

	static boolean isLowProfile(Model model, int renderableModelHeight)
	{
		Bounds bounds = bounds(model);
		if (bounds == null)
		{
			return false;
		}

		if (renderableModelHeight >= 0 && renderableModelHeight <= MAX_LOW_PROFILE_MODEL_HEIGHT)
		{
			return true;
		}

		return bounds.verticalSpan < Math.max(2.0d, bounds.horizontalSpan * MAX_LOW_PROFILE_VERTICAL_RATIO);
	}

	static boolean supportsVerticalPlaneOcclusion(Model model)
	{
		Bounds bounds = bounds(model);
		return bounds != null
			&& bounds.verticalSpan >= Math.max(2.0d, bounds.horizontalSpan * MAX_LOW_PROFILE_VERTICAL_RATIO);
	}

	private static Bounds bounds(Model model)
	{
		if (model == null)
		{
			return null;
		}
		int vertexCount = model.getVerticesCount();
		if (vertexCount <= 0)
		{
			return null;
		}

		float[] verticesX = model.getVerticesX();
		float[] verticesY = model.getVerticesY();
		float[] verticesZ = model.getVerticesZ();
		if (verticesX == null || verticesY == null || verticesZ == null)
		{
			return null;
		}

		// RuneLite models may retain padded backing arrays. Only arrays shorter
		// than the advertised vertex count are inconsistent and unusable.
		if (verticesX.length < vertexCount || verticesY.length < vertexCount || verticesZ.length < vertexCount)
		{
			return null;
		}

		float minX = Float.POSITIVE_INFINITY;
		float minY = Float.POSITIVE_INFINITY;
		float minZ = Float.POSITIVE_INFINITY;
		float maxX = Float.NEGATIVE_INFINITY;
		float maxY = Float.NEGATIVE_INFINITY;
		float maxZ = Float.NEGATIVE_INFINITY;
		for (int i = 0; i < vertexCount; i++)
		{
			if (!Float.isFinite(verticesX[i]) || !Float.isFinite(verticesY[i]) || !Float.isFinite(verticesZ[i]))
			{
				return null;
			}

			minX = Math.min(minX, verticesX[i]);
			minY = Math.min(minY, verticesY[i]);
			minZ = Math.min(minZ, verticesZ[i]);
			maxX = Math.max(maxX, verticesX[i]);
			maxY = Math.max(maxY, verticesY[i]);
			maxZ = Math.max(maxZ, verticesZ[i]);
		}

		if (!Float.isFinite(minX) || !Float.isFinite(minY) || !Float.isFinite(minZ)
			|| !Float.isFinite(maxX) || !Float.isFinite(maxY) || !Float.isFinite(maxZ))
		{
			return null;
		}

		double verticalSpan = maxY - minY;
		double horizontalSpan = Math.max(maxX - minX, maxZ - minZ);
		if (!Double.isFinite(verticalSpan) || !Double.isFinite(horizontalSpan))
		{
			return null;
		}

		return new Bounds(verticalSpan, horizontalSpan);
	}

	private static final class Bounds
	{
		private final double verticalSpan;
		private final double horizontalSpan;

		private Bounds(double verticalSpan, double horizontalSpan)
		{
			this.verticalSpan = verticalSpan;
			this.horizontalSpan = horizontalSpan;
		}
	}
}

package com.kierenboal.npcsnap.rendering;

import net.runelite.api.Model;

public final class BillboardModelStateHash
{
	private BillboardModelStateHash()
	{
	}

	public static int hash(Model model)
	{
		if (model == null)
		{
			return 0;
		}

		int hash = 1;
		hash = (31 * hash) + model.getVerticesCount();
		hash = (31 * hash) + model.getModelHeight();
		hash = sampleFloatArrayHash(hash, model.getVerticesX());
		hash = sampleFloatArrayHash(hash, model.getVerticesY());
		hash = sampleFloatArrayHash(hash, model.getVerticesZ());
		hash = sampleByteArrayHash(hash, model.getFaceTransparencies());
		hash = (31 * hash) + Byte.toUnsignedInt(model.getOverrideAmount());
		hash = (31 * hash) + Byte.toUnsignedInt(model.getOverrideHue());
		hash = (31 * hash) + Byte.toUnsignedInt(model.getOverrideSaturation());
		hash = (31 * hash) + Byte.toUnsignedInt(model.getOverrideLuminance());
		return hash;
	}

	private static int sampleFloatArrayHash(int seed, float[] values)
	{
		if (values == null)
		{
			return (31 * seed) - 1;
		}

		int hash = (31 * seed) + values.length;
		if (values.length > 0)
		{
			hash = (31 * hash) + Float.floatToIntBits(values[0]);
			hash = (31 * hash) + Float.floatToIntBits(values[values.length / 2]);
			hash = (31 * hash) + Float.floatToIntBits(values[values.length - 1]);
		}
		return hash;
	}

	private static int sampleByteArrayHash(int seed, byte[] values)
	{
		if (values == null)
		{
			return (31 * seed) - 1;
		}

		int hash = (31 * seed) + values.length;
		if (values.length > 0)
		{
			hash = (31 * hash) + values[0];
			hash = (31 * hash) + values[values.length / 2];
			hash = (31 * hash) + values[values.length - 1];
		}
		return hash;
	}
}

package com.kierenboal.npcsnap.rendering;

import com.kierenboal.npcsnap.NpcSnapConfig;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Projectile;
import net.runelite.api.coords.LocalPoint;

public final class BillboardOrientationCalculator
{
	private final Client client;
	private final NpcSnapConfig config;

	public BillboardOrientationCalculator(Client client, NpcSnapConfig config)
	{
		this.client = client;
		this.config = config;
	}

	public int relativeYaw()
	{
		return snappedYaw(cameraYaw());
	}

	public int relativeYaw(Actor actor)
	{
		return relativeYaw(actor, actor != null ? actor.getCurrentOrientation() : 0);
	}

	public int relativeYaw(Actor actor, int actorOrientation)
	{
		int rawRelativeYaw = cameraYaw() + BillboardAngleUtils.angleToBillboardUnits(actorOrientation, BillboardAngleUtils.ACTOR_FULL_CIRCLE);
		if (shouldCombatSnap(actor))
		{
			return BillboardAngleUtils.combatYaw(rawRelativeYaw);
		}

		return snappedYaw(rawRelativeYaw);
	}

	public int relativeYaw(Projectile projectile)
	{
		return snappedYaw(cameraYaw() + projectileYaw(projectile));
	}

	/** Body-only correction: spot animations and exported angles retain their existing yaw. */
	public int relativeActorBodyYaw(Actor actor, int actorOrientation, LocalPoint mainWorldLocation)
	{
		int yaw = actorBodyRawYaw(actorOrientation, mainWorldLocation);
		return shouldCombatSnap(actor) ? BillboardAngleUtils.combatYaw(yaw) : snappedYaw(yaw);
	}

	public int actorBodyRawYaw(int actorOrientation, LocalPoint mainWorldLocation)
	{
		int viewYaw = cameraYaw();
		if (!config.ignoreCameraAwareRotation() && mainWorldLocation != null)
		{
			double cameraX = client.isGpu() ? client.getCameraFpX() : client.getCameraX();
			double cameraY = client.isGpu() ? client.getCameraFpY() : client.getCameraY();
			double dx = mainWorldLocation.getX() - cameraX;
			double dy = mainWorldLocation.getY() - cameraY;
			if (Double.isFinite(dx) && Double.isFinite(dy) && Math.hypot(dx, dy) > 1.0d)
			{
				// Camera right = x*cos(yaw) + y*sin(yaw), so the viewing
				// direction that centers this actor has yaw = atan2(-dx, dy).
				viewYaw = Math.floorMod((int) Math.round(Math.atan2(-dx, dy)
					* BillboardAngleUtils.BILLBOARD_FULL_CIRCLE / (2.0d * Math.PI)),
					BillboardAngleUtils.BILLBOARD_FULL_CIRCLE);
			}
		}
		return Math.floorMod(viewYaw + BillboardAngleUtils.angleToBillboardUnits(actorOrientation,
			BillboardAngleUtils.ACTOR_FULL_CIRCLE), BillboardAngleUtils.BILLBOARD_FULL_CIRCLE);
	}

	public int relativeGroundItemYaw()
	{
		return snappedYaw(cameraYaw());
	}

	public int relativePitch()
	{
		return relativePitch(false);
	}

	public int relativePitch(boolean lowProfile)
	{
		int rawPitch = cameraPitch();
		if (!config.enableRotationSnapping())
		{
			return -rawPitch;
		}

		int minimumPitch = lowProfile ? BillboardAngleUtils.GROUND_ITEM_MIN_PITCH : 0;
		int snappedPitch = BillboardAngleUtils.snapPitchByAngles(rawPitch, minimumPitch, config.numberOfPitchRotationAngles());
		// Invert because model pitch is applied opposite to camera pitch.
		return -snappedPitch;
	}

	public int relativePitch(Actor actor)
	{
		return relativePitch(actor, false);
	}

	public int relativePitch(Actor actor, boolean lowProfile)
	{
		if (shouldCombatSnap(actor))
		{
			return 0;
		}

		return relativePitch(lowProfile);
	}

	public int relativeGroundItemPitch()
	{
		return relativePitch(true);
	}

	private int snappedYaw(int rawRelativeYaw)
	{
		if (!config.enableRotationSnapping())
		{
			return Math.floorMod(rawRelativeYaw, BillboardAngleUtils.BILLBOARD_FULL_CIRCLE);
		}

		return BillboardAngleUtils.snapJauByAngles(rawRelativeYaw, config.numberOfYawRotationAngles());
	}

	private int cameraYaw()
	{
		return BillboardAngleUtils.angleToBillboardUnits(client.getCameraYaw(), BillboardAngleUtils.CAMERA_FULL_CIRCLE);
	}

	private int cameraPitch()
	{
		int pitch = BillboardAngleUtils.angleToBillboardUnits(client.getCameraPitch(), BillboardAngleUtils.CAMERA_FULL_CIRCLE);
		return Math.max(0, Math.min(BillboardAngleUtils.MAX_PITCH, pitch));
	}

	private static int projectileYaw(Projectile projectile)
	{
		return projectile == null
			? 0
			: BillboardAngleUtils.angleToBillboardUnits(projectile.getOrientation(), BillboardAngleUtils.PROJECTILE_FULL_CIRCLE);
	}

	private boolean shouldCombatSnap(Actor actor)
	{
		return config.enableBillboardCombatSnapping() && isMutuallyInteracting(actor);
	}

	private static boolean isMutuallyInteracting(Actor actor)
	{
		if (actor == null)
		{
			return false;
		}

		Actor interacting = actor.getInteracting();
		return interacting != null && interacting.getInteracting() == actor;
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.Arrays;

public final class BillboardOutlineRenderer
{
	private static final int[] CARDINAL_X = {-1, 1, 0, 0};
	private static final int[] CARDINAL_Y = {0, 0, -1, 1};
	private static final int[] ADJACENT_X = {-1, 0, 1, -1, 1, -1, 0, 1};
	private static final int[] ADJACENT_Y = {-1, -1, -1, 0, 0, 1, 1, 1};
	private static final double SHADOW_DARKEN_FACTOR = 0.67d;
	private static final double HIGHLIGHT_BRIGHTEN_FACTOR = 1.33d;
	private static final int SPRITE_SHADOW_ALPHA = 80;
	private static final int SPRITE_SHADOW_MIN_SPREAD = 2;
	public static final double DEFAULT_SPRITE_SHADOW_HEIGHT_RATIO = 0.10d;

	private BillboardOutlineRenderer()
	{
	}

	public static void applyOutline(
		BufferedImage image,
		boolean highlightOutline,
		boolean shadowOutline,
		boolean solidOutline,
		boolean spriteShadow,
		boolean highlightInline,
		boolean shadowInline,
		boolean solidInline,
		Color solidOutlineColor)
	{
		applyOutline(image, new Scratch(), highlightOutline, shadowOutline, solidOutline, spriteShadow, highlightInline, shadowInline, solidInline, solidOutlineColor);
	}

	public static void applyOutline(
		BufferedImage image,
		Scratch scratch,
		boolean highlightOutline,
		boolean shadowOutline,
		boolean solidOutline,
		boolean spriteShadow,
		boolean highlightInline,
		boolean shadowInline,
		boolean solidInline,
		Color solidOutlineColor)
	{
		applyOutline(
			image, scratch, highlightOutline, shadowOutline, solidOutline, spriteShadow,
			highlightInline, shadowInline, solidInline, solidOutlineColor,
			DEFAULT_SPRITE_SHADOW_HEIGHT_RATIO);
	}

	public static void applyOutline(
		BufferedImage image,
		Scratch scratch,
		boolean highlightOutline,
		boolean shadowOutline,
		boolean solidOutline,
		boolean spriteShadow,
		boolean highlightInline,
		boolean shadowInline,
		boolean solidInline,
		Color solidOutlineColor,
		double spriteShadowHeightRatio)
	{
		int width = image.getWidth();
		int height = image.getHeight();
		if (width <= 0 || height <= 0 || (!highlightOutline && !shadowOutline && !solidOutline && !spriteShadow && !highlightInline && !shadowInline && !solidInline))
		{
			return;
		}

		if (!(image.getRaster().getDataBuffer() instanceof DataBufferInt))
		{
			return;
		}

		int pixelCount = width * height;
		int[] sourcePixels = ((DataBufferInt) image.getRaster().getDataBuffer()).getData();
		scratch.ensureCapacity(pixelCount);
		System.arraycopy(sourcePixels, 0, scratch.resultPixels, 0, pixelCount);
		populateBoundaryMasks(sourcePixels, width, height, scratch);

		// Build the shadow behind the edge effects. The shadow occupies transparent
		// pixels near the feet, so drawing it last would replace the coloured
		// exterior outline at the sprite's original silhouette.
		if (spriteShadow)
		{
			applySpriteShadow(sourcePixels, scratch.resultPixels, width, height, spriteShadowHeightRatio);
		}

		applyInteriorBoundary(sourcePixels, scratch.resultPixels, width, height, scratch.exteriorOpaqueBoundary, false, false, solidInline, solidOutlineColor);
		applyInteriorBoundary(sourcePixels, scratch.resultPixels, width, height, scratch.exteriorOpaqueBoundary, false, shadowInline, false, solidOutlineColor);
		applyInteriorBoundary(sourcePixels, scratch.resultPixels, width, height, scratch.exteriorOpaqueBoundary, highlightInline, false, false, solidOutlineColor);
		applyExteriorBoundary(sourcePixels, scratch.resultPixels, width, height, scratch.exteriorTransparentBoundary, false, false, solidOutline, solidOutlineColor);
		applyExteriorBoundary(sourcePixels, scratch.resultPixels, width, height, scratch.exteriorTransparentBoundary, false, shadowOutline, false, solidOutlineColor);
		applyExteriorBoundary(sourcePixels, scratch.resultPixels, width, height, scratch.exteriorTransparentBoundary, highlightOutline, false, false, solidOutlineColor);
		System.arraycopy(scratch.resultPixels, 0, sourcePixels, 0, pixelCount);
	}

	public static int[] captureExteriorBoundaryIndices(BufferedImage image, Scratch scratch)
	{
		if (image == null)
		{
			return new int[0];
		}

		int width = image.getWidth();
		int height = image.getHeight();
		if (width <= 0 || height <= 0)
		{
			return new int[0];
		}

		if (!(image.getRaster().getDataBuffer() instanceof DataBufferInt))
		{
			return new int[0];
		}

		int[] sourcePixels = ((DataBufferInt) image.getRaster().getDataBuffer()).getData();
		int pixelCount = width * height;
		scratch.ensureCapacity(pixelCount);
		populateBoundaryMasks(sourcePixels, width, height, scratch);
		int count = 0;
		for (int index = 0; index < pixelCount; index++)
		{
			if (scratch.exteriorTransparentBoundary[index])
			{
				count++;
			}
		}

		int[] indices = new int[count];
		int next = 0;
		for (int index = 0; index < pixelCount; index++)
		{
			if (scratch.exteriorTransparentBoundary[index])
			{
				indices[next++] = index;
			}
		}

		return indices;
	}

	public static void drawDynamicOutline(Graphics2D graphics, BufferedImage image, Rectangle drawRect, int[] exteriorBoundaryIndices, Color outlineColor)
	{
		if (graphics == null || image == null || drawRect == null || outlineColor == null || outlineColor.getAlpha() == 0 || exteriorBoundaryIndices == null || exteriorBoundaryIndices.length == 0)
		{
			return;
		}

		int width = image.getWidth();
		int height = image.getHeight();
		if (width <= 0 || height <= 0 || drawRect.width <= 0 || drawRect.height <= 0)
		{
			return;
		}

		graphics.setColor(outlineColor);
		for (int index : exteriorBoundaryIndices)
		{
			int x = index % width;
			int y = index / width;
			int minX = drawRect.x + (int) Math.floor((x * (double) drawRect.width) / width);
			int maxX = drawRect.x + (int) Math.ceil(((x + 1) * (double) drawRect.width) / width);
			int minY = drawRect.y + (int) Math.floor((y * (double) drawRect.height) / height);
			int maxY = drawRect.y + (int) Math.ceil(((y + 1) * (double) drawRect.height) / height);
			if (maxX <= minX || maxY <= minY)
			{
				continue;
			}

			graphics.fillRect(minX, minY, maxX - minX, maxY - minY);
		}
	}

	public static final class Scratch
	{
		private int[] resultPixels = new int[0];
		private boolean[] visited = new boolean[0];
		private boolean[] exteriorTransparentBoundary = new boolean[0];
		private boolean[] exteriorOpaqueBoundary = new boolean[0];
		private int[] queue = new int[0];
		private int queueHead;
		private int queueTail;

		private void ensureCapacity(int capacity)
		{
			if (resultPixels.length >= capacity)
			{
				return;
			}

			resultPixels = new int[capacity];
			visited = new boolean[capacity];
			exteriorTransparentBoundary = new boolean[capacity];
			exteriorOpaqueBoundary = new boolean[capacity];
			queue = new int[capacity];
		}

		private void clearQueue()
		{
			queueHead = 0;
			queueTail = 0;
		}

		private void enqueue(int index)
		{
			queue[queueTail++] = index;
		}

		private boolean hasQueuedPixels()
		{
			return queueHead < queueTail;
		}

		private int dequeue()
		{
			return queue[queueHead++];
		}
	}

	private static void applyExteriorBoundary(
		int[] sourcePixels,
		int[] resultPixels,
		int width,
		int height,
		boolean[] exteriorTransparentBoundary,
		boolean highlightOutline,
		boolean shadowOutline,
		boolean solidOutline,
		Color solidOutlineColor)
	{
		for (int index = 0; index < exteriorTransparentBoundary.length; index++)
		{
			if (!exteriorTransparentBoundary[index])
			{
				continue;
			}

			int x = index % width;
			int y = index / width;
			int outlineArgb = highlightOutline
				? highlightOutlineColor(sourcePixels, width, height, x, y)
				: shadowOutline
					? shadowOutlineColor(sourcePixels, width, height, x, y)
					: solidOutline ? solidOutlineColor.getRGB() : 0;
			if (outlineArgb != 0)
			{
				resultPixels[index] = outlineArgb;
			}
		}
	}

	private static void applyInteriorBoundary(
		int[] sourcePixels,
		int[] resultPixels,
		int width,
		int height,
		boolean[] exteriorOpaqueBoundary,
		boolean highlightInline,
		boolean shadowInline,
		boolean solidInline,
		Color solidOutlineColor)
	{
		for (int index = 0; index < exteriorOpaqueBoundary.length; index++)
		{
			if (!exteriorOpaqueBoundary[index])
			{
				continue;
			}

			int x = index % width;
			int y = index / width;
			int inlineArgb = highlightInline
				? highlightInlineColor(sourcePixels, width, height, x, y)
				: shadowInline
					? shadowInlineColor(sourcePixels, width, height, x, y)
					: solidInline ? solidOutlineColor.getRGB() : 0;
			if (inlineArgb != 0)
			{
				resultPixels[index] = inlineArgb;
			}
		}
	}

	private static void applySpriteShadow(
		int[] sourcePixels,
		int[] resultPixels,
		int width,
		int height,
		double shadowHeightRatio)
	{
		double boundedHeightRatio = Double.isFinite(shadowHeightRatio)
			? Math.max(0.0d, Math.min(1.0d, shadowHeightRatio))
			: DEFAULT_SPRITE_SHADOW_HEIGHT_RATIO;
		int shadowBandHeight = Math.max(1, (int) Math.ceil(height * boundedHeightRatio));
		int shadowBandStartY = Math.max(0, height - shadowBandHeight);
		int minX = width;
		int maxX = -1;
		int[] columnBottoms = new int[width];
		Arrays.fill(columnBottoms, -1);

		for (int y = shadowBandStartY; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				int argb = sourcePixels[(y * width) + x];
				if (!isOpaque(argb))
				{
					continue;
				}

				minX = Math.min(minX, x);
				maxX = Math.max(maxX, x);
				columnBottoms[x] = Math.max(columnBottoms[x], y);
			}
		}

		if (maxX < minX)
		{
			return;
		}

		int verticalSpread = Math.max(1, shadowBandHeight);
		int horizontalSpread = Math.max(SPRITE_SHADOW_MIN_SPREAD, verticalSpread + 1);
		for (int x = Math.max(0, minX - horizontalSpread); x <= Math.min(width - 1, maxX + horizontalSpread); x++)
		{
			for (int y = shadowBandStartY; y < height; y++)
			{
				int index = (y * width) + x;
				if (isOpaque(sourcePixels[index]))
				{
					continue;
				}

				int alpha = spriteShadowAlpha(columnBottoms, width, x, y, shadowBandStartY, verticalSpread, horizontalSpread);
				if (alpha <= 0)
				{
					continue;
				}

				resultPixels[index] = blendShadow(resultPixels[index], alpha);
			}
		}
	}

	private static int spriteShadowAlpha(
		int[] columnBottoms,
		int width,
		int x,
		int y,
		int shadowBandStartY,
		int verticalSpread,
		int horizontalSpread)
	{
		double strongest = 0.0d;
		for (int sampleX = Math.max(0, x - horizontalSpread); sampleX <= Math.min(width - 1, x + horizontalSpread); sampleX++)
		{
			int bottomY = columnBottoms[sampleX];
			if (bottomY < shadowBandStartY || y < bottomY)
			{
				continue;
			}

			int dx = Math.abs(x - sampleX);
			int dy = y - bottomY;
			if (dy > verticalSpread)
			{
				continue;
			}

			double horizontalAllowance = horizontalSpread * (1.0d - (dy / (double) (verticalSpread + 1)));
			if (dx > horizontalAllowance)
			{
				continue;
			}

			double horizontalFactor = 1.0d - Math.min(1.0d, dx / Math.max(1.0d, horizontalAllowance));
			double verticalFactor = 1.0d - (dy / (double) (verticalSpread + 1));
			strongest = Math.max(strongest, horizontalFactor * verticalFactor);
		}

		return clampToByte((int) Math.round(SPRITE_SHADOW_ALPHA * strongest));
	}

	private static int blendShadow(int existingArgb, int alpha)
	{
		if (alpha <= 0)
		{
			return existingArgb;
		}

		int existingAlpha = (existingArgb >>> 24) & 0xFF;
		int blendedAlpha = Math.max(existingAlpha, alpha);
		return (blendedAlpha << 24);
	}

	private static void enqueueBorderTransparentPixels(int[] pixels, int width, int height, Scratch scratch)
	{
		for (int x = 0; x < width; x++)
		{
			enqueueTransparentPixel(pixels, width, 0, x, scratch);
			enqueueTransparentPixel(pixels, width, height - 1, x, scratch);
		}

		for (int y = 1; y < height - 1; y++)
		{
			enqueueTransparentPixel(pixels, width, y, 0, scratch);
			enqueueTransparentPixel(pixels, width, y, width - 1, scratch);
		}
	}

	private static void enqueueTransparentPixel(int[] pixels, int width, int y, int x, Scratch scratch)
	{
		int index = y * width + x;
		if (scratch.visited[index] || isOpaque(pixels[index]))
		{
			return;
		}

		scratch.visited[index] = true;
		scratch.enqueue(index);
	}

	private static int shadowOutlineColor(int[] pixels, int width, int height, int x, int y)
	{
		return darkenedAverageOpaqueNeighborColor(pixels, width, height, x, y);
	}

	private static int highlightOutlineColor(int[] pixels, int width, int height, int x, int y)
	{
		return brightenedAverageOpaqueNeighborColor(pixels, width, height, x, y);
	}

	private static int shadowInlineColor(int[] pixels, int width, int height, int x, int y)
	{
		return darkenedAverageOpaqueNeighborColor(pixels, width, height, x, y);
	}

	private static int highlightInlineColor(int[] pixels, int width, int height, int x, int y)
	{
		return brightenedAverageOpaqueNeighborColor(pixels, width, height, x, y);
	}

	private static int darkenedAverageOpaqueNeighborColor(int[] pixels, int width, int height, int x, int y)
	{
		int color = averageOpaqueNeighborColor(pixels, width, height, x, y);
		if (color == 0)
		{
			return 0;
		}

		int alpha = (color >>> 24) & 0xFF;
		int avgRed = darken((color >>> 16) & 0xFF);
		int avgGreen = darken((color >>> 8) & 0xFF);
		int avgBlue = darken(color & 0xFF);
		return (alpha << 24) | (avgRed << 16) | (avgGreen << 8) | avgBlue;
	}

	private static int brightenedAverageOpaqueNeighborColor(int[] pixels, int width, int height, int x, int y)
	{
		int color = averageOpaqueNeighborColor(pixels, width, height, x, y);
		if (color == 0)
		{
			return 0;
		}

		int alpha = (color >>> 24) & 0xFF;
		int avgRed = brighten((color >>> 16) & 0xFF);
		int avgGreen = brighten((color >>> 8) & 0xFF);
		int avgBlue = brighten(color & 0xFF);
		return (alpha << 24) | (avgRed << 16) | (avgGreen << 8) | avgBlue;
	}

	private static int averageOpaqueNeighborColor(int[] pixels, int width, int height, int x, int y)
	{
		int alpha = 0;
		int red = 0;
		int green = 0;
		int blue = 0;
		int count = 0;
		for (int i = 0; i < ADJACENT_X.length; i++)
		{
			int neighborX = x + ADJACENT_X[i];
			int neighborY = y + ADJACENT_Y[i];
			if (!isInBounds(width, height, neighborX, neighborY))
			{
				continue;
			}

			int argb = pixels[(neighborY * width) + neighborX];
			if (!isOpaque(argb))
			{
				continue;
			}

			alpha += (argb >>> 24) & 0xFF;
			red += (argb >>> 16) & 0xFF;
			green += (argb >>> 8) & 0xFF;
			blue += argb & 0xFF;
			count++;
		}

		if (count == 0)
		{
			return 0;
		}

		int avgAlpha = clampToByte((int) Math.round(alpha / (double) count));
		int avgRed = clampToByte((int) Math.round(red / (double) count));
		int avgGreen = clampToByte((int) Math.round(green / (double) count));
		int avgBlue = clampToByte((int) Math.round(blue / (double) count));
		return (avgAlpha << 24) | (avgRed << 16) | (avgGreen << 8) | avgBlue;
	}

	private static boolean hasOpaqueNeighbor(int[] pixels, int width, int height, int x, int y)
	{
		for (int i = 0; i < CARDINAL_X.length; i++)
		{
			int neighborX = x + CARDINAL_X[i];
			int neighborY = y + CARDINAL_Y[i];
			if (!isInBounds(width, height, neighborX, neighborY))
			{
				continue;
			}

			if (isOpaque(pixels[(neighborY * width) + neighborX]))
			{
				return true;
			}
		}

		return false;
	}

	private static void markOpaqueNeighbors(int[] pixels, int width, int height, int x, int y, boolean[] exteriorOpaqueBoundary)
	{
		for (int i = 0; i < CARDINAL_X.length; i++)
		{
			int neighborX = x + CARDINAL_X[i];
			int neighborY = y + CARDINAL_Y[i];
			if (!isInBounds(width, height, neighborX, neighborY))
			{
				continue;
			}

			int index = (neighborY * width) + neighborX;
			if (isOpaque(pixels[index]))
			{
				exteriorOpaqueBoundary[index] = true;
			}
		}
	}

	private static int darken(double color)
	{
		return clampToByte((int) Math.round(color * SHADOW_DARKEN_FACTOR));
	}

	private static int brighten(double color)
	{
		return clampToByte((int) Math.round(color * HIGHLIGHT_BRIGHTEN_FACTOR));
	}

	private static int clampToByte(int value)
	{
		return Math.max(0, Math.min(255, value));
	}

	private static void populateBoundaryMasks(int[] sourcePixels, int width, int height, Scratch scratch)
	{
		int pixelCount = width * height;
		Arrays.fill(scratch.visited, 0, pixelCount, false);
		Arrays.fill(scratch.exteriorTransparentBoundary, 0, pixelCount, false);
		Arrays.fill(scratch.exteriorOpaqueBoundary, 0, pixelCount, false);
		scratch.clearQueue();

		enqueueBorderTransparentPixels(sourcePixels, width, height, scratch);
		while (scratch.hasQueuedPixels())
		{
			int index = scratch.dequeue();
			int x = index % width;
			int y = index / width;
			if (hasOpaqueNeighbor(sourcePixels, width, height, x, y))
			{
				scratch.exteriorTransparentBoundary[index] = true;
				markOpaqueNeighbors(sourcePixels, width, height, x, y, scratch.exteriorOpaqueBoundary);
			}

			for (int i = 0; i < CARDINAL_X.length; i++)
			{
				int nextX = x + CARDINAL_X[i];
				int nextY = y + CARDINAL_Y[i];
				if (!isInBounds(width, height, nextX, nextY))
				{
					continue;
				}

				int nextIndex = nextY * width + nextX;
				if (scratch.visited[nextIndex] || isOpaque(sourcePixels[nextIndex]))
				{
					continue;
				}

				scratch.visited[nextIndex] = true;
				scratch.enqueue(nextIndex);
			}
		}
	}

	private static boolean isOpaque(int argb)
	{
		return ((argb >>> 24) & 0xFF) != 0;
	}

	private static boolean isInBounds(int width, int height, int x, int y)
	{
		return x >= 0 && x < width && y >= 0 && y < height;
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public final class BillboardPaintOrder
{
	public static final long NO_PRIORITY_GROUP = Long.MIN_VALUE;

	private BillboardPaintOrder()
	{
	}

	public static <T> List<T> sort(List<Entry<T>> entries)
	{
		if (entries.isEmpty())
		{
			return new ArrayList<>();
		}

		int size = entries.size();
		int[] parent = new int[size];
		for (int i = 0; i < size; i++)
		{
			parent[i] = i;
		}

		for (int i = 0; i < size; i++)
		{
			Rectangle left = entries.get(i).bounds;
			if (left == null)
			{
				continue;
			}

			for (int j = i + 1; j < size; j++)
			{
				Rectangle right = entries.get(j).bounds;
				if (right != null && left.intersects(right))
				{
					union(parent, i, j);
				}
			}
		}

		List<Group<T>> groups = new ArrayList<>();
		for (int i = 0; i < size; i++)
		{
			if (find(parent, i) != i)
			{
				continue;
			}

			List<Entry<T>> groupEntries = new ArrayList<>();
			for (int j = 0; j < size; j++)
			{
				if (find(parent, j) == i)
				{
					groupEntries.add(entries.get(j));
				}
			}

			groupEntries.sort(BillboardPaintOrder::compareWithinGroup);
			groups.add(Group.of(groupEntries));
		}

		groups.sort(Comparator
			.comparingDouble(Group<T>::getDepth).reversed()
			.thenComparingInt(Group::getTopY)
			.thenComparingLong(Group::getStableOrder));

		List<T> ordered = new ArrayList<>(size);
		for (Group<T> group : groups)
		{
			for (Entry<T> entry : group.entries)
			{
				ordered.add(entry.value);
			}
		}

		return ordered;
	}

	private static <T> int compareWithinGroup(Entry<T> left, Entry<T> right)
	{
		if (left.priorityGroup != NO_PRIORITY_GROUP && left.priorityGroup == right.priorityGroup)
		{
			int byPriority = Integer.compare(left.renderPriority, right.renderPriority);
			if (byPriority != 0)
			{
				return byPriority;
			}
		}

		if (left.depthFirst || right.depthFirst)
		{
			int byDepth = Double.compare(right.depth, left.depth);
			if (byDepth != 0)
			{
				return byDepth;
			}
		}

		int byBottom = Integer.compare(left.screenBottomY, right.screenBottomY);
		if (byBottom != 0)
		{
			return byBottom;
		}

		int byDepth = Double.compare(right.depth, left.depth);
		if (byDepth != 0)
		{
			return byDepth;
		}

		return Long.compare(left.stableOrder, right.stableOrder);
	}

	private static int find(int[] parent, int index)
	{
		int root = index;
		while (parent[root] != root)
		{
			root = parent[root];
		}

		while (parent[index] != index)
		{
			int next = parent[index];
			parent[index] = root;
			index = next;
		}

		return root;
	}

	private static void union(int[] parent, int left, int right)
	{
		int leftRoot = find(parent, left);
		int rightRoot = find(parent, right);
		if (leftRoot != rightRoot)
		{
			parent[rightRoot] = leftRoot;
		}
	}

	public static final class Entry<T>
	{
		private final T value;
		private final Rectangle bounds;
		private final int renderPriority;
		private final long priorityGroup;
		private final int screenBottomY;
		private final double depth;
		private final boolean depthFirst;
		private final long stableOrder;

		public Entry(T value, Rectangle bounds, int renderPriority, long priorityGroup, int screenBottomY, double depth, long stableOrder)
		{
			this(value, bounds, renderPriority, priorityGroup, screenBottomY, depth, false, stableOrder);
		}

		public Entry(T value, Rectangle bounds, int renderPriority, long priorityGroup, int screenBottomY, double depth, boolean depthFirst, long stableOrder)
		{
			this.value = value;
			this.bounds = bounds;
			this.renderPriority = renderPriority;
			this.priorityGroup = priorityGroup;
			this.screenBottomY = screenBottomY;
			this.depth = depth;
			this.depthFirst = depthFirst;
			this.stableOrder = stableOrder;
		}
	}

	private static final class Group<T>
	{
		private final List<Entry<T>> entries;
		private final double depth;
		private final int topY;
		private final long stableOrder;

		private Group(List<Entry<T>> entries, double depth, int topY, long stableOrder)
		{
			this.entries = entries;
			this.depth = depth;
			this.topY = topY;
			this.stableOrder = stableOrder;
		}

		private static <T> Group<T> of(List<Entry<T>> entries)
		{
			double maxDepth = Double.NEGATIVE_INFINITY;
			int minTopY = Integer.MAX_VALUE;
			long minStableOrder = Long.MAX_VALUE;
			for (Entry<T> entry : entries)
			{
				maxDepth = Math.max(maxDepth, entry.depth);
				minTopY = Math.min(minTopY, entry.bounds != null ? entry.bounds.y : entry.screenBottomY);
				minStableOrder = Math.min(minStableOrder, entry.stableOrder);
			}

			return new Group<>(entries, maxDepth, minTopY, minStableOrder);
		}

		private double getDepth()
		{
			return depth;
		}

		private int getTopY()
		{
			return topY;
		}

		private long getStableOrder()
		{
			return stableOrder;
		}
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Polygon;
import java.awt.Rectangle;
import net.runelite.api.Point;

/** A world parallelogram projected through the camera, including its perspective divide. */
public final class BillboardProjectedQuad
{
	public final Rectangle bounds;
	private final double[] forward;
	private final double[] inverse;
	private final double contentCenterU;
	private final double contentTopV;

	private BillboardProjectedQuad(Rectangle bounds, double[] forward, double[] inverse,
		double contentCenterU, double contentTopV)
	{
		this.bounds = bounds;
		this.forward = forward;
		this.inverse = inverse;
		this.contentCenterU = contentCenterU;
		this.contentTopV = contentTopV;
	}

	public static BillboardProjectedQuad create(BillboardCanvasPoint topLeft, BillboardCanvasPoint topRight,
		BillboardCanvasPoint bottomRight, BillboardCanvasPoint bottomLeft, Rectangle image, Rectangle content)
	{
		BillboardCanvasPoint[] corners = {topLeft, topRight, bottomRight, bottomLeft};
		if (image == null || image.isEmpty() || content == null || content.isEmpty())
		{
			return null;
		}
		double minX = Double.POSITIVE_INFINITY, minY = Double.POSITIVE_INFINITY;
		double maxX = Double.NEGATIVE_INFINITY, maxY = Double.NEGATIVE_INFINITY;
		double area = 0.0d;
		for (int i = 0; i < 4; i++)
		{
			BillboardCanvasPoint p = corners[i];
			if (p == null || !Double.isFinite(p.x) || !Double.isFinite(p.y)
				|| !Double.isFinite(p.depth) || p.depth < 50.0d
				|| Math.abs(p.x) > 1_000_000 || Math.abs(p.y) > 1_000_000)
			{
				return null;
			}
			minX = Math.min(minX, p.x);
			minY = Math.min(minY, p.y);
			maxX = Math.max(maxX, p.x);
			maxY = Math.max(maxY, p.y);
		}
		for (int i = 0; i < 4; i++)
		{
			BillboardCanvasPoint a = corners[i], b = corners[(i + 1) % 4];
			area += a.x * b.y - b.x * a.y;
		}
		if (Math.abs(area) < 2.0d || maxX - minX < 1.0d || maxY - minY < 1.0d
			|| Math.ceil(maxX) - Math.floor(minX) > 8192 || Math.ceil(maxY) - Math.floor(minY) > 8192)
		{
			return null;
		}
		// Homogeneous camera coordinates are affine over a world plane. Columns
		// are its two edges and origin; division by the third row supplies depth.
		double x = topLeft.x * topLeft.depth, y = topLeft.y * topLeft.depth;
		double[] h = {
			topRight.x * topRight.depth - x, bottomLeft.x * bottomLeft.depth - x, x,
			topRight.y * topRight.depth - y, bottomLeft.y * bottomLeft.depth - y, y,
			topRight.depth - topLeft.depth, bottomLeft.depth - topLeft.depth, topLeft.depth
		};
		double[] inv = invert(h);
		if (inv == null)
		{
			return null;
		}
		Rectangle bounds = new Rectangle((int) Math.floor(minX), (int) Math.floor(minY),
			(int) Math.ceil(maxX) - (int) Math.floor(minX), (int) Math.ceil(maxY) - (int) Math.floor(minY));
		return new BillboardProjectedQuad(bounds, h, inv,
			(content.getCenterX() - image.x) / image.width, (content.y - image.y) / (double) image.height);
	}

	/** Reusable output avoids allocating in the pixel loop. Depth is camera-forward depth. */
	public static final class Sample
	{
		public double u;
		public double v;
		public double depth;
	}

	public boolean sample(double x, double y, Sample result)
	{
		double reciprocalDepth = inverse[6] * x + inverse[7] * y + inverse[8];
		if (!Double.isFinite(reciprocalDepth) || reciprocalDepth <= 0.0d)
		{
			return false;
		}
		result.u = (inverse[0] * x + inverse[1] * y + inverse[2]) / reciprocalDepth;
		result.v = (inverse[3] * x + inverse[4] * y + inverse[5]) / reciprocalDepth;
		result.depth = 1.0d / reciprocalDepth;
		return result.u >= 0.0d && result.u < 1.0d && result.v >= 0.0d && result.v < 1.0d
			&& Double.isFinite(result.depth);
	}

	public double depthAt(double u, double v)
	{
		return forward[6] * u + forward[7] * v + forward[8];
	}

	public Point canvasPoint(double u, double v)
	{
		double depth = depthAt(u, v);
		return new Point((int) Math.round((forward[0] * u + forward[1] * v + forward[2]) / depth),
			(int) Math.round((forward[3] * u + forward[4] * v + forward[5]) / depth));
	}

	public Point contentTopCenter()
	{
		return canvasPoint(contentCenterU, contentTopV);
	}

	public Polygon polygon()
	{
		Point a = canvasPoint(0, 0), b = canvasPoint(1, 0), c = canvasPoint(1, 1), d = canvasPoint(0, 1);
		return new Polygon(new int[] {a.getX(), b.getX(), c.getX(), d.getX()},
			new int[] {a.getY(), b.getY(), c.getY(), d.getY()}, 4);
	}

	private static double[] invert(double[] m)
	{
		double[] cofactors = {
			m[4] * m[8] - m[5] * m[7], m[2] * m[7] - m[1] * m[8], m[1] * m[5] - m[2] * m[4],
			m[5] * m[6] - m[3] * m[8], m[0] * m[8] - m[2] * m[6], m[2] * m[3] - m[0] * m[5],
			m[3] * m[7] - m[4] * m[6], m[1] * m[6] - m[0] * m[7], m[0] * m[4] - m[1] * m[3]
		};
		double determinant = m[0] * cofactors[0] + m[1] * cofactors[3] + m[2] * cofactors[6];
		if (!Double.isFinite(determinant) || Math.abs(determinant) < 1e-8d)
		{
			return null;
		}
		for (int i = 0; i < 9; i++)
		{
			cofactors[i] /= determinant;
			if (!Double.isFinite(cofactors[i]))
			{
				return null;
			}
		}
		return cofactors;
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Projectile;
import net.runelite.api.coords.LocalPoint;

public final class BillboardProjectileGeometry
{
	private BillboardProjectileGeometry()
	{
	}

	public static LocalPoint localPoint(Projectile projectile)
	{
		return new LocalPoint((int) projectile.getX(), (int) projectile.getY());
	}

	public static int verticalOffset(Client client, Projectile projectile)
	{
		LocalPoint localPoint = localPoint(projectile);
		int tileHeight = Perspective.getTileHeight(client, localPoint, projectile.getFloor());
		// getZ() is the current world coordinate, including the client's arc and
		// launch/target heights. Convert it only for APIs expecting a tile offset.
		return (int) Math.round(BillboardDepthCalculator.worldHeight(tileHeight, projectile.getZ()));
	}

	public static Rectangle drawBounds(
		BillboardDepthCalculator depthCalculator, Projectile projectile, Rectangle imageBounds, double canvasScale)
	{
		// The cached sprite's bounds are relative to model-local zero. Adding half
		// the live model height moves that origin as the projectile animates/pitches.
		// Project the native flight position directly, retaining fractional XYZ and
		// avoiding terrain-relative rounding or any model-height-based adjustment.
		BillboardCanvasPoint origin = depthCalculator.projectCanvasPoint(
			projectile.getX(), projectile.getY(), projectile.getZ());
		return BillboardGeometryUtils.projectedDrawBounds(imageBounds, origin, canvasScale);
	}
}

package com.kierenboal.npcsnap.rendering;

public final class BillboardRenderQuality
{
	public static final double MIN_RENDER_QUALITY = 0.01d;

	private BillboardRenderQuality()
	{
	}

	public static double fromPercent(double qualityPercent)
	{
		return clamp(qualityPercent / 100.0d);
	}

	public static double clamp(double qualityScale)
	{
		return Math.max(MIN_RENDER_QUALITY, Math.min(1.0d, qualityScale));
	}

	public static int key(double qualityScale)
	{
		return (int) Math.round(clamp(qualityScale) * 10_000.0d);
	}

	public static int rasterSafePadding(int sourcePadding, double qualityScale)
	{
		if (sourcePadding <= 0)
		{
			return 0;
		}

		return Math.max(sourcePadding, (int) Math.ceil(sourcePadding / clamp(qualityScale)));
	}

	public static double seededScale(double fullQualityScale, int nearPriorityIndex, int maxUpdatesPerFrame)
	{
		int updatesPerFrame = Math.max(1, maxUpdatesPerFrame);
		int maxBootstrapEntries = updatesPerFrame * 3;
		int clampedPriorityIndex = Math.min(Math.max(0, nearPriorityIndex), Math.max(0, maxBootstrapEntries - 1));
		int qualityTier = clampedPriorityIndex / updatesPerFrame;
		double seededQualityScale = clamp(fullQualityScale);
		for (int i = 0; i < qualityTier; i++)
		{
			seededQualityScale *= 0.5d;
		}

		return clamp(seededQualityScale);
	}
}

