public final class BillboardCacheStore
{
	private final Map<Renderable, CachedBillboard> entries = new IdentityHashMap<>();

	public CachedBillboard get(Renderable renderable)
	{
		return entries.get(renderable);
	}

	public boolean contains(Renderable renderable)
	{
		return entries.containsKey(renderable);
	}

	public void put(Renderable renderable, CachedBillboard cached)
	{
		CachedBillboard previous = entries.put(renderable, cached);
		if (previous != null && previous != cached)
		{
			previous.flush();
		}
	}

	public void remove(Renderable renderable)
	{
		CachedBillboard cached = entries.remove(renderable);
		if (cached != null)
		{
			cached.flush();
		}
	}

	public void clear()
	{
		for (CachedBillboard cached : entries.values())
		{
			cached.flush();
		}
		entries.clear();
	}

	public void expire(long nowMillis)
	{
		Iterator<CachedBillboard> iterator = entries.values().iterator();
		while (iterator.hasNext())
		{
			CachedBillboard cached = iterator.next();
			if (nowMillis - cached.lastUsedMillis() > BillboardConstants.CACHE_TTL_MILLIS)
			{
				cached.flush();
				iterator.remove();
			}
		}
	}
}

package com.kierenboal.npcsnap.state;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.function.LongSupplier;

public final class BillboardPerformanceMetrics
{
	private static final long SNAPSHOT_INTERVAL_NANOS = 500_000_000L;
	private final MetricNode root = new MetricNode("Overall");
	private final List<MetricNode> stack = new ArrayList<>();
	private final LongSupplier nanoTime;
	private List<MetricRow> publishedRows = Collections.emptyList();
	private boolean enabled;
	private long rootStartNanos = -1L;
	private long intervalStartNanos = -1L;

	public BillboardPerformanceMetrics()
	{
		this(System::nanoTime);
	}

	public BillboardPerformanceMetrics(LongSupplier nanoTime)
	{
		this.nanoTime = nanoTime;
	}

	public void beginFrame(boolean enabled)
	{
		long now = nanoTime.getAsLong();
		if (!enabled)
		{
			this.enabled = false;
			rootStartNanos = -1L;
			intervalStartNanos = -1L;
			publishedRows = Collections.emptyList();
			stack.clear();
			resetCurrent(root);
			resetInterval(root);
			return;
		}

		if (!this.enabled || intervalStartNanos < 0L)
		{
			intervalStartNanos = now;
			resetInterval(root);
			publishedRows = Collections.emptyList();
		}

		this.enabled = true;
		stack.clear();
		resetCurrent(root);
		root.touched = true;
		rootStartNanos = now;
		stack.add(root);
	}

	public Timer time(String name)
	{
		if (!enabled || stack.isEmpty())
		{
			return Timer.NOOP;
		}

		MetricNode parent = stack.get(stack.size() - 1);
		MetricNode node = parent.child(name);
		node.touched = true;
		node.startNanos = nanoTime.getAsLong();
		stack.add(node);
		return new Timer(this, node);
	}

	public void addElapsed(String name, long elapsedNanos)
	{
		if (!enabled || stack.isEmpty() || elapsedNanos <= 0L)
		{
			return;
		}

		MetricNode parent = stack.get(stack.size() - 1);
		MetricNode node = parent.child(name);
		node.touched = true;
		node.currentNanos += elapsedNanos;
	}

	public void finishFrame()
	{
		if (!enabled || rootStartNanos < 0L)
		{
			stack.clear();
			return;
		}

		long now = nanoTime.getAsLong();
		root.currentNanos = Math.max(0L, now - rootStartNanos);
		recordFrame(root);
		if (now - intervalStartNanos >= SNAPSHOT_INTERVAL_NANOS)
		{
			publishedRows = buildRows(Integer.MAX_VALUE);
			resetInterval(root);
			intervalStartNanos = now;
		}
		stack.clear();
	}

	public List<MetricRow> rows(int maxRows)
	{
		if (!enabled || maxRows <= 0 || publishedRows.isEmpty())
		{
			return Collections.emptyList();
		}

		if (publishedRows.size() <= maxRows)
		{
			return publishedRows;
		}

		return new ArrayList<>(publishedRows.subList(0, maxRows));
	}

	public boolean isEnabled()
	{
		return enabled;
	}

	private void close(Timer timer)
	{
		if (!enabled || timer == null || timer.node == null || timer.closed)
		{
			return;
		}

		timer.closed = true;
		MetricNode node = timer.node;
		node.currentNanos += Math.max(0L, nanoTime.getAsLong() - node.startNanos);
		if (!stack.isEmpty() && stack.get(stack.size() - 1) == node)
		{
			stack.remove(stack.size() - 1);
			return;
		}

		stack.remove(node);
	}

	private void resetCurrent(MetricNode node)
	{
		node.currentNanos = 0L;
		node.startNanos = 0L;
		node.touched = false;
		for (MetricNode child : node.children)
		{
			resetCurrent(child);
		}
	}

	private void resetInterval(MetricNode node)
	{
		node.sampleCount = 0;
		node.sampleTotalNanos = 0L;
		node.sampleMinNanos = Long.MAX_VALUE;
		node.sampleMaxNanos = 0L;
		for (MetricNode child : node.children)
		{
			resetInterval(child);
		}
	}

	private void recordFrame(MetricNode node)
	{
		if (node.touched)
		{
			node.sampleCount++;
			node.sampleTotalNanos += node.currentNanos;
			node.sampleMinNanos = Math.min(node.sampleMinNanos, node.currentNanos);
			node.sampleMaxNanos = Math.max(node.sampleMaxNanos, node.currentNanos);
		}

		for (MetricNode child : node.children)
		{
			recordFrame(child);
		}
	}

	private List<MetricRow> buildRows(int maxRows)
	{
		List<MetricRow> rows = new ArrayList<>();
		appendRows(root, 0, maxRows, rows);
		return rows;
	}

	private void appendRows(MetricNode node, int depth, int maxRows, List<MetricRow> rows)
	{
		if (node.sampleCount <= 0 || rows.size() >= maxRows)
		{
			return;
		}

		rows.add(MetricRow.from(node, depth));
		if (rows.size() >= maxRows)
		{
			return;
		}

		List<MetricNode> children = new ArrayList<>();
		for (MetricNode child : node.children)
		{
			if (child.sampleCount > 0)
			{
				children.add(child);
			}
		}
		children.sort(Comparator
			.comparingDouble(MetricNode::sampleAverageNanos).reversed()
			.thenComparing(MetricNode::name));
		for (MetricNode child : children)
		{
			appendRows(child, depth + 1, maxRows, rows);
			if (rows.size() >= maxRows)
			{
				return;
			}
		}
	}

	public static Color colorForName(String name)
	{
		int hash = name != null ? name.hashCode() : 0;
		int red = brightChannel(hash);
		int green = brightChannel(hash >> 8);
		int blue = brightChannel(hash >> 16);
		return new Color(red, green, blue, 255);
	}

	private static int brightChannel(int value)
	{
		return 140 + Math.floorMod(value, 116);
	}

	public static final class MetricRow
	{
		public final String name;
		public final int depth;
		public final double minMillis;
		public final double avgMillis;
		public final double maxMillis;
		public final double percentOfOverall;
		public final Color color;

		private MetricRow(String name, int depth, double minMillis, double avgMillis, double maxMillis, double percentOfOverall, Color color)
		{
			this.name = name;
			this.depth = depth;
			this.minMillis = minMillis;
			this.avgMillis = avgMillis;
			this.maxMillis = maxMillis;
			this.percentOfOverall = percentOfOverall;
			this.color = color;
		}

		private static MetricRow from(MetricNode node, int depth)
		{
			double overallAverage = node.root().sampleAverageNanos();
			double percentOfOverall = overallAverage > 0.0d ? (node.sampleAverageNanos() * 100.0d) / overallAverage : 0.0d;
			return new MetricRow(
				node.name,
				depth,
				node.sampleMinNanos / 1_000_000.0d,
				node.sampleAverageNanos() / 1_000_000.0d,
				node.sampleMaxNanos / 1_000_000.0d,
				percentOfOverall,
				colorForName(node.name)
			);
		}
	}

	public static final class Timer implements AutoCloseable
	{
		private static final Timer NOOP = new Timer(null, null);
		private final BillboardPerformanceMetrics metrics;
		private final MetricNode node;
		private boolean closed;

		private Timer(BillboardPerformanceMetrics metrics, MetricNode node)
		{
			this.metrics = metrics;
			this.node = node;
		}

		@Override
		public void close()
		{
			if (metrics != null)
			{
				metrics.close(this);
			}
		}
	}

	private static final class MetricNode
	{
		private final String name;
		private final MetricNode parent;
		private final List<MetricNode> children = new ArrayList<>();
		private long currentNanos;
		private long startNanos;
		private int sampleCount;
		private long sampleTotalNanos;
		private long sampleMinNanos = Long.MAX_VALUE;
		private long sampleMaxNanos;
		private boolean touched;

		private MetricNode(String name)
		{
			this(name, null);
		}

		private MetricNode(String name, MetricNode parent)
		{
			this.name = name;
			this.parent = parent;
		}

		private MetricNode child(String name)
		{
			for (MetricNode child : children)
			{
				if (child.name.equals(name))
				{
					return child;
				}
			}

			MetricNode child = new MetricNode(name, this);
			children.add(child);
			return child;
		}

		private String name()
		{
			return name;
		}

		private double sampleAverageNanos()
		{
			return sampleCount > 0 ? sampleTotalNanos / (double) sampleCount : 0.0d;
		}

		private MetricNode root()
		{
			MetricNode node = this;
			while (node.parent != null)
			{
				node = node.parent;
			}
			return node;
		}
	}
}

package com.kierenboal.npcsnap.state;

import com.kierenboal.npcsnap.BillboardConstants;
import java.awt.Rectangle;
import java.util.Collection;
import java.util.EnumSet;
import java.util.StringJoiner;

/** Independent causes of a dirty sprite, carried from its update plan to debug drawing. */
public enum BillboardRedrawReason
{
	INITIAL_DRAW("Initial sprite"),
	FRAME_COUNT("Frame count"),
	ACTOR_RESIZE("Clickbox/hull size change"),
	ANIMATION_CHANGE("Animation change"),
	INTERACTION_CHANGE("Hover/interaction change"),
	VIEW_CHANGE("View angle change"),
	MODEL_CHANGE("Model change"),
	TEXTURE_CHANGE("Texture change"),
	QUALITY_CHANGE("Quality change"),
	APPEARANCE_CHANGE("Appearance change"),
	BOUNDS_CHANGE("Sprite bounds change"),
	CACHE_EXPIRY("Cache expiry");

	private final String label;

	BillboardRedrawReason(String label)
	{
		this.label = label;
	}

	public static String format(Collection<BillboardRedrawReason> reasons)
	{
		StringJoiner labels = new StringJoiner(", ");
		for (BillboardRedrawReason reason : reasons)
		{
			labels.add(reason.label);
		}
		return labels.toString();
	}

	public static EnumSet<BillboardRedrawReason> cacheChanges(CachedBillboard displayed, BillboardCacheKey current,
		Rectangle imageBounds, long nowMillis)
	{
		EnumSet<BillboardRedrawReason> reasons = EnumSet.noneOf(BillboardRedrawReason.class);
		if (displayed == null)
		{
			reasons.add(INITIAL_DRAW);
			return reasons;
		}
		BillboardCacheKey previous = displayed.key;
		if (previous.animationFrame != current.animationFrame || previous.poseAnimationFrame != current.poseAnimationFrame)
		{
			reasons.add(FRAME_COUNT);
		}
		if (previous.animationId != current.animationId || previous.poseAnimationId != current.poseAnimationId)
		{
			reasons.add(ANIMATION_CHANGE);
		}
		if (previous.hoverOutline != current.hoverOutline || previous.interactOutline != current.interactOutline
			|| previous.hoverOutlineColor != current.hoverOutlineColor || previous.interactOutlineColor != current.interactOutlineColor)
		{
			reasons.add(INTERACTION_CHANGE);
		}
		if (previous.relativeYaw != current.relativeYaw || previous.relativePitch != current.relativePitch)
		{
			reasons.add(VIEW_CHANGE);
		}
		if (previous.modelStateHash != current.modelStateHash)
		{
			reasons.add(MODEL_CHANGE);
		}
		if (previous.textureStateHash != current.textureStateHash
			|| previous.animatedTextureOffsetStateHash != current.animatedTextureOffsetStateHash)
		{
			reasons.add(TEXTURE_CHANGE);
		}
		if (previous.renderQuality != current.renderQuality)
		{
			reasons.add(QUALITY_CHANGE);
		}
		if (previous.colorBands != current.colorBands || previous.lightBoost != current.lightBoost
			|| previous.outlinePadding != current.outlinePadding || previous.highlightOutline != current.highlightOutline
			|| previous.shadowOutline != current.shadowOutline || previous.solidOutline != current.solidOutline
			|| previous.spriteShadow != current.spriteShadow || previous.highlightInline != current.highlightInline
			|| previous.shadowInline != current.shadowInline || previous.solidInline != current.solidInline
			|| previous.outlineColor != current.outlineColor)
		{
			reasons.add(APPEARANCE_CHANGE);
		}
		if (!displayed.bounds.equals(imageBounds))
		{
			reasons.add(BOUNDS_CHANGE);
		}
		if (nowMillis - displayed.lastRedrawMillis() > BillboardConstants.CACHE_TTL_MILLIS)
		{
			reasons.add(CACHE_EXPIRY);
		}
		return reasons;
	}
}

package com.kierenboal.npcsnap.state;

public final class BillboardUpdatePriority
{
	private BillboardUpdatePriority()
	{
	}

	public static double stateChangeScore(BillboardUpdateState state, UpdateHeuristicSnapshot snapshot)
	{
		if (state == null || snapshot == null)
		{
			return 0.0d;
		}

		double score = 0.0d;
		if (state.hasModelChanged(snapshot) || state.hasModelChangedSinceRedraw(snapshot))
		{
			score += 25_000.0d;
		}

		if (state.hasAnimationChanged(snapshot) || state.hasAnimationChangedSinceRedraw(snapshot))
		{
			score += 12_000.0d;
		}

		if (state.hasViewChangedSinceRedraw(snapshot))
		{
			score += 6_000.0d;
		}

		if (state.hasMoved(snapshot))
		{
			score += 1_200.0d;
		}
		else if (state.hasTextureChanged(snapshot) || state.hasTextureChangedSinceRedraw(snapshot) || snapshot.animated)
		{
			score += 450.0d;
		}

		return score;
	}
}

package com.kierenboal.npcsnap.state;

import com.kierenboal.npcsnap.targeting.BillboardTargetKey;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;

public final class BillboardUpdateQueue implements Iterable<BillboardTargetKey>
{
	private final Deque<BillboardTargetKey> entries = new ArrayDeque<>();
	private final Set<BillboardTargetKey> membership = new HashSet<>();
	private final Map<BillboardTargetKey, Integer> debugPositions = new HashMap<>();
	private final Map<BillboardTargetKey, Double> debugScores = new HashMap<>();

	public void clear()
	{
		entries.clear();
		membership.clear();
		debugPositions.clear();
		debugScores.clear();
	}

	public int size()
	{
		return entries.size();
	}

	public boolean isEmpty()
	{
		return entries.isEmpty();
	}

	public boolean contains(BillboardTargetKey key)
	{
		return membership.contains(key);
	}

	public BillboardTargetKey pollFirst()
	{
		BillboardTargetKey key = entries.pollFirst();
		if (key != null)
		{
			membership.remove(key);
		}
		return key;
	}

	public void addLast(BillboardTargetKey key)
	{
		if (membership.add(key))
		{
			entries.addLast(key);
		}
	}

	public void addFirst(BillboardTargetKey key)
	{
		if (membership.add(key))
		{
			entries.addFirst(key);
		}
	}

	public List<BillboardTargetKey> prune(Set<BillboardTargetKey> validKeys)
	{
		List<BillboardTargetKey> removed = new ArrayList<>();
		Iterator<BillboardTargetKey> iterator = entries.iterator();
		while (iterator.hasNext())
		{
			BillboardTargetKey key = iterator.next();
			if (!validKeys.contains(key))
			{
				iterator.remove();
				membership.remove(key);
				debugPositions.remove(key);
				debugScores.remove(key);
				removed.add(key);
			}
		}
		return removed;
	}

	public void replaceWith(List<QueuedBillboardTarget> prioritizedTargets)
	{
		entries.clear();
		membership.clear();
		for (QueuedBillboardTarget target : prioritizedTargets)
		{
			addLast(target.key);
		}
		refreshDebugPositions();
	}

	public int debugPosition(BillboardTargetKey key)
	{
		return debugPositions.getOrDefault(key, -1);
	}

	public void putDebugScore(BillboardTargetKey key, double score)
	{
		debugScores.put(key, score);
	}

	public Double debugScore(BillboardTargetKey key)
	{
		return debugScores.get(key);
	}

	public Collection<Double> debugScores()
	{
		return debugScores.values();
	}

	public boolean hasDebugScores()
	{
		return !debugScores.isEmpty();
	}

	private void refreshDebugPositions()
	{
		debugPositions.clear();
		int index = 0;
		for (BillboardTargetKey key : entries)
		{
			debugPositions.put(key, index++);
		}
	}

	@Override
	public Iterator<BillboardTargetKey> iterator()
	{
		return entries.iterator();
	}
}

package com.kierenboal.npcsnap.state;

import com.kierenboal.npcsnap.rendering.BillboardRenderQuality;
import com.kierenboal.npcsnap.targeting.ObjectRenderablePart;
import com.kierenboal.npcsnap.targeting.BillboardTargetType;
import net.runelite.api.DynamicObject;

public final class BillboardUpdateScheduler
{
	private BillboardUpdateScheduler()
	{
	}

	public static boolean usesAnimationCadence(BillboardTargetType type, boolean frameLimitingEnabled)
	{
		return frameLimitingEnabled && (type == BillboardTargetType.PROJECTILE
			|| type == BillboardTargetType.GRAPHICS_OBJECT
			|| type == BillboardTargetType.ACTOR_SPOT_ANIM);
	}

	public static boolean usesTileObjectAnimationCadence(Iterable<ObjectRenderablePart> parts, boolean frameLimitingEnabled)
	{
		if (!frameLimitingEnabled || parts == null)
		{
			return false;
		}
		for (ObjectRenderablePart part : parts)
		{
			if (part != null && part.renderable instanceof DynamicObject
				&& ((DynamicObject) part.renderable).getAnimation() != null)
			{
				return true;
			}
		}
		return false;
	}

	public static double initialQualityScale(boolean hasCachedBillboard, double fullQualityScale, int nearPriorityIndex, int maxDrawsPerFrame)
	{
		return hasCachedBillboard
			? BillboardRenderQuality.clamp(fullQualityScale)
			: BillboardRenderQuality.seededScale(fullQualityScale, nearPriorityIndex, maxDrawsPerFrame);
	}

	public static boolean allTileObjectPartsCached(Iterable<ObjectRenderablePart> parts, java.util.function.Predicate<net.runelite.api.Renderable> hasCache)
	{
		if (parts == null || hasCache == null)
		{
			return false;
		}

		boolean sawRenderablePart = false;
		for (ObjectRenderablePart part : parts)
		{
			if (part == null || part.renderable == null)
			{
				continue;
			}

			sawRenderablePart = true;
			if (!hasCache.test(part.renderable))
			{
				return false;
			}
		}

		return sawRenderablePart;
	}
}

package com.kierenboal.npcsnap.state;

public final class BillboardUpdateScore
{
	private BillboardUpdateScore()
	{
	}

	public static double compute(
		boolean hasCachedBillboard,
		boolean forceInteractionRedraw,
		boolean targetIsPriorityActor,
		boolean targetIsLocalPlayer,
		boolean ownerIsLocalPlayer,
		boolean ownerIsPriorityActor,
		boolean actorSpotAnimation,
		BillboardUpdateState state,
		UpdateHeuristicSnapshot snapshot,
		int gameCycle,
		int queueIndex)
	{
		return compute(hasCachedBillboard, forceInteractionRedraw, false, targetIsPriorityActor,
			targetIsLocalPlayer, ownerIsLocalPlayer, ownerIsPriorityActor, actorSpotAnimation,
			state, snapshot, gameCycle, queueIndex);
	}

	public static double compute(
		boolean hasCachedBillboard,
		boolean forceInteractionRedraw,
		boolean forceActorResizeRedraw,
		boolean targetIsPriorityActor,
		boolean targetIsLocalPlayer,
		boolean ownerIsLocalPlayer,
		boolean ownerIsPriorityActor,
		boolean actorSpotAnimation,
		BillboardUpdateState state,
		UpdateHeuristicSnapshot snapshot,
		int gameCycle,
		int queueIndex)
	{
		// Separate priority bands keep resize updates above ordinary state changes,
		// and interaction updates above resize updates even when both models change.
		double score = hasCachedBillboard ? 0.0d : 10_000.0d;
		score += forceInteractionRedraw ? 1_000_000.0d : forceActorResizeRedraw ? 100_000.0d : 0.0d;
		if (forceInteractionRedraw)
		{
			score += 50_000.0d;
			if (targetIsPriorityActor)
			{
				score += 10_000.0d;
			}
			else if (targetIsLocalPlayer)
			{
				score += 9_000.0d;
			}
		}

		if (ownerIsLocalPlayer)
		{
			score += 6_000.0d;
		}
		if (ownerIsPriorityActor)
		{
			score += 8_000.0d;
		}
		if (actorSpotAnimation)
		{
			score += 2_500.0d;
		}

		score += BillboardUpdatePriority.stateChangeScore(state, snapshot);
		double depth = Math.max(0.0d, snapshot.depth);
		score += 8_000.0d / Math.max(128.0d, depth + 128.0d);
		score += Math.min(4_000.0d, state.cyclesSinceRedraw(gameCycle) * 160.0d);
		score += Math.min(3_000.0d, state.overdueCycles(gameCycle) * 220.0d);
		return score - (queueIndex * 0.01d);
	}
}

package com.kierenboal.npcsnap.state;

import com.kierenboal.npcsnap.rendering.BillboardRenderQuality;

public final class BillboardUpdateState
{
	public double qualityScale;
	private int nextEligibleGameCycle;
	private int lastRedrawGameCycle;
	private long lastRedrawPositionKey;
	private int lastRedrawAnimationHash;
	private int lastRedrawModelStateHash;
	private int lastRedrawTextureStateHash;
	private int lastRedrawViewHash;
	private long lastObservedPositionKey;
	private int lastObservedAnimationHash;
	private int lastObservedModelStateHash;
	private int lastObservedTextureStateHash;
	private boolean hasObservation;

	public BillboardUpdateState(double qualityScale)
	{
		this.qualityScale = qualityScale;
		this.nextEligibleGameCycle = Integer.MIN_VALUE;
		this.lastRedrawGameCycle = Integer.MIN_VALUE;
		this.lastRedrawPositionKey = Long.MIN_VALUE;
		this.lastRedrawAnimationHash = Integer.MIN_VALUE;
		this.lastRedrawModelStateHash = Integer.MIN_VALUE;
		this.lastRedrawTextureStateHash = Integer.MIN_VALUE;
		this.lastRedrawViewHash = Integer.MIN_VALUE;
		this.lastObservedPositionKey = Long.MIN_VALUE;
		this.lastObservedAnimationHash = Integer.MIN_VALUE;
		this.lastObservedModelStateHash = Integer.MIN_VALUE;
		this.lastObservedTextureStateHash = Integer.MIN_VALUE;
		this.hasObservation = false;
	}

	public boolean isReady(int gameCycle, boolean hasCachedBillboard)
	{
		return !hasCachedBillboard || gameCycle >= nextEligibleGameCycle;
	}

	public boolean hasMoved(UpdateHeuristicSnapshot snapshot)
	{
		return hasObservation
			&& snapshot.hasPosition()
			&& lastObservedPositionKey != Long.MIN_VALUE
			&& lastObservedPositionKey != snapshot.positionKey;
	}

	public boolean hasAnimationChanged(UpdateHeuristicSnapshot snapshot)
	{
		return snapshot != null
			&& hasObservation
			&& lastObservedAnimationHash != Integer.MIN_VALUE
			&& lastObservedAnimationHash != snapshot.animationHash;
	}

	public boolean hasModelChanged(UpdateHeuristicSnapshot snapshot)
	{
		return snapshot != null
			&& hasObservation
			&& lastObservedModelStateHash != Integer.MIN_VALUE
			&& lastObservedModelStateHash != snapshot.modelStateHash;
	}

	public boolean hasTextureChanged(UpdateHeuristicSnapshot snapshot)
	{
		return snapshot != null
			&& hasObservation
			&& lastObservedTextureStateHash != Integer.MIN_VALUE
			&& lastObservedTextureStateHash != snapshot.textureStateHash;
	}

	public boolean hasPositionChangedSinceRedraw(UpdateHeuristicSnapshot snapshot)
	{
		return snapshot != null
			&& snapshot.hasPosition()
			&& lastRedrawPositionKey != Long.MIN_VALUE
			&& lastRedrawPositionKey != snapshot.positionKey;
	}

	public boolean hasViewChangedSinceRedraw(UpdateHeuristicSnapshot snapshot)
	{
		return snapshot != null
			&& lastRedrawViewHash != Integer.MIN_VALUE
			&& lastRedrawViewHash != snapshot.viewHash;
	}

	public boolean hasAnimationChangedSinceRedraw(UpdateHeuristicSnapshot snapshot)
	{
		return snapshot != null
			&& lastRedrawAnimationHash != Integer.MIN_VALUE
			&& lastRedrawAnimationHash != snapshot.animationHash;
	}

	public boolean hasModelChangedSinceRedraw(UpdateHeuristicSnapshot snapshot)
	{
		return snapshot != null
			&& lastRedrawModelStateHash != Integer.MIN_VALUE
			&& lastRedrawModelStateHash != snapshot.modelStateHash;
	}

	public boolean hasTextureChangedSinceRedraw(UpdateHeuristicSnapshot snapshot)
	{
		return snapshot != null
			&& lastRedrawTextureStateHash != Integer.MIN_VALUE
			&& lastRedrawTextureStateHash != snapshot.textureStateHash;
	}

	public int cyclesSinceRedraw(int gameCycle)
	{
		if (lastRedrawGameCycle == Integer.MIN_VALUE)
		{
			return 64;
		}

		return Math.max(0, gameCycle - lastRedrawGameCycle);
	}

	public int overdueCycles(int gameCycle)
	{
		if (nextEligibleGameCycle == Integer.MIN_VALUE)
		{
			return cyclesSinceRedraw(gameCycle);
		}

		return Math.max(0, gameCycle - nextEligibleGameCycle);
	}

	public void observe(UpdateHeuristicSnapshot snapshot)
	{
		if (snapshot == null)
		{
			return;
		}

		lastObservedPositionKey = snapshot.positionKey;
		lastObservedAnimationHash = snapshot.animationHash;
		lastObservedModelStateHash = snapshot.modelStateHash;
		lastObservedTextureStateHash = snapshot.textureStateHash;
		hasObservation = true;
	}

	public void defer(int gameCycle, int baseRefreshInterval)
	{
		nextEligibleGameCycle = gameCycle + Math.max(1, baseRefreshInterval);
	}

	public void advance(int gameCycle, int baseRefreshInterval, double fullQualityScale, UpdateHeuristicSnapshot snapshot, int minimumAnimatedRedrawInterval)
	{
		double clampedFullQuality = BillboardRenderQuality.clamp(fullQualityScale);
		double clampedCurrentQuality = Math.max(BillboardRenderQuality.MIN_RENDER_QUALITY, Math.min(clampedFullQuality, qualityScale));
		double refreshRatio = clampedCurrentQuality / clampedFullQuality;
		int nextDelay = Math.max(1, (int) Math.round(baseRefreshInterval * refreshRatio));
		if (snapshot != null && snapshot.animated)
		{
			nextDelay = Math.max(nextDelay, Math.max(1, minimumAnimatedRedrawInterval));
		}
		nextEligibleGameCycle = gameCycle + nextDelay;
		qualityScale = Math.min(clampedFullQuality, clampedCurrentQuality * 2.0d);
		lastRedrawGameCycle = gameCycle;
		if (snapshot != null)
		{
			lastRedrawPositionKey = snapshot.positionKey;
			lastRedrawAnimationHash = snapshot.animationHash;
			lastRedrawModelStateHash = snapshot.modelStateHash;
			lastRedrawTextureStateHash = snapshot.textureStateHash;
			lastRedrawViewHash = snapshot.viewHash;
		}
	}
}

package com.kierenboal.npcsnap.state;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import net.runelite.api.Renderable;
import net.runelite.api.TileObject;

public final class BillboardVisibilityState
{
	public final Set<Renderable> activeBillboards = identitySet();
	public final Set<Renderable> suppressedRenderables = identitySet();
	public final Set<TileObject> activeTileObjects = identitySet();

	private volatile Set<Renderable> activeBillboardSnapshot = Collections.emptySet();
	private volatile Set<Renderable> suppressedRenderableSnapshot = Collections.emptySet();
	private volatile Set<TileObject> activeTileObjectSnapshot = Collections.emptySet();
	private volatile Set<Renderable> drawableActor2dSnapshot = Collections.emptySet();

	public void clearSelections()
	{
		activeBillboards.clear();
		suppressedRenderables.clear();
		activeTileObjects.clear();
	}

	public void clearSnapshots()
	{
		activeBillboardSnapshot = Collections.emptySet();
		suppressedRenderableSnapshot = Collections.emptySet();
		activeTileObjectSnapshot = Collections.emptySet();
		drawableActor2dSnapshot = Collections.emptySet();
	}

	public void publishSnapshots()
	{
		activeBillboardSnapshot = updatedSnapshot(activeBillboards, activeBillboardSnapshot);
		suppressedRenderableSnapshot = updatedSnapshot(suppressedRenderables, suppressedRenderableSnapshot);
		activeTileObjectSnapshot = updatedSnapshot(activeTileObjects, activeTileObjectSnapshot);
	}

	public boolean shouldHideRenderable(Renderable renderable, boolean clientThread)
	{
		return clientThread
			? activeBillboards.contains(renderable) || suppressedRenderables.contains(renderable)
			: activeBillboardSnapshot.contains(renderable) || suppressedRenderableSnapshot.contains(renderable);
	}

	public boolean hasActiveBillboard(Renderable renderable, boolean clientThread)
	{
		return clientThread ? activeBillboards.contains(renderable) : activeBillboardSnapshot.contains(renderable);
	}

	public boolean hadDrawableActor2dBillboard(Renderable renderable)
	{
		return drawableActor2dSnapshot.contains(renderable);
	}

	public void publishDrawableActor2d(Set<Renderable> renderables)
	{
		drawableActor2dSnapshot = copy(renderables);
	}

	public boolean hasActiveTileObject(TileObject tileObject, boolean clientThread)
	{
		return clientThread ? activeTileObjects.contains(tileObject) : activeTileObjectSnapshot.contains(tileObject);
	}

	public void clearActiveTileObjects()
	{
		activeTileObjects.clear();
		activeTileObjectSnapshot = Collections.emptySet();
	}

	private static <T> Set<T> copy(Set<T> source)
	{
		Set<T> copy = identitySet();
		copy.addAll(source);
		return copy;
	}

	private static <T> Set<T> updatedSnapshot(Set<T> source, Set<T> currentSnapshot)
	{
		return source.size() == currentSnapshot.size() && currentSnapshot.containsAll(source)
			? currentSnapshot
			: copy(source);
	}

	private static <T> Set<T> identitySet()
	{
		return Collections.newSetFromMap(new IdentityHashMap<>());
	}
}

