package com.kierenboal.npcsnap.state;

import com.kierenboal.npcsnap.rendering.BillboardModelStateHash;
import com.kierenboal.npcsnap.rendering.BillboardRenderRequest;

import net.runelite.api.coords.LocalPoint;

public final class UpdateHeuristicSnapshot
{
	public final double depth;
	public final long positionKey;
	public final int animationHash;
	public final int modelStateHash;
	public final int textureStateHash;
	public final int viewHash;
	public final boolean animated;

	public UpdateHeuristicSnapshot(
		double depth,
		long positionKey,
		int animationHash,
		int modelStateHash,
		int textureStateHash,
		int viewHash,
		boolean animated)
	{
		this.depth = depth;
		this.positionKey = positionKey;
		this.animationHash = animationHash;
		this.modelStateHash = modelStateHash;
		this.textureStateHash = textureStateHash;
		this.viewHash = viewHash;
		this.animated = animated;
	}

	public static UpdateHeuristicSnapshot empty()
	{
		return new UpdateHeuristicSnapshot(
			Double.POSITIVE_INFINITY,
			Long.MIN_VALUE,
			Integer.MIN_VALUE,
			Integer.MIN_VALUE,
			Integer.MIN_VALUE,
			Integer.MIN_VALUE,
			false);
	}

	public static UpdateHeuristicSnapshot forDepth(double depth)
	{
		return new UpdateHeuristicSnapshot(
			depth,
			Long.MIN_VALUE,
			Integer.MIN_VALUE,
			Integer.MIN_VALUE,
			Integer.MIN_VALUE,
			Integer.MIN_VALUE,
			false);
	}

	/**
	 * An animated effect keeps tracking its screen position while its sprite image is held
	 * until the next animation cadence update. Its continuously changing model and
	 * orientation therefore must not bypass that cadence.
	 */
	public static UpdateHeuristicSnapshot cadencedProjectile(double depth)
	{
		return new UpdateHeuristicSnapshot(
			depth,
			Long.MIN_VALUE,
			1,
			1,
			1,
			1,
			true);
	}

	public static UpdateHeuristicSnapshot fromRequest(BillboardRenderRequest request, double depth, int animatedTextureOffsetStateHash)
	{
		long positionKey = positionKey(request.localPoint, request.plane);
		int animationHash = 1;
		int modelStateHash = BillboardModelStateHash.hash(request.model);
		int textureStateHash = 1;
		int viewHash = 1;
		viewHash = (31 * viewHash) + request.relativeYaw;
		viewHash = (31 * viewHash) + request.relativePitch;
		animationHash = (31 * animationHash) + request.animationId;
		animationHash = (31 * animationHash) + request.animationFrame;
		animationHash = (31 * animationHash) + request.poseAnimationId;
		animationHash = (31 * animationHash) + request.poseAnimationFrame;
		textureStateHash = (31 * textureStateHash) + request.animatedTextureId;
		textureStateHash = (31 * textureStateHash) + animatedTextureOffsetStateHash;
		boolean animated = request.animationId >= 0
			|| request.poseAnimationId >= 0
			|| request.animationFrame >= 0
			|| request.poseAnimationFrame >= 0
			|| request.animatedTextureId >= 0;
		return new UpdateHeuristicSnapshot(
			depth,
			positionKey,
			animationHash,
			modelStateHash,
			textureStateHash,
			viewHash,
			animated);
	}

	public boolean hasPosition()
	{
		return positionKey != Long.MIN_VALUE;
	}

	public static long positionKey(LocalPoint localPoint, int plane)
	{
		if (localPoint == null)
		{
			return Long.MIN_VALUE;
		}

		long x = localPoint.getX() & 0x1FFFFL;
		long y = localPoint.getY() & 0x1FFFFL;
		long z = plane & 0x3L;
		return (z << 34) | (x << 17) | y;
	}
}

package com.kierenboal.npcsnap.targeting;

import java.util.IdentityHashMap;
import java.util.Map;
import net.runelite.api.Actor;

/** Records the order in which the scene actually submits actor models. */
public final class ActorDrawOrderTracker
{
	private final Map<Actor, Long> current = new IdentityHashMap<>();
	private final Map<Actor, Long> previous = new IdentityHashMap<>();
	private long sequence;

	public synchronized void record(Actor actor)
	{
		if (actor != null)
		{
			current.put(actor, ++sequence);
		}
	}

	public synchronized void advanceFrame()
	{
		previous.clear();
		previous.putAll(current);
		current.clear();
		sequence = 0;
	}

	public synchronized boolean drawnAfter(Actor candidate, Actor selected)
	{
		Long candidateOrder = previous.get(candidate);
		Long selectedOrder = previous.get(selected);
		return candidateOrder != null && (selectedOrder == null || candidateOrder > selectedOrder);
	}

	public synchronized Actor preferred(Actor selected, Actor candidate, Actor localPlayer)
	{
		if (selected == null || candidate == localPlayer)
		{
			return candidate;
		}
		if (selected == localPlayer)
		{
			return selected;
		}
		return drawnAfter(candidate, selected) ? candidate : selected;
	}

	public synchronized void clear()
	{
		current.clear();
		previous.clear();
		sequence = 0;
	}
}

package com.kierenboal.npcsnap.targeting;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Actor;
import net.runelite.api.coords.LocalPoint;

public final class ActorStackTracker
{
	private static final int REQUIRED_TICK_ADVANCES = 2;
	private final Map<OccupiedTileKey, Overlap> overlaps = new HashMap<>();

	public Set<OccupiedTileKey> confirmedStackedTiles(
		Map<OccupiedTileKey, List<Actor>> actorsByTile,
		Map<OccupiedTileKey, Actor> topActorsByTile,
		int tickCount)
	{
		Set<OccupiedTileKey> observedStackedTiles = new HashSet<>();
		Set<OccupiedTileKey> confirmed = new HashSet<>();
		if (actorsByTile != null)
		{
			for (Map.Entry<OccupiedTileKey, List<Actor>> entry : actorsByTile.entrySet())
			{
				OccupiedTileKey tile = entry.getKey();
				List<Actor> actors = entry.getValue();
				if (tile == null || actors == null || actors.size() < 2)
				{
					continue;
				}

				observedStackedTiles.add(tile);
				Actor topActor = topActorsByTile != null ? topActorsByTile.get(tile) : null;
				Overlap overlap = overlaps.get(tile);
				if (overlap == null
					|| !overlap.matches(actors)
					|| !overlap.matchesTopActor(topActor)
					|| tickCount < overlap.firstObservedTick)
				{
					overlaps.put(tile, new Overlap(actors, topActor, tickCount));
					continue;
				}

				if (overlap.topActorMoved())
				{
					// The actor stack is no longer stable as soon as the selected top
					// actor's client-rendered position changes. Reset confirmation so
					// lower actors become eligible in this same frame and the stack
					// must settle again before it can be hidden.
					overlaps.put(tile, new Overlap(actors, topActor, tickCount));
					continue;
				}

				// Waiting for two tick-count advances guarantees at least one complete
				// game-tick interval elapsed after the overlap was first observed. A
				// one-tile walk-through therefore never briefly collapses the actors.
				if (tickCount - overlap.firstObservedTick >= REQUIRED_TICK_ADVANCES)
				{
					confirmed.add(tile);
				}
			}
		}

		Iterator<OccupiedTileKey> iterator = overlaps.keySet().iterator();
		while (iterator.hasNext())
		{
			if (!observedStackedTiles.contains(iterator.next()))
			{
				iterator.remove();
			}
		}
		return confirmed;
	}

	public void clear()
	{
		overlaps.clear();
	}

	private static final class Overlap
	{
		private final Set<Actor> actors = Collections.newSetFromMap(new IdentityHashMap<>());
		private final Actor topActor;
		private final int firstObservedTick;
		private final int lastTopX;
		private final int lastTopY;
		private final boolean hasTopLocation;

		private Overlap(List<Actor> actors, Actor topActor, int firstObservedTick)
		{
			this.actors.addAll(actors);
			this.topActor = topActor;
			this.firstObservedTick = firstObservedTick;

			LocalPoint topLocation = topActor != null ? topActor.getLocalLocation() : null;
			this.hasTopLocation = topLocation != null;
			this.lastTopX = topLocation != null ? topLocation.getX() : 0;
			this.lastTopY = topLocation != null ? topLocation.getY() : 0;
		}

		private boolean matches(List<Actor> currentActors)
		{
			if (currentActors.size() != actors.size())
			{
				return false;
			}

			for (Actor actor : currentActors)
			{
				if (!actors.contains(actor))
				{
					return false;
				}
			}
			return true;
		}

		private boolean matchesTopActor(Actor currentTopActor)
		{
			return topActor == currentTopActor;
		}

		private boolean topActorMoved()
		{
			if (!hasTopLocation || topActor == null)
			{
				return false;
			}

			LocalPoint currentLocation = topActor.getLocalLocation();
			return currentLocation != null
				&& (currentLocation.getX() != lastTopX || currentLocation.getY() != lastTopY);
		}
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.NpcSnapConfig;
import com.kierenboal.npcsnap.rendering.BillboardProjectileGeometry;

import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.DynamicObject;
import net.runelite.api.GameObject;
import net.runelite.api.GraphicsObject;
import net.runelite.api.GroundObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Projectile;
import net.runelite.api.Renderable;
import net.runelite.api.TileItem;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;
import org.slf4j.Logger;

public final class BillboardClassificationDebug
{
	private final Client client;
	private final NpcSnapConfig config;
	private final Logger log;
	private final Map<Object, String> previousMessages = new IdentityHashMap<>();

	public BillboardClassificationDebug(Client client, NpcSnapConfig config, Logger log)
	{
		this.client = client;
		this.config = config;
		this.log = log;
	}

	public void clear()
	{
		previousMessages.clear();
	}

	public ClassifiedObjectType resolveObservedTileObjectType(ObservedTileObject observed)
	{
		if (observed == null)
		{
			return ClassifiedObjectType.UNKNOWN;
		}

		ObjectClassifier.ClassificationDecision decision = classifyObservedTileObjectDecision(observed);
		logObservedTileObjectClassification(observed, decision);
		ClassifiedObjectType classifiedType = decision.classification;
		if (classifiedType == ClassifiedObjectType.UNKNOWN)
		{
			return observed.classifiedType;
		}

		observed.classifiedType = classifiedType;
		return classifiedType;
	}

	public void logDecision(Object source, ObjectClassifier.ClassificationDecision decision)
	{
		logDecision(source, decision, null);
	}

	public void logDecision(Object source, ObjectClassifier.ClassificationDecision decision, String extraTypes)
	{
		if (!log.isDebugEnabled() || !config.debugLogClassifications() || source == null || decision == null)
		{
			return;
		}

		String message = classificationDebugMessage(source, decision, extraTypes);
		String previousMessage = previousMessages.put(source, message);
		if (message.equals(previousMessage))
		{
			return;
		}

		log.debug(message);
	}

	public String actorDebugKey(Actor actor)
	{
		return classificationDebugApiType(actor) + ":" + classificationDebugId(actor) + ":" + classificationDebugName(actor);
	}

	private ObjectClassifier.ClassificationDecision classifyObservedTileObjectDecision(ObservedTileObject observed)
	{
		if (observed == null || observed.tileObject == null)
		{
			return ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.UNKNOWN, "observed == null || observed.tileObject == null");
		}

		boolean hasEffectLikePart = observedHasEffectLikePart(observed);
		TileObject tileObject = observed.tileObject;
		if (tileObject instanceof GameObject)
		{
			return hasEffectLikePart
				? ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.EFFECT, "observed GameObject has effect-like part")
				: ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.OBJECT, "observed GameObject has no effect-like part");
		}

		if (tileObject instanceof DecorativeObject)
		{
			return hasEffectLikePart
				? ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.EFFECT, "observed DecorativeObject has effect-like part")
				: ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.UNKNOWN, "observed DecorativeObject has no effect-like part");
		}

		if (tileObject instanceof WallObject)
		{
			return hasEffectLikePart
				? ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.EFFECT, "observed WallObject has effect-like part")
				: ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.UNKNOWN, "observed WallObject has no effect-like part");
		}

		if (tileObject instanceof GroundObject)
		{
			return hasEffectLikePart
				? ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.EFFECT, "observed GroundObject has effect-like part")
				: ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.UNKNOWN, "observed GroundObject has no effect-like part");
		}

		return ObjectClassifier.ClassificationDecision.of(ClassifiedObjectType.UNKNOWN, "observed tileObject wrapper not handled");
	}

	private boolean observedHasEffectLikePart(ObservedTileObject observed)
	{
		if (observed == null || observed.parts == null)
		{
			return false;
		}

		for (ObjectRenderablePart part : observed.parts)
		{
			if (part == null || part.renderable == null)
			{
				continue;
			}

			if (ObjectClassifier.classifyRenderable(part.renderable) == ClassifiedObjectType.EFFECT)
			{
				return true;
			}
		}

		return false;
	}

	private String classificationDebugMessage(Object source, ObjectClassifier.ClassificationDecision decision, String extraTypes)
	{
		String type = classificationDebugApiType(source);
		String implType = source.getClass().getSimpleName();
		String id = classificationDebugId(source);
		String name = classificationDebugName(source);
		String position = classificationDebugPosition(source);
		String relatedTypes = extraTypes == null || extraTypes.isEmpty() ? "-" : extraTypes;
		return "Classification: Type: " + type
			+ ", Impl: " + implType
			+ ", ID: " + id
			+ ", Name: " + name
			+ ", Position: " + position
			+ ", Related: " + relatedTypes
			+ ", Reason: '" + decision.reason + "'"
			+ ", Classification: " + decision.classification;
	}

	private String classificationDebugApiType(Object source)
	{
		if (source instanceof NPC)
		{
			return "NPC";
		}

		if (source instanceof Player)
		{
			return "Player";
		}

		if (source instanceof Projectile)
		{
			return "Projectile";
		}

		if (source instanceof GraphicsObject)
		{
			return "GraphicsObject";
		}

		if (source instanceof ActorSpotAnim)
		{
			return "ActorSpotAnim";
		}

		if (source instanceof TileItem)
		{
			return "TileItem";
		}

		if (source instanceof GameObject)
		{
			return "GameObject";
		}

		if (source instanceof DecorativeObject)
		{
			return "DecorativeObject";
		}

		if (source instanceof WallObject)
		{
			return "WallObject";
		}

		if (source instanceof GroundObject)
		{
			return "GroundObject";
		}

		if (source instanceof TileObject)
		{
			return "TileObject";
		}

		if (source instanceof DynamicObject)
		{
			return "DynamicObject";
		}

		if (source instanceof Renderable)
		{
			return "Renderable";
		}

		return source.getClass().getSimpleName();
	}

	private String classificationDebugId(Object source)
	{
		if (source instanceof TileObject)
		{
			return Integer.toString(((TileObject) source).getId());
		}

		if (source instanceof NPC)
		{
			return Integer.toString(((NPC) source).getId());
		}

		if (source instanceof TileItem)
		{
			return Integer.toString(((TileItem) source).getId());
		}

		if (source instanceof GraphicsObject)
		{
			return Integer.toString(((GraphicsObject) source).getId());
		}

		if (source instanceof ActorSpotAnim)
		{
			return Integer.toString(((ActorSpotAnim) source).getId());
		}

		if (source instanceof Projectile)
		{
			return Integer.toString(((Projectile) source).getId());
		}

		if (source instanceof Player)
		{
			Player player = (Player) source;
			return player.getName() != null ? player.getName() : "player";
		}

		return "-";
	}

	private String classificationDebugName(Object source)
	{
		if (source instanceof Player)
		{
			String name = ((Player) source).getName();
			return name != null && !name.isEmpty() ? name : "-";
		}

		if (source instanceof NPC)
		{
			String name = ((NPC) source).getName();
			return name != null && !name.isEmpty() ? name : "-";
		}

		if (source instanceof TileObject)
		{
			if (!client.isClientThread())
			{
				return "-";
			}

			net.runelite.api.ObjectComposition objectDefinition = client.getObjectDefinition(((TileObject) source).getId());
			if (objectDefinition == null)
			{
				return "-";
			}

			String name = objectDefinition.getName();
			return name != null && !name.trim().isEmpty() ? name : "-";
		}

		return "-";
	}

	private String classificationDebugPosition(Object source)
	{
		if (source instanceof TileObject)
		{
			TileObject tileObject = (TileObject) source;
			LocalPoint localPoint = tileObject.getLocalLocation();
			String local = formatLocalPoint(localPoint);
			String world = tileObject.getWorldLocation() != null
				? tileObject.getWorldLocation().getX() + "," + tileObject.getWorldLocation().getY() + "," + tileObject.getPlane()
				: "-";
			return "world=" + world + " local=" + local;
		}

		if (source instanceof Actor)
		{
			Actor actor = (Actor) source;
			LocalPoint localPoint = actor.getLocalLocation();
			String local = formatLocalPoint(localPoint);
			String world = actor.getWorldLocation() != null
				? actor.getWorldLocation().getX() + "," + actor.getWorldLocation().getY() + "," + actor.getWorldView().getPlane()
				: "-";
			return "world=" + world + " local=" + local;
		}

		if (source instanceof GraphicsObject)
		{
			GraphicsObject graphicsObject = (GraphicsObject) source;
			return "level=" + graphicsObject.getLevel() + " local=" + formatLocalPoint(graphicsObject.getLocation());
		}

		if (source instanceof Projectile)
		{
			Projectile projectile = (Projectile) source;
			return "floor=" + projectile.getFloor() + " local=" + formatLocalPoint(BillboardProjectileGeometry.localPoint(projectile));
		}

		return "-";
	}

	private void logObservedTileObjectClassification(ObservedTileObject observed, ObjectClassifier.ClassificationDecision decision)
	{
		if (!log.isDebugEnabled() || observed == null || observed.tileObject == null || decision == null)
		{
			return;
		}

		if (decision.classification == observed.lastLoggedClassification
			&& Objects.equals(decision.reason, observed.lastLoggedClassificationReason))
		{
			return;
		}

		observed.lastLoggedClassification = decision.classification;
		observed.lastLoggedClassificationReason = decision.reason;

		TileObject tileObject = observed.tileObject;
		String renderableTypes = observedRenderableTypes(observed);
		logDecision(tileObject, decision, renderableTypes);
	}

	private String observedRenderableTypes(ObservedTileObject observed)
	{
		if (observed == null || observed.parts == null || observed.parts.isEmpty())
		{
			return "-";
		}

		StringBuilder builder = new StringBuilder();
		for (ObjectRenderablePart part : observed.parts)
		{
			if (part == null || part.renderable == null)
			{
				continue;
			}

			if (builder.length() > 0)
			{
				builder.append(", ");
			}

			builder.append(classificationDebugApiType(part.renderable))
				.append("(")
				.append(part.renderable.getClass().getSimpleName())
				.append(")");
		}

		return builder.length() > 0 ? builder.toString() : "-";
	}

	private static String formatLocalPoint(LocalPoint localPoint)
	{
		if (localPoint == null)
		{
			return "-";
		}

		return localPoint.getX() + "," + localPoint.getY();
	}

}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.features.GroundItemBillboard;
import java.util.Map;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Renderable;
import net.runelite.api.TileItem;

public final class BillboardHoverInteractionResolver
{
	private BillboardHoverInteractionResolver()
	{
	}

	public static Actor hoveredActor(Client client)
	{
		Renderable target = hoveredTarget(client, null);
		return target instanceof Actor ? (Actor) target : null;
	}

	public static Renderable hoveredTarget(Client client, Iterable<Map.Entry<TileItem, GroundItemBillboard>> groundItems)
	{
		MenuEntry[] menuEntries = client.getMenuEntries();
		if (menuEntries == null || menuEntries.length == 0)
		{
			return null;
		}

		MenuEntry hoveredEntry = client.isMenuOpen()
			? hoveredMenuEntry(client, menuEntries)
			: menuEntries[menuEntries.length - 1];
		if (hoveredEntry == null)
		{
			return null;
		}

		if (isActorHoverAction(hoveredEntry.getType()))
		{
			return hoveredEntry.getActor();
		}
		return isGroundItemAction(hoveredEntry.getType())
			? groundItem(hoveredEntry, groundItems)
			: null;
	}

	public static Actor interactedActor(Client client, Actor explicitInteraction)
	{
		if (explicitInteraction != null)
		{
			return explicitInteraction;
		}

		Player localPlayer = client.getLocalPlayer();
		return localPlayer != null ? localPlayer.getInteracting() : null;
	}

	public static boolean isActorHoverAction(MenuAction action)
	{
		if (action == null)
		{
			return false;
		}

		switch (action)
		{
			case ITEM_USE_ON_NPC:
			case WIDGET_TARGET_ON_NPC:
			case NPC_FIRST_OPTION:
			case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION:
			case NPC_FOURTH_OPTION:
			case NPC_FIFTH_OPTION:
			case ITEM_USE_ON_PLAYER:
			case WIDGET_TARGET_ON_PLAYER:
			case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION:
			case PLAYER_THIRD_OPTION:
			case PLAYER_FOURTH_OPTION:
			case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION:
			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	public static boolean isActorInteractionAction(MenuAction action)
	{
		return isActorHoverAction(action) || action == MenuAction.WORLD_ENTITY_FIRST_OPTION;
	}

	public static boolean isGroundItemAction(MenuAction action)
	{
		if (action == null)
		{
			return false;
		}
		switch (action)
		{
			case ITEM_USE_ON_GROUND_ITEM:
			case WIDGET_TARGET_ON_GROUND_ITEM:
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	public static TileItem groundItem(MenuEntry entry, Iterable<Map.Entry<TileItem, GroundItemBillboard>> groundItems)
	{
		if (entry == null || groundItems == null)
		{
			return null;
		}
		for (Map.Entry<TileItem, GroundItemBillboard> candidate : groundItems)
		{
			TileItem item = candidate.getKey();
			GroundItemBillboard billboard = candidate.getValue();
			if (item != null && billboard != null && item.getId() == entry.getIdentifier()
				&& billboard.localPoint.getSceneX() == entry.getParam0()
				&& billboard.localPoint.getSceneY() == entry.getParam1())
			{
				return item;
			}
		}
		return null;
	}

	private static MenuEntry hoveredMenuEntry(Client client, MenuEntry[] menuEntries)
	{
		int menuX = client.getMenuX();
		int menuY = client.getMenuY();
		int menuWidth = client.getMenuWidth();
		Point mouse = client.getMouseCanvasPosition();
		int row = mouse.getY() - menuY - 19;
		if (row < 0)
		{
			return menuEntries[menuEntries.length - 1];
		}

		row = (menuEntries.length - 1) - (row / 15);
		if (mouse.getX() > menuX && mouse.getX() < menuX + menuWidth && row >= 0 && row < menuEntries.length)
		{
			return menuEntries[row];
		}

		return menuEntries[menuEntries.length - 1];
	}
}

package com.kierenboal.npcsnap.targeting;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.TileItem;
import com.kierenboal.npcsnap.features.GroundItemBillboard;
import java.util.Map;

public final class BillboardInteractionState
{
	private Actor clickedActor;
	private TileItem clickedGroundItem;
	private int clickedActorTick = Integer.MIN_VALUE;
	private Renderable frameHoveredTarget;
	private Renderable frameInteractionTarget;
	private Renderable lastHoveredTarget;
	private Renderable lastInteractionTarget;

	public void noteClick(Actor actor, int tickCount)
	{
		clickedGroundItem = null;
		clickedActor = actor;
		clickedActorTick = actor != null ? tickCount : Integer.MIN_VALUE;
	}

	public void noteGroundItemClick(TileItem item)
	{
		clickedActor = null;
		clickedActorTick = Integer.MIN_VALUE;
		clickedGroundItem = item;
	}

	public void clearIfStale(Player localPlayer, int tickCount)
	{
		if (clickedActor == null || tickCount <= clickedActorTick)
		{
			return;
		}

		Actor currentTarget = localPlayer != null ? localPlayer.getInteracting() : null;
		if (currentTarget != clickedActor)
		{
			clear();
		}
	}

	public void onLocalPlayerInteractionChanged(Actor target, int tickCount)
	{
		if (clickedActor != null && target != clickedActor && tickCount > clickedActorTick)
		{
			clear();
		}
	}

	public void clearIfMatches(Actor actor)
	{
		if (actor == clickedActor)
		{
			clear();
		}
	}

	public void clear()
	{
		clickedActor = null;
		clickedGroundItem = null;
		clickedActorTick = Integer.MIN_VALUE;
		frameInteractionTarget = null;
		lastInteractionTarget = null;
	}

	public Change update(Client client, Iterable<Map.Entry<TileItem, GroundItemBillboard>> groundItems)
	{
		Renderable hoveredTarget = BillboardHoverInteractionResolver.hoveredTarget(client, groundItems);
		Renderable interactionTarget = clickedGroundItem != null
			? clickedGroundItem
			: BillboardHoverInteractionResolver.interactedActor(client, clickedActor);
		frameHoveredTarget = hoveredTarget;
		frameInteractionTarget = interactionTarget;
		if (hoveredTarget == lastHoveredTarget && interactionTarget == lastInteractionTarget)
		{
			return Change.unchanged();
		}

		Change change = new Change(lastHoveredTarget, hoveredTarget, lastInteractionTarget, interactionTarget);
		lastHoveredTarget = hoveredTarget;
		lastInteractionTarget = interactionTarget;
		return change;
	}

	public Renderable frameHoveredTarget()
	{
		return frameHoveredTarget;
	}

	public Renderable frameInteractionTarget()
	{
		return frameInteractionTarget;
	}

	public Renderable priorityTarget()
	{
		return frameInteractionTarget != null ? frameInteractionTarget : frameHoveredTarget;
	}

	public Actor clickedActor()
	{
		return clickedActor;
	}

	public TileItem clickedGroundItem()
	{
		return clickedGroundItem;
	}

	public void clearIfMatches(TileItem item)
	{
		if (item == clickedGroundItem)
		{
			clear();
		}
	}

	public static final class Change
	{
		private static final Change UNCHANGED = new Change(null, null, null, null, false);
		public final Renderable previousHoveredTarget;
		public final Renderable hoveredTarget;
		public final Renderable previousInteractionTarget;
		public final Renderable interactionTarget;
		public final boolean changed;

		private Change(Renderable previousHoveredTarget, Renderable hoveredTarget, Renderable previousInteractionTarget, Renderable interactionTarget)
		{
			this(previousHoveredTarget, hoveredTarget, previousInteractionTarget, interactionTarget, true);
		}

		private Change(Renderable previousHoveredTarget, Renderable hoveredTarget, Renderable previousInteractionTarget, Renderable interactionTarget, boolean changed)
		{
			this.previousHoveredTarget = previousHoveredTarget;
			this.hoveredTarget = hoveredTarget;
			this.previousInteractionTarget = previousInteractionTarget;
			this.interactionTarget = interactionTarget;
			this.changed = changed;
		}

		private static Change unchanged()
		{
			return UNCHANGED;
		}
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.NpcSnapConfig;

import net.runelite.api.DecorativeObject;
import net.runelite.api.Actor;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.ItemLayer;
import net.runelite.api.Renderable;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;

public final class BillboardSceneDrawCallbacks
{
	public interface OverlayAccess
	{
		void noteSceneRenderable(Renderable renderable);

		default void noteSceneActorDraw(Actor actor)
		{
		}

		void observeTileObject(TileObject tileObject);

		boolean shouldHideRenderable(Renderable renderable);

		boolean shouldHideActor2d(Renderable renderable);

		boolean shouldHideTileObject(TileObject tileObject);
	}

	private final NpcSnapConfig config;
	private final OverlayAccess overlay;

	public BillboardSceneDrawCallbacks(NpcSnapConfig config, OverlayAccess overlay)
	{
		this.config = config;
		this.overlay = overlay;
	}

	public boolean addEntity(Renderable renderable, boolean drawingUi)
	{
		if (drawingUi)
		{
			return !overlay.shouldHideActor2d(renderable);
		}
		if (!isActiveSceneDraw(drawingUi))
		{
			return true;
		}

		overlay.noteSceneRenderable(renderable);
		// addEntity() controls whether RuneLite adds the temporary entity at all.
		// It must not be used for visual suppression: returning false removes the
		// entity from the scene traversal before the draw callback can hide its
		// model.
		// Keep every entity in the callback chain and apply suppression in draw().
		return true;
	}

	public boolean draw(Renderable renderable, boolean drawingUi)
	{
		if (drawingUi)
		{
			return !overlay.shouldHideActor2d(renderable);
		}
		if (!isActiveSceneDraw(drawingUi))
		{
			return true;
		}

		overlay.noteSceneRenderable(renderable);
		return !overlay.shouldHideRenderable(renderable);
	}

	public boolean drawObject(TileObject tileObject)
	{
		if (!config.enable2dBillboardSprites())
		{
			return true;
		}

		if (tileObject instanceof GameObject)
		{
			return shouldDrawObservedObject(tileObject, ((GameObject) tileObject).getRenderable());
		}

		if (tileObject instanceof GroundObject)
		{
			return shouldDrawObservedObject(tileObject, ((GroundObject) tileObject).getRenderable());
		}

		if (tileObject instanceof DecorativeObject)
		{
			if (observeAndShouldHide(tileObject))
			{
				return false;
			}
			DecorativeObject object = (DecorativeObject) tileObject;
			return shouldDrawAll(object.getRenderable(), object.getRenderable2());
		}

		if (tileObject instanceof WallObject)
		{
			if (observeAndShouldHide(tileObject))
			{
				return false;
			}
			WallObject object = (WallObject) tileObject;
			return shouldDrawAll(object.getRenderable1(), object.getRenderable2());
		}

		if (tileObject instanceof ItemLayer)
		{
			ItemLayer layer = (ItemLayer) tileObject;
			Renderable bottom = layer.getBottom();
			Renderable middle = layer.getMiddle();
			Renderable top = layer.getTop();
			overlay.noteSceneRenderable(bottom);
			overlay.noteSceneRenderable(middle);
			overlay.noteSceneRenderable(top);
			return shouldDrawAll(bottom, middle, top);
		}

		return true;
	}

	private boolean isActiveSceneDraw(boolean drawingUi)
	{
		return config.enable2dBillboardSprites() && !drawingUi;
	}

	private boolean shouldDrawObservedObject(TileObject tileObject, Renderable renderable)
	{
		overlay.noteSceneRenderable(renderable);
		return !observeAndShouldHide(tileObject) && shouldDraw(renderable);
	}

	private boolean observeAndShouldHide(TileObject tileObject)
	{
		if (!config.applyToObjects() && !config.applyToGraphicsObjects())
		{
			return false;
		}

		overlay.observeTileObject(tileObject);
		return overlay.shouldHideTileObject(tileObject);
	}

	private boolean shouldDrawAll(Renderable first, Renderable second)
	{
		return shouldDraw(first) && shouldDraw(second);
	}

	private boolean shouldDrawAll(Renderable first, Renderable second, Renderable third)
	{
		return shouldDraw(first) && shouldDraw(second) && shouldDraw(third);
	}

	private boolean shouldDraw(Renderable renderable)
	{
		overlay.noteSceneRenderable(renderable);
		if (renderable instanceof Actor)
		{
			overlay.noteSceneActorDraw((Actor) renderable);
		}
		return !overlay.shouldHideRenderable(renderable);
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.features.GroundItemBillboard;
import com.kierenboal.npcsnap.rendering.BillboardPaintOrder;

import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Renderable;
import net.runelite.api.TileItem;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;

public final class BillboardTarget
{
	public final BillboardTargetType type;
	public final ClassifiedObjectType classifiedType;
	public final Renderable renderable;
	public final Actor parentActor;
	public final TileObject tileObject;
	public final ObservedTileObject observedTileObject;
	public final GroundItemBillboard groundItem;
	public final double depth;
	public final int renderPriority;
	public final PriorityTileKey priorityTileKey;
	public final BillboardTargetKey targetKey;

	private BillboardTarget(
		BillboardTargetType type,
		ClassifiedObjectType classifiedType,
		Renderable renderable,
		Actor parentActor,
		TileObject tileObject,
		ObservedTileObject observedTileObject,
		GroundItemBillboard groundItem,
		double depth,
		int renderPriority,
		PriorityTileKey priorityTileKey,
		BillboardTargetKey targetKey
	)
	{
		this.type = type;
		this.classifiedType = classifiedType;
		this.renderable = renderable;
		this.parentActor = parentActor;
		this.tileObject = tileObject;
		this.observedTileObject = observedTileObject;
		this.groundItem = groundItem;
		this.depth = depth;
		this.renderPriority = renderPriority;
		this.priorityTileKey = priorityTileKey;
		this.targetKey = targetKey;
	}

	public static BillboardTarget forRenderable(
		BillboardTargetType type,
		ClassifiedObjectType classifiedType,
		Renderable renderable,
		double depth,
		LocalPoint localPoint,
		int plane
	)
	{
		int renderPriority = ObjectClassifier.renderPriority(classifiedType);
		return new BillboardTarget(
			type,
			classifiedType,
			renderable,
			null,
			null,
			null,
			null,
			depth,
			renderPriority,
			PriorityTileKey.of(localPoint, plane, renderPriority),
			BillboardTargetKey.forRenderable(type, renderable, localPoint, plane)
		);
	}

	public static BillboardTarget forActorSpotAnim(ActorSpotAnim actorSpotAnim, Actor actor, double depth)
	{
		LocalPoint localPoint = actor.getLocalLocation();
		int plane = actor.getWorldView().getPlane();
		int renderPriority = ObjectClassifier.renderPriority(ClassifiedObjectType.EFFECT);
		return new BillboardTarget(
			BillboardTargetType.ACTOR_SPOT_ANIM,
			ClassifiedObjectType.EFFECT,
			actorSpotAnim,
			actor,
			null,
			null,
			null,
			depth,
			renderPriority,
			PriorityTileKey.of(localPoint, plane, renderPriority),
			BillboardTargetKey.forActorSpotAnim(actorSpotAnim, actor, localPoint, plane)
		);
	}

	public static BillboardTarget forGroundItem(TileItem item, GroundItemBillboard groundItem, double depth)
	{
		int renderPriority = ObjectClassifier.renderPriority(ClassifiedObjectType.GROUND_ITEM);
		return new BillboardTarget(
			BillboardTargetType.GROUND_ITEM,
			ClassifiedObjectType.GROUND_ITEM,
			item,
			null,
			null,
			null,
			groundItem,
			depth,
			renderPriority,
			PriorityTileKey.of(groundItem.localPoint, groundItem.plane, renderPriority),
			BillboardTargetKey.forGroundItem(item, groundItem)
		);
	}

	public static BillboardTarget forTileObject(ObservedTileObject observedTileObject, double depth)
	{
		ClassifiedObjectType classifiedType = observedTileObject != null ? observedTileObject.classifiedType : ClassifiedObjectType.UNKNOWN;
		int renderPriority = ObjectClassifier.renderPriority(classifiedType);
		return new BillboardTarget(
			BillboardTargetType.TILE_OBJECT,
			classifiedType,
			null,
			null,
			observedTileObject.tileObject,
			observedTileObject,
			null,
			depth,
			renderPriority,
			PriorityTileKey.of(firstLocalPoint(observedTileObject), firstPlane(observedTileObject), renderPriority),
			BillboardTargetKey.forTileObject(observedTileObject.tileObject, firstLocalPoint(observedTileObject), firstPlane(observedTileObject))
		);
	}

	public double getDepth()
	{
		return depth;
	}

	public int getRenderPriority()
	{
		return renderPriority;
	}

	public PriorityTileKey getPriorityTileKey()
	{
		return priorityTileKey;
	}

	public long priorityGroupSortKey()
	{
		return priorityTileKey != null ? priorityTileKey.sortKey() : BillboardPaintOrder.NO_PRIORITY_GROUP;
	}

	private static LocalPoint firstLocalPoint(ObservedTileObject observedTileObject)
	{
		if (observedTileObject == null)
		{
			return null;
		}

		for (ObjectRenderablePart part : observedTileObject.parts)
		{
			if (part.localPoint != null)
			{
				return part.localPoint;
			}
		}

		return null;
	}

	private static int firstPlane(ObservedTileObject observedTileObject)
	{
		if (observedTileObject == null)
		{
			return -1;
		}

		for (ObjectRenderablePart part : observedTileObject.parts)
		{
			return part.plane;
		}

		return -1;
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.BillboardConstants;
import com.kierenboal.npcsnap.features.GroundItemBillboard;
import com.kierenboal.npcsnap.NpcSnapConfig;
import com.kierenboal.npcsnap.occlusion.BillboardPlaneUtils;
import com.kierenboal.npcsnap.rendering.BillboardProjectileGeometry;
import com.kierenboal.npcsnap.rendering.BillboardEffectGeometry;
import com.kierenboal.npcsnap.rendering.BillboardRenderRequest;
import com.kierenboal.npcsnap.rendering.BillboardRenderRequestFactory;

import java.awt.Polygon;
import java.awt.Rectangle;
import java.util.function.BiPredicate;
import java.util.function.Function;
import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Client;
import net.runelite.api.GraphicsObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Projectile;
import net.runelite.api.Renderable;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

public final class BillboardTargetEligibility
{
	private final Client client;
	private final NpcSnapConfig config;
	private final BillboardRenderRequestFactory requestFactory;
	private final Function<BillboardRenderRequest, Rectangle> projectedBounds;
	private final BiPredicate<Renderable, BillboardRenderRequest> renderedInFront;

	public BillboardTargetEligibility(
		Client client,
		NpcSnapConfig config,
		BillboardRenderRequestFactory requestFactory,
		Function<BillboardRenderRequest, Rectangle> projectedBounds,
		BiPredicate<Renderable, BillboardRenderRequest> renderedInFront)
	{
		this.client = client;
		this.config = config;
		this.requestFactory = requestFactory;
		this.projectedBounds = projectedBounds;
		this.renderedInFront = renderedInFront;
	}

	public boolean actor(LocalPoint localPlayerLocation, LocalPoint actorLocation, Actor actor, Rectangle viewport)
	{
		WorldView actorWorldView = actor.getWorldView();
		boolean projectedNested = !actorWorldView.isTopLevel();
		actorLocation = WorldViewLocationResolver.toMainWorld(client.getTopLevelWorldView(), actorWorldView, actorLocation);
		int actorPlane = projectedNested ? 0 : actorWorldView.getPlane();
		if (!hasEligibleLocation(localPlayerLocation, actorLocation, actorPlane))
		{
			return false;
		}

		Polygon tilePolygon = actor.getCanvasTilePoly();
		if (tilePolygon != null && tilePolygon.getBounds().intersects(viewport))
		{
			return true;
		}

		int verticalOffset = actor.getAnimationHeightOffset();
		Point canvasPoint = Perspective.localToCanvas(
			client, actorLocation, actorPlane, verticalOffset + (actor.getModelHeight() / 2));
		if (isInside(viewport, canvasPoint))
		{
			return true;
		}

		BillboardRenderRequest request = requestFactory.buildActor(actor);
		return projectedOrInFront(actor, request, viewport);
	}

	public boolean projectile(LocalPoint localPlayerLocation, Projectile projectile, Rectangle viewport)
	{
		if (!projectileInWorld(localPlayerLocation, projectile))
		{
			return false;
		}

		Point canvasPoint = Perspective.localToCanvas(
			client, (int) projectile.getX(), (int) projectile.getY(), (int) Math.round(projectile.getZ()));
		if (isInside(viewport, canvasPoint))
		{
			return true;
		}

		BillboardRenderRequest request = requestFactory.buildProjectile(projectile);
		return projectedOrInFront(projectile, request, viewport);
	}

	public boolean projectileInWorld(LocalPoint localPlayerLocation, Projectile projectile)
	{
		return projectile != null
			&& projectile.getModel() != null
			&& hasEligibleLocation(localPlayerLocation, BillboardProjectileGeometry.localPoint(projectile), projectile.getFloor());
	}

	public boolean graphicsObject(LocalPoint localPlayerLocation, GraphicsObject object, Rectangle viewport)
	{
		LocalPoint location = object.getLocation();
		if (!hasEligibleLocation(localPlayerLocation, location, object.getLevel()) || object.getModel() == null)
		{
			return false;
		}

		Point canvasPoint = Perspective.localToCanvas(client, location, object.getLevel(),
			BillboardEffectGeometry.graphicsVerticalOffset(client, object));
		if (isInside(viewport, canvasPoint))
		{
			return true;
		}

		BillboardRenderRequest request = requestFactory.buildGraphicsObject(object);
		return projectedOrInFront(object, request, viewport);
	}

	public boolean actorSpotAnimation(Actor actor, ActorSpotAnim spotAnimation, Rectangle viewport)
	{
		if (actor == null || spotAnimation == null || viewport == null)
		{
			return false;
		}

		LocalPoint localPlayerLocation = client.getLocalPlayer() != null ? client.getLocalPlayer().getLocalLocation() : null;
		LocalPoint actorLocation = WorldViewLocationResolver.toMainWorld(client.getTopLevelWorldView(), actor);
		int plane = actor.getWorldView().isTopLevel() ? actor.getWorldView().getPlane() : 0;
		if (!hasEligibleLocation(localPlayerLocation, actorLocation, plane)
			|| spotAnimation.getModel() == null)
		{
			return false;
		}

		int verticalOffset = BillboardEffectGeometry.actorSpotVerticalOffset(spotAnimation);
		Point canvasPoint = Perspective.localToCanvas(
			client, actorLocation, plane, verticalOffset + (spotAnimation.getModelHeight() / 2));
		if (isInside(viewport, canvasPoint))
		{
			return true;
		}

		BillboardRenderRequest request = requestFactory.buildActorSpotAnimation(spotAnimation, actor);
		return projectedOrInFront(spotAnimation, request, viewport);
	}

	public boolean groundItem(LocalPoint localPlayerLocation, TileItem item, GroundItemBillboard groundItem, Rectangle viewport)
	{
		if (groundItem == null || !hasEligibleLocation(localPlayerLocation, groundItem.localPoint, groundItem.plane))
		{
			return false;
		}

		Point canvasPoint = Perspective.localToCanvas(
			client,
			groundItem.localPoint,
			groundItem.plane,
			groundItem.verticalOffset + Math.max(0, item.getModelHeight() / 2));
		if (isInside(viewport, canvasPoint))
		{
			return true;
		}

		BillboardRenderRequest request = requestFactory.buildGroundItem(item, groundItem);
		return projectedOrInFront(item, request, viewport);
	}

	public boolean tileObject(LocalPoint localPlayerLocation, ObservedTileObject observed, Rectangle viewport)
	{
		if (localPlayerLocation == null || observed == null)
		{
			return false;
		}

		for (ObjectRenderablePart part : observed.parts)
		{
			if (part.localPoint == null || part.renderable == null
				|| !hasEligibleLocation(localPlayerLocation, part.localPoint, part.plane))
			{
				continue;
			}

			Point canvasPoint = Perspective.localToCanvas(
				client, part.localPoint, part.plane, Math.max(0, part.renderable.getModelHeight() / 2));
			if (isInside(viewport, canvasPoint))
			{
				return true;
			}

			BillboardRenderRequest request = requestFactory.buildStaticObjectPart(part);
			if (projectedOrInFront(part.renderable, request, viewport))
			{
				return true;
			}
		}
		return false;
	}

	private boolean hasEligibleLocation(LocalPoint player, LocalPoint target, int targetPlane)
	{
		return player != null
			&& target != null
			&& isPlaneEligible(targetPlane)
			&& isWithinRadius(player, target, config.billboardRadiusTiles());
	}

	private boolean isPlaneEligible(int targetPlane)
	{
		return config.renderBillboardsOnAllPlanes()
			|| BillboardPlaneUtils.shouldRenderTargetPlane(client.getPlane(), targetPlane);
	}

	private static boolean isWithinRadius(LocalPoint source, LocalPoint target, int radiusTiles)
	{
		int dx = source.getX() - target.getX();
		int dy = source.getY() - target.getY();
		int radius = radiusTiles * BillboardConstants.LOCAL_TILE_SIZE;
		return (dx * dx) + (dy * dy) <= (radius * radius);
	}

	private boolean projectedOrInFront(Renderable renderable, BillboardRenderRequest request, Rectangle viewport)
	{
		Rectangle bounds = projectedBounds.apply(request);
		return (bounds != null && bounds.intersects(viewport)) || renderedInFront.test(renderable, request);
	}

	private static boolean isInside(Rectangle viewport, Point point)
	{
		return point != null && viewport.contains(point.getX(), point.getY());
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.BillboardConstants;
import com.kierenboal.npcsnap.features.GroundItemBillboard;

import net.runelite.api.Actor;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.GraphicsObject;
import net.runelite.api.NPC;
import net.runelite.api.Projectile;
import net.runelite.api.Renderable;
import net.runelite.api.TileItem;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;

public final class BillboardTargetKey
{
	private final long orderKey;
	private final long uniqueKey;

	private BillboardTargetKey(long orderKey, long uniqueKey)
	{
		this.orderKey = orderKey;
		this.uniqueKey = uniqueKey;
	}

	public static BillboardTargetKey forRenderable(BillboardTargetType type, Renderable renderable, LocalPoint localPoint, int plane)
	{
		int entityId = renderableEntityId(type, renderable);
		long locationKey = locationKey(localPoint, plane);
		long orderKey = composeOrderKey(type.ordinal(), entityId, locationKey);
		long uniqueKey = composeUniqueKey(orderKey, System.identityHashCode(renderable));
		return new BillboardTargetKey(orderKey, uniqueKey);
	}

	public static BillboardTargetKey forActorSpotAnim(ActorSpotAnim actorSpotAnim, Actor actor, LocalPoint localPoint, int plane)
	{
		long locationKey = locationKey(localPoint, plane);
		long orderKey = composeOrderKey(BillboardTargetType.ACTOR_SPOT_ANIM.ordinal(), actorSpotAnim.getId(), locationKey);
		long uniqueKey = composeUniqueKey(orderKey, System.identityHashCode(actorSpotAnim) ^ System.identityHashCode(actor));
		return new BillboardTargetKey(orderKey, uniqueKey);
	}

	public static BillboardTargetKey forGroundItem(TileItem item, GroundItemBillboard groundItem)
	{
		LocalPoint localPoint = groundItem != null ? groundItem.localPoint : null;
		int plane = groundItem != null ? groundItem.plane : -1;
		long locationKey = locationKey(localPoint, plane);
		long orderKey = composeOrderKey(BillboardTargetType.GROUND_ITEM.ordinal(), item.getId(), locationKey);
		long uniqueKey = composeUniqueKey(orderKey, System.identityHashCode(item));
		return new BillboardTargetKey(orderKey, uniqueKey);
	}

	public static BillboardTargetKey forTileObject(TileObject tileObject, LocalPoint localPoint, int plane)
	{
		int objectId = tileObject != null ? tileObject.getId() : -1;
		long locationKey = locationKey(localPoint, plane);
		long orderKey = composeOrderKey(BillboardTargetType.TILE_OBJECT.ordinal(), objectId, locationKey);
		long uniqueKey = composeUniqueKey(orderKey, System.identityHashCode(tileObject));
		return new BillboardTargetKey(orderKey, uniqueKey);
	}

	public static int compareForQueueOrder(BillboardTargetKey left, BillboardTargetKey right)
	{
		int byOrder = Long.compare(left.orderKey, right.orderKey);
		if (byOrder != 0)
		{
			return byOrder;
		}

		return Long.compare(left.uniqueKey, right.uniqueKey);
	}

	public long stableSortOrder()
	{
		return uniqueKey;
	}

	private static int renderableEntityId(BillboardTargetType type, Renderable renderable)
	{
		if (renderable == null)
		{
			return -1;
		}

		switch (type)
		{
			case NPC:
				return ((NPC) renderable).getId();
			case PROJECTILE:
				return ((Projectile) renderable).getId();
			case GRAPHICS_OBJECT:
				return ((GraphicsObject) renderable).getId();
			case GROUND_ITEM:
				return ((TileItem) renderable).getId();
			default:
				return System.identityHashCode(renderable);
		}
	}

	private static long composeOrderKey(int typeOrdinal, int entityId, long locationKey)
	{
		long key = ((long) typeOrdinal & 0xFFL) << 56;
		key |= ((long) entityId & 0xFFFFFFL) << 32;
		key |= locationKey & 0xFFFFFFFFL;
		return key;
	}

	private static long composeUniqueKey(long orderKey, int identityHash)
	{
		return (orderKey * 31L) ^ (identityHash & 0xFFFFFFFFL);
	}

	private static long locationKey(LocalPoint localPoint, int plane)
	{
		if (localPoint == null)
		{
			return plane & 0x3L;
		}

		long tileX = (localPoint.getX() / BillboardConstants.LOCAL_TILE_SIZE) & 0x7FFL;
		long tileY = (localPoint.getY() / BillboardConstants.LOCAL_TILE_SIZE) & 0x7FFL;
		long planeBits = plane & 0x3L;
		return (planeBits << 22) | (tileX << 11) | tileY;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}

		if (!(other instanceof BillboardTargetKey))
		{
			return false;
		}

		BillboardTargetKey that = (BillboardTargetKey) other;
		return orderKey == that.orderKey && uniqueKey == that.uniqueKey;
	}

	@Override
	public int hashCode()
	{
		int result = Long.hashCode(orderKey);
		result = (31 * result) + Long.hashCode(uniqueKey);
		return result;
	}
}

package com.kierenboal.npcsnap.targeting;

import java.util.IdentityHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Scene;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.client.callback.RenderCallbackManager;

/** Keeps sprites on a boat subject to the visibility of their parent scene. */
@Singleton
public class BillboardWorldViewVisibility
{
	private final Client client;
	private final RenderCallbackManager renderCallbacks;
	private final Map<WorldView, WorldEntity> parents = new IdentityHashMap<>();
	private final Map<Scene, Boolean> sceneVisibility = new IdentityHashMap<>();

	@Inject
	public BillboardWorldViewVisibility(Client client, RenderCallbackManager renderCallbacks)
	{
		this.client = client;
		this.renderCallbacks = renderCallbacks;
	}

	public void beginFrame()
	{
		clear();
		WorldView topLevel = client.getTopLevelWorldView();
		if (topLevel == null || topLevel.worldEntities() == null)
		{
			return;
		}
		// Only inspect the tracked boats, never the scene's tiles or models.
		for (WorldEntity entity : topLevel.worldEntities())
		{
			if (entity != null && entity.getWorldView() != null)
			{
				parents.put(entity.getWorldView(), entity);
			}
		}
	}

	public boolean isVisible(Actor actor)
	{
		return actor != null && isVisible(actor.getWorldView());
	}

	public boolean isVisible(WorldView view)
	{
		if (view == null)
		{
			return false;
		}
		if (view.isTopLevel())
		{
			return true;
		}
		WorldEntity parent = parents.get(view);
		// Overlap state may change during scene drawing, after BeforeRender.
		// Read it live even when the callback decision has already been cached.
		if (parent == null || parent.isHiddenForOverlap())
		{
			return false;
		}
		Scene scene = view.getScene();
		if (scene == null)
		{
			return false;
		}
		// Entity Hider makes its boat decision on this Scene, preserving its
		// exceptions for the local player's boat and non-player boats.
		return sceneVisibility.computeIfAbsent(scene, value -> renderCallbacks.addEntity(value, false));
	}

	public void clear()
	{
		parents.clear();
		sceneVisibility.clear();
	}
}

package com.kierenboal.npcsnap.targeting;

import java.util.List;
import java.util.Map;
import net.runelite.api.Actor;

