		guard.onLoggedIn();

		assertTrue(guard.shouldIgnore(change(Skill.WOODCUTTING, 110), GameState.LOGGED_IN, tracker));
		assertTrue(guard.shouldIgnore(change(Skill.WOODCUTTING, 120), GameState.LOGGED_IN, tracker));
		guard.advanceTick();
		assertFalse(guard.shouldIgnore(change(Skill.WOODCUTTING, 130), GameState.LOGGED_IN, tracker));
	}

	@Test
	public void doesNotIgnoreUntrackedNonIncreaseLoggedOutOrLateDrops()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.seedXp(Skill.WOODCUTTING, 100);
		LoginXpDropGuard guard = new LoginXpDropGuard();
		guard.onLoggedIn();

		assertFalse(guard.shouldIgnore(change(Skill.WOODCUTTING, 100), GameState.LOGGED_IN, tracker));
		assertFalse(guard.shouldIgnore(change(Skill.ATTACK, 110), GameState.LOGGED_IN, tracker));
		assertFalse(guard.shouldIgnore(change(Skill.WOODCUTTING, 110), GameState.LOGIN_SCREEN, tracker));
		for (int i = 0; i < 11; i++)
		{
			guard.advanceTick();
		}
		assertFalse(guard.shouldIgnore(change(Skill.WOODCUTTING, 110), GameState.LOGGED_IN, tracker));
	}

	@Test
	public void logoutCancelsGracePeriod()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.seedXp(Skill.WOODCUTTING, 100);
		LoginXpDropGuard guard = new LoginXpDropGuard();
		guard.onLoggedIn();
		guard.onLoggedOut();

		assertFalse(guard.shouldIgnore(change(Skill.WOODCUTTING, 110), GameState.LOGGED_IN, tracker));
	}

	private static StatChanged change(Skill skill, int xp)
	{
		return new StatChanged(skill, xp, 1, 1);
	}
}

package com.kierenboal.npcsnap.features;

import java.awt.Color;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class RetroChatRendererTest
{
	@Test
	public void parsesEveryRetroColourAndRemovesPrefix()
	{
		String[] codes = {"red", "dre", "lre", "ora", "or1", "or2", "or3", "yel", "gr1",
			"gre", "gr2", "gr3", "blu", "cya", "mag", "bla", "whi"};
		for (String code : codes)
		{
			RetroChatRenderer.ParsedChat chat = RetroChatRenderer.parse("@" + code.toUpperCase() + "@Hello");
			assertEquals("Hello", chat.text);
			assertEquals(RetroChatRenderer.ColorMode.SOLID, chat.colorMode);
		}
	}

	@Test
	public void malformedAndUnknownPrefixesRemainVisible()
	{
		assertEquals("@wat@Hello", RetroChatRenderer.parse("@wat@Hello").text);
		assertEquals("red Hello", RetroChatRenderer.parse("red Hello").text);
	}

	@Test
	public void parsesBuiltInColourAndMotionInEitherOrder()
	{
		RetroChatRenderer.ParsedChat first = RetroChatRenderer.parse("flash2:wave:Hello");
		assertEquals("Hello", first.text);
		assertEquals(RetroChatRenderer.ColorMode.FLASH2, first.colorMode);
		assertEquals(RetroChatRenderer.Motion.WAVE, first.motion);

		RetroChatRenderer.ParsedChat second = RetroChatRenderer.parse("shake:white:Hello");
		assertEquals("Hello", second.text);
		assertEquals(Color.WHITE, second.color);
		assertEquals(RetroChatRenderer.Motion.SHAKE, second.motion);
	}

	@Test
	public void plainChatDoesNotParseCommands()
	{
		RetroChatRenderer.ParsedChat chat = RetroChatRenderer.plain("@red@Hello");
		assertEquals("@red@Hello", chat.text);
		assertEquals(Color.YELLOW, chat.color);
	}

	@Test
	public void randomColourIsStableWithinBucket()
	{
		RetroChatRenderer.ParsedChat chat = RetroChatRenderer.parse("@ran@Hello");
		Object actor = new Object();
		assertEquals(RetroChatRenderer.color(chat, actor, 400L, 0),
			RetroChatRenderer.color(chat, actor, 599L, 0));
	}

	@Test
	public void inlineRetroColoursCreateIndependentRuns()
	{
		RetroChatRenderer.ParsedChat chat = RetroChatRenderer.parse("@red@hello @blu@world!");
		assertEquals("hello world!", chat.text);
		assertEquals(new Color(0xFF0000), chat.colors[0]);
		assertEquals(new Color(0xFF0000), chat.colors[5]);
		assertEquals(new Color(0x0000FF), chat.colors[6]);
		assertEquals(new Color(0x0000FF), chat.colors[11]);
	}

	@Test
	public void randomModeIsAssignedPerCharacter()
	{
		RetroChatRenderer.ParsedChat chat = RetroChatRenderer.parse("@ran@abcdefghijklmno");
		Object actor = new Object();
		boolean foundDifferentColour = false;
		Color first = RetroChatRenderer.color(chat, actor, 400L, 0);
		for (int i = 1; i < chat.text.length(); i++)
		{
			foundDifferentColour |= !first.equals(RetroChatRenderer.color(chat, actor, 400L, i));
		}
		org.junit.Assert.assertTrue(foundDifferentColour);
	}

	@Test
	public void flashAndGlowAdvanceDeterministically()
	{
		Object actor = new Object();
		RetroChatRenderer.ParsedChat flash = RetroChatRenderer.parse("flash1:Hi");
		assertNotEquals(RetroChatRenderer.color(flash, actor, 0L, 0),
			RetroChatRenderer.color(flash, actor, 250L, 0));
		RetroChatRenderer.ParsedChat glow = RetroChatRenderer.parse("glow1:Hi");
		assertNotEquals(RetroChatRenderer.color(glow, actor, 0L, 0),
			RetroChatRenderer.color(glow, actor, 200L, 0));
	}
}

package com.kierenboal.npcsnap.features;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import javax.imageio.ImageIO;
import net.runelite.api.HitsplatID;
import net.runelite.client.ui.FontManager;

/** Development-only contact sheet: never reads or writes files from the plugin. */
public final class RetroHitsplatPreview
{
	private static final int UNKNOWN_COUNT = 32;
	private static final int UNKNOWN_START = 1001;
	private static final Row[] KNOWN_ROWS = {
		new Row("Damage", "Damage_hitsplat", HitsplatID.DAMAGE_ME, HitsplatID.DAMAGE_OTHER, HitsplatID.DAMAGE_MAX_ME),
		new Row("Block / hit 0", "Zero_damage_hitsplat", HitsplatID.BLOCK_ME, HitsplatID.BLOCK_OTHER, -1),
		new Row("Shield / cyan", "Shield_hitsplat", HitsplatID.DAMAGE_ME_CYAN, HitsplatID.DAMAGE_OTHER_CYAN, HitsplatID.DAMAGE_MAX_ME_CYAN),
		new Row("Armour / orange", "Armour_hitsplat", HitsplatID.DAMAGE_ME_ORANGE, HitsplatID.DAMAGE_OTHER_ORANGE, HitsplatID.DAMAGE_MAX_ME_ORANGE),
		new Row("Charge / yellow", "Charge_hitsplat", HitsplatID.DAMAGE_ME_YELLOW, HitsplatID.DAMAGE_OTHER_YELLOW, HitsplatID.DAMAGE_MAX_ME_YELLOW),
		new Row("Uncharge / white", "Uncharge_hitsplat", HitsplatID.DAMAGE_ME_WHITE, HitsplatID.DAMAGE_OTHER_WHITE, HitsplatID.DAMAGE_MAX_ME_WHITE),
		new Row("Poise", "Poise_hitsplat", HitsplatID.DAMAGE_ME_POISE, HitsplatID.DAMAGE_OTHER_POISE, HitsplatID.DAMAGE_MAX_ME_POISE),
		new Row("Poison", "Poison_hitsplat", HitsplatID.POISON),
		new Row("Venom", "Venom_hitsplat", HitsplatID.VENOM),
		new Row("Disease", "Disease_hitsplat", HitsplatID.DISEASE),
		new Row("Disease blocked", "Disease_hitsplat", HitsplatID.DISEASE_BLOCKED),
		new Row("Heal", "Heal_hitsplat", HitsplatID.HEAL),
		new Row("Prayer drain", "Prayer_drain_hitsplat", HitsplatID.PRAYER_DRAIN),
		new Row("Corruption", "Corruption_hitsplat", HitsplatID.CORRUPTION),
		new Row("Bleed", "Bleed_hitsplat", HitsplatID.BLEED),
		new Row("Burn", "Burn_hitsplat", HitsplatID.BURN),
		new Row("Sanity drain", "Sanity_hitsplat", HitsplatID.SANITY_DRAIN),
		new Row("Sanity restore", "Heal_hitsplat_(sanity)", HitsplatID.SANITY_RESTORE),
		new Row("Doom", "Doom_stack_hitsplat", HitsplatID.DOOM),
		new Row("Alternate charge", "Alt_charge_hitsplat", HitsplatID.CYAN_UP),
		new Row("Alternate uncharge", "Alt_uncharge_hitsplat", HitsplatID.CYAN_DOWN)
	};
	private static final Row[] ROWS = rows();

	private static Row[] rows()
	{
		Row[] rows = java.util.Arrays.copyOf(KNOWN_ROWS, KNOWN_ROWS.length + UNKNOWN_COUNT);
		for (int i = 0; i < UNKNOWN_COUNT; i++)
		{
			rows[KNOWN_ROWS.length + i] = new Row("Undocumented #" + (i + 1), null, UNKNOWN_START + i);
		}
		return rows;
	}

	private RetroHitsplatPreview()
	{
	}

	public static void main(String[] args) throws IOException
	{
		Path output = Paths.get(args[0]);
		String attempt = args[1];
		Path wikiDirectory = resolveWikiDirectory(args.length > 3 ? Paths.get(args[3]) : Paths.get("tmp_wiki_page"));
		if (!attempt.matches("[a-zA-Z0-9_-]+"))
		{
			throw new IllegalArgumentException("Use a simple attempt name");
		}
		Files.createDirectories(output);
		BufferedImage sheet = new BufferedImage(1180, 170 + ROWS.length * 92, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = sheet.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			g.setColor(new Color(0x24262B));
			g.fillRect(0, 0, sheet.getWidth(), sheet.getHeight());
			g.setColor(Color.WHITE);
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 18));
			g.drawString("Retro vector hitsplats - " + attempt, 20, 27);
			g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
			g.drawString("Wiki backgrounds beside production vector drawing; enlarged views use nearest-neighbour scaling.", 20, 49);
			g.drawString("Native size", 165, 150);
			g.drawString("Normal: wiki / vector (3x)", 280, 150);
			g.drawString("Tinted: wiki / vector (3x)", 535, 150);
			g.drawString("Max: wiki / vector (3x)", 790, 150);
			g.drawString("Wide / zero (1x)", 1040, 150);
			if (args.length > 2 && !args[2].isEmpty())
			{
				BufferedImage reference = ImageIO.read(Paths.get(args[2]).toFile());
				g.drawString("Supplied RSC reference", 20, 76);
				g.drawImage(reference, 175, 60, reference.getWidth() * 3, reference.getHeight() * 3, null);
			}
			for (int i = 0; i < ROWS.length; i++)
			{
				Row row = ROWS[i];
				int y = 165 + i * 92;
				g.setColor(new Color(i % 2 == 0 ? 0x303339 : 0x282B30));
				g.fillRect(0, y, sheet.getWidth(), 92);
				g.setColor(Color.WHITE);
				g.drawString(row.label, 15, y + 34);
				g.setColor(new Color(0xAAB0BB));
				g.drawString("ID " + row.type, 15, y + 54);
				BufferedImage wiki = row.file != null ? wiki(wikiDirectory, row.file + ".png") : null;
				int amount = row.type == HitsplatID.BLOCK_ME || row.type == HitsplatID.DISEASE_BLOCKED ? 0 : 8;
				BufferedImage vector = render(row.type, amount, 32);
				g.drawImage(wiki, 165, y + 28, null);
				g.drawImage(vector, 210, y + 20, null);
				pair(g, wiki, vector, 280, y);
				if (wiki == null)
				{
					g.drawString("No wiki reference", 280, y + 28);
					g.drawString("Synthetic ID", 280, y + 47);
					Color color = RetroHitsplatRenderer.fill(row.type, amount);
					g.drawString(String.format("RGB %d, %d, %d", color.getRed(), color.getGreen(), color.getBlue()), 535, y + 34);
				}
				if (row.tinted >= 0)
				{
					pair(g, wiki(wikiDirectory, row.file + "_(tinted).png"), render(row.tinted, amount, 32), 535, y);
				}
				if (row.max >= 0)
				{
					pair(g, wiki(wikiDirectory, row.file + "_(max_hit).png"), render(row.max, amount, 32), 790, y);
				}
				g.drawImage(render(row.type, row.type == HitsplatID.BLOCK_ME ? 0 : 1234, 80),
					1040, y + (wiki == null ? 5 : 10), null);
				g.drawImage(render(row.type, 0, 80), 1040, y + (wiki == null ? 57 : 48), null);
			}
		}
		finally
		{
			g.dispose();
		}
		Path file = output.resolve(attempt + ".png");
		ImageIO.write(sheet, "png", file.toFile());
		System.out.println(file.toAbsolutePath());
		Path undocumented = output.resolve(attempt + "-undocumented.png");
		ImageIO.write(undocumentedSheet(), "png", undocumented.toFile());
		System.out.println(undocumented.toAbsolutePath());
	}

	private static BufferedImage undocumentedSheet()
	{
		BufferedImage sheet = new BufferedImage(1080, 60 + 8 * 150, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = sheet.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			g.setColor(new Color(0x24262B));
			g.fillRect(0, 0, sheet.getWidth(), sheet.getHeight());
			g.setColor(Color.WHITE);
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 18));
			g.drawString("32 undocumented IDs - no adjacent colour or shape repeats", 16, 25);
			g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
			g.drawString("Read left to right, then down. Enlarged / native / zero. All IDs are synthetic.", 16, 46);
			for (int i = 0; i < UNKNOWN_COUNT; i++)
			{
				int type = UNKNOWN_START + i, x = i % 4 * 270, y = 60 + i / 4 * 150;
				g.setColor(new Color(i % 2 == 0 ? 0x303339 : 0x282B30));
				g.fillRect(x, y, 270, 150);
				g.setColor(Color.WHITE);
				g.drawString(type + "  " + RetroHitsplatRenderer.unknownShape(type), x + 12, y + 19);
				Color color = RetroHitsplatRenderer.fill(type, 8);
				g.setColor(new Color(0xAAB0BB));
				g.drawString(String.format("RGB %d, %d, %d", color.getRed(), color.getGreen(), color.getBlue()), x + 12, y + 36);
				BufferedImage large = render(type, 8, 32);
				g.drawImage(large, x + 10, y + 42, large.getWidth() * 3, large.getHeight() * 3, null);
				g.drawImage(large, x + 166, y + 54, null);
				g.drawImage(render(type, 0, 32), x + 216, y + 54, null);
			}
		}
		finally
		{
			g.dispose();
		}
		return sheet;
	}

	private static void pair(Graphics2D g, BufferedImage wiki, BufferedImage vector, int x, int y)
	{
		if (wiki != null)
		{
			g.drawImage(wiki, x, y + 7, wiki.getWidth() * 3, wiki.getHeight() * 3, null);
		}
		g.drawImage(vector, x + 105, y - 1, vector.getWidth() * 3, vector.getHeight() * 3, null);
	}

	private static Path resolveWikiDirectory(Path savedPage) throws IOException
	{
		Path directory = Files.isRegularFile(savedPage) ? savedPage.toAbsolutePath().getParent() : savedPage;
		if (Files.isRegularFile(directory.resolve("Damage_hitsplat.png")))
		{
			return directory;
		}
		Path assets = directory.resolve("Hitsplat - OSRS Wiki_files");
		if (Files.isDirectory(assets))
		{
			return assets;
		}
		throw new IOException("Point -PhitsplatWikiDirectory at the saved HTML, its folder, or the *_files folder: " + savedPage);
	}

	private static BufferedImage wiki(Path directory, String file) throws IOException
	{
		BufferedImage image = ImageIO.read(directory.resolve(file).toFile());
		if (image == null)
		{
			throw new IOException("Invalid wiki PNG: " + file);
		}
		return image;
	}

	static BufferedImage render(int type, int amount, int width)
	{
		BufferedImage image = new BufferedImage(width, 30, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			boolean unknown = RetroHitsplatRenderer.style(type, amount) == RetroHitsplatRenderer.Style.UNKNOWN;
			int height = unknown
				? Math.max(30, g.getFontMetrics().stringWidth(Integer.toString(amount)) + 22) : 30;
			int canvasWidth = unknown ? Math.max(width, RetroHitsplatRenderer.unknownWidth(type,
				Math.max(20, g.getFontMetrics().stringWidth(Integer.toString(amount)) + 12)) + 10) : width;
			if (height > image.getHeight() || canvasWidth > image.getWidth())
			{
				g.dispose();
				image = new BufferedImage(canvasWidth, height, BufferedImage.TYPE_INT_ARGB);
				g = image.createGraphics();
				g.setFont(FontManager.getRunescapeSmallFont());
			}
			RetroHitsplatRenderer.draw(g, type, amount, canvasWidth / 2, height / 2 + 5);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	private static final class Row
	{
		final String label, file;
		final int type, tinted, max;

		Row(String label, String file, int type)
		{
			this(label, file, type, -1, -1);
		}

		Row(String label, String file, int type, int tinted, int max)
		{
			this.label = label;
			this.file = file;
			this.type = type;
			this.tinted = tinted;
			this.max = max;
		}
	}
}

package com.kierenboal.npcsnap.features;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import net.runelite.api.HitsplatID;
import org.junit.Test;

import static org.junit.Assert.*;

public class RetroHitsplatRendererTest
{
	@Test
	public void nativeTypeOverridesAmountIncludingSpecialistZeros()
	{
		assertEquals(new Color(0x3155D9), RetroHitsplatRenderer.fill(HitsplatID.BLOCK_ME, 12));
		assertEquals(new Color(0xE51B17), RetroHitsplatRenderer.fill(HitsplatID.DAMAGE_ME, 0));
		assertEquals(new Color(0x00C000), RetroHitsplatRenderer.fill(HitsplatID.POISON, 0));
		assertEquals(new Color(0x40957E), RetroHitsplatRenderer.fill(HitsplatID.VENOM, 0));
		assertEquals(new Color(0xFCB712), RetroHitsplatRenderer.fill(HitsplatID.DISEASE_BLOCKED, 0));
		assertEquals(RetroHitsplatRenderer.Style.HEAL, RetroHitsplatRenderer.style(HitsplatID.HEAL, 0));
		assertEquals(RetroHitsplatRenderer.Style.SANITY, RetroHitsplatRenderer.style(HitsplatID.SANITY_DRAIN, 0));
		assertEquals(RetroHitsplatRenderer.Style.SANITY_RESTORE, RetroHitsplatRenderer.style(HitsplatID.SANITY_RESTORE, 0));
		assertEquals(RetroHitsplatRenderer.Style.DOOM, RetroHitsplatRenderer.style(HitsplatID.DOOM, 0));
		assertEquals(RetroHitsplatRenderer.Style.UNKNOWN, RetroHitsplatRenderer.style(-123, 0));
		assertEquals(RetroHitsplatRenderer.Style.UNKNOWN, RetroHitsplatRenderer.style(-123, 12));
	}

	@Test
	public void undocumentedIdsUseStableNonGreyPastelsAndVariedShapesWithoutAdjacentRepeats()
	{
		java.util.Set<Color> colors = new java.util.HashSet<>();
		java.util.Set<RetroHitsplatRenderer.UnknownShape> shapes = new java.util.HashSet<>();
		Color previousColor = null;
		RetroHitsplatRenderer.UnknownShape previousShape = null;
		for (int type = 1001; type <= 1032; type++)
		{
			Color color = RetroHitsplatRenderer.fill(type, 8);
			RetroHitsplatRenderer.UnknownShape shape = RetroHitsplatRenderer.unknownShape(type);
			colors.add(color);
			shapes.add(shape);
			assertNotEquals(previousColor, color);
			assertNotEquals(previousShape, shape);
			previousColor = color;
			previousShape = shape;
			assertEquals(color, RetroHitsplatRenderer.fill(type, 0));
			assertEquals(color, RetroHitsplatRenderer.fill(type, 1234));
			int endpoints = 0;
			for (int channel : new int[] {color.getRed(), color.getGreen(), color.getBlue()})
			{
				assertTrue(channel >= 128 && channel <= 255);
				if (channel == 128 || channel == 255) { endpoints++; }
			}
			assertEquals(2, endpoints);
			assertFalse(color.getRed() == color.getGreen() && color.getGreen() == color.getBlue());
			assertFalse(RetroHitsplatRenderer.maxHit(type));
			assertEquals(Color.BLACK, RetroHitsplatRenderer.border(type, 1234));
			for (int amount : new int[] {0, 8, 1234})
			{
				BufferedImage image = RetroHitsplatPreview.render(type, amount, 80);
				int left = image.getWidth(), top = image.getHeight(), right = -1, bottom = -1;
				for (int y = 0; y < image.getHeight(); y++)
				{
					for (int x = 0; x < image.getWidth(); x++)
					{
						if (image.getRGB(x, y) != 0)
						{
							left = Math.min(left, x); right = Math.max(right, x);
							top = Math.min(top, y); bottom = Math.max(bottom, y);
						}
					}
				}
				if (shape != RetroHitsplatRenderer.UnknownShape.TRIANGLE)
				{
					assertEquals("Circle and square retain equal dimensions", right - left, bottom - top, 1);
				}
				else
				{
					assertTrue("Triangle has a wider base to fit its number", right - left > bottom - top);
				}
			}
		}
		assertTrue("The sheet should have a broad palette", colors.size() >= 24);
		assertEquals(3, shapes.size());
		// Reverse lookup must not re-roll an already assigned descriptor.
		for (int type = 1032; type >= 1001; type--)
		{
			assertEquals(RetroHitsplatRenderer.fill(type, 0), RetroHitsplatRenderer.fill(type, 8));
			if (type > 1001)
			{
				assertNotEquals(RetroHitsplatRenderer.fill(type, 8), RetroHitsplatRenderer.fill(type - 1, 8));
				assertNotEquals(RetroHitsplatRenderer.unknownShape(type), RetroHitsplatRenderer.unknownShape(type - 1));
			}
		}
	}

	@Test
	public void variantsPreserveSilhouettesAndOnlyClassicBordersAreTinted()
	{
		int[][] families = {
			{HitsplatID.DAMAGE_ME, HitsplatID.DAMAGE_OTHER, HitsplatID.DAMAGE_MAX_ME},
			{HitsplatID.DAMAGE_ME_CYAN, HitsplatID.DAMAGE_OTHER_CYAN, HitsplatID.DAMAGE_MAX_ME_CYAN},
			{HitsplatID.DAMAGE_ME_ORANGE, HitsplatID.DAMAGE_OTHER_ORANGE, HitsplatID.DAMAGE_MAX_ME_ORANGE},
			{HitsplatID.DAMAGE_ME_YELLOW, HitsplatID.DAMAGE_OTHER_YELLOW, HitsplatID.DAMAGE_MAX_ME_YELLOW},
			{HitsplatID.DAMAGE_ME_WHITE, HitsplatID.DAMAGE_OTHER_WHITE, HitsplatID.DAMAGE_MAX_ME_WHITE},
			{HitsplatID.DAMAGE_ME_POISE, HitsplatID.DAMAGE_OTHER_POISE, HitsplatID.DAMAGE_MAX_ME_POISE}
		};
		for (int[] family : families)
		{
			assertEquals(RetroHitsplatRenderer.style(family[0], 8), RetroHitsplatRenderer.style(family[1], 8));
			assertEquals(RetroHitsplatRenderer.style(family[0], 8), RetroHitsplatRenderer.style(family[2], 8));
			assertFalse(RetroHitsplatRenderer.maxHit(family[0]));
			assertTrue(RetroHitsplatRenderer.tinted(family[1]));
			assertTrue(RetroHitsplatRenderer.maxHit(family[2]));
			assertEquals(new Color(0xFFD65A), RetroHitsplatRenderer.border(family[2], 8));
			if (family[0] == HitsplatID.DAMAGE_ME)
			{
				assertEquals(RetroHitsplatRenderer.fill(family[0], 8), RetroHitsplatRenderer.fill(family[1], 8));
			}
			else
			{
				assertNotEquals(RetroHitsplatRenderer.fill(family[0], 8), RetroHitsplatRenderer.fill(family[1], 8));
			}
		}
		assertEquals(RetroHitsplatRenderer.fill(HitsplatID.BLOCK_ME, 0), RetroHitsplatRenderer.fill(HitsplatID.BLOCK_OTHER, 0));
		assertNotEquals(RetroHitsplatRenderer.border(HitsplatID.BLOCK_ME, 0), RetroHitsplatRenderer.border(HitsplatID.BLOCK_OTHER, 0));
		assertNotEquals(RetroHitsplatRenderer.border(HitsplatID.DAMAGE_ME, 8), RetroHitsplatRenderer.border(HitsplatID.DAMAGE_OTHER, 8));
		assertEquals(Color.BLACK, RetroHitsplatRenderer.border(HitsplatID.DAMAGE_ME, Integer.MAX_VALUE));
	}

	@Test
	public void wideNumbersAndMaxTrimStayInsideThePreviewCanvas()
	{
		int[] types = {HitsplatID.DAMAGE_MAX_ME, HitsplatID.BLOCK_OTHER, HitsplatID.DAMAGE_MAX_ME_CYAN,
			HitsplatID.DAMAGE_MAX_ME_ORANGE, HitsplatID.DAMAGE_MAX_ME_YELLOW, HitsplatID.DAMAGE_MAX_ME_WHITE,
			HitsplatID.DAMAGE_MAX_ME_POISE, HitsplatID.CYAN_UP, HitsplatID.CYAN_DOWN, HitsplatID.POISON,
			HitsplatID.VENOM, HitsplatID.DISEASE, HitsplatID.DISEASE_BLOCKED, HitsplatID.HEAL,
			HitsplatID.PRAYER_DRAIN, HitsplatID.CORRUPTION, HitsplatID.BLEED, HitsplatID.BURN,
			HitsplatID.SANITY_DRAIN, HitsplatID.SANITY_RESTORE, HitsplatID.DOOM, 1001, 1002, 1003, 1004};
		for (int type : types)
		{
			for (int amount : new int[] {0, 8, 1234, Integer.MAX_VALUE})
			{
				BufferedImage image = RetroHitsplatPreview.render(type, amount, 140);
				int painted = 0, white = 0;
				for (int y = 0; y < image.getHeight(); y++)
				{
					for (int x = 0; x < image.getWidth(); x++)
					{
						int pixel = image.getRGB(x, y);
						if (pixel != 0)
						{
							assertTrue("Clipped type " + type, x > 0 && x < image.getWidth() - 1 && y > 0 && y < image.getHeight() - 1);
							painted++;
							if (pixel == Color.WHITE.getRGB()) { white++; }
						}
					}
				}
				assertTrue(painted > 0);
				assertTrue("Number must remain visible", white > 0);
			}
		}
	}

	@Test
	public void drawingDoesNotLeakGraphicsSettings()
	{
		Graphics2D g = new BufferedImage(60, 40, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try
		{
			BasicStroke stroke = new BasicStroke(5);
			g.setStroke(stroke);
			g.setColor(Color.MAGENTA);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			RetroHitsplatRenderer.draw(g, HitsplatID.DAMAGE_MAX_ME, 8, 30, 20);
			assertEquals(stroke, g.getStroke());
			assertEquals(Color.MAGENTA, g.getColor());
			assertEquals(RenderingHints.VALUE_ANTIALIAS_ON, g.getRenderingHint(RenderingHints.KEY_ANTIALIASING));
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.kierenboal.npcsnap.features;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import net.runelite.api.Skill;
import org.junit.Test;

public class SkillingActivityTrackerTest
{
	@Test
	public void firstObservedXpSeedsWithoutActivating()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();

		boolean activated = tracker.recordXp(Skill.MINING, 100, 1_000L, 10_000L);

		assertFalse(activated);
		assertTrue(tracker.getRenderableSkills(1_000L, 2_500L).isEmpty());
	}

	@Test
	public void xpIncreaseActivatesTrackedSkill()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordXp(Skill.MINING, 100, 1_000L, 10_000L);

		boolean activated = tracker.recordXp(Skill.MINING, 125, 2_000L, 10_000L);

		assertTrue(activated);
		assertEquals(List.of(Skill.MINING), tracker.getRenderableSkills(2_000L, 2_500L));
	}

	@Test
	public void repeatedXpRefreshesExpiry()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordXp(Skill.WOODCUTTING, 100, 500L, 10_000L);
		tracker.recordXp(Skill.WOODCUTTING, 125, 1_000L, 10_000L);
		tracker.recordXp(Skill.WOODCUTTING, 150, 9_000L, 10_000L);

		assertEquals(List.of(Skill.WOODCUTTING), tracker.getRenderableSkills(18_999L, 2_500L));
		assertEquals(List.of(Skill.WOODCUTTING), tracker.getRenderableSkills(19_000L, 2_500L));
	}

	@Test
	public void expiredSkillsAreRemoved()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordXp(Skill.FISHING, 100, 500L, 10_000L);
		tracker.recordXp(Skill.FISHING, 125, 1_000L, 10_000L);

		assertEquals(List.of(Skill.FISHING), tracker.getRenderableSkills(11_000L, 2_500L));
		assertTrue(tracker.getRenderableSkills(13_500L, 2_500L).isEmpty());
	}

	@Test
	public void combatAndOmittedSkillsAreIgnored()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordXp(Skill.ATTACK, 100, 500L, 10_000L);
		tracker.recordXp(Skill.PRAYER, 100, 500L, 10_000L);
		tracker.recordXp(Skill.SLAYER, 100, 500L, 10_000L);

		assertFalse(tracker.recordXp(Skill.ATTACK, 125, 1_000L, 10_000L));
		assertFalse(tracker.recordXp(Skill.PRAYER, 125, 1_000L, 10_000L));
		assertFalse(tracker.recordXp(Skill.SLAYER, 125, 1_000L, 10_000L));
		assertTrue(tracker.getRenderableSkills(1_000L, 2_500L).isEmpty());
	}

	@Test
	public void multipleNonCombatSkillsRemainActiveTogether()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.recordXp(Skill.COOKING, 100, 500L, 10_000L);
		tracker.recordXp(Skill.FARMING, 100, 500L, 10_000L);
		tracker.recordXp(Skill.COOKING, 125, 1_000L, 10_000L);
		tracker.recordXp(Skill.FARMING, 125, 2_000L, 10_000L);

		assertEquals(List.of(Skill.COOKING, Skill.FARMING), tracker.getRenderableSkills(2_000L, 2_500L));
	}

	@Test
	public void seededXpAllowsFirstObservedGainToActivate()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.seedXp(Skill.MINING, 100);

		boolean activated = tracker.recordXp(Skill.MINING, 125, 2_000L, 10_000L);

		assertTrue(activated);
		assertEquals(List.of(Skill.MINING), tracker.getRenderableSkills(2_000L, 2_500L));
		assertEquals(2_000L, tracker.getVisibleFromMillis(Skill.MINING));
	}

	@Test
	public void refreshWithinActiveWindowKeepsOriginalFadeInStart()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.seedXp(Skill.WOODCUTTING, 100);
		tracker.recordXp(Skill.WOODCUTTING, 125, 1_000L, 10_000L);
		tracker.recordXp(Skill.WOODCUTTING, 150, 5_000L, 10_000L);

		assertEquals(1_000L, tracker.getVisibleFromMillis(Skill.WOODCUTTING));
		assertEquals(15_000L, tracker.getActiveUntilMillis(Skill.WOODCUTTING));
	}

	@Test
	public void zeroTimeoutExpiresAtTheEventTime()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.seedXp(Skill.MINING, 100);

		assertTrue(tracker.recordXp(Skill.MINING, 125, 2_000L, -1L));
		assertTrue(tracker.getRenderableSkills(2_000L, 0L).isEmpty());
	}

	@Test
	public void clearRemovesXpSeedsAndVisibleState()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		tracker.seedXp(Skill.MINING, 100);
		tracker.recordXp(Skill.MINING, 125, 2_000L, 10_000L);

		tracker.clear();

		assertFalse(tracker.isTrackedXpIncrease(Skill.MINING, 150));
		assertEquals(0L, tracker.getVisibleFromMillis(Skill.MINING));
		assertEquals(0L, tracker.getActiveUntilMillis(Skill.MINING));
		assertTrue(tracker.getRenderableSkills(2_000L, 1_000L).isEmpty());
	}
}

package com.kierenboal.npcsnap.features;

import java.util.List;
import net.runelite.api.Skill;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class SkillingBubbleAnimationTest
{
	@Test
	public void skillFadesInStaysOpaqueAndFadesOut()
	{
		SkillingBubbleAnimation animation = activeAnimation(Skill.MINING, 1_000L, 10_000L);

		assertEquals(0f, animation.skillAlpha(Skill.MINING, 1_000L), 0f);
		assertEquals(0.5f, animation.skillAlpha(Skill.MINING, 1_250L), 0.001f);
		assertEquals(1f, animation.skillAlpha(Skill.MINING, 1_500L), 0f);
		assertEquals(1f, animation.skillAlpha(Skill.MINING, 11_000L), 0f);
		assertEquals(0.5f, animation.skillAlpha(Skill.MINING, 12_250L), 0.001f);
		assertEquals(0f, animation.skillAlpha(Skill.MINING, 13_500L), 0f);
	}

	@Test
	public void missingSkillStateIsTransparent()
	{
		SkillingBubbleAnimation animation = new SkillingBubbleAnimation(new SkillingActivityTracker());

		assertEquals(0f, animation.skillAlpha(Skill.MINING, 1_000L), 0f);
		assertEquals(0f, animation.bubbleAlpha(List.of(), 1_000L), 0f);
		assertEquals(1f, animation.introProgress(List.of(), 1_000L), 0f);
	}

	@Test
	public void bubbleUsesMostVisibleSkillAndSlowestIntro()
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		activate(tracker, Skill.MINING, 1_000L, 10_000L);
		activate(tracker, Skill.FISHING, 1_200L, 10_000L);
		SkillingBubbleAnimation animation = new SkillingBubbleAnimation(tracker);

		assertEquals(1f, animation.bubbleAlpha(List.of(Skill.MINING, Skill.FISHING), 1_500L), 0.001f);
		assertEquals(0.6f, animation.introProgress(List.of(Skill.MINING, Skill.FISHING), 1_500L), 0.001f);
	}

	private static SkillingBubbleAnimation activeAnimation(Skill skill, long start, long timeout)
	{
		SkillingActivityTracker tracker = new SkillingActivityTracker();
		activate(tracker, skill, start, timeout);
		return new SkillingBubbleAnimation(tracker);
	}

	private static void activate(SkillingActivityTracker tracker, Skill skill, long start, long timeout)
	{
		tracker.seedXp(skill, 100);
		tracker.recordXp(skill, 101, start, timeout);
	}
}

package com.kierenboal.npcsnap.features;

import com.kierenboal.npcsnap.NpcSnapConfig;
import com.kierenboal.npcsnap.targeting.BillboardWorldViewVisibility;
import java.awt.Color;
