package com.kierenboal.npcsnap.rendering;

import com.kierenboal.npcsnap.state.CachedBillboard;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.api.AABB;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static com.kierenboal.npcsnap.TestProxies.method;
import static com.kierenboal.npcsnap.TestProxies.proxy;
import static org.junit.Assert.*;

public class ActorBillboardBoundsTest
{
	@Test
	public void eitherDimensionOfEitherBoxCanTriggerGrowthOrShrinkage()
	{
		ActorBillboardBounds displayed = bounds(100, 100, 100, 100);
		assertTrue(bounds(111, 100, 100, 100).exceedsResizeThreshold(displayed, 10));
		assertTrue(bounds(100, 89, 100, 100).exceedsResizeThreshold(displayed, 10));
		assertTrue(bounds(100, 100, 89, 100).exceedsResizeThreshold(displayed, 10));
		assertTrue(bounds(100, 100, 100, 111).exceedsResizeThreshold(displayed, 10));
		// Equal area must not hide opposing width/height changes.
		assertTrue(bounds(200, 50, 100, 100).exceedsResizeThreshold(displayed, 10));
	}

	@Test
	public void thresholdIsStrictAndZeroDisablesTheCheck()
	{
		ActorBillboardBounds displayed = bounds(100, 100, 100, 100);
		assertFalse(bounds(110, 90, 110, 90).exceedsResizeThreshold(displayed, 10));
		assertFalse(bounds(500, 500, 500, 500).exceedsResizeThreshold(displayed, 0));
		assertFalse(bounds(200, 200, 200, 200).exceedsResizeThreshold(displayed, 100));
		assertTrue(bounds(201, 100, 100, 100).exceedsResizeThreshold(displayed, 100));
	}

	@Test
	public void translationAndMissingOrDegenerateBoxesDoNotInvalidateSprites()
	{
		ActorBillboardBounds displayed = bounds(100, 100, 100, 100);
		assertFalse(new ActorBillboardBounds(new Rectangle(500, 600, 100, 100),
			new Rectangle(-100, -200, 100, 100)).exceedsResizeThreshold(displayed, 10));
		assertFalse(new ActorBillboardBounds(null, new Rectangle(0, 0, 0, 100))
			.exceedsResizeThreshold(displayed, 10));
		assertTrue(new ActorBillboardBounds(null, new Rectangle(0, 0, 100, 111))
			.exceedsResizeThreshold(displayed, 10));
		assertFalse(displayed.exceedsResizeThreshold(null, 10));
		assertFalse(displayed.exceedsResizeThreshold(new ActorBillboardBounds(null, null), 10));
	}

	@Test
	public void observationsAccumulateAgainstTheSpriteBaselineWithoutChangingIt()
	{
		ActorBillboardBounds displayed = bounds(100, 100, 100, 100);
		CachedBillboard sprite = new CachedBillboard(null, new Rectangle(100, 100), new Rectangle(100, 100),
			new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), 0L, displayed);
		assertFalse(bounds(106, 100, 100, 100).exceedsResizeThreshold(sprite.actorBounds, 10));
		sprite.touch(10L); // Reusing a cached sprite does not advance its geometry baseline.
		assertTrue(bounds(112, 100, 100, 100).exceedsResizeThreshold(sprite.actorBounds, 10));
		assertSame(displayed, sprite.actorBounds);
	}

	@Test
	public void samplesModelBoxAndHullIndependentlyWithPublicProjection()
	{
		WorldView view = proxy(WorldView.class, method("isTopLevel", true), method("contains", true),
			method("getTileSettings", new byte[4][16][16]));
		Client client = proxy(Client.class, method("getWorldView", view), method("getScale", 512),
			method("getViewportWidth", 800), method("getViewportHeight", 600));
		Actor actor = proxy(Actor.class, method("getWorldView", view),
			method("getLocalLocation", new LocalPoint(512, 1024)));
		Model initial = model(50, 50, true);
		ActorBillboardBounds.Sampler sampler = new ActorBillboardBounds.Sampler(client);
		ActorBillboardBounds displayed = sampler.sample(actor, initial);
		assertNotNull(displayed);
		assertFalse(sampler.sample(actor, initial).exceedsResizeThreshold(displayed, 10));
		assertTrue(sampler.sample(actor, model(70, 50, true)).exceedsResizeThreshold(displayed, 10));
		assertTrue(sampler.sample(actor, model(50, 70, true)).exceedsResizeThreshold(displayed, 10));
		// A box-only trigger does not need to fetch/project all hull vertices.
		Model resizedBox = proxy(Model.class, method("getAABB", proxy(AABB.class,
			method("getExtremeX", 70), method("getExtremeY", 50), method("getExtremeZ", 10), method("getCenterY", -50))),
			com.kierenboal.npcsnap.TestProxies.methodSupplier("getVerticesX", () ->
			{
				throw new AssertionError("An independent box trigger must skip hull projection");
			}));
		assertTrue(sampler.sampleForResize(actor, resizedBox, displayed, 10).exceedsResizeThreshold(displayed, 10));
		// An unchanged box must still check the hull independently.
		assertTrue(sampler.sampleForResize(actor, model(70, 50, true), displayed, 10).exceedsResizeThreshold(displayed, 10));
		// Missing AABB does not prevent the independent hull check.
		assertTrue(sampler.sample(actor, model(70, 50, false)).exceedsResizeThreshold(displayed, 10));
		assertNull(sampler.sample(actor, null));
		assertNull(sampler.sample(proxy(Actor.class), initial));
	}

	private static Model model(int hullHalfWidth, int boxHalfWidth, boolean withBox)
	{
		AABB box = proxy(AABB.class, method("getExtremeX", boxHalfWidth), method("getExtremeY", 50),
			method("getExtremeZ", 10), method("getCenterY", -50));
		return proxy(Model.class, method("getVerticesCount", 4),
			method("getVerticesX", new float[] { -hullHalfWidth, hullHalfWidth, hullHalfWidth, -hullHalfWidth }),
			method("getVerticesY", new float[] { -100, -100, 0, 0 }),
			method("getVerticesZ", new float[4]), method("getAABB", withBox ? box : null));
	}

	private static ActorBillboardBounds bounds(int modelWidth, int modelHeight, int hullWidth, int hullHeight)
	{
		return new ActorBillboardBounds(new Rectangle(0, 0, modelWidth, modelHeight),
			new Rectangle(0, 0, hullWidth, hullHeight));
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static com.kierenboal.npcsnap.TestProxies.method;
import static com.kierenboal.npcsnap.TestProxies.proxy;
import static org.junit.Assert.*;

public class ActorWorldPlaneTest
{
	@Test
	public void asymmetricBoundsAndPaddingMapIntoTheSameWorldPlane()
	{
		for (boolean gpu : new boolean[] {false, true})
		{
			BillboardDepthCalculator camera = camera(gpu, 0, 0);
			Rectangle content = new Rectangle(-30, -100, 80, 100);
			Rectangle image = new Rectangle(-40, -110, 100, 120);
			BillboardDrawGeometry geometry = ActorWorldPlane.project(camera, new LocalPoint(0, 1000), 0,
				0, image, content);
			assertNotNull(geometry);
			assertEquals(new Point(385, 250), geometry.canvasPoint(0.1, 1.0 / 12.0));
			assertEquals(new Point(425, 300), geometry.canvasPoint(0.9, 11.0 / 12.0));
			assertEquals(new Point(405, 250), geometry.contentTopCenter());
			assertEquals(new Point(380, 245), geometry.canvasPoint(0, 0));
			assertEquals(new Point(430, 305), geometry.canvasPoint(1, 1));
			assertEquals(new Point(400, 300), geometry.canvasPoint(0.4, 11.0 / 12.0));
			assertTrue(geometry.bounds.contains(geometry.polygon().getBounds()));
		}
	}

	@Test
	public void perspectiveMappingRoundTripsAndDepthVariesAcrossARow()
	{
		BillboardDepthCalculator camera = camera(false, 0, 0);
		Rectangle image = new Rectangle(-150, -240, 300, 240);
		BillboardDrawGeometry geometry = ActorWorldPlane.project(camera, new LocalPoint(-400, 1000),
			0, Math.atan2(400, 1000), image, image);
		assertNotNull(geometry);
		BillboardProjectedQuad.Sample sample = new BillboardProjectedQuad.Sample();
		for (double u : new double[] {0.1, 0.3, 0.5, 0.9})
		{
			for (double v : new double[] {0.1, 0.5, 0.9})
			{
				Point point = geometry.canvasPoint(u, v);
				assertTrue(geometry.projectedQuad.sample(point.getX(), point.getY(), sample));
				assertEquals(u, sample.u, 0.015);
				assertEquals(v, sample.v, 0.015);
				assertEquals(geometry.projectedQuad.depthAt(sample.u, sample.v), sample.depth, 1e-7);
			}
		}
		Point left = geometry.canvasPoint(0.2, 0.5), right = geometry.canvasPoint(0.8, 0.5);
		assertTrue(geometry.projectedQuad.sample(left.getX(), 240, sample));
		double leftDepth = sample.depth;
		assertTrue(geometry.projectedQuad.sample(right.getX(), 240, sample));
		assertTrue(sample.depth > leftDepth);
		assertFalse(geometry.projectedQuad.sample(-1000, 0, sample));
	}

	@Test
	public void cameraPitchAndYawAgreeBetweenCpuAndGpu()
	{
		Rectangle image = new Rectangle(-50, -160, 100, 160);
		for (int yaw : new int[] {0, 512, 1024})
		{
			for (int pitch : new int[] {0, 1024, 2048, 3072})
			{
				BillboardDrawGeometry cpu = ActorWorldPlane.project(camera(false, yaw, pitch), new LocalPoint(500, 1500), 0,
					Math.atan2(-500, 1500), image, image);
				BillboardDrawGeometry gpu = ActorWorldPlane.project(camera(true, yaw, pitch), new LocalPoint(500, 1500), 0,
					Math.atan2(-500, 1500), image, image);
				assertNotNull(cpu);
				assertNotNull(gpu);
				for (double u : new double[] {0, 0.5, 1})
				{
					Point a = cpu.canvasPoint(u, 0.5), b = gpu.canvasPoint(u, 0.5);
					assertEquals(a.getX(), b.getX(), 1.0);
					assertEquals(a.getY(), b.getY(), 1.0);
				}
			}
		}
	}

	@Test
	public void planeFacesCameraAndPreservesCapturedSizeThroughoutAnOrbit()
	{
		Rectangle image = new Rectangle(-50, -100, 100, 100);
		LocalPoint location = new LocalPoint(0, 1000);
		for (boolean gpu : new boolean[] {false, true})
		{
			for (int yaw = 0; yaw < 16384; yaw += 2048)
			{
				double angle = yaw * 2.0 * Math.PI / 16384;
				int cameraX = (int) Math.round(1000 * Math.sin(angle));
				int cameraY = (int) Math.round(1000 - 1000 * Math.cos(angle));
				Client client = cameraClient(gpu, yaw, 0, cameraX, cameraY);
				double bearing = ActorWorldPlane.viewingBearing(client, location);
				BillboardDrawGeometry geometry = ActorWorldPlane.project(new BillboardDepthCalculator(client), location,
					0, bearing, image, image);
				assertNotNull(geometry);
				// Raster bounds round outward; measure the projected corners instead.
				assertEquals(50, geometry.canvasPoint(1, 0).getX() - geometry.canvasPoint(0, 0).getX(), 1);
				assertEquals(50, geometry.canvasPoint(0, 1).getY() - geometry.canvasPoint(0, 0).getY(), 1);
				assertEquals(geometry.projectedQuad.depthAt(0, 0), geometry.projectedQuad.depthAt(1, 0), 0.1);
				assertEquals(geometry.projectedQuad.depthAt(0.5, 0), geometry.projectedQuad.depthAt(0.5, 1), 1e-8);
			}
		}
	}

	@Test
	public void coincidentCameraUsesItsCpuOrGpuYawAndPositionConventions()
	{
		LocalPoint location = new LocalPoint(512, 1024);
		Client cpu = proxy(Client.class, method("getCameraX", 512), method("getCameraY", 1024),
			method("getCameraYaw", 4096), method("getCameraFpYaw", 0.7f));
		assertEquals(Math.PI / 2, ActorWorldPlane.viewingBearing(cpu, location), 1e-8);
		Client gpu = proxy(Client.class, method("isGpu", true), method("getCameraFpX", 512.0f),
			method("getCameraFpY", 1024.0f), method("getCameraYaw", 4096), method("getCameraFpYaw", 0.7f));
		assertEquals(0.7f, ActorWorldPlane.viewingBearing(gpu, location), 1e-8);
		Client offsetGpu = proxy(Client.class, method("isGpu", true), method("getCameraX", 512),
			method("getCameraY", 1024), method("getCameraFpX", 112.0f), method("getCameraFpY", 24.0f));
		assertEquals(Math.atan2(-400, 1000), ActorWorldPlane.viewingBearing(offsetGpu, location), 1e-8);
	}

	@Test
	public void differentCapturesSupplyTheirOwnWidthHeightAndOrigin()
	{
		Rectangle image = new Rectangle(-50, -100, 100, 100);
		Rectangle next = new Rectangle(-10, -200, 50, 200);
		BillboardDrawGeometry a = ActorWorldPlane.project(camera(false, 0, 0), new LocalPoint(0, 1000), 0, 0, image, image);
		BillboardDrawGeometry b = ActorWorldPlane.project(camera(false, 0, 0), new LocalPoint(0, 1000), 0, 0, next, next);
		assertEquals(50, a.bounds.width);
		assertEquals(50, a.bounds.height);
		assertEquals(25, b.bounds.width);
		assertEquals(100, b.bounds.height);
		assertEquals(new Point(395, 200), b.canvasPoint(0, 0));
		assertEquals(new Point(420, 300), b.canvasPoint(1, 1));
	}

	@Test
	public void invalidNearPlaneTinyAndOversizedProjectionsAreRejected()
	{
		Rectangle image = new Rectangle(-100, -200, 200, 200);
		assertNull(ActorWorldPlane.project(camera(false, 0, 0), new LocalPoint(50, 50), 0,
			-Math.PI / 4, image, image));
		assertNull(ActorWorldPlane.project(camera(false, 0, 0), new LocalPoint(0, 1000000), 0,
			0, image, image));
		Rectangle oversized = new Rectangle(-10000, -20000, 20000, 20000);
		assertNull(ActorWorldPlane.project(camera(false, 0, 0), new LocalPoint(0, 1000), 0, 0, oversized, oversized));
		assertNull(ActorWorldPlane.project(camera(false, 0, 0), null, 0, 0, image, image));
		assertNull(ActorWorldPlane.project(camera(false, 0, 0), new LocalPoint(0, 1000), Double.NaN,
			0, image, image));
	}

	private static BillboardDepthCalculator camera(boolean gpu, int yaw, int pitch)
	{
		return new BillboardDepthCalculator(cameraClient(gpu, yaw, pitch, 0, 0));
	}

	private static Client cameraClient(boolean gpu, int yaw, int pitch, int cameraX, int cameraY)
	{
		return proxy(Client.class, method("isGpu", gpu),
			method("getCameraX", cameraX), method("getCameraY", cameraY),
			method("getCameraFpX", (float) cameraX), method("getCameraFpY", (float) cameraY),
			method("getCameraYaw", yaw), method("getCameraPitch", pitch),
			method("getCameraFpYaw", (float) (yaw * 2.0 * Math.PI / 16384)),
			method("getCameraFpPitch", (float) (pitch * 2.0 * Math.PI / 16384)),
			method("getScale", 500), method("getViewportWidth", 800), method("getViewportHeight", 600));
	}
}

package com.kierenboal.npcsnap.rendering;

import com.kierenboal.npcsnap.TestProxies;

import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class AnimationFrameSnapperTest
{
	@Test
	public void snapsFramesIntoEvenlySpacedBucketsAndClampsOutOfRangeFrames()
	{
		Animation animation = animation(42, 10);
		Client client = TestProxies.proxy(Client.class, TestProxies.method("loadAnimation", animation));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);

		assertEquals(0, snapper.snapAnimationFrame(42, 0, 3));
		assertEquals(0, snapper.snapAnimationFrame(42, 2, 3));
		assertEquals(3, snapper.snapAnimationFrame(42, 4, 3));
		assertEquals(6, snapper.snapAnimationFrame(42, 9, 3));
		assertEquals(6, snapper.snapAnimationFrame(42, 100, 3));
	}

	@Test
	public void wrapsFullAnimationsWhenDeterministicLoopingIsDisabled()
	{
		Animation animation = animation(42, 10);
		Client client = TestProxies.proxy(Client.class, TestProxies.method("loadAnimation", animation));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);

		assertEquals(1, snapper.snapAnimationFrame(42, 41, 10, false));
	}

	@Test
	public void followsPartialAnimationLoopMetadata()
	{
		Animation animation = animation(42, 17, 12);
		Client client = TestProxies.proxy(Client.class, TestProxies.method("loadAnimation", animation));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);

		assertEquals(5, snapper.snapAnimationFrame(42, 17, 17, false));
		assertEquals(6, snapper.snapAnimationFrame(42, 18, 17, false));
	}

	@Test
	public void preservesPartialLoopAfterAnActorFrameResets()
	{
		Animation animation = animation(42, 36, 24);
		Client client = TestProxies.proxy(Client.class, TestProxies.method("loadAnimation", animation));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);
		net.runelite.api.Actor actor = TestProxies.proxy(net.runelite.api.Actor.class);

		assertEquals(35, snapper.snapActorAnimationFrame(actor, 42, 35, 36, false, false));
		assertEquals(35, snapper.snapActorAnimationFrame(actor, 42, 0, 36, false, false));
		assertEquals(13, snapper.snapActorAnimationFrame(actor, 42, 1, 36, false, false));
		assertEquals(24, snapper.snapActorAnimationFrame(actor, 42, 12, 36, false, false));
		assertEquals(35, snapper.snapActorAnimationFrame(actor, 42, 23, 36, false, false));
		assertEquals(12, snapper.snapActorAnimationFrame(actor, 42, 24, 36, false, false));
	}

	@Test
	public void keepsTheFrameRateCadenceAcrossNativePartialLoops()
	{
		Animation animation = animation(42, 37, 31);
		Client client = TestProxies.proxy(Client.class, TestProxies.method("loadAnimation", animation));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);
		net.runelite.api.Actor actor = TestProxies.proxy(net.runelite.api.Actor.class);

		assertEquals(0, snapper.snapActorAnimationFrame(actor, 42, 0, 3, false, false));
		assertEquals(16, snapper.snapActorAnimationFrame(actor, 42, 16, 3, false, false));
		assertEquals(32, snapper.snapActorAnimationFrame(actor, 42, 32, 3, false, false));
		assertEquals(32, snapper.snapActorAnimationFrame(actor, 42, 6, 3, false, false));
		assertEquals(18, snapper.snapActorAnimationFrame(actor, 42, 18, 3, false, false));
		assertEquals(34, snapper.snapActorAnimationFrame(actor, 42, 34, 3, false, false));
	}

	@Test
	public void doesNotApplyPreviousLoopOffsetWhenTheSameAnimationRestarts()
	{
		Animation animation = animation(42, 36, 24);
		Client client = TestProxies.proxy(Client.class, TestProxies.method("loadAnimation", animation));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);
		net.runelite.api.Actor actor = TestProxies.proxy(net.runelite.api.Actor.class);

		assertEquals(35, snapper.snapActorAnimationFrame(actor, 42, 35, 36, false, false));
		assertEquals(35, snapper.snapActorAnimationFrame(actor, 42, 0, 36, false, false));
		assertEquals(-1, snapper.snapActorAnimationFrame(actor, -1, -1, 36, false, false));
		assertEquals(0, snapper.snapActorAnimationFrame(actor, 42, 0, 36, false, false));
	}

	@Test
	public void leavesNonLoopingAnimationsOnTheirFinalFrame()
	{
		Animation animation = animation(42, 17, -1);
		Client client = TestProxies.proxy(Client.class, TestProxies.method("loadAnimation", animation));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);

		assertEquals(16, snapper.snapAnimationFrame(42, 41, 17, false));
	}

	@Test
	public void returnsOriginalFrameForInvalidOrUnnecessarySnapping()
	{
		Client client = TestProxies.proxy(Client.class, TestProxies.method("loadAnimation", animation(7, 4)));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);

		assertEquals(3, snapper.snapAnimationFrame(-1, 3, 2));
		assertEquals(-1, snapper.snapAnimationFrame(7, -1, 2));
		assertEquals(3, snapper.snapAnimationFrame(7, 3, 0));
		assertEquals(3, snapper.snapAnimationFrame(7, 3, 4));
		assertEquals(3, snapper.snapFrame(null, 3, true, 2));
		assertEquals(3, snapper.snapFrame(animation(7, 4), 3, false, 2));
	}

	@Test
	public void cachesFrameCountsUntilCleared()
	{
		AtomicInteger loads = new AtomicInteger();
		Animation animation = animation(5, 8);
		Client client = TestProxies.proxy(Client.class,
			TestProxies.methodSupplier("loadAnimation", () ->
			{
				loads.incrementAndGet();
				return animation;
			}));
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(client);

		snapper.snapAnimationFrame(5, 1, 2);
		snapper.snapAnimationFrame(5, 2, 2);
		assertEquals(1, loads.get());
		snapper.clear();
		snapper.snapAnimationFrame(5, 2, 2);
		assertEquals(2, loads.get());
	}

	@Test
	public void toleratesMissingAnimation()
	{
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(TestProxies.proxy(Client.class));

		assertEquals(4, snapper.snapAnimationFrame(123, 4, 2));
	}

	@Test
	public void successfullyCapturedLivePoseDoesNotRewindToAnOlderBucket()
	{
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(TestProxies.proxy(Client.class,
			TestProxies.method("loadAnimation", animation(42, 10))));
		net.runelite.api.Actor actor = TestProxies.proxy(net.runelite.api.Actor.class);
		assertEquals(3, snapper.snapActorAnimationFrame(actor, 42, 5, 3, true, false));
		snapper.commitActorLivePose(actor, 42, 5, -1, -1);
		assertEquals(5, snapper.snapActorAnimationFrame(actor, 42, 5, 3, true, false));
		assertEquals(5, snapper.snapActorAnimationFrame(actor, 42, 6, 3, true, false));
		assertEquals(6, snapper.snapActorAnimationFrame(actor, 42, 7, 3, true, false));
	}

	@Test
	public void actionAndPoseFloorsAreIndependentAndRealLoopsCanRestart()
	{
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(TestProxies.proxy(Client.class,
			TestProxies.method("loadAnimation", animation(42, 10))));
		net.runelite.api.Actor actor = TestProxies.proxy(net.runelite.api.Actor.class);
		snapper.snapActorAnimationFrame(actor, 42, 5, 3, true, false);
		snapper.snapActorAnimationFrame(actor, 43, 9, 3, true, true);
		snapper.commitActorLivePose(actor, 42, 5, 43, 9);
		assertEquals(5, snapper.snapActorAnimationFrame(actor, 42, 5, 3, true, false));
		assertEquals(0, snapper.snapActorAnimationFrame(actor, 43, 0, 3, true, true));
		assertEquals(5, snapper.snapActorAnimationFrame(actor, 42, 6, 3, true, false));
		assertEquals(0, snapper.snapActorAnimationFrame(actor, 43, 1, 3, true, true));
	}

	@Test
	public void partialLoopCadenceHoldsTheCapturedPoseUntilTheScheduleCatchesUp()
	{
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(TestProxies.proxy(Client.class,
			TestProxies.method("loadAnimation", animation(42, 36, 24))));
		net.runelite.api.Actor actor = TestProxies.proxy(net.runelite.api.Actor.class);
		assertEquals(16, snapper.snapActorAnimationFrame(actor, 42, 17, 3, false, false));
		snapper.commitActorLivePose(actor, 42, 17, -1, -1);
		assertEquals(17, snapper.snapActorAnimationFrame(actor, 42, 18, 3, false, false));
		assertEquals(32, snapper.snapActorAnimationFrame(actor, 42, 32, 3, false, false));
		snapper.snapActorAnimationFrame(actor, 42, 35, 3, false, false);
		snapper.commitActorLivePose(actor, 42, 35, -1, -1);
		assertEquals(35, snapper.snapActorAnimationFrame(actor, 42, 0, 3, false, false));
		assertEquals(35, snapper.snapActorAnimationFrame(actor, 42, 1, 3, false, false));
		assertEquals(25, snapper.snapActorAnimationFrame(actor, 42, 13, 3, false, false));
	}

	@Test
	public void partialLoopCaptureUsesTheActualPoseEvenWhenItsRawFrameDiffersFromTheAccumulatedTimeline()
	{
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(TestProxies.proxy(Client.class,
			TestProxies.method("loadAnimation", animation(42, 36, 24))));
		net.runelite.api.Actor actor = TestProxies.proxy(net.runelite.api.Actor.class);
		snapper.snapActorAnimationFrame(actor, 42, 35, 3, false, false);
		snapper.snapActorAnimationFrame(actor, 42, 0, 3, false, false);
		snapper.commitActorLivePose(actor, 42, 0, -1, -1);
		assertEquals(0, snapper.snapActorAnimationFrame(actor, 42, 1, 3, false, false));
		assertEquals(25, snapper.snapActorAnimationFrame(actor, 42, 13, 3, false, false));
	}

	@Test
	public void animationChangesResetsAndCacheClearDoNotKeepThePreviousPoseFloor()
	{
		AnimationFrameSnapper snapper = new AnimationFrameSnapper(TestProxies.proxy(Client.class,
			TestProxies.method("loadAnimation", animation(42, 10))));
		net.runelite.api.Actor actor = TestProxies.proxy(net.runelite.api.Actor.class);
		snapper.snapActorAnimationFrame(actor, 42, 5, 3, true, false);
		snapper.commitActorLivePose(actor, 42, 5, -1, -1);
		assertEquals(3, snapper.snapActorAnimationFrame(actor, 43, 5, 3, true, false));
		snapper.commitActorLivePose(actor, 43, 5, -1, -1);
		assertEquals(-1, snapper.snapActorAnimationFrame(actor, -1, -1, 3, true, false));
		assertEquals(3, snapper.snapActorAnimationFrame(actor, 43, 5, 3, true, false));
		snapper.commitActorLivePose(actor, 43, 5, -1, -1);
		snapper.clear();
		assertEquals(3, snapper.snapActorAnimationFrame(actor, 43, 5, 3, true, false));
	}

	private static Animation animation(int id, int frameCount)
	{
		return animation(id, frameCount, 0);
	}

	private static Animation animation(int id, int frameCount, int frameStep)
	{
		return TestProxies.proxy(Animation.class,
			TestProxies.method("getId", id),
			TestProxies.method("getNumFrames", frameCount),
			TestProxies.method("getFrameStep", frameStep));
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Color;
import org.junit.Assert;
import org.junit.Test;

public class BillboardAngleColorUtilsTest
{
	@Test
	public void convertsLegacyActorYawToBillboardUnits()
	{
		Assert.assertEquals(4096, BillboardAngleUtils.angleToBillboardUnits(512, 2048));
		Assert.assertEquals(8192, BillboardAngleUtils.angleToBillboardUnits(1024, 2048));
		Assert.assertEquals(12288, BillboardAngleUtils.angleToBillboardUnits(1536, 2048));
	}

	@Test
	public void preservesCameraYawAlreadyInBillboardUnits()
	{
		Assert.assertEquals(4096, BillboardAngleUtils.angleToBillboardUnits(4096, 16384));
		Assert.assertEquals(8192, BillboardAngleUtils.angleToBillboardUnits(8192, 16384));
		Assert.assertEquals(12288, BillboardAngleUtils.angleToBillboardUnits(12288, 16384));
	}

	@Test
	public void wrapsConvertedAngles()
	{
		Assert.assertEquals(0, BillboardAngleUtils.angleToBillboardUnits(2048, 2048));
		Assert.assertEquals(4096, BillboardAngleUtils.angleToBillboardUnits(2560, 2048));
		Assert.assertEquals(12288, BillboardAngleUtils.angleToBillboardUnits(-512, 2048));
	}

	@Test
	public void skipsExactCapeArtifactFaceColor()
	{
		Assert.assertTrue(BillboardColorUtils.isSkippedCapeArtifactFaceColor(new Color(147, 143, 143, 255)));
	}

	@Test
	public void doesNotSkipCapeArtifactRgbWithDifferentAlpha()
	{
		Assert.assertFalse(BillboardColorUtils.isSkippedCapeArtifactFaceColor(new Color(147, 143, 143, 254)));
	}

	@Test
	public void doesNotSkipNearbyGrayFaceColors()
	{
		Assert.assertFalse(BillboardColorUtils.isSkippedCapeArtifactFaceColor(new Color(146, 143, 143, 255)));
		Assert.assertFalse(BillboardColorUtils.isSkippedCapeArtifactFaceColor(new Color(147, 142, 143, 255)));
		Assert.assertFalse(BillboardColorUtils.isSkippedCapeArtifactFaceColor(new Color(147, 143, 142, 255)));
	}

	@Test
	public void identifiesRuneLiteHiddenAndFullyTransparentFaces()
	{
		Assert.assertTrue(BillboardColorUtils.isInvisibleFace(0, new int[] {-2}, new byte[] {0}));
		Assert.assertTrue(BillboardColorUtils.isInvisibleFace(0, new int[] {123}, new byte[] {(byte) 255}));
		Assert.assertFalse(BillboardColorUtils.isInvisibleFace(0, new int[] {-1}, new byte[] {0}));
		Assert.assertFalse(BillboardColorUtils.isInvisibleFace(0, new int[] {123}, new byte[] {(byte) 254}));
	}

	@Test
	public void hiddenFaceSentinelRequiresAValidFaceIndex()
	{
		Assert.assertFalse(BillboardColorUtils.isInvisibleFace(-1, new int[] {-2}, new byte[] {(byte) 255}));
		Assert.assertFalse(BillboardColorUtils.isInvisibleFace(1, new int[] {-2}, new byte[] {(byte) 255}));
	}

	@Test
	public void applyLightBoostScalesRgbAndPreservesAlpha()
	{
		Color color = BillboardColorUtils.applyLightBoost(new Color(80, 100, 120, 150), 125.0d);

		Assert.assertEquals(new Color(100, 125, 150, 150), color);
	}

	@Test
	public void applyLightBoostClampsRgbToMaximum()
	{
		Color color = BillboardColorUtils.applyLightBoost(new Color(200, 220, 240, 255), 150.0d);

		Assert.assertEquals(new Color(255, 255, 255, 255), color);
	}

	@Test
	public void modulateTexturePixelMultipliesSampleByShadeBeforeBanding()
	{
		int expected = NpcSnapColorBanding.snapTexturePixel(0x402020C0, 8);

		int pixel = BillboardColorUtils.modulateTexturePixel(0x804080C0, new Color(128, 64, 255, 128), 8);

		Assert.assertEquals(expected, pixel);
	}

	@Test
	public void modulateTexturePixelTreatsRgbOnlySamplesAsOpaque()
	{
		int expected = NpcSnapColorBanding.snapTexturePixel(0xFF010203, 8);

		int pixel = BillboardColorUtils.modulateTexturePixel(0x00010203, new Color(255, 255, 255, 255), 8);

		Assert.assertEquals(expected, pixel);
	}

	@Test
	public void resolveFaceColorPrefersUnlitMaterialColorWhenLitIsNotMoreColorful()
	{
		Color color = BillboardColorUtils.resolveFaceColor(
			0,
			new int[] {40},
			new int[] {40},
			new int[] {40},
			new short[] {80},
			200
		);

		Assert.assertEquals(new Color(159, 159, 159, 200), color);
	}

	@Test
	public void resolveFaceColorPrefersColorfulLitColorOverGrayUnlitColor()
	{
		Color color = BillboardColorUtils.resolveFaceColor(
			0,
			new int[] {(1 << 10) | (7 << 7) | 16},
			new int[] {(1 << 10) | (7 << 7) | 16},
			new int[] {(1 << 10) | (7 << 7) | 16},
			new short[] {13},
			255
		);

		Assert.assertTrue(color.getRed() > color.getGreen());
		Assert.assertTrue(color.getGreen() > color.getBlue());
	}

	@Test
	public void resolveFaceColorDoesNotTreatPackedFaceColorsAsDirectRgb()
	{
		Color color = BillboardColorUtils.resolveFaceColor(
			0,
			new int[] {63},
			new int[] {5},
			new int[] {0},
			new short[] {13},
			255
		);

		Assert.assertEquals(new Color(26, 26, 26, 255), color);
	}

	@Test
	public void resolveFaceColorKeepsGrayUnlitColorWhenLitColorIsBlack()
	{
		Color color = BillboardColorUtils.resolveFaceColor(
			0,
			new int[] {0},
			new int[] {0},
			new int[] {0},
			new short[] {13},
			255
		);

		Assert.assertEquals(new Color(26, 26, 26, 255), color);
	}

	@Test
	public void resolveFaceColorUsesFlatPackedColorWhenThirdFaceColorIsMissing()
	{
		Color color = BillboardColorUtils.resolveFaceColor(
			0,
			new int[] {912},
			new int[] {0},
			new int[] {-1},
			null,
			255
		);

		Assert.assertTrue(color.getRed() > 0);
		Assert.assertEquals(0, color.getGreen());
		Assert.assertEquals(0, color.getBlue());
	}

	@Test
	public void resolveFaceColorFallsBackToUnlitColorWhenLitColorsAreMissing()
	{
		Color color = BillboardColorUtils.resolveFaceColor(
			0,
			new int[] {-1},
			new int[] {-1},
			new int[] {-1},
			new short[] {80},
			200
		);

		Assert.assertEquals(new Color(159, 159, 159, 200), color);
	}

	@Test
	public void resolveFaceColorUnpacksMaxSaturationWithoutWashingOutRed()
	{
		Color color = BillboardColorUtils.resolveFaceColor(
			0,
			new int[] {-1},
			new int[] {-1},
			new int[] {-1},
			new short[] {(short) ((7 << 7) | 32)},
			255
		);

		Assert.assertTrue(color.getRed() >= 120);
		Assert.assertTrue(color.getGreen() <= 4);
		Assert.assertTrue(color.getBlue() <= 4);
	}
}

