		groundItemShadow.setRGB(10, 14, 0xFFFFFFFF);

		BillboardOutlineRenderer.applyOutline(
			defaultShadow, new BillboardOutlineRenderer.Scratch(),
			false, false, false, true, false, false, false, new Color(0xDDDDDD),
