		image.setRGB(2, 2, 0xFFFFFFFF);

		BillboardOutlineRenderer.applyOutline(image, false, false, true, false, false, false, false, new Color(0x90FF0000, true));

		assertEquals(0x90FF0000, image.getRGB(2, 1));
	}

	@Test
	public void applyOutlinePreservesNeighborAlphaForGeneratedColors()
	{
		BufferedImage image = new BufferedImage(5, 5, BufferedImage.TYPE_INT_ARGB);
		image.setRGB(2, 2, 0x80804000);

		BillboardOutlineRenderer.applyOutline(image, true, false, false, false, false, false, false, new Color(0xDDDDDD));

		assertEquals(0x80AA5500, image.getRGB(2, 1));
	}

	@Test
	public void applyOutlineUsesHighestPriorityExteriorColorOnSingleFootprint()
	{
		BufferedImage image = new BufferedImage(5, 5, BufferedImage.TYPE_INT_ARGB);
		image.setRGB(2, 2, 0xFF804000);

		BillboardOutlineRenderer.applyOutline(image, true, true, true, false, false, false, false, new Color(0x9000FF00, true));

		assertEquals(0xFFAA5500, image.getRGB(2, 1));
		assertEquals(0x00000000, image.getRGB(1, 1));
	}

	@Test
	public void captureExteriorBoundaryIndicesDoesNotLeakStaleIndicesFromLargerImage()
	{
		BillboardOutlineRenderer.Scratch scratch = new BillboardOutlineRenderer.Scratch();

		BufferedImage largeImage = new BufferedImage(9, 9, BufferedImage.TYPE_INT_ARGB);
		largeImage.setRGB(4, 4, 0xFFFFFFFF);
		BillboardOutlineRenderer.captureExteriorBoundaryIndices(largeImage, scratch);

		BufferedImage smallImage = new BufferedImage(3, 3, BufferedImage.TYPE_INT_ARGB);
		smallImage.setRGB(1, 1, 0xFFFFFFFF);
		int[] indices = BillboardOutlineRenderer.captureExteriorBoundaryIndices(smallImage, scratch);

		for (int index : indices)
		{
			if (index < 0 || index >= 9)
			{
				throw new AssertionError("Boundary index leaked past current image: " + index);
			}
		}
	}
}

package com.kierenboal.npcsnap.rendering;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class BillboardPaintOrderTest
{
	@Test
	public void overlappingBillboardsSortByScreenBottom()
	{
		List<String> ordered = BillboardPaintOrder.sort(Arrays.asList(
			new BillboardPaintOrder.Entry<>("near-high", new Rectangle(20, 10, 30, 40), 1, BillboardPaintOrder.NO_PRIORITY_GROUP, 50, 100.0d, 2L),
			new BillboardPaintOrder.Entry<>("far-low", new Rectangle(25, 30, 30, 40), 1, BillboardPaintOrder.NO_PRIORITY_GROUP, 70, 140.0d, 1L)
		));

		Assert.assertEquals(Arrays.asList("near-high", "far-low"), ordered);
	}

	@Test
	public void sameTilePriorityStillKeepsGroundItemsUnderActors()
	{
		long sameTile = 1234L;
		List<String> ordered = BillboardPaintOrder.sort(Arrays.asList(
			new BillboardPaintOrder.Entry<>("actor", new Rectangle(40, 20, 24, 36), 1, sameTile, 56, 120.0d, 2L),
			new BillboardPaintOrder.Entry<>("ground", new Rectangle(42, 34, 20, 12), 0, sameTile, 46, 90.0d, 1L)
		));

		Assert.assertEquals(Arrays.asList("ground", "actor"), ordered);
	}

	@Test
	public void nonOverlappingGroupsStillSortByDepth()
	{
		List<String> ordered = BillboardPaintOrder.sort(Arrays.asList(
			new BillboardPaintOrder.Entry<>("near-left", new Rectangle(10, 20, 20, 20), 1, BillboardPaintOrder.NO_PRIORITY_GROUP, 40, 80.0d, 1L),
			new BillboardPaintOrder.Entry<>("far-right", new Rectangle(200, 20, 20, 20), 1, BillboardPaintOrder.NO_PRIORITY_GROUP, 40, 140.0d, 2L)
		));

		Assert.assertEquals(Arrays.asList("far-right", "near-left"), ordered);
	}

	@Test
	public void projectileUsesThreeDimensionalDepthBeforeScreenBottom()
	{
		List<String> ordered = BillboardPaintOrder.sort(Arrays.asList(
			new BillboardPaintOrder.Entry<>("projectile", new Rectangle(40, 20, 24, 24), 1, BillboardPaintOrder.NO_PRIORITY_GROUP, 44, 100.0d, true, 1L),
			new BillboardPaintOrder.Entry<>("npc", new Rectangle(42, 34, 24, 36), 1, BillboardPaintOrder.NO_PRIORITY_GROUP, 70, 140.0d, false, 2L)
		));

		Assert.assertEquals(Arrays.asList("npc", "projectile"), ordered);
	}
}

package com.kierenboal.npcsnap.rendering;

import com.kierenboal.npcsnap.TestProxies;

import java.awt.Rectangle;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Client;
import net.runelite.api.Projectile;
import net.runelite.api.coords.LocalPoint;
import org.junit.Assert;
import org.junit.Test;

import static com.kierenboal.npcsnap.TestProxies.method;
import static com.kierenboal.npcsnap.TestProxies.proxy;

public class BillboardProjectileGeometryTest
{
	@Test
	public void localPointUsesProjectileWorldLocalCoordinates()
	{
		Projectile projectile = proxy(
			Projectile.class,
			method("getX", 320.75d),
			method("getY", 448.25d)
		);

		LocalPoint localPoint = BillboardProjectileGeometry.localPoint(projectile);

		Assert.assertEquals(new LocalPoint(320, 448), localPoint);
	}

	@Test
	public void drawBoundsFollowProvidedLaunchArcAndImpactCoordinates()
	{
		BillboardDepthCalculator calculator = new BillboardDepthCalculator(projectionClient(false));
		Rectangle imageBounds = new Rectangle(-10, -10, 20, 20);
		double[][] positions = {
			{0, -100}, {50, -200}, {100, -250}, {150, -200}, {200, -100}
		};
		for (double[] position : positions)
		{
			Projectile projectile = projectile(position[0], 1000.0d, position[1]);
			Rectangle draw = BillboardProjectileGeometry.drawBounds(calculator, projectile, imageBounds, 1000.0d);
			Assert.assertEquals(new Rectangle((int) (390 + position[0]), (int) (290 + position[1]), 20, 20), draw);
		}
	}

	@Test
	public void nativeHeightAndFractionalCoordinatesArePreservedAcrossCpuAndGpu()
	{
		for (boolean gpu : new boolean[] {false, true})
		{
			BillboardDepthCalculator calculator = new BillboardDepthCalculator(projectionClient(gpu));
			Rectangle imageBounds = new Rectangle(-10, -10, 20, 20);
			Assert.assertEquals(new Rectangle(391, 189, 20, 20),
				BillboardProjectileGeometry.drawBounds(calculator, projectile(0.99d, 1000.0d, -100.99d), imageBounds, 1000.0d));
			// Higher launches and unusual impact heights stay exactly where the
			// client's current Z places them, without adding an actor/model height.
			Assert.assertEquals(new Rectangle(390, -10, 20, 20),
				BillboardProjectileGeometry.drawBounds(calculator, projectile(0.0d, 1000.0d, -300.0d), imageBounds, 1000.0d));
			Assert.assertEquals(new Rectangle(390, 330, 20, 20),
				BillboardProjectileGeometry.drawBounds(calculator, projectile(0.0d, 1000.0d, 40.0d), imageBounds, 1000.0d));
		}
	}

	@Test
	public void cachedSpriteDoesNotMoveOrResizeWhenLiveProjectileModelHeightChanges()
	{
		AtomicInteger height = new AtomicInteger(20);
		Projectile projectile = proxy(Projectile.class, method("getX", 100.0d), method("getY", 1000.0d),
			method("getZ", -100.0d), TestProxies.methodSupplier("getModelHeight", height::get));
		BillboardDepthCalculator calculator = new BillboardDepthCalculator(projectionClient(false));
		Rectangle imageBounds = new Rectangle(-10, -10, 20, 20);
		Rectangle first = BillboardProjectileGeometry.drawBounds(calculator, projectile, imageBounds, 1000.0d);
		height.set(400);
		Assert.assertEquals(first, BillboardProjectileGeometry.drawBounds(calculator, projectile, imageBounds, 1000.0d));
		height.set(0);
		Assert.assertEquals(first, BillboardProjectileGeometry.drawBounds(calculator, projectile, imageBounds, 1000.0d));
	}

	@Test
	public void cropAndPaddingKeepTheModelOriginAtTheSameFlightPosition()
	{
		BillboardDepthCalculator calculator = new BillboardDepthCalculator(projectionClient(false));
		Projectile projectile = projectile(100.0d, 1000.0d, -100.0d);
		Rectangle first = BillboardProjectileGeometry.drawBounds(calculator, projectile,
			new Rectangle(-10, -10, 20, 20), 1000.0d);
		Rectangle padded = BillboardProjectileGeometry.drawBounds(calculator, projectile,
			new Rectangle(-15, -15, 30, 30), 1000.0d);
		Assert.assertEquals(first.getCenterX(), padded.getCenterX(), 0.0d);
		Assert.assertEquals(first.getCenterY(), padded.getCenterY(), 0.0d);
		Rectangle asymmetric = BillboardProjectileGeometry.drawBounds(calculator, projectile,
			new Rectangle(-10, -30, 20, 40), 1000.0d);
		Assert.assertEquals(new Rectangle(490, 170, 20, 40), asymmetric);
		Assert.assertEquals(200, asymmetric.y + 30);
	}

	@Test
	public void invalidOrNearPlaneFlightPositionsDoNotUseAFallbackAnchor()
	{
		BillboardDepthCalculator calculator = new BillboardDepthCalculator(projectionClient(false));
		Rectangle imageBounds = new Rectangle(-10, -10, 20, 20);
		Assert.assertNull(BillboardProjectileGeometry.drawBounds(calculator, projectile(0.0d, 49.0d, -100.0d), imageBounds, 1000.0d));
		Assert.assertNull(BillboardProjectileGeometry.drawBounds(calculator, projectile(0.0d, -100.0d, -100.0d), imageBounds, 1000.0d));
		Assert.assertNull(BillboardProjectileGeometry.drawBounds(calculator, projectile(Double.NaN, 1000.0d, -100.0d), imageBounds, 1000.0d));
		Assert.assertNull(BillboardProjectileGeometry.drawBounds(calculator, projectile(0.0d, 1000.0d, Double.NaN), imageBounds, 1000.0d));
	}

	private static Projectile projectile(double x, double y, double z)
	{
		return proxy(Projectile.class, method("getX", x), method("getY", y), method("getZ", z));
	}

	private static Client projectionClient(boolean gpu)
	{
		return proxy(Client.class, method("isGpu", gpu), method("getScale", 1000),
			method("getViewportWidth", 800), method("getViewportHeight", 600));
	}
}

package com.kierenboal.npcsnap.rendering;

import org.junit.Assert;
import org.junit.Test;

public class BillboardRenderQualityTest
{
	@Test
	public void clampsQualityScaleToSupportedRange()
	{
		Assert.assertEquals(0.01d, BillboardRenderQuality.clamp(0.0d), 0.00001d);
		Assert.assertEquals(0.5d, BillboardRenderQuality.clamp(0.5d), 0.00001d);
		Assert.assertEquals(1.0d, BillboardRenderQuality.clamp(2.0d), 0.00001d);
	}

	@Test
	public void convertsPercentToQualityScale()
	{
		Assert.assertEquals(0.25d, BillboardRenderQuality.fromPercent(25), 0.00001d);
		Assert.assertEquals(1.0d, BillboardRenderQuality.fromPercent(250), 0.00001d);
	}

	@Test
	public void buildsStableIntegerQualityKeys()
	{
		Assert.assertEquals(100, BillboardRenderQuality.key(0.0d));
		Assert.assertEquals(2500, BillboardRenderQuality.key(0.25d));
		Assert.assertEquals(10_000, BillboardRenderQuality.key(2.0d));
	}

	@Test
	public void paddingAlwaysLeavesOneRasterPixelAtReducedQuality()
	{
		Assert.assertEquals(0, BillboardRenderQuality.rasterSafePadding(0, 0.25d));
		Assert.assertEquals(1, BillboardRenderQuality.rasterSafePadding(1, 1.0d));
		Assert.assertEquals(2, BillboardRenderQuality.rasterSafePadding(1, 0.5d));
		Assert.assertEquals(4, BillboardRenderQuality.rasterSafePadding(1, 0.25d));
	}

	@Test
	public void seededScaleDropsQualityByBootstrapTier()
	{
		Assert.assertEquals(0.8d, BillboardRenderQuality.seededScale(0.8d, 0, 2), 0.00001d);
		Assert.assertEquals(0.4d, BillboardRenderQuality.seededScale(0.8d, 2, 2), 0.00001d);
		Assert.assertEquals(0.2d, BillboardRenderQuality.seededScale(0.8d, 4, 2), 0.00001d);
	}
}

