import java.awt.image.BufferedImage;
import net.runelite.api.Model;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class BillboardCacheModelsTest
{
	@Test
	public void fullAndPreviewFactoriesStayInSync()
	{
		NpcSnapConfig config = config();
		BillboardRenderRequest request = request(true, false);
		BillboardCacheKey key = BillboardCacheKey.create(request, config, 2, 12, 75, 99, 101);
		BillboardCachePreviewKey preview = BillboardCachePreviewKey.create(request, config, 2, 75, 101);
		CachedBillboard cached = new CachedBillboard(
			key, new Rectangle(1, 2, 3, 4), new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), 10L);

		assertTrue(cached.matchesPreviewKey(preview));
		assertEquals(12, key.colorBands);
		assertEquals(99, key.textureStateHash);
	}

	@Test
	public void previewRejectsChangedRequestOrAnimatedTextureState()
	{
		NpcSnapConfig config = config();
		BillboardCacheKey key = BillboardCacheKey.create(request(true, false), config, 2, 12, 75, 99, 101);
		CachedBillboard cached = new CachedBillboard(
			key, new Rectangle(1, 2, 3, 4), new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), 10L);

		assertFalse(cached.matchesPreviewKey(null));
		assertFalse(cached.matchesPreviewKey(BillboardCachePreviewKey.create(request(false, false), config, 2, 75, 101)));
		assertFalse(cached.matchesPreviewKey(BillboardCachePreviewKey.create(request(true, false), config, 2, 75, 102)));
	}

	@Test
	public void brightnessChangeInvalidatesPreview()
	{
		NpcSnapConfig config = config();
		BillboardRenderRequest request = request(false, false);
		BillboardCacheKey key = BillboardCacheKey.create(request, config, 2, 12, 75, 99, 101, 180);
		CachedBillboard cached = new CachedBillboard(key,
			new Rectangle(1, 2, 3, 4), new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB), 10L);

		assertTrue(cached.matchesPreviewKey(BillboardCachePreviewKey.create(request, config, 2, 75, 101, 180)));
		assertFalse(cached.matchesPreviewKey(BillboardCachePreviewKey.create(request, config, 2, 75, 101, 360)));
	}

	@Test
	public void fullKeyEqualityIncludesTextureAndColorInputs()
	{
		NpcSnapConfig config = config();
		BillboardRenderRequest request = request(false, true);
		BillboardCacheKey base = BillboardCacheKey.create(request, config, 1, 8, 50, 7, 9);
		BillboardCacheKey same = BillboardCacheKey.create(request, config, 1, 8, 50, 7, 9);
		BillboardCacheKey otherBands = BillboardCacheKey.create(request, config, 1, 9, 50, 7, 9);
		BillboardCacheKey otherTexture = BillboardCacheKey.create(request, config, 1, 8, 50, 8, 9);

		assertEquals(base, same);
		assertEquals(base.hashCode(), same.hashCode());
		assertNotEquals(base, otherBands);
		assertNotEquals(base, otherTexture);
		assertNotEquals(base, null);
	}

	@Test
	public void cachedBillboardStateIsConsumableAndBoundsAreDefensivelyCopied()
	{
		Rectangle sourceBounds = new Rectangle(1, 2, 3, 4);
		Rectangle contentBounds = new Rectangle(2, 3, 1, 2);
		CachedBillboard cached = new CachedBillboard(
			BillboardCacheKey.create(request(false, false), config(), 1, 8, 50, 0, 0),
			sourceBounds,
			contentBounds,
			new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB),
			10L);
		sourceBounds.x = 100;
		contentBounds.x = 100;

		assertEquals(1, cached.bounds.x);
		assertEquals(2, cached.contentBounds.x);
		assertTrue(cached.consumeDirty());
		assertFalse(cached.consumeDirty());
		assertTrue(cached.consumeDebugFrameRedrawn());
		assertFalse(cached.consumeDebugFrameRedrawn());
		cached.touch(20L);
		assertEquals(20L, cached.lastUsedMillis());
	}

	private static NpcSnapConfig config()
	{
		return TestProxies.proxy(NpcSnapConfig.class,
			TestProxies.method("billboardColorBands", 12),
			TestProxies.method("billboardLightBoostPercent", 180),
			TestProxies.method("enableBillboardHighlightOutline", true),
			TestProxies.method("enableBillboardShadowOutline", false),
			TestProxies.method("enableBillboardSpriteOutline", true),
			TestProxies.method("enableBillboardSpriteShadows", true),
			TestProxies.method("enableBillboardHighlightInline", false),
			TestProxies.method("enableBillboardShadowInline", true),
			TestProxies.method("enableBillboardSpriteInline", false),
			TestProxies.method("billboardSpriteOutlineColor", Color.BLUE),
			TestProxies.method("billboardHoverOutlineColor", Color.YELLOW),
			TestProxies.method("billboardInteractionOutlineColor", Color.RED));
	}

	private static BillboardRenderRequest request(boolean hover, boolean interact)
	{
		Model model = TestProxies.proxy(Model.class,
			TestProxies.method("getVerticesCount", 0),
			TestProxies.method("getModelHeight", 10));
		return new BillboardRenderRequest(
			null, model, null, 0, 0, 10, 20, 30, 40, 50, 60, -1,
			hover, interact, VerticalAnchor.BOTTOM, null);
	}
}

package com.kierenboal.npcsnap.state;

import com.kierenboal.npcsnap.BillboardConstants;
import com.kierenboal.npcsnap.TestProxies;

import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.api.Renderable;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class BillboardCacheStoreTest
{
	@Test
	public void putGetAndContainsUseRenderableIdentity()
	{
		BillboardCacheStore store = new BillboardCacheStore();
		Renderable renderable = TestProxies.proxy(Renderable.class);
		CachedBillboard cached = cached(new TrackingImage(), 10L);

		store.put(renderable, cached);

		assertSame(cached, store.get(renderable));
		assertTrue(store.contains(renderable));
		assertFalse(store.contains(TestProxies.proxy(Renderable.class)));
	}

	@Test
	public void replacementRemovalAndClearFlushOwnedImages()
	{
		BillboardCacheStore store = new BillboardCacheStore();
		Renderable firstKey = TestProxies.proxy(Renderable.class);
		Renderable secondKey = TestProxies.proxy(Renderable.class);
		TrackingImage replacedImage = new TrackingImage();
		TrackingImage removedImage = new TrackingImage();
		TrackingImage clearedImage = new TrackingImage();
		store.put(firstKey, cached(replacedImage, 10L));
		store.put(firstKey, cached(removedImage, 10L));
		store.put(secondKey, cached(clearedImage, 10L));

		assertTrue(replacedImage.flushed);
		store.remove(firstKey);
		assertTrue(removedImage.flushed);
		assertNull(store.get(firstKey));
		store.clear();
		assertTrue(clearedImage.flushed);
		assertFalse(store.contains(secondKey));
	}

	@Test
	public void expirationUsesIdleTtlAndFlushesExpiredEntries()
	{
		BillboardCacheStore store = new BillboardCacheStore();
		Renderable expiredKey = TestProxies.proxy(Renderable.class);
		Renderable liveKey = TestProxies.proxy(Renderable.class);
		TrackingImage expiredImage = new TrackingImage();
		store.put(expiredKey, cached(expiredImage, 0L));
		store.put(liveKey, cached(new TrackingImage(), BillboardConstants.CACHE_TTL_MILLIS));

		store.expire(BillboardConstants.CACHE_TTL_MILLIS + 1L);

		assertFalse(store.contains(expiredKey));
		assertTrue(expiredImage.flushed);
		assertTrue(store.contains(liveKey));
	}

	private static CachedBillboard cached(BufferedImage image, long lastUsed)
	{
		return new CachedBillboard(null, new Rectangle(0, 0, 1, 1), image, lastUsed);
	}

	private static final class TrackingImage extends BufferedImage
	{
		private boolean flushed;

		private TrackingImage()
		{
			super(1, 1, BufferedImage.TYPE_INT_ARGB);
		}

		@Override
		public void flush()
		{
			flushed = true;
			super.flush();
		}
	}
}

package com.kierenboal.npcsnap.state;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.util.List;
import org.junit.Test;

public class BillboardPerformanceMetricsTest
{
	@Test
	public void disabledMetricsDoNotRetainFrameData()
	{
		TestClock clock = new TestClock();
		BillboardPerformanceMetrics metrics = new BillboardPerformanceMetrics(clock::nanos);

		metrics.beginFrame(false);
		metrics.addElapsed("Hidden", 10_000_000L);
		metrics.finishFrame();

		assertTrue(metrics.rows(10).isEmpty());
	}

	@Test
	public void doesNotPublishSnapshotBeforeFiveHundredMilliseconds()
	{
		TestClock clock = new TestClock();
		BillboardPerformanceMetrics metrics = new BillboardPerformanceMetrics(clock::nanos);

		metrics.beginFrame(true);
		metrics.addElapsed("Stage", 10_000_000L);
		clock.advanceMillis(499);
		metrics.finishFrame();

		assertTrue(metrics.rows(10).isEmpty());
	}

	@Test
	public void publishesMinAvgAndMaxAfterFiveHundredMilliseconds()
	{
		TestClock clock = new TestClock();
		BillboardPerformanceMetrics metrics = new BillboardPerformanceMetrics(clock::nanos);

		recordFrame(metrics, clock, "Stage", 10, 100);
		recordFrame(metrics, clock, "Stage", 20, 400);

		List<BillboardPerformanceMetrics.MetricRow> rows = metrics.rows(10);
		BillboardPerformanceMetrics.MetricRow stage = rows.get(1);
		assertEquals("Stage", stage.name);
		assertEquals(1, stage.depth);
		assertEquals(10.0d, stage.minMillis, 0.0001d);
		assertEquals(15.0d, stage.avgMillis, 0.0001d);
		assertEquals(20.0d, stage.maxMillis, 0.0001d);
		assertEquals(6.0d, stage.percentOfOverall, 0.0001d);
		assertEquals(100.0d, rows.get(0).percentOfOverall, 0.0001d);
	}

	@Test
	public void rowsUseDepthInsteadOfDashPrefixes()
	{
		TestClock clock = new TestClock();
		BillboardPerformanceMetrics metrics = new BillboardPerformanceMetrics(clock::nanos);

		metrics.beginFrame(true);
		try (BillboardPerformanceMetrics.Timer ignored = metrics.time("Rasterization"))
		{
			metrics.addElapsed("Painting triangles", 12_000_000L);
		}
		clock.advanceMillis(500);
		metrics.finishFrame();

		List<BillboardPerformanceMetrics.MetricRow> rows = metrics.rows(10);
		assertEquals("Painting triangles", rows.get(2).name);
		assertEquals(2, rows.get(2).depth);
		assertFalse(rows.get(2).name.startsWith("-"));
	}

	@Test
	public void sortsSiblingMetricsByIntervalAverageDescending()
	{
		TestClock clock = new TestClock();
		BillboardPerformanceMetrics metrics = new BillboardPerformanceMetrics(clock::nanos);

		metrics.beginFrame(true);
		metrics.addElapsed("Fast", 1_000_000L);
		metrics.addElapsed("Slow", 5_000_000L);
		clock.advanceMillis(500);
		metrics.finishFrame();

		List<BillboardPerformanceMetrics.MetricRow> rows = metrics.rows(10);
		assertEquals("Slow", rows.get(1).name);
		assertEquals("Fast", rows.get(2).name);
		assertEquals(0.2d, rows.get(2).percentOfOverall, 0.0001d);
	}

	@Test
	public void colorsAreStableAndBright()
	{
		Color first = BillboardPerformanceMetrics.colorForName("Rasterization");
		Color second = BillboardPerformanceMetrics.colorForName("Rasterization");

		assertEquals(first, second);
		assertBright(first.getRed());
		assertBright(first.getGreen());
		assertBright(first.getBlue());
	}

	private static void recordFrame(BillboardPerformanceMetrics metrics, TestClock clock, String name, int elapsedMillis, int frameMillis)
	{
		metrics.beginFrame(true);
		metrics.addElapsed(name, elapsedMillis * 1_000_000L);
		clock.advanceMillis(frameMillis);
		metrics.finishFrame();
	}

	private static void assertBright(int channel)
	{
		assertTrue(channel >= 140);
		assertTrue(channel <= 255);
	}

	private static final class TestClock
	{
		private long nanos;

		private long nanos()
		{
			return nanos;
		}

		private void advanceMillis(int millis)
		{
			nanos += millis * 1_000_000L;
		}
	}
}

package com.kierenboal.npcsnap.state;

