import static com.kierenboal.npcsnap.TestProxies.method;
import static com.kierenboal.npcsnap.TestProxies.proxy;

public class BillboardHoverInteractionResolverTest
{
	@Test
	public void recognizesActorHoverActions()
	{
		Assert.assertTrue(BillboardHoverInteractionResolver.isActorHoverAction(MenuAction.NPC_FIRST_OPTION));
		Assert.assertTrue(BillboardHoverInteractionResolver.isActorHoverAction(MenuAction.PLAYER_FIRST_OPTION));
		Assert.assertTrue(BillboardHoverInteractionResolver.isActorHoverAction(MenuAction.WIDGET_TARGET_ON_PLAYER));
	}

	@Test
	public void rejectsNonActorHoverActions()
	{
		Assert.assertFalse(BillboardHoverInteractionResolver.isActorHoverAction(null));
		Assert.assertFalse(BillboardHoverInteractionResolver.isActorHoverAction(MenuAction.WALK));
		Assert.assertFalse(BillboardHoverInteractionResolver.isActorHoverAction(MenuAction.CC_OP));
		Assert.assertFalse(BillboardHoverInteractionResolver.isActorHoverAction(MenuAction.WORLD_ENTITY_FIRST_OPTION));
	}

	@Test
	public void recognizesWorldEntityActorInteractions()
	{
		Assert.assertTrue(BillboardHoverInteractionResolver.isActorInteractionAction(MenuAction.WORLD_ENTITY_FIRST_OPTION));
		Assert.assertTrue(BillboardHoverInteractionResolver.isActorInteractionAction(MenuAction.NPC_FIRST_OPTION));
	}

	@Test
	public void recognizesAndResolvesGroundItemActions()
	{
		Assert.assertTrue(BillboardHoverInteractionResolver.isGroundItemAction(MenuAction.GROUND_ITEM_FIRST_OPTION));
		Assert.assertTrue(BillboardHoverInteractionResolver.isGroundItemAction(MenuAction.ITEM_USE_ON_GROUND_ITEM));
		Assert.assertFalse(BillboardHoverInteractionResolver.isGroundItemAction(MenuAction.WALK));

		WorldView worldView = proxy(WorldView.class, method("getBaseX", 0), method("getBaseY", 0));
		LocalPoint point = new LocalPoint(10 << 7, 20 << 7, worldView);
		TileItem item = proxy(TileItem.class, method("getId", 42));
		MenuEntry entry = proxy(
			MenuEntry.class,
			method("getIdentifier", 42),
			method("getParam0", 10),
			method("getParam1", 20));

		Assert.assertSame(
			item,
			BillboardHoverInteractionResolver.groundItem(
				entry,
				Collections.singletonList(new AbstractMap.SimpleEntry<>(
					item, new GroundItemBillboard(0, point)))));
	}

	@Test
	public void hoveredActorUsesTopMenuEntryWhenMenuIsClosed()
	{
		Actor actor = proxy(Actor.class);
		MenuEntry walk = proxy(MenuEntry.class, method("getType", MenuAction.WALK));
		MenuEntry attack = proxy(MenuEntry.class, method("getType", MenuAction.NPC_FIRST_OPTION), method("getActor", actor));
		Client client = proxy(
			Client.class,
			method("getMenuEntries", new MenuEntry[] { walk, attack }),
			method("isMenuOpen", false)
		);

		Assert.assertSame(actor, BillboardHoverInteractionResolver.hoveredActor(client));
	}

	@Test
	public void hoveredActorUsesMouseRowWhenMenuIsOpen()
	{
		Actor actor = proxy(Actor.class);
		MenuEntry bottom = proxy(MenuEntry.class, method("getType", MenuAction.WALK));
		MenuEntry middle = proxy(MenuEntry.class, method("getType", MenuAction.NPC_FIRST_OPTION), method("getActor", actor));
		MenuEntry top = proxy(MenuEntry.class, method("getType", MenuAction.CC_OP));
		Client client = proxy(
			Client.class,
			method("getMenuEntries", new MenuEntry[] { bottom, middle, top }),
			method("isMenuOpen", true),
			method("getMenuX", 10),
			method("getMenuY", 20),
			method("getMenuWidth", 150),
			method("getMouseCanvasPosition", new Point(40, 55))
		);

		Assert.assertSame(actor, BillboardHoverInteractionResolver.hoveredActor(client));
	}

	@Test
	public void interactedActorPrefersExplicitActorOverLocalPlayerTarget()
	{
		Actor explicitActor = proxy(Actor.class);
		Actor playerTarget = proxy(Actor.class);
		Player localPlayer = proxy(Player.class, method("getInteracting", playerTarget));
		Client client = proxy(Client.class, method("getLocalPlayer", localPlayer));

		Assert.assertSame(explicitActor, BillboardHoverInteractionResolver.interactedActor(client, explicitActor));
		Assert.assertSame(playerTarget, BillboardHoverInteractionResolver.interactedActor(client, null));
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.TestProxies;

import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.TileItem;
import org.junit.Test;

import static org.junit.Assert.assertSame;

public class BillboardInteractionStateTest
{
	@Test
	public void keepsClickedActorThroughClickTickAndMatchingInteraction()
	{
		Actor actor = TestProxies.proxy(Actor.class);
		Player interactingPlayer = TestProxies.proxy(Player.class, TestProxies.method("getInteracting", actor));
		BillboardInteractionState state = new BillboardInteractionState();

		state.noteClick(actor, 10);
		state.clearIfStale(null, 10);
		assertSame(actor, state.clickedActor());
		state.clearIfStale(interactingPlayer, 11);
		assertSame(actor, state.clickedActor());
	}

	@Test
	public void clearsClickedActorWhenInteractionDoesNotMaterializeOnLaterTick()
	{
		Actor actor = TestProxies.proxy(Actor.class);
		BillboardInteractionState state = new BillboardInteractionState();

		state.noteClick(actor, 10);
		state.clearIfStale(null, 11);

		assertSame(null, state.clickedActor());
	}

	@Test
	public void ignoresInteractionChangeDuringClickTickButClearsItLater()
	{
		Actor actor = TestProxies.proxy(Actor.class);
		Actor other = TestProxies.proxy(Actor.class);
		BillboardInteractionState state = new BillboardInteractionState();

		state.noteClick(actor, 10);
		state.onLocalPlayerInteractionChanged(other, 10);
		assertSame(actor, state.clickedActor());
		state.onLocalPlayerInteractionChanged(other, 11);
		assertSame(null, state.clickedActor());
	}

	@Test
	public void onlyMatchingDespawnClearsClickedActor()
	{
		Actor actor = TestProxies.proxy(Actor.class);
		BillboardInteractionState state = new BillboardInteractionState();

		state.noteClick(actor, 10);
		state.clearIfMatches(TestProxies.proxy(Actor.class));
		assertSame(actor, state.clickedActor());
		state.clearIfMatches(actor);
		assertSame(null, state.clickedActor());
	}

	@Test
	public void groundItemInteractionPersistsUntilMatchingItemClears()
	{
		TileItem item = TestProxies.proxy(TileItem.class);
		BillboardInteractionState state = new BillboardInteractionState();

		state.noteGroundItemClick(item);
		state.clearIfMatches(TestProxies.proxy(TileItem.class));
		assertSame(item, state.clickedGroundItem());
		state.clearIfMatches(item);
		assertSame(null, state.clickedGroundItem());
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.NpcSnapConfig;
import com.kierenboal.npcsnap.TestProxies;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import net.runelite.api.GameObject;
import net.runelite.api.ItemLayer;
import net.runelite.api.NPC;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BillboardSceneDrawCallbacksTest
{
	@Test
	public void disabledAndUiCallbacksPassThroughWithoutTracking()
	{
		FakeOverlay overlay = new FakeOverlay();
		Renderable renderable = TestProxies.proxy(Renderable.class);
		BillboardSceneDrawCallbacks disabled = callbacks(false, false, false, overlay);

		assertTrue(disabled.addEntity(renderable, false));
		assertTrue(disabled.draw(renderable, false));
		assertTrue(callbacks(true, false, false, overlay).draw(renderable, true));
		assertTrue(overlay.noted.isEmpty());
	}

	@Test
	public void uiCallbacksOnlySuppressActorsEligibleForOverheadReplacement()
	{
		FakeOverlay overlay = new FakeOverlay();
		NPC npc = TestProxies.proxy(NPC.class);

		assertTrue(callbacks(true, false, false, overlay).addEntity(npc, true));
		overlay.hiddenActor2d.add(npc);
		assertFalse(callbacks(true, false, false, overlay).addEntity(npc, true));
		assertFalse(callbacks(true, false, false, overlay).draw(npc, true));
		assertTrue(overlay.noted.isEmpty());
	}

	@Test
	public void addEntityAlwaysPreservesActorInteraction()
	{
		FakeOverlay overlay = new FakeOverlay();
		NPC npc = TestProxies.proxy(NPC.class);
		overlay.hiddenRenderables.add(npc);

		assertTrue(callbacks(true, false, false, overlay).addEntity(npc, false));
		assertTrue(overlay.noted.contains(npc));
	}

	@Test
	public void addEntityPreservesNestedSceneInteractionWhileDrawSuppressesItsPixels()
	{
		FakeOverlay overlay = new FakeOverlay();
		Scene scene = TestProxies.proxy(Scene.class);
		overlay.hiddenRenderables.add(scene);
		BillboardSceneDrawCallbacks callbacks = callbacks(true, false, false, overlay);

		assertTrue(callbacks.addEntity(scene, false));
		assertFalse(callbacks.draw(scene, false));
		assertTrue(overlay.noted.contains(scene));
	}

	@Test
	public void addEntityKeepsHiddenRenderableInSceneForLaterSuppression()
	{
		FakeOverlay overlay = new FakeOverlay();
		Renderable renderable = TestProxies.proxy(Renderable.class);
		overlay.hiddenRenderables.add(renderable);
		BillboardSceneDrawCallbacks callbacks = callbacks(true, false, false, overlay);

		assertTrue(callbacks.addEntity(renderable, false));
		assertFalse(callbacks.draw(renderable, false));
		assertTrue(overlay.noted.contains(renderable));
	}

	@Test
	public void selectedObjectPartIsSuppressedBySceneDraw()
	{
		FakeOverlay overlay = new FakeOverlay();
		Renderable part = TestProxies.proxy(Renderable.class);
		GameObject object = TestProxies.proxy(GameObject.class, TestProxies.method("getRenderable", part));
		overlay.hiddenRenderables.add(part);
		BillboardSceneDrawCallbacks callbacks = callbacks(true, false, false, overlay);

		assertFalse(callbacks.drawObject(object));
		assertTrue(callbacks.addEntity(part, false));
		assertFalse(callbacks.draw(part, false));
	}

	@Test
	public void gameObjectIsObservedAndSuppressedAsAWhole()
	{
		FakeOverlay overlay = new FakeOverlay();
		Renderable part = TestProxies.proxy(Renderable.class);
		GameObject object = TestProxies.proxy(GameObject.class, TestProxies.method("getRenderable", part));
		overlay.hiddenTileObjects.add(object);

		assertFalse(callbacks(true, true, false, overlay).drawObject(object));
		assertTrue(overlay.observed.contains(object));
		assertTrue(overlay.noted.contains(part));
	}

	@Test
	public void gameObjectPartIsSuppressedWhenWholeObjectIsNotYetCached()
	{
		FakeOverlay overlay = new FakeOverlay();
		Renderable part = TestProxies.proxy(Renderable.class);
		GameObject object = TestProxies.proxy(GameObject.class, TestProxies.method("getRenderable", part));
		overlay.hiddenRenderables.add(part);

		assertFalse(callbacks(true, true, false, overlay).drawObject(object));
		assertTrue(overlay.observed.contains(object));
		assertTrue(overlay.noted.contains(part));
	}

	@Test
	public void itemLayerTracksAllPartsAndHidesIfAnyPartIsHidden()
	{
		FakeOverlay overlay = new FakeOverlay();
		Renderable bottom = TestProxies.proxy(Renderable.class);
		Renderable middle = TestProxies.proxy(Renderable.class);
		Renderable top = TestProxies.proxy(Renderable.class);
		ItemLayer layer = TestProxies.proxy(ItemLayer.class,
			TestProxies.method("getBottom", bottom),
			TestProxies.method("getMiddle", middle),
			TestProxies.method("getTop", top));
		overlay.hiddenRenderables.add(middle);

		assertFalse(callbacks(true, false, false, overlay).drawObject(layer));
		assertTrue(overlay.noted.contains(bottom));
		assertTrue(overlay.noted.contains(middle));
		assertTrue(overlay.noted.contains(top));
	}

	@Test
	public void objectObservationRequiresAnEnabledObjectCategory()
	{
		FakeOverlay overlay = new FakeOverlay();
		Renderable part = TestProxies.proxy(Renderable.class);
		GameObject object = TestProxies.proxy(GameObject.class, TestProxies.method("getRenderable", part));

		assertTrue(callbacks(true, false, false, overlay).drawObject(object));
		assertTrue(overlay.observed.isEmpty());
	}

	private static BillboardSceneDrawCallbacks callbacks(
		boolean enabled, boolean objects, boolean graphicsObjects, FakeOverlay overlay)
	{
		NpcSnapConfig config = TestProxies.proxy(NpcSnapConfig.class,
			TestProxies.method("enable2dBillboardSprites", enabled),
			TestProxies.method("applyToObjects", objects),
			TestProxies.method("applyToGraphicsObjects", graphicsObjects));
		return new BillboardSceneDrawCallbacks(config, overlay);
	}

	private static final class FakeOverlay implements BillboardSceneDrawCallbacks.OverlayAccess
	{
		private final Set<Renderable> noted = identitySet();
		private final Set<TileObject> observed = identitySet();
		private final Set<Renderable> hiddenRenderables = identitySet();
		private final Set<TileObject> hiddenTileObjects = identitySet();
		private final Set<Renderable> hiddenActor2d = identitySet();

		@Override
		public void noteSceneRenderable(Renderable renderable)
		{
			if (renderable != null)
			{
				noted.add(renderable);
			}
		}

		@Override
		public void observeTileObject(TileObject tileObject)
		{
			observed.add(tileObject);
		}

		@Override
		public boolean shouldHideRenderable(Renderable renderable)
		{
			return hiddenRenderables.contains(renderable);
		}

		@Override
		public boolean shouldHideActor2d(Renderable renderable)
		{
			return hiddenActor2d.contains(renderable);
		}

		@Override
		public boolean shouldHideTileObject(TileObject tileObject)
		{
			return hiddenTileObjects.contains(tileObject);
		}

		private static <T> Set<T> identitySet()
		{
			return Collections.newSetFromMap(new IdentityHashMap<>());
		}
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.NpcSnapConfig;
import com.kierenboal.npcsnap.TestProxies;

import java.awt.Polygon;
import java.awt.Rectangle;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Projectile;
import net.runelite.api.Model;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BillboardTargetEligibilityTest
{
	private static final Rectangle VIEWPORT = new Rectangle(0, 0, 100, 100);

	@Test
	public void actorRequiresPlayerAndActorLocations()
	{
		Actor actor = actor(null, 0, visibleTile());
		BillboardTargetEligibility eligibility = eligibility(0, false, 10);

		assertFalse(eligibility.actor(null, null, actor, VIEWPORT));
	}

	@Test
	public void actorRejectsOtherPlaneUnlessAllPlanesEnabled()
	{
		LocalPoint player = point(0, 0, 0);
		LocalPoint target = point(128, 0, 1);
		Actor actor = actor(target, 1, visibleTile());

		assertFalse(eligibility(0, false, 10).actor(player, target, actor, VIEWPORT));
		assertTrue(eligibility(0, true, 10).actor(player, target, actor, VIEWPORT));
	}

	@Test
	public void actorUsesCircularRadiusRatherThanSquareBounds()
	{
		LocalPoint player = point(0, 0, 0);
		LocalPoint diagonal = point(128, 128, 0);
		Actor actor = actor(diagonal, 0, visibleTile());

		assertFalse(eligibility(0, false, 1).actor(player, diagonal, actor, VIEWPORT));
	}

	@Test
	public void visibleActorTilePolygonIsEligibleWithoutProjectionFallback()
	{
		LocalPoint player = point(0, 0, 0);
		LocalPoint target = point(128, 0, 0);

		assertTrue(eligibility(0, false, 10).actor(player, target, actor(target, 0, visibleTile()), VIEWPORT));
	}

	@Test
	public void projectileWithoutModelIsRejectedBeforeProjection()
	{
		LocalPoint player = point(0, 0, 0);
		Projectile projectile = TestProxies.proxy(Projectile.class,
			TestProxies.method("getX", 128d),
			TestProxies.method("getY", 0d),
			TestProxies.method("getFloor", 0),
			TestProxies.method("getModel", null));

		assertFalse(eligibility(0, false, 10).projectile(player, projectile, VIEWPORT));
	}

	@Test
	public void projectileRemainsWorldEligibleWithoutCanvasProjection()
	{
		LocalPoint player = point(0, 0, 0);
		Projectile projectile = TestProxies.proxy(Projectile.class,
			TestProxies.method("getX", 128d),
			TestProxies.method("getY", 0d),
			TestProxies.method("getFloor", 0),
			TestProxies.method("getModel", TestProxies.proxy(Model.class)));

		assertTrue(eligibility(0, false, 10).projectileInWorld(player, projectile));
	}

	private static BillboardTargetEligibility eligibility(int plane, boolean allPlanes, int radius)
	{
		Client client = TestProxies.proxy(Client.class, TestProxies.method("getPlane", plane));
		NpcSnapConfig config = TestProxies.proxy(NpcSnapConfig.class,
			TestProxies.method("renderBillboardsOnAllPlanes", allPlanes),
			TestProxies.method("billboardRadiusTiles", radius));
		return new BillboardTargetEligibility(client, config, null, request -> null, (renderable, request) -> false);
	}

