import org.junit.Assert;
import org.junit.Test;

import static com.kierenboal.npcsnap.TestProxies.method;
import static com.kierenboal.npcsnap.TestProxies.proxy;

public class ObservedTileObjectBuilderTest
{
	@Test
	public void gameObjectBuildsSingleRenderablePartAtTileLocation()
	{
		Renderable renderable = proxy(Renderable.class);
		LocalPoint localPoint = new LocalPoint(128, 256);
		GameObject gameObject = proxy(
			GameObject.class,
			method("getRenderable", renderable),
			method("getLocalLocation", localPoint),
			method("getPlane", 2),
			method("getModelOrientation", 512),
			method("getZ", -417)
		);

		ObservedTileObject observed = ObservedTileObjectBuilder.build(gameObject);

		Assert.assertNotNull(observed);
		Assert.assertSame(gameObject, observed.tileObject);
		Assert.assertEquals(1, observed.parts.size());
		Assert.assertSame(renderable, observed.parts.get(0).renderable);
		Assert.assertEquals(localPoint, observed.parts.get(0).localPoint);
		Assert.assertEquals(2, observed.parts.get(0).plane);
		Assert.assertEquals(-417, observed.parts.get(0).worldHeight);
		Assert.assertEquals(512, observed.parts.get(0).modelOrientation);
	}

	@Test
	public void decorativeObjectAppliesPerRenderableOffsets()
	{
		Renderable first = proxy(Renderable.class);
		Renderable second = proxy(Renderable.class);
		DecorativeObject decorativeObject = proxy(
			DecorativeObject.class,
			method("getRenderable", first),
			method("getRenderable2", second),
			method("getLocalLocation", new LocalPoint(128, 256)),
			method("getPlane", 1),
			method("getZ", -288),
			method("getXOffset", 10),
			method("getYOffset", -20),
			method("getXOffset2", -30),
			method("getYOffset2", 40)
		);

		ObservedTileObject observed = ObservedTileObjectBuilder.build(decorativeObject);

		Assert.assertNotNull(observed);
		Assert.assertEquals(2, observed.parts.size());
		Assert.assertSame(first, observed.parts.get(0).renderable);
		Assert.assertEquals(new LocalPoint(138, 236), observed.parts.get(0).localPoint);
		Assert.assertSame(second, observed.parts.get(1).renderable);
		Assert.assertEquals(new LocalPoint(98, 296), observed.parts.get(1).localPoint);
		Assert.assertEquals(-288, observed.parts.get(0).worldHeight);
		Assert.assertEquals(-288, observed.parts.get(1).worldHeight);
	}

	@Test
	public void buildIgnoresDynamicSceneRenderablesOwnedByOtherPipelines()
	{
		Assert.assertNull(observedGameObject(proxy(Actor.class)));
		Assert.assertNull(observedGameObject(proxy(Projectile.class)));
		Assert.assertNull(observedGameObject(proxy(GraphicsObject.class)));
		Assert.assertNull(observedGameObject(proxy(TileItem.class)));
	}

	private static ObservedTileObject observedGameObject(Renderable renderable)
	{
		GameObject gameObject = proxy(
			GameObject.class,
			method("getRenderable", renderable),
			method("getLocalLocation", new LocalPoint(128, 256)),
			method("getPlane", 0)
		);
		return ObservedTileObjectBuilder.build(gameObject);
	}
}

package com.kierenboal.npcsnap.targeting;

import com.kierenboal.npcsnap.TestProxies;
import java.util.Collections;
import net.runelite.api.Actor;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.Projection;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static com.kierenboal.npcsnap.TestProxies.method;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertEquals;

public class WorldViewLocationResolverTest
{
	@Test
	public void leavesTopLevelActorLocationUnchanged()
	{
		WorldView top = TestProxies.proxy(WorldView.class, method("isTopLevel", true));
		LocalPoint point = new LocalPoint(128, 256, top);
		Actor actor = TestProxies.proxy(Actor.class, method("getWorldView", top), method("getLocalLocation", point));

		assertSame(point, WorldViewLocationResolver.toMainWorld(top, actor));
	}

	@Test
	public void transformsNestedActorThroughOwningWorldEntity()
	{
		Projection projection = TestProxies.proxy(Projection.class);
		WorldView nested = TestProxies.proxy(WorldView.class,
			method("isTopLevel", false), method("getMainWorldProjection", projection));
		LocalPoint nestedPoint = new LocalPoint(64, 96, nested);
		LocalPoint projected = new LocalPoint(512, 640);
		WorldEntity entity = TestProxies.proxy(WorldEntity.class,
			method("getWorldView", nested), method("transformToMainWorld", projected));
		IndexedObjectSet<WorldEntity> entities = indexed(entity);
		WorldView top = TestProxies.proxy(WorldView.class, method("isTopLevel", true), method("worldEntities", entities));

		assertSame(projected, WorldViewLocationResolver.toMainWorld(top, nested, nestedPoint));
	}

	@Test
	public void addsOwningBoatOrientationToNestedActorOrientation()
	{
		WorldView nested = TestProxies.proxy(WorldView.class, method("isTopLevel", false));
		WorldEntity entity = TestProxies.proxy(WorldEntity.class,
			method("getWorldView", nested), method("getOrientation", 512));
		WorldView top = TestProxies.proxy(WorldView.class,
			method("isTopLevel", true), method("worldEntities", indexed(entity)));
		Actor actor = TestProxies.proxy(Actor.class,
			method("getWorldView", nested), method("getCurrentOrientation", 256));

		assertEquals(768, WorldViewLocationResolver.toMainWorldOrientation(top, actor));
	}

	@SuppressWarnings("unchecked")
	private static <T> IndexedObjectSet<T> indexed(T value)
	{
		return TestProxies.proxy(IndexedObjectSet.class,
			method("iterator", Collections.singletonList(value).iterator()));
	}
}
